export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Physics state ----------
  const GRAV = [
    { name: 'Earth', g: 9.81, color: 0x2f6fdb },
    { name: 'Moon', g: 1.62, color: 0xb8bcc4 },
    { name: 'Mars', g: 3.71, color: 0xd9602b },
  ];
  const AMP = 0.3;            // release angle in rad (about 17 deg)
  const VIS = 0.18;           // visual metres per model metre of string
  const H = 1 / 480;          // fixed physics step
  let L = 1.0;                // model string length (m)
  let gi = 0;                 // gravity preset index
  let theta = AMP, omega = 0, prevTheta = AMP;
  let simT = 0, acc = 0;
  let refT = 0, mult = 4;     // first zero crossing occurs after a quarter period
  let displayLen = L * VIS;
  const periods = [];
  let lastMax = -1;

  const theory = () => 2 * Math.PI * Math.sqrt(L / GRAV[gi].g);
  const lenText = () => 'L = ' + L.toFixed(2) + ' m';
  const theoryText = () => 'Formula: ' + theory().toFixed(2) + ' s | g = ' + GRAV[gi].g.toFixed(2) + ' m/s2';

  // ---------- Stand ----------
  const PX = -0.24;
  const metal = new THREE.MeshStandardMaterial({ color: 0x8d949e, roughness: 0.5, metalness: 0.5 });
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.015, 0.1), new THREE.MeshStandardMaterial({ color: 0x3a3f48, roughness: 0.7 }));
  base.name = 'Base';
  base.position.set(PX, 0.0075, 0);
  root.add(base);

  const postGeo = new THREE.CylinderGeometry(0.007, 0.007, 0.45, 12);
  for (const s of [-1, 1]) {
    const post = new THREE.Mesh(postGeo, metal);
    post.position.set(PX + s * 0.15, 0.24, 0);
    root.add(post);
  }
  const beam = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.012, 0.015), metal);
  beam.position.set(PX, 0.456, 0);
  root.add(beam);

  // ---------- Pendulum ----------
  const pivot = new THREE.Group();
  pivot.position.set(PX, 0.45, 0);
  root.add(pivot);

  const stringGeo = new THREE.CylinderGeometry(0.0015, 0.0015, 1, 6);
  stringGeo.translate(0, -0.5, 0);
  const string = new THREE.Mesh(stringGeo, new THREE.MeshStandardMaterial({ color: 0xeeeeee, roughness: 0.8 }));
  string.name = 'String';
  pivot.add(string);

  const bobMat = new THREE.MeshStandardMaterial({ color: GRAV[0].color, roughness: 0.35, metalness: 0.3 });
  const bob = new THREE.Mesh(new THREE.SphereGeometry(0.025, 28, 16), bobMat);
  bob.name = 'Bob';
  pivot.add(bob);

  // ---------- Chart (3D bars) ----------
  const CX = 0.1, CBASE = 0.02, CMAXH = 0.09;
  const board = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.112, 0.008), new THREE.MeshStandardMaterial({ color: 0x23272e, roughness: 0.8 }));
  board.name = 'ChartBoard';
  board.position.set(CX, 0.07, -0.012);
  root.add(board);

  const lineMat = new THREE.MeshBasicMaterial({ color: 0x6b7480 });
  const lineGeo = new THREE.BoxGeometry(0.29, 0.001, 0.002);
  for (const f of [0.5, 1]) {
    const ln = new THREE.Mesh(lineGeo, lineMat);
    ln.position.set(CX, CBASE + CMAXH * f, -0.006);
    root.add(ln);
  }

  const barGeo = new THREE.BoxGeometry(0.02, 1, 0.02);
  barGeo.translate(0, 0.5, 0);
  const barMat = new THREE.MeshStandardMaterial({ color: 0x4fc3f7, roughness: 0.5 });
  const latestMat = new THREE.MeshStandardMaterial({ color: 0xffd54a, emissive: 0x553f00, roughness: 0.5 });
  const bars = [];
  for (let i = 0; i < 10; i++) {
    const b = new THREE.Mesh(barGeo, barMat);
    b.name = 'PeriodBar' + i;
    b.position.set(CX + (i - 4.5) * 0.026, CBASE, 0);
    b.scale.y = 0.001;
    b.visible = false;
    root.add(b);
    bars.push(b);
  }

  // ---------- Panels ----------
  const css = `
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .row { width: 460px; flex-direction: row; align-items: center; justify-content: space-between; }
      .rowc { width: 460px; flex-direction: row; align-items: center; justify-content: center; gap: 20px; }
      .lbl { color: #aab2bd; font-size: 24px; }
      .big { color: #ffd54a; font-size: 40px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .btn { width: 140px; height: 52px; align-items: center; justify-content: center; border-radius: 12px; background-color: #3a3f48; }
      .btn-on { width: 140px; height: 52px; align-items: center; justify-content: center; border-radius: 12px; background-color: #2f6fdb; }
      .sq { width: 100px; height: 52px; align-items: center; justify-content: center; border-radius: 12px; background-color: #3a3f48; }
      .wide { width: 460px; height: 52px; align-items: center; justify-content: center; border-radius: 12px; background-color: #2e8b57; }
      .bt { color: #ffffff; font-size: 24px; font-weight: 700; }
      .lenbox { width: 240px; align-items: center; justify-content: center; }
      .lentext { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .ctitle { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .csub { color: #aab2bd; font-size: 22px; text-align: center; }
      .ccard { width: 460px; flex-direction: column; align-items: center; gap: 4px; padding-top: 10px; padding-bottom: 10px;
               padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #1f2228; }
    </style>`;

  const controls = ui(`${css}
    <div class="card">
      <span class="title">Pendulum Lab</span>
      <div class="row">
        <span class="lbl">Period</span>
        <span class="big" id="per">...</span>
      </div>
      <span class="body" id="theory">${theoryText()}</span>
      <div class="rowc">
        <button class="sq" id="lenminus"><span class="bt">-</span></button>
        <div class="lenbox"><span class="lentext" id="len">${lenText()}</span></div>
        <button class="sq" id="lenplus"><span class="bt">+</span></button>
      </div>
      <div class="rowc">
        <button class="btn-on" id="g0"><span class="bt">Earth</span></button>
        <button class="btn" id="g1"><span class="bt">Moon</span></button>
        <button class="btn" id="g2"><span class="bt">Mars</span></button>
      </div>
      <button class="wide" id="release"><span class="bt">Release again</span></button>
    </div>`, { width: 0.3, position: [CX, 0.345, 0] });
  root.add(controls.object3D);

  const chartInfo = ui(`${css}
    <div class="ccard">
      <span class="ctitle">Last 10 periods</span>
      <span class="csub" id="chartmax">Full bar = 1.0 s</span>
    </div>`, { width: 0.3, position: [CX, 0.175, 0] });
  root.add(chartInfo.object3D);

  // ---------- Logic ----------
  function release() {
    theta = AMP; omega = 0; prevTheta = AMP;
    refT = simT; mult = 4;
  }

  function refreshChart() {
    const n = periods.length;
    let mx = 0;
    for (let i = 0; i < n; i++) if (periods[i] > mx) mx = periods[i];
    const niceMax = Math.max(1, Math.ceil(mx * 1.1 * 2) / 2);
    for (let i = 0; i < 10; i++) {
      const k = i - (10 - n);
      const b = bars[i];
      if (k < 0) { b.visible = false; continue; }
      b.visible = true;
      b.scale.y = Math.max(0.001, (periods[k] / niceMax) * CMAXH);
      b.material = k === n - 1 ? latestMat : barMat;
    }
    if (niceMax !== lastMax) {
      lastMax = niceMax;
      chartInfo.set('chartmax', { text: 'Full bar = ' + niceMax.toFixed(1) + ' s' });
    }
  }

  function recordPeriod(p) {
    periods.push(p);
    if (periods.length > 10) periods.shift();
    controls.set('per', { text: p.toFixed(2) + ' s' });
    refreshChart();
  }

  function applyChange() {
    controls.set('len', { text: lenText() });
    controls.set('theory', { text: theoryText() });
    release();
  }

  function selectGravity(i) {
    gi = i;
    bobMat.color.setHex(GRAV[i].color);
    for (let k = 0; k < 3; k++) {
      controls.set('g' + k, { backgroundColor: k === i ? '#2f6fdb' : '#3a3f48' });
    }
    applyChange();
  }

  controls.on('lenminus', 'click', () => { L = Math.max(0.25, L - 0.25); applyChange(); });
  controls.on('lenplus', 'click', () => { L = Math.min(2.0, L + 0.25); applyChange(); });
  controls.on('g0', 'click', () => selectGravity(0));
  controls.on('g1', 'click', () => selectGravity(1));
  controls.on('g2', 'click', () => selectGravity(2));
  controls.on('release', 'click', () => release());

  // ---------- Frame update ----------
  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      acc += dt;
      const g = GRAV[gi].g;
      while (acc >= H) {
        acc -= H;
        prevTheta = theta;
        omega += -(g / L) * Math.sin(theta) * H;
        theta += omega * H;
        simT += H;
        if ((prevTheta < 0 && theta >= 0) || (prevTheta > 0 && theta <= 0)) {
          const f = prevTheta / (prevTheta - theta);
          const tc = simT - H + f * H;
          recordPeriod(mult * (tc - refT));
          refT = tc;
          mult = 2;
        }
      }
      displayLen += (L * VIS - displayLen) * Math.min(1, dt * 8);
      pivot.rotation.z = theta;
      string.scale.y = displayLen;
      bob.position.y = -displayLen;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Recipe data ----------
  const INGREDIENTS = [
    '1 1/2 cups flour',
    '3 1/2 tsp baking powder',
    '1 tbsp sugar',
    '1/4 tsp salt',
    '1 1/4 cups milk',
    '1 egg',
    '3 tbsp melted butter',
  ];
  const STEPS = [
    { title: 'Mix the dry ingredients', text: 'In a large bowl, whisk 1 1/2 cups flour, 3 1/2 tsp baking powder, 1 tbsp sugar and 1/4 tsp salt.', secs: 30 },
    { title: 'Mix the wet ingredients', text: 'In a second bowl, whisk 1 1/4 cups milk, 1 egg and 3 tbsp melted butter until smooth.', secs: 30 },
    { title: 'Combine gently', text: 'Pour the wet mix into the dry mix. Stir only until just combined. A few lumps are fine.', secs: 20 },
    { title: 'Rest the batter', text: 'Let the batter rest for 5 minutes. It thickens a little and the pancakes turn out fluffier.', secs: 300 },
    { title: 'Heat the pan', text: 'Warm a lightly oiled pan over medium heat. A drop of water should sizzle when it is ready.', secs: 60 },
    { title: 'Pour and cook side one', text: 'Pour about 1/4 cup batter. Cook about 2 minutes, until bubbles form and the edges look set.', secs: 120 },
    { title: 'Flip and finish', text: 'Flip once and cook 1 to 2 minutes, until golden brown. Repeat with the rest of the batter.', secs: 90 },
    { title: 'Serve warm', text: 'Stack the pancakes and add butter and maple syrup. Enjoy!', secs: 0 },
  ];
  const N = STEPS.length;
  const LAST = N - 1;

  // ---------- State ----------
  let idx = 0;
  let finished = false;
  let remaining = STEPS[0].secs;
  let running = false;
  let timerDone = false;
  let shown = -1;
  const checks = INGREDIENTS.map(() => false);

  const C_GREEN = '#35c46f';
  const C_AMBER = '#f5a524';
  const C_GRAY = '#3a3f48';

  function fmt(sec) {
    const s = Math.max(0, Math.ceil(sec));
    const m = Math.floor(s / 60);
    const r = s % 60;
    return (m < 10 ? '0' : '') + m + ':' + (r < 10 ? '0' : '') + r;
  }
  function segColor(i) {
    if (finished || i < idx) return C_GREEN;
    if (i === idx) return C_AMBER;
    return C_GRAY;
  }
  function pctText() {
    const p = finished ? 100 : Math.round((idx / N) * 100);
    return 'Recipe progress: ' + p + '%';
  }

  // ---------- 3D station on a wooden board ----------
  const board = new THREE.Mesh(
    new THREE.CylinderGeometry(0.075, 0.075, 0.012, 32),
    new THREE.MeshStandardMaterial({ color: 0x8b5e3c, roughness: 0.8 }),
  );
  board.name = 'Cooking board';
  board.position.set(0.31, 0.006, 0.05);
  root.add(board);
  traits(board, { grab: true });

  // status ring around the board
  const ringMat = new THREE.MeshStandardMaterial({ color: 0x4a5560, emissive: 0x4a5560, emissiveIntensity: 0.15 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.073, 0.003, 8, 48), ringMat);
  ring.name = 'Timer ring';
  ring.rotation.x = Math.PI / 2;
  ring.position.y = 0.006;
  board.add(ring);

  // Bowl (steps 1-4)
  const bowl = new THREE.Group();
  bowl.name = 'Bowl';
  board.add(bowl);
  const bowlShell = new THREE.Mesh(
    new THREE.SphereGeometry(0.05, 28, 14, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2),
    new THREE.MeshStandardMaterial({ color: 0xdfe6ee, roughness: 0.4, side: THREE.DoubleSide }),
  );
  bowlShell.position.y = 0.056;
  bowl.add(bowlShell);
  const bowlFillMat = new THREE.MeshStandardMaterial({ color: 0xf4efe4, roughness: 0.9 });
  const bowlFill = new THREE.Mesh(new THREE.CircleGeometry(0.046, 28), bowlFillMat);
  bowlFill.name = 'Bowl contents';
  bowlFill.rotation.x = -Math.PI / 2;
  bowlFill.position.y = 0.044;
  bowl.add(bowlFill);

  // Pan (steps 5-7)
  const pan = new THREE.Group();
  pan.name = 'Pan';
  board.add(pan);
  const panBody = new THREE.Mesh(
    new THREE.CylinderGeometry(0.057, 0.05, 0.02, 32),
    new THREE.MeshStandardMaterial({ color: 0x2b2d31, roughness: 0.4, metalness: 0.5 }),
  );
  panBody.position.y = 0.016;
  pan.add(panBody);
  const panInnerMat = new THREE.MeshStandardMaterial({ color: 0x1a1b1e, emissive: 0xff4400, emissiveIntensity: 0, roughness: 0.5 });
  const panInner = new THREE.Mesh(new THREE.CircleGeometry(0.05, 32), panInnerMat);
  panInner.rotation.x = -Math.PI / 2;
  panInner.position.y = 0.0265;
  pan.add(panInner);
  const panHandle = new THREE.Mesh(
    new THREE.BoxGeometry(0.012, 0.008, 0.06),
    new THREE.MeshStandardMaterial({ color: 0x555a63, roughness: 0.6 }),
  );
  panHandle.position.set(0, 0.022, 0.085);
  pan.add(panHandle);
  const pancakeMat = new THREE.MeshStandardMaterial({ color: 0xf3e0a8, roughness: 0.8 });
  const panPancake = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.008, 32), pancakeMat);
  panPancake.name = 'Pancake';
  panPancake.position.y = 0.031;
  pan.add(panPancake);

  // Plate with stack (final step)
  const plate = new THREE.Group();
  plate.name = 'Plate';
  board.add(plate);
  const plateMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(0.065, 0.055, 0.008, 32),
    new THREE.MeshStandardMaterial({ color: 0xf5f5f5, roughness: 0.3 }),
  );
  plateMesh.position.y = 0.01;
  plate.add(plateMesh);
  const stackGeo = new THREE.CylinderGeometry(0.045, 0.045, 0.01, 32);
  const stackMat = new THREE.MeshStandardMaterial({ color: 0xdba24e, roughness: 0.8 });
  for (let i = 0; i < 4; i++) {
    const p = new THREE.Mesh(stackGeo, stackMat);
    p.name = 'Pancake ' + (i + 1);
    p.position.set((i % 2 ? 0.002 : -0.002), 0.019 + i * 0.011, (i % 2 ? -0.002 : 0.002));
    plate.add(p);
  }
  const stackTop = 0.019 + 3 * 0.011 + 0.005;
  const syrup = new THREE.Mesh(
    new THREE.CylinderGeometry(0.03, 0.03, 0.002, 24),
    new THREE.MeshStandardMaterial({ color: 0x9a4a0c, roughness: 0.2, transparent: true, opacity: 0.9 }),
  );
  syrup.position.y = stackTop + 0.001;
  plate.add(syrup);
  const butter = new THREE.Mesh(
    new THREE.BoxGeometry(0.016, 0.008, 0.016),
    new THREE.MeshStandardMaterial({ color: 0xfff0a0, roughness: 0.5 }),
  );
  butter.position.y = stackTop + 0.006;
  plate.add(butter);

  let heat = false;
  function applyStage() {
    bowl.visible = !finished && idx <= 3;
    pan.visible = !finished && idx >= 4 && idx <= 6;
    plate.visible = finished || idx === 7;
    panPancake.visible = idx === 5 || idx === 6;
    pancakeMat.color.setHex(idx === 5 ? 0xf3e0a8 : 0xd9a04a);
    if (idx === 0) bowlFillMat.color.setHex(0xf4efe4);
    else if (idx === 1) bowlFillMat.color.setHex(0xf3e6b4);
    else bowlFillMat.color.setHex(0xf0d9a0);
    heat = !finished && idx >= 4 && idx <= 6;
  }
  applyStage();

  // ---------- Ingredient panel ----------
  let rows = '';
  for (let i = 0; i < INGREDIENTS.length; i++) {
    rows += '<button class="row" id="ing' + i + '"><div class="box" id="box' + i + '"></div>' +
      '<span class="lbl" id="lbl' + i + '">' + INGREDIENTS[i] + '</span></button>';
  }
  const ingPanel = ui(`
    <style>
      .card { width: 400px; flex-direction: column; gap: 10px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #aab2bd; font-size: 22px; }
      .row { width: 356px; flex-direction: row; align-items: center; gap: 14px; padding-top: 8px; padding-bottom: 8px;
             padding-left: 10px; padding-right: 10px; border-radius: 12px; background-color: #2a2e35; }
      .box { width: 30px; height: 30px; border-radius: 8px; background-color: #3a3f48; }
      .lbl { color: #ffffff; font-size: 22px; }
      .count { color: #f5a524; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Ingredients</span>
      <span class="sub">Makes about 8 pancakes. Tap each item as you measure it.</span>
      ${rows}
      <span class="count" id="count">0 of 7 ready</span>
    </div>`, { width: 0.25, position: [-0.27, 0.23, 0], rotationY: 0.15 });
  root.add(ingPanel.object3D);

  INGREDIENTS.forEach((_, i) => {
    ingPanel.on('ing' + i, 'click', () => {
      checks[i] = !checks[i];
      ingPanel.set('box' + i, { backgroundColor: checks[i] ? C_GREEN : C_GRAY });
      ingPanel.set('lbl' + i, { color: checks[i] ? '#8a93a0' : '#ffffff' });
      let n = 0;
      for (let k = 0; k < checks.length; k++) if (checks[k]) n++;
      if (n === checks.length) {
        ingPanel.set('count', { text: 'All ready! Time to cook.', color: C_GREEN });
      } else {
        ingPanel.set('count', { text: n + ' of ' + checks.length + ' ready', color: C_AMBER });
      }
    });
  });

  // ---------- Step panel ----------
  let segs = '';
  for (let i = 0; i < N; i++) segs += '<div class="seg" id="seg' + i + '" style="background-color:' + segColor(i) + '"></div>';
  const s0 = STEPS[0];
  const info = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 14px; padding-top: 22px; padding-bottom: 22px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .stepno { color: #f5a524; font-size: 24px; font-weight: 700; }
      .stitle { color: #ffffff; font-size: 32px; font-weight: 700; }
      .bodybox { width: 472px; height: 150px; }
      .body { color: #d7dbe2; font-size: 24px; }
      .trow { width: 472px; flex-direction: row; align-items: center; gap: 12px; }
      .timewrap { width: 180px; }
      .time { color: #ffffff; font-size: 52px; font-weight: 700; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 12px; padding-right: 12px; border-radius: 14px;
             align-items: center; justify-content: center; }
      .btext { color: #ffffff; font-size: 26px; font-weight: 700; }
      .nav { width: 472px; flex-direction: row; gap: 14px; }
      .prow { width: 472px; flex-direction: row; gap: 8px; }
      .seg { width: 50px; height: 16px; border-radius: 8px; background-color: #3a3f48; }
      .pct { color: #aab2bd; font-size: 22px; }
    </style>
    <div class="card">
      <span class="stepno" id="stepno">Step 1 of ${N}</span>
      <span class="stitle" id="stitle">${s0.title}</span>
      <div class="bodybox"><span class="body" id="body">${s0.text}</span></div>
      <div class="trow" id="timerRow">
        <div class="timewrap"><span class="time" id="time">${fmt(s0.secs)}</span></div>
        <button class="btn" id="startBtn" style="width:150px;background-color:#2f6fdb"><span class="btext" id="startLbl">Start</span></button>
        <button class="btn" id="resetBtn" style="width:110px;background-color:#3a3f48"><span class="btext">Reset</span></button>
      </div>
      <div class="nav">
        <button class="btn" id="backBtn" style="width:229px;background-color:#2a2e35"><span class="btext" id="backLbl" style="color:#6b7280">Back</span></button>
        <button class="btn" id="nextBtn" style="width:229px;background-color:#2f9e5b"><span class="btext" id="nextLbl">Next</span></button>
      </div>
      <div class="prow">${segs}</div>
      <span class="pct" id="pct">${pctText()}</span>
    </div>`, { width: 0.33, position: [0.05, 0.23, 0] });
  root.add(info.object3D);

  // ---------- UI refresh helpers ----------
  function refreshTimerUI() {
    const secs = STEPS[idx].secs;
    timerDone = secs > 0 && remaining <= 0;
    shown = Math.ceil(remaining);
    if (timerDone) {
      info.set('time', { text: 'DONE', color: '#6fe39b' });
      info.set('startLbl', { text: 'Again' });
      info.set('startBtn', { backgroundColor: '#2f9e5b' });
      ringMat.color.setHex(0x35c46f); ringMat.emissive.setHex(0x35c46f);
    } else if (running) {
      info.set('time', { text: fmt(remaining), color: '#ffd37a' });
      info.set('startLbl', { text: 'Pause' });
      info.set('startBtn', { backgroundColor: '#d98a1c' });
      ringMat.color.setHex(0xf5a524); ringMat.emissive.setHex(0xf5a524);
    } else {
      info.set('time', { text: fmt(remaining), color: '#ffffff' });
      info.set('startLbl', { text: remaining < secs ? 'Resume' : 'Start' });
      info.set('startBtn', { backgroundColor: '#2f6fdb' });
      ringMat.color.setHex(0x4a5560); ringMat.emissive.setHex(0x4a5560);
    }
  }

  function refreshAll() {
    const st = STEPS[idx];
    if (finished) {
      info.set('stepno', { text: 'Recipe complete' });
      info.set('stitle', { text: 'All done - enjoy!' });
      info.set('body', { text: 'Great work, chef! Press Back to review a step, or tick the ingredients again for the next batch.' });
      info.set('timerRow', { display: 'none' });
    } else {
      info.set('stepno', { text: 'Step ' + (idx + 1) + ' of ' + N });
      info.set('stitle', { text: st.title });
      info.set('body', { text: st.text });
      if (st.secs > 0) {
        info.set('timerRow', { display: 'flex' });
        refreshTimerUI();
      } else {
        info.set('timerRow', { display: 'none' });
        ringMat.color.setHex(0x4a5560); ringMat.emissive.setHex(0x4a5560);
      }
    }
    const backOff = idx === 0 && !finished;
    info.set('backBtn', { backgroundColor: backOff ? '#2a2e35' : '#3a3f48' });
    info.set('backLbl', { color: backOff ? '#6b7280' : '#ffffff' });
    if (finished) {
      info.set('nextLbl', { text: 'Done', color: '#6b7280' });
      info.set('nextBtn', { backgroundColor: '#2a2e35' });
    } else {
      info.set('nextLbl', { text: idx === LAST ? 'Finish' : 'Next', color: '#ffffff' });
      info.set('nextBtn', { backgroundColor: '#2f9e5b' });
    }
    for (let i = 0; i < N; i++) info.set('seg' + i, { backgroundColor: segColor(i) });
    info.set('pct', { text: pctText() });
    applyStage();
  }

  function resetTimer() {
    remaining = STEPS[idx].secs;
    running = false;
    timerDone = false;
  }

  // ---------- Interactions ----------
  info.on('nextBtn', 'click', () => {
    if (finished) return;
    if (idx < LAST) {
      idx++;
      resetTimer();
    } else {
      finished = true;
      running = false;
    }
    refreshAll();
  });

  info.on('backBtn', 'click', () => {
    if (finished) {
      finished = false;
    } else if (idx > 0) {
      idx--;
    } else {
      return;
    }
    resetTimer();
    refreshAll();
  });

  info.on('startBtn', 'click', () => {
    if (finished || STEPS[idx].secs <= 0) return;
    if (remaining <= 0) {
      remaining = STEPS[idx].secs;
      running = true;
    } else {
      running = !running;
    }
    refreshTimerUI();
  });

  info.on('resetBtn', 'click', () => {
    if (finished || STEPS[idx].secs <= 0) return;
    resetTimer();
    refreshTimerUI();
  });

  // ---------- Animation ----------
  return {
    root,
    update(time, delta) {
      if (running) {
        remaining -= delta;
        if (remaining <= 0) {
          remaining = 0;
          running = false;
          refreshTimerUI();
        } else {
          const c = Math.ceil(remaining);
          if (c !== shown) {
            shown = c;
            info.set('time', { text: fmt(remaining) });
          }
        }
      }

      // status ring: pulses while running, blinks when the timer finishes
      if (running) {
        ringMat.emissiveIntensity = 0.55 + 0.4 * Math.sin(time * 4);
      } else if (timerDone) {
        ringMat.emissiveIntensity = Math.sin(time * 10) > 0 ? 1.0 : 0.15;
      } else {
        ringMat.emissiveIntensity = 0.15;
      }

      // hot pan glow
      panInnerMat.emissiveIntensity = heat ? 0.3 + 0.1 * Math.sin(time * 2) : 0;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
