      .row { width: 452px; flex-direction: row; gap: 8px; align-items: center; }
      .spread { width: 452px; flex-direction: row; align-items: center; justify-content: space-between; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .price { color: #7ee2a0; font-size: 30px; font-weight: 700; }
      .body { width: 452px; color: #d7dbe2; font-size: 24px; }
      .lbl { color: #9fb3c8; font-size: 24px; font-weight: 700; }
      .note { width: 452px; color: #d7dbe2; font-size: 24px; }
      .nav { width: 222px; padding-top: 10px; padding-bottom: 10px; align-items: center; justify-content: center;
             border-radius: 12px; background-color: #2f6fdb; }
      .navt { color: #ffffff; font-size: 24px; font-weight: 700; }
      .chip { width: 104px; padding-top: 10px; padding-bottom: 10px; align-items: center; justify-content: center;
              border-radius: 12px; background-color: #3a3f47; }
      .chipw { width: 142px; padding-top: 10px; padding-bottom: 10px; align-items: center; justify-content: center;
              border-radius: 12px; background-color: #3a3f47; }
      .chipt { color: #ffffff; font-size: 24px; font-weight: 700; }
      .add { width: 452px; padding-top: 14px; padding-bottom: 14px; align-items: center; justify-content: center;
             border-radius: 14px; background-color: #2f9e5b; }
      .addt { color: #ffffff; font-size: 28px; font-weight: 700; }
    </style>
    <div class="panel">
      <div class="row">
        <button class="nav" id="prev"><span class="navt">Previous</span></button>
        <button class="nav" id="next"><span class="navt">Next</span></button>
      </div>
      <div class="spread">
        <span class="title" id="name">Aura</span>
        <span class="price" id="price">$129</span>
      </div>
      <span class="body" id="desc">Over-ear, 30 h battery, warm balanced sound.</span>
      <span class="lbl">Color</span>
      <div class="row">
        <button class="chip" id="col0"><span class="chipt" id="colt0">Black</span></button>
        <button class="chip" id="col1"><span class="chipt" id="colt1">Red</span></button>
        <button class="chip" id="col2"><span class="chipt" id="colt2">Blue</span></button>
        <button class="chip" id="col3"><span class="chipt" id="colt3">White</span></button>
      </div>
      <span class="lbl">Size</span>
      <div class="row">
        <button class="chipw" id="sz0"><span class="chipt" id="szt0">Small</span></button>
        <button class="chipw" id="sz1"><span class="chipt" id="szt1">Medium</span></button>
        <button class="chipw" id="sz2"><span class="chipt" id="szt2">Large</span></button>
      </div>
      <button class="add" id="add"><span class="addt">Add to cart</span></button>
      <span class="note" id="status">Press a headphone or use Next to browse.</span>
    </div>`, { width: 0.26, position: [-0.275, 0.21, 0.02], rotationY: 0.3 });
  root.add(info.object3D);

  // ---------- UI: cart + checkout panel ----------
  let rowsMarkup = '';
  for (let i = 0; i < MAX_LINES; i++) {
    rowsMarkup += `
      <div class="crow" id="row${i}">
        <div class="clabel">
          <span class="cname" id="lab${i}">Item</span>
          <span class="csub" id="sub${i}">1 x $0</span>
        </div>
        <button class="qbtn" id="dec${i}"><span class="qt">-</span></button>
        <div class="qtyb"><span class="qt" id="qty${i}">1</span></div>
        <button class="qbtn" id="inc${i}"><span class="qt">+</span></button>
      </div>`;
  }
  const cart = ui(`
    <style>
      .panel { width: 500px; flex-direction: column; gap: 10px; padding-top: 24px; padding-bottom: 24px;
               padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .note { width: 452px; color: #d7dbe2; font-size: 24px; }
      .crow { width: 452px; flex-direction: row; gap: 8px; align-items: center; }
      .clabel { width: 260px; flex-direction: column; }
      .cname { color: #ffffff; font-size: 24px; font-weight: 700; }
      .csub { color: #aab2bd; font-size: 24px; }
      .qbtn { width: 52px; height: 46px; align-items: center; justify-content: center;
              border-radius: 12px; background-color: #3a3f47; }
      .qtyb { width: 40px; align-items: center; justify-content: center; }
      .qt { color: #ffffff; font-size: 28px; font-weight: 700; }
      .line { width: 452px; height: 2px; background-color: #444a54; }
      .spread { width: 452px; flex-direction: row; align-items: center; justify-content: space-between; }
      .sl { color: #d7dbe2; font-size: 24px; }
      .sv { color: #ffffff; font-size: 24px; font-weight: 700; }
      .tl { color: #ffffff; font-size: 30px; font-weight: 700; }
      .tv { color: #7ee2a0; font-size: 30px; font-weight: 700; }
      .go { width: 452px; padding-top: 14px; padding-bottom: 14px; align-items: center; justify-content: center;
            border-radius: 14px; background-color: #2f6fdb; }
      .got { color: #ffffff; font-size: 28px; font-weight: 700; }
    </style>
    <div class="panel">
      <span class="title">Your cart</span>
      <div id="emptyBox"><span class="note">Cart is empty. Add headphones from the left panel.</span></div>
      ${rowsMarkup}
      <div class="line"></div>
      <div class="spread"><span class="sl">Subtotal</span><span class="sv" id="vSub">$0.00</span></div>
      <div class="spread"><span class="sl">Tax (8%)</span><span class="sv" id="vTax">$0.00</span></div>
      <div class="spread"><span class="tl">Total</span><span class="tv" id="vTot">$0.00</span></div>
      <button class="go" id="checkout"><span class="got">Checkout</span></button>
      <span class="note" id="msg">Review your order, then check out.</span>
    </div>`, { width: 0.26, position: [0.275, 0.2, 0.02], rotationY: -0.3 });
  root.add(cart.object3D);

  // ---------- logic ----------
  const money = (cents) => '$' + (cents / 100).toFixed(2);
  const DEFAULT_MSG = 'Review your order, then check out.';

  function setChip(btnId, textId, on) {
    info.set(btnId, { backgroundColor: on ? '#ffffff' : '#3a3f47' });
    info.set(textId, { color: on ? '#1a1d22' : '#ffffff' });
  }

  function refreshProduct() {
    const p = PRODUCTS[selected];
    info.set('name', { text: p.name });
    info.set('price', { text: '$' + p.price });
    info.set('desc', { text: p.desc });
    for (let c = 0; c < COLORS.length; c++) setChip('col' + c, 'colt' + c, c === colorSel[selected]);
    for (let s = 0; s < SIZES.length; s++) setChip('sz' + s, 'szt' + s, s === sizeSel[selected]);
  }

  function select(i) {
    selected = i;
    const desired = -i * TAU / 3;
    let diff = desired - ringTarget;
    diff -= TAU * Math.round(diff / TAU);
    ringTarget += diff;
    refreshProduct();
    info.set('status', { text: 'Choose a color and size, then add to cart.' });
  }

  function renderCart(resetMsg) {
    let subC = 0;
    for (let i = 0; i < MAX_LINES; i++) {
      const l = lines[i];
      if (l) {
        const p = PRODUCTS[l.p];
        cart.set('row' + i, { display: 'flex' });
        cart.set('lab' + i, { text: p.name + ' ' + COLORS[l.c].name + ' ' + SIZES[l.s].short });
        cart.set('sub' + i, { text: l.qty + ' x $' + p.price + ' = $' + (p.price * l.qty) });
        cart.set('qty' + i, { text: String(l.qty) });
        subC += p.price * l.qty * 100;
      } else {
        cart.set('row' + i, { display: 'none' });
      }
    }
    cart.set('emptyBox', { display: lines.length ? 'none' : 'flex' });
    const taxC = Math.round(subC * TAX_RATE);
    cart.set('vSub', { text: money(subC) });
    cart.set('vTax', { text: money(taxC) });
    cart.set('vTot', { text: money(subC + taxC) });
    if (resetMsg) cart.set('msg', { text: DEFAULT_MSG });
  }

  info.on('prev', 'click', () => select((selected + PRODUCTS.length - 1) % PRODUCTS.length));
  info.on('next', 'click', () => select((selected + 1) % PRODUCTS.length));

  for (let c = 0; c < COLORS.length; c++) {
    info.on('col' + c, 'click', () => {
      colorSel[selected] = c;
      items[selected].mat.color.setHex(COLORS[c].hex);
      refreshProduct();
      info.set('status', { text: 'Color: ' + COLORS[c].name + '.' });
    });
  }
  for (let s = 0; s < SIZES.length; s++) {
    info.on('sz' + s, 'click', () => {
      sizeSel[selected] = s;
      refreshProduct();
      info.set('status', { text: 'Size: ' + SIZES[s].name + '.' });
    });
  }

  info.on('add', 'click', () => {
    const p = selected, c = colorSel[p], s = sizeSel[p];
    let line = null;
    for (let i = 0; i < lines.length; i++) {
      if (lines[i].p === p && lines[i].c === c && lines[i].s === s) line = lines[i];
    }
    if (line) {
      if (line.qty >= 9) {
        info.set('status', { text: 'Maximum 9 of one item.' });
        return;
      }
      line.qty++;
    } else {
      if (lines.length >= MAX_LINES) {
        info.set('status', { text: 'Cart is full. Remove an item first.' });
        return;
      }
      lines.push({ p, c, s, qty: 1 });
    }
    info.set('status', { text: 'Added ' + PRODUCTS[p].name + ' ' + COLORS[c].name + ' ' + SIZES[s].short + ' to cart.' });
    renderCart(true);
  });

  for (let i = 0; i < MAX_LINES; i++) {
    cart.on('dec' + i, 'click', () => {
      const l = lines[i];
      if (!l) return;
      l.qty--;
      if (l.qty <= 0) lines.splice(i, 1);
      renderCart(true);
    });
    cart.on('inc' + i, 'click', () => {
      const l = lines[i];
      if (!l) return;
      if (l.qty < 9) l.qty++;
      renderCart(true);
    });
  }

  cart.on('checkout', 'click', () => {
    if (!lines.length) {
      cart.set('msg', { text: 'Your cart is empty.' });
      return;
    }
    let count = 0, subC = 0;
    for (let i = 0; i < lines.length; i++) {
      count += lines[i].qty;
      subC += PRODUCTS[lines[i].p].price * lines[i].qty * 100;
    }
    const totC = subC + Math.round(subC * TAX_RATE);
    lines.length = 0;
    renderCart(false);
    cart.set('msg', { text: 'Order placed! ' + count + (count === 1 ? ' item' : ' items') + ', paid ' + money(totC) + '. Thank you!' });
  });

  refreshProduct();
  renderCart(true);

  // ---------- animation ----------
  return {
    root,
    update(time, delta) {
      const k = 1 - Math.exp(-delta * 5);
      ringAngle += (ringTarget - ringAngle) * k;
      const ks = 1 - Math.exp(-delta * 8);
      for (let i = 0; i < items.length; i++) {
        const it = items[i];
        const a = ringAngle + i * TAU / 3;
        it.group.position.set(Math.sin(a) * R, 0, Math.cos(a) * R);
        it.head.rotation.y = time * 0.5 + i * 1.3;
        const target = SIZES[sizeSel[i]].scale;
        it.scale += (target - it.scale) * ks;
        it.head.scale.setScalar(it.scale);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- layout constants (meters) ----------
  const SHIFT = 0.26; // centers the arm (built in "arm coords" from the shoulder end)
  const Y0 = 0.09;
  const Z0 = 0.08;

  // ---------- shared geometry ----------
  const sphereGeo = new THREE.SphereGeometry(1, 20, 14);
  const capCache = {};
  function capsuleGeo(r, len) {
    const key = r + '_' + len;
    if (!capCache[key]) capCache[key] = new THREE.CapsuleGeometry(r, len, 4, 12);
    return capCache[key];
  }

  const parts = [];
  const partByName = {};

  function makePart(name, cx, z, spreadOffset) {
    const group = new THREE.Group();
    group.name = name;
    group.position.set(cx - SHIFT, Y0, Z0 + z);
    root.add(group);
    const mat = new THREE.MeshStandardMaterial({
      color: 0xeee4cc, roughness: 0.65, emissive: 0x000000, emissiveIntensity: 0,
    });
    const home = group.position.clone();
    const spread = home.clone().add(new THREE.Vector3(spreadOffset[0], spreadOffset[1], spreadOffset[2]));
    const part = { name, group, mat, home, spread, target: home };
    parts.push(part);
    partByName[name] = part;
    return part;
  }

  function addSphere(part, rx, ry, rz, x, y, z) {
    const m = new THREE.Mesh(sphereGeo, part.mat);
    m.scale.set(rx, ry, rz);
    m.position.set(x, y, z);
    part.group.add(m);
    return m;
  }

  // capsule lying along X (optionally fanned by angle a around Y)
  function addCapsule(part, r, len, x, y, z, a) {
    const m = new THREE.Mesh(capsuleGeo(r, len), part.mat);
    m.rotation.set(0, -(a || 0), Math.PI / 2);
    m.position.set(x, y, z);
    part.group.add(m);
    return m;
  }

  // ---------- Humerus ----------
  const humerus = makePart('Humerus', 0.0785, 0, [-0.05, 0, 0]);
  addCapsule(humerus, 0.009, 0.10, 0, 0, 0, 0);
  addSphere(humerus, 0.017, 0.017, 0.017, -0.064, 0.004, 0);
  addSphere(humerus, 0.011, 0.017, 0.015, 0.064, 0, 0);

  // ---------- Ulna ----------
  const ulna = makePart('Ulna', 0.240, -0.011, [0, 0, -0.04]);
  addCapsule(ulna, 0.006, 0.12, 0, 0, 0, 0);
  addSphere(ulna, 0.011, 0.012, 0.009, -0.068, 0, 0);
  addSphere(ulna, 0.0065, 0.0065, 0.0065, 0.068, 0, 0);

  // ---------- Radius ----------
  const radius = makePart('Radius', 0.248, 0.011, [0, 0, 0.045]);
  addCapsule(radius, 0.0055, 0.115, 0, 0, 0, 0);
  addSphere(radius, 0.004, 0.008, 0.008, -0.0625, 0, 0);
  addSphere(radius, 0.012, 0.011, 0.013, 0.063, 0, 0);

  // ---------- Carpals (8 small bones in two rows) ----------
  const carpals = makePart('Carpals', 0.347, 0, [0.03, 0, 0]);
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 4; c++) {
      const s = 0.0072 * (0.9 + 0.1 * ((r * 4 + c) % 3));
      addSphere(carpals, s, s, s, (r - 0.5) * 0.015, 0, (c - 1.5) * 0.0125);
    }
  }

  // ---------- Metacarpals and Phalanges ----------
  const META_CX = 0.40;
  const PHAL_CX = 0.46;
  const metacarpals = makePart('Metacarpals', META_CX, 0, [0.06, 0, 0]);
  const phalanges = makePart('Phalanges', PHAL_CX, 0, [0.09, 0, 0]);

  const metaLens = [0.040, 0.043, 0.046, 0.043, 0.030];
  const phalLens = [
    [0.012, 0.007, 0.007], // little
    [0.022, 0.012, 0.010], // ring
    [0.025, 0.014, 0.010], // middle
    [0.022, 0.012, 0.010], // index
    [0.020, 0.012],        // thumb (2 phalanges)
  ];
  const phalR = [0.0045, 0.004, 0.0036];
  for (let i = 0; i < 5; i++) {
    const thumb = i === 4;
    const a = thumb ? 0.5 : (i - 2) * 0.07;
    const x0 = thumb ? 0.366 : 0.372;
    const z0 = thumb ? 0.026 : (i - 2) * 0.0115;
    const ca = Math.cos(a);
    const sa = Math.sin(a);
    const mr = 0.0045;
    const mTotal = metaLens[i] + 2 * mr;
    addCapsule(metacarpals, mr, metaLens[i],
      x0 + ca * mTotal / 2 - META_CX, 0, z0 + sa * mTotal / 2, a);
    let dist = mTotal + 0.003;
    for (let k = 0; k < phalLens[i].length; k++) {
      const r = phalR[k];
      const tot = phalLens[i][k] + 2 * r;
      const cd = dist + tot / 2;
      addCapsule(phalanges, r, phalLens[i][k],
        x0 + ca * cd - PHAL_CX, 0, z0 + sa * cd, a);
      dist += tot + 0.003;
    }
  }

  // ---------- bone info ----------
  const info = {
    Humerus: ['Upper arm', 'The longest bone of the arm. It links the shoulder to the elbow and anchors the muscles that lift and bend the arm.'],
    Ulna: ['Forearm, pinky side', 'Its top end, the olecranon, forms the point of your elbow. It is the main hinge of the elbow joint.'],
    Radius: ['Forearm, thumb side', 'It rotates around the ulna so you can turn your palm up or down. Its wide end forms most of the wrist joint.'],
    Carpals: ['Wrist', 'Eight small bones in two rows of four. They let the hand bend and tilt in many directions.'],
    Metacarpals: ['Palm of the hand', 'Five long bones in the palm. Each one connects a wrist bone to a finger or the thumb.'],
    Phalanges: ['Fingers', 'The finger bones: 14 in each hand. Each finger has 3, the thumb has 2. They let you grip and pinch.'],
  };

  const infoPanel = ui(`
    <style>
      .card { display: flex; width: 520px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 20px; padding-right: 20px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .tag { color: #7fc4ff; font-size: 24px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .btn { display: flex; width: 236px; padding-top: 12px; padding-bottom: 12px; padding-left: 8px; padding-right: 8px;
             border-radius: 14px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn2 { display: flex; width: 236px; padding-top: 12px; padding-bottom: 12px; padding-left: 8px; padding-right: 8px;
              border-radius: 14px; background-color: #3a4552; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="title">Arm bones</span>
      <span class="tag" id="tag">Tap a bone to learn about it</span>
      <span class="body" id="body">Pinch a bone to pull it out of place. Press Reassemble to snap everything back.</span>
      <div class="row">
        <button class="btn2" id="spread"><span class="btn-text">Pull apart</span></button>
        <button class="btn" id="assemble"><span class="btn-text">Reassemble</span></button>
      </div>
    </div>`, { width: 0.32, position: [-0.19, 0.33, -0.12] });
  root.add(infoPanel.object3D);

  // ---------- quiz ----------
  const questions = [
    { hl: 'Humerus', q: 'The glowing bone is in the upper arm. What is it called?',
      opts: ['Radius', 'Humerus', 'Ulna'], correct: 1,
      expl: 'The humerus runs from shoulder to elbow.' },
    { hl: null, q: 'Which forearm bone is on the thumb side?',
      opts: ['Ulna', 'Humerus', 'Radius'], correct: 2,
      expl: 'The radius is on the thumb side of the forearm.' },
    { hl: 'Ulna', q: 'Name the glowing forearm bone that forms the point of the elbow.',
      opts: ['Ulna', 'Radius', 'Humerus'], correct: 0,
      expl: "The ulna's top end, the olecranon, is your elbow point." },
    { hl: 'Carpals', q: 'How many carpal bones are in the glowing wrist?',
      opts: ['5', '8', '14'], correct: 1,
      expl: 'Eight carpals sit in two rows of four.' },
    { hl: 'Phalanges', q: 'What are the glowing finger bones called?',
      opts: ['Phalanges', 'Metacarpals', 'Carpals'], correct: 0,
      expl: 'Each hand has 14 phalanges: 3 per finger, 2 in the thumb.' },
  ];

  const quiz = ui(`
    <style>
      .qcard { display: flex; width: 520px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
               padding-left: 20px; padding-right: 20px; border-radius: 20px; background-color: #1f2228; }
      .qhead { color: #ffcf6b; font-size: 24px; font-weight: 700; }
      .qtext { color: #ffffff; font-size: 24px; font-weight: 700; }
      .ans { display: flex; width: 480px; flex-direction: row; align-items: center; padding-top: 10px; padding-bottom: 10px;
             padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #343a44; }
      .ans-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .fb { color: #aab4c2; font-size: 22px; }
      .next { display: flex; width: 480px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
              padding-left: 14px; padding-right: 14px; border-radius: 14px; background-color: #2f6fdb; }
    </style>
    <div class="qcard">
      <span class="qhead" id="qhead">Question 1 of 5  |  Score 0</span>
      <span class="qtext" id="qtext">Question</span>
      <button class="ans" id="a0"><span class="ans-text" id="t0">A</span></button>
      <button class="ans" id="a1"><span class="ans-text" id="t1">B</span></button>
      <button class="ans" id="a2"><span class="ans-text" id="t2">C</span></button>
      <span class="fb" id="fb">Choose an answer.</span>
      <button class="next" id="next"><span class="ans-text" id="ntext">Next question</span></button>
    </div>`, { width: 0.32, position: [0.19, 0.33, -0.12] });
  root.add(quiz.object3D);

  let qi = 0;
  let score = 0;
  let answered = false;
  let finished = false;
  let hlName = null;
  let selectedName = null;
  const ansIds = ['a0', 'a1', 'a2'];
  const txtIds = ['t0', 't1', 't2'];

  function showQuestion() {
    const q = questions[qi];
    answered = false;
    quiz.set('qhead', { text: 'Question ' + (qi + 1) + ' of 5  |  Score ' + score });
    quiz.set('qtext', { text: q.q });
    for (let i = 0; i < 3; i++) {
      quiz.set(txtIds[i], { text: q.opts[i] });
      quiz.set(ansIds[i], { backgroundColor: '#343a44', display: 'flex' });
    }
    quiz.set('fb', { text: 'Choose an answer.', color: '#aab4c2' });
    quiz.set('next', { display: 'none' });
    hlName = q.hl;
  }

  function answer(idx) {
    if (answered || finished) return;
    answered = true;
    const q = questions[qi];
    const ok = idx === q.correct;
    if (ok) score++;
    quiz.set(ansIds[q.correct], { backgroundColor: '#2e8b57' });
    if (!ok) quiz.set(ansIds[idx], { backgroundColor: '#b5453a' });
    quiz.set('fb', {
      text: (ok ? 'Correct! ' : 'Not quite. ') + q.expl,
      color: ok ? '#7be08f' : '#ff9a8f',
    });
    quiz.set('qhead', { text: 'Question ' + (qi + 1) + ' of 5  |  Score ' + score });
    quiz.set('ntext', { text: qi === 4 ? 'See my score' : 'Next question' });
    quiz.set('next', { display: 'flex' });
  }

  ansIds.forEach((id, i) => quiz.on(id, 'click', () => answer(i)));

  quiz.on('next', 'click', () => {
    if (finished) {
      qi = 0; score = 0; finished = false;
      showQuestion();
      return;
    }
    if (!answered) return;
    if (qi === 4) {
      finished = true;
      hlName = null;
      for (let i = 0; i < 3; i++) quiz.set(ansIds[i], { display: 'none' });
      quiz.set('qhead', { text: 'Quiz complete' });
      quiz.set('qtext', { text: 'You scored ' + score + ' out of 5.' });
      let msg = 'Keep exploring: tap each bone, then try again.';
      if (score === 5) msg = 'Perfect! You know your arm bones.';
      else if (score >= 3) msg = 'Nice work! Tap the bones to review, then retry.';
      quiz.set('fb', { text: msg, color: score >= 3 ? '#7be08f' : '#ffcf6b' });
      quiz.set('ntext', { text: 'Try again' });
      return;
    }
    qi++;
    showQuestion();
  });

  showQuestion();

  // ---------- interactions ----------
  function select(part) {
    selectedName = part.name;
    infoPanel.set('title', { text: part.name });
    infoPanel.set('tag', { text: info[part.name][0] });
    infoPanel.set('body', { text: info[part.name][1] });
  }

  parts.forEach((p) => {
    traits(p.group, { grab: true, onPress: () => select(p) });
  });

  let moving = false;
  infoPanel.on('assemble', 'click', () => {
    parts.forEach((p) => { p.target = p.home; });
    moving = true;
  });
  infoPanel.on('spread', 'click', () => {
    parts.forEach((p) => { p.target = p.spread; });
    moving = true;
  });

  const IDENT = new THREE.Quaternion();

  return {
    root,
    update(time, delta) {
      if (moving) {
        const k = 1 - Math.exp(-3 * delta);
        let any = false;
        for (let i = 0; i < parts.length; i++) {
          const p = parts[i];
          const g = p.group;
          if (isGrabbed(g)) continue;
          g.position.lerp(p.target, k);
          g.quaternion.slerp(IDENT, k);
          if (g.position.distanceToSquared(p.target) > 1e-6 || g.quaternion.angleTo(IDENT) > 0.02) {
            any = true;
          } else {
            g.position.copy(p.target);
            g.quaternion.identity();
          }
        }
        moving = any;
      }
      for (let i = 0; i < parts.length; i++) {
        const p = parts[i];
        if (p.name === hlName) {
          p.mat.emissive.setHex(0x2f8cff);
          p.mat.emissiveIntensity = 0.45 + 0.3 * Math.sin(time * 4);
        } else if (p.name === selectedName) {
          p.mat.emissive.setHex(0xff9a1f);
          p.mat.emissiveIntensity = 0.35;
        } else {
          p.mat.emissiveIntensity = 0;
        }
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Layout constants ----------
  const COL_X = [-0.3, -0.1, 0.1, 0.3];
  const BOARD_Z = -0.1;
  const TOP_Y = 0.405;
  const PITCH = 0.068;
  const COLS = [
    { name: 'To do', color: '#4b5563', slab: 0x2b3038 },
    { name: 'In progress', color: '#2563eb', slab: 0x232c3d },
    { name: 'Review', color: '#9333ea', slab: 0x2f2640 },
    { name: 'Done', color: '#16a34a', slab: 0x20332a },
  ];
  const PRIO_COLOR = { high: '#ef4444', medium: '#f59e0b', low: '#22c55e' };

  // Sprint data (story points total 26)
  const TASKS = [
    { title: 'Login page', prio: 'high', pts: 5, start: 1 },
    { title: 'Checkout bug', prio: 'high', pts: 8, start: 2 },
    { title: 'API tests', prio: 'medium', pts: 3, start: 1 },
    { title: 'DB backup', prio: 'medium', pts: 5, start: 0 },
    { title: 'Dark mode', prio: 'low', pts: 3, start: 0 },
    { title: 'Update docs', prio: 'low', pts: 2, start: 0 },
  ];
  const TOTAL = TASKS.reduce((s, t) => s + t.pts, 0);
  const DAYS = 5; // days 0..5

  // ---------- Column backdrops ----------
  const slabGeo = new THREE.BoxGeometry(0.186, 0.43, 0.006);
  COLS.forEach((c, i) => {
    const m = new THREE.Mesh(slabGeo, new THREE.MeshStandardMaterial({ color: c.slab, roughness: 0.9 }));
    m.name = 'Column ' + c.name;
    m.position.set(COL_X[i], 0.235, BOARD_Z - 0.006);
    root.add(m);
  });

  // ---------- Column headers ----------
  const headers = COLS.map((c, i) => {
    const h = ui(`
      <style>
        .h { width: 300px; flex-direction: row; justify-content: space-between; align-items: center;
             padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: ${c.color}; }
        .t { color: #ffffff; font-size: 26px; font-weight: 700; }
        .n { color: #ffffff; font-size: 26px; font-weight: 700; }
      </style>
      <div class="h"><span class="t">${c.name}</span><span class="n" id="n">0</span></div>`,
      { width: 0.175, position: [COL_X[i], 0.475, BOARD_Z] });
    root.add(h.object3D);
    return h;
  });

  // ---------- Task cards ----------
  const cols = [[], [], [], []];
  const cards = TASKS.map((d) => {
    const col = PRIO_COLOR[d.prio];
    const h = ui(`
      <style>
        .card { width: 300px; flex-direction: column; background-color: #262a31; border-radius: 14px; }
        .bar { width: 300px; height: 8px; background-color: ${col}; border-radius: 4px; }
        .body { flex-direction: column; gap: 4px; padding-top: 6px; padding-bottom: 8px;
                padding-left: 10px; padding-right: 10px; }
        .top { flex-direction: row; justify-content: space-between; align-items: center; }
        .title { color: #ffffff; font-size: 22px; font-weight: 700; }
        .pts { color: #aab2bd; font-size: 22px; }
        .row { flex-direction: row; justify-content: space-between; align-items: center; }
        .arrow { width: 84px; height: 52px; border-radius: 10px; background-color: #3b82f6;
                 align-items: center; justify-content: center; }
        .at { color: #ffffff; font-size: 22px; font-weight: 700; }
        .prio { color: ${col}; font-size: 22px; font-weight: 700; }
      </style>
      <div class="card">
        <div class="bar"></div>
        <div class="body">
          <div class="top">
            <span class="title" id="title">${d.title}</span>
            <span class="pts">${d.pts} pts</span>
          </div>
          <div class="row">
            <button class="arrow" id="lt"><span class="at" id="ltt">Back</span></button>
            <span class="prio">${d.prio.toUpperCase()}</span>
            <button class="arrow" id="rt"><span class="at" id="rtt">Next</span></button>
          </div>
        </div>
      </div>`, { width: 0.175, position: [0, 0.2, BOARD_Z] });
    h.object3D.name = 'Card ' + d.title;
    root.add(h.object3D);
    const card = { d, h, col: d.start, tx: 0, ty: 0, show: true };
    h.on('lt', 'click', () => moveCard(card, -1));
    h.on('rt', 'click', () => moveCard(card, 1));
    return card;
  });

  // ---------- Burndown chart (3D) ----------
  const H = 0.12;
  const BASE_Y = 0.006;
  const chart = new THREE.Group();
  chart.name = 'Burndown chart';
  chart.position.set(-0.17, 0, 0.14);
  root.add(chart);

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.32, 0.006, 0.07),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.8 }),
  );
  base.position.set(0, 0.003, 0);
  chart.add(base);

  const backdrop = new THREE.Mesh(
    new THREE.BoxGeometry(0.31, H + 0.01, 0.004),
    new THREE.MeshStandardMaterial({ color: 0x20252c, roughness: 0.9 }),
  );
  backdrop.position.set(0, BASE_Y + (H + 0.01) / 2, -0.022);
  chart.add(backdrop);

  const gridPts = [];
  for (let k = 1; k <= 4; k++) {
    const y = BASE_Y + (H * k) / 4;
    gridPts.push(new THREE.Vector3(-0.15, y, -0.019), new THREE.Vector3(0.15, y, -0.019));
  }
  const grid = new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(gridPts),
    new THREE.LineBasicMaterial({ color: 0x4a5260 }),
  );
  chart.add(grid);

  const barGeo = new THREE.BoxGeometry(0.03, 1, 0.03);
  barGeo.translate(0, 0.5, 0);
  const matOk = new THREE.MeshStandardMaterial({ color: 0x3ddc97, roughness: 0.5 });
  const matLate = new THREE.MeshStandardMaterial({ color: 0xffb020, roughness: 0.5 });
  const bars = [];
  const idealOf = (i) => TOTAL * (1 - i / DAYS);
  const idealPts = [];
  const markerGeo = new THREE.SphereGeometry(0.006, 16, 8);
  const markerMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
  for (let i = 0; i <= DAYS; i++) {
    const x = -0.125 + i * 0.05;
    const bar = new THREE.Mesh(barGeo, matOk);
    bar.name = 'Burndown bar D' + i;
    bar.position.set(x, BASE_Y, 0);
    chart.add(bar);
    bars.push(bar);
    const y = BASE_Y + (H * idealOf(i)) / TOTAL;
    idealPts.push(new THREE.Vector3(x, y, 0.02));
    const mk = new THREE.Mesh(markerGeo, markerMat);
    mk.position.set(x, y, 0.02);
    chart.add(mk);
  }
  const idealLine = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(idealPts),
    new THREE.LineBasicMaterial({ color: 0xffffff }),
  );
  idealLine.name = 'Ideal burndown';
  chart.add(idealLine);

  // Day labels under the chart (in front of it, on the desk)
  const dayLabels = ui(`
    <style>
      .row { width: 360px; flex-direction: row; justify-content: space-between;
             background-color: #1a1d22; border-radius: 10px; }
      .cell { width: 60px; align-items: center; justify-content: center;
              padding-top: 4px; padding-bottom: 4px; }
      .lab { color: #6b7380; font-size: 24px; font-weight: 700; }
    </style>
    <div class="row">
      <div class="cell"><span class="lab" id="d0">D0</span></div>
      <div class="cell"><span class="lab" id="d1">D1</span></div>
      <div class="cell"><span class="lab" id="d2">D2</span></div>
      <div class="cell"><span class="lab" id="d3">D3</span></div>
      <div class="cell"><span class="lab" id="d4">D4</span></div>
      <div class="cell"><span class="lab" id="d5">D5</span></div>
    </div>`, { width: 0.3, position: [-0.17, 0.022, 0.21] });
  root.add(dayLabels.object3D);

  // ---------- Info / controls panel ----------
  const info = ui(`
    <style>
      .p { width: 440px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
           padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .line { color: #d7dbe2; font-size: 24px; }
      .small { color: #aab2bd; font-size: 22px; }
      .btns { flex-direction: row; gap: 10px; }
      .b1 { width: 150px; height: 52px; border-radius: 12px; background-color: #3b82f6;
            align-items: center; justify-content: center; }
      .b2 { width: 130px; height: 52px; border-radius: 12px; background-color: #3b82f6;
            align-items: center; justify-content: center; }
      .b3 { width: 90px; height: 52px; border-radius: 12px; background-color: #4b5563;
            align-items: center; justify-content: center; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="p">
      <span class="title">Sprint burndown</span>
      <span class="line" id="l1">Day 0/5 - Done 0/6</span>
      <span class="line" id="l2">Points left: 26 of 26</span>
      <span class="small">Bars: points left. Line: ideal.</span>
      <div class="btns">
        <button class="b1" id="flt"><span class="bt" id="fltt">Show: All</span></button>
        <button class="b2" id="nxt"><span class="bt" id="nxtt">Next day</span></button>
        <button class="b3" id="rst"><span class="bt">Reset</span></button>
      </div>
    </div>`, { width: 0.3, position: [0.2, 0.1, 0.14] });
  root.add(info.object3D);

  // ---------- State ----------
  let highOnly = false;
  let day = 0;
  const hist = [0, 0, 0, 0, 0, 0];

  function resetColumns() {
    for (let c = 0; c < 4; c++) cols[c].length = 0;
    cards.forEach((card) => {
      card.col = card.d.start;
      cols[card.col].push(card);
    });
  }

  function remaining() {
    let r = 0;
    for (let i = 0; i < cards.length; i++) if (cards[i].col !== 3) r += cards[i].d.pts;
    return r;
  }

  function moveCard(card, dir) {
    const to = card.col + dir;
    if (to < 0 || to > 3) return;
    const idx = cols[card.col].indexOf(card);
    if (idx >= 0) cols[card.col].splice(idx, 1);
    cols[to].push(card);
    card.col = to;
    refresh(false);
  }

  function refresh(snap) {
    // layout cards
    for (let c = 0; c < 4; c++) {
      let slot = 0;
      for (const card of cols[c]) {
        const show = !highOnly || card.d.prio === 'high';
        card.show = show;
        card.h.object3D.visible = show;
        if (show) {
          card.tx = COL_X[c];
          card.ty = TOP_Y - slot * PITCH;
          slot++;
          if (snap) card.h.object3D.position.set(card.tx, card.ty, BOARD_Z);
        }
        // arrow button states and done styling
        card.h.set('lt', { backgroundColor: c === 0 ? '#3a3f47' : '#3b82f6' });
        card.h.set('ltt', { color: c === 0 ? '#7b838f' : '#ffffff' });
        card.h.set('rt', { backgroundColor: c === 3 ? '#3a3f47' : '#3b82f6' });
        card.h.set('rtt', { color: c === 3 ? '#7b838f' : '#ffffff' });
        card.h.set('title', { color: c === 3 ? '#7ee2a8' : '#ffffff' });
      }
      headers[c].set('n', { text: highOnly ? slot + '/' + cols[c].length : String(slot) });
    }

    // status + chart
    const rem = remaining();
    info.set('l1', { text: 'Day ' + day + '/5 - Done ' + cols[3].length + '/6' });
    info.set('l2', { text: 'Points left: ' + rem + ' of ' + TOTAL });
    info.set('nxt', { backgroundColor: day >= DAYS ? '#3a3f47' : '#3b82f6' });
    for (let i = 0; i <= DAYS; i++) {
      const bar = bars[i];
      if (i > day) { bar.visible = false; continue; }
      const v = i < day ? hist[i] : rem;
      bar.visible = true;
      bar.scale.y = Math.max(0.002, (v / TOTAL) * H);
      bar.material = v <= idealOf(i) + 1e-6 ? matOk : matLate;
    }
    for (let i = 0; i <= DAYS; i++) {
      dayLabels.set('d' + i, { color: i === day ? '#ffd166' : i < day ? '#d7dbe2' : '#6b7380' });
    }
  }

  info.on('flt', 'click', () => {
    highOnly = !highOnly;
    info.set('fltt', { text: highOnly ? 'Show: High' : 'Show: All' });
    info.set('flt', { backgroundColor: highOnly ? '#ef4444' : '#3b82f6' });
    refresh(false);
  });

  info.on('nxt', 'click', () => {
    if (day >= DAYS) return;
    hist[day] = remaining();
    day++;
    refresh(false);
  });

  info.on('rst', 'click', () => {
    day = 0;
    hist.fill(0);
    resetColumns();
    refresh(false);
  });

  resetColumns();
  refresh(true);

  // ---------- Animation: cards glide to their slots ----------
  return {
    root,
    update(time, delta) {
      const k = 1 - Math.exp(-delta * 9);
      for (let i = 0; i < cards.length; i++) {
        const card = cards[i];
        if (!card.show) continue;
        const p = card.h.object3D.position;
        p.x += (card.tx - p.x) * k;
        p.y += (card.ty - p.y) * k;
        const dx = card.tx - p.x;
        const dy = card.ty - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        p.z = BOARD_Z + Math.min(0.03, dist * 1.0); // lift while travelling so cards never overlap
      }
    },
  };
}

