          <button class="edit" id="e1"><span class="btn-text">Edit</span></button>
        </div>
        <div class="row">
          <div class="rowcol"><span class="rowlabel">T-shirt size</span><span class="rowvalue" id="rvSize">-</span></div>
          <button class="edit" id="e2"><span class="btn-text">Edit</span></button>
