  }

  function workCount() {
    let n = 0;
    for (let i = 0; i < state.work.length; i++) if (state.work[i]) n++;
    return n;
  }

  function refreshTickets() {
    tickets.forEach((t, i) => {
      const on = state.ticket === i;
      panel.set('t' + i, { backgroundColor: on ? BLUE : OPT });
      panel.set('r' + i, { backgroundColor: on ? '#ffffff' : '#1a1d22' });
    });
    badgeMat.color.setHex(state.ticket >= 0 ? tickets[state.ticket].color : 0x555b66);
  }

  function refreshWork() {
    for (let i = 0; i < workshops.length; i++) {
      const on = state.work[i];
      panel.set('w' + i, { backgroundColor: on ? '#27456e' : OPT });
      panel.set('wb' + i, { backgroundColor: on ? BLUE : '#1a1d22' });
      panel.set('wc' + i, { color: on ? '#ffffff' : '#1a1d22' });
    }
    panel.set('count', { text: 'Selected: ' + workCount() + ' of 2', color: '#d7dbe2' });
  }

  function refreshSize() {
    panel.set('sizeText', { text: sizes[state.size] });
    panel.set('sizeHint', { text: 'Size ' + (state.size + 1) + ' of 6 (XS to XXL)' });
    shirtTarget = sizeScale[state.size];
  }

  function refreshReview() {
    const t = state.ticket >= 0 ? tickets[state.ticket] : null;
    panel.set('rvTicket', { text: t ? t.name + ' ($' + t.price + ')' : 'Not chosen' });
    const names = [];
    for (let i = 0; i < workshops.length; i++) if (state.work[i]) names.push(workshops[i]);
    panel.set('rvWork', { text: names.length ? names.join(', ') : 'None selected' });
    panel.set('rvSize', { text: sizes[state.size] });
    panel.set('rvTotal', { text: 'Total: $' + (t ? t.price : 0) + ' (workshops included)' });
  }

  const views = ['t', 'w', 's', 'r', 'd'];
  const titles = {
    t: 'Choose your ticket',
    w: 'Pick up to 2 workshops',
    s: 'Choose a t-shirt size',
    r: 'Review your registration',
    d: 'You are registered!',
  };
  const subs = {
    t: 'Step 1 of 3',
    w: 'Step 2 of 3 (optional)',
    s: 'Step 3 of 3',
    r: 'Check everything, then confirm',
    d: 'See you at the conference',
  };

  function showView(v) {
    state.view = v;
    views.forEach((id) => panel.set('view_' + id, { display: id === v ? 'flex' : 'none' }));
    panel.set('title', { text: titles[v] });
    panel.set('step', { text: subs[v] });
    const idx = v === 't' ? 0 : v === 'w' ? 1 : v === 's' ? 2 : 3;
    for (let i = 0; i < 3; i++) {
      panel.set('p' + i, { backgroundColor: i < idx ? GREEN : i === idx ? BLUE : GRAY });
    }
    const showNav = v === 't' || v === 'w' || v === 's';
    panel.set('nav', { display: showNav ? 'flex' : 'none' });
    panel.set('back', { display: v !== 't' && !state.fromReview ? 'flex' : 'none' });
    let label = 'Next';
    if (state.fromReview) label = 'Save and review';
    else if (v === 's') label = 'Review';
    panel.set('nextLabel', { text: label });
    if (v === 'r') refreshReview();
    if (v === 'd') {
      const t = tickets[state.ticket];
      panel.set('doneText', {
        text: 'Thank you! ' + t.name + ' ticket, t-shirt size ' + sizes[state.size] + '.',
      });
    }
    msg(' ', false);
  }

  function goReview() {
    state.fromReview = false;
    showView('r');
  }

  // ---------- Interactions ----------
  tickets.forEach((t, i) => {
    panel.on('t' + i, 'click', () => {
      state.ticket = i;
      refreshTickets();
      msg(t.name + ' ticket selected.', false);
    });
  });

  workshops.forEach((w, i) => {
    panel.on('w' + i, 'click', () => {
      if (state.work[i]) {
        state.work[i] = false;
        refreshWork();
        msg(' ', false);
      } else if (workCount() >= 2) {
        refreshWork();
        panel.set('count', { text: 'Selected: 2 of 2 (limit reached)', color: '#ff8a80' });
        msg('Too many workshops! You can pick only 2. Uncheck one first.', true);
      } else {
        state.work[i] = true;
        refreshWork();
        msg(' ', false);
      }
    });
  });

  panel.on('minus', 'click', () => {
    if (state.size > 0) {
      state.size--;
      refreshSize();
      msg(' ', false);
    } else {
      msg('XS is the smallest size.', true);
    }
  });
  panel.on('plus', 'click', () => {
    if (state.size < sizes.length - 1) {
      state.size++;
      refreshSize();
      msg(' ', false);
    } else {
      msg('XXL is the largest size.', true);
    }
  });

  panel.on('next', 'click', () => {
    if (state.view === 't') {
      if (state.ticket < 0) {
        msg('Please choose a ticket type to continue.', true);
        return;
      }
      if (state.fromReview) goReview();
      else showView('w');
    } else if (state.view === 'w') {
      if (state.fromReview) goReview();
      else showView('s');
    } else if (state.view === 's') {
      goReview();
    }
  });

  panel.on('back', 'click', () => {
    if (state.view === 'w') showView('t');
    else if (state.view === 's') showView('w');
  });

  panel.on('e0', 'click', () => { state.fromReview = true; showView('t'); });
  panel.on('e1', 'click', () => { state.fromReview = true; showView('w'); });
  panel.on('e2', 'click', () => { state.fromReview = true; showView('s'); });

  panel.on('confirm', 'click', () => {
    if (state.ticket < 0) {
      msg('Please choose a ticket first (press Edit on Ticket).', true);
      return;
    }
    showView('d');
  });

  panel.on('again', 'click', () => {
    state.ticket = -1;
    state.work = [false, false, false, false];
    state.size = 2;
    state.fromReview = false;
    refreshTickets();
    refreshWork();
    refreshSize();
    showView('t');
  });

  // ---------- Initial state ----------
  refreshTickets();
  refreshWork();
  refreshSize();
  showView('t');

  return {
    root,
    update(time, delta) {
      if (!isGrabbed(badge)) badge.rotation.y = Math.sin(time * 0.6) * 0.25;
      const k = Math.min(1, delta * 6);
      shirtScale += (shirtTarget - shirtScale) * k;
      shirt.scale.setScalar(shirtScale);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Data (USD per month, Jan-Jun) ----------
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'];
  const cats = [
    { name: 'Housing',   col: '#6aa5ff', data: [1200, 1200, 1200, 1200, 1200, 1200] },
    { name: 'Food',      col: '#ffb454', data: [420, 460, 440, 480, 450, 470] },
    { name: 'Transport', col: '#4fd1a5', data: [200, 180, 240, 210, 220, 260] },
    { name: 'Fun',       col: '#ff6f91', data: [150, 220, 170, 260, 180, 210] },
    { name: 'Utilities', col: '#c792ea', data: [170, 190, 150, 140, 160, 150] },
    { name: 'Other',     col: '#e6e86a', data: [100, 140, 90, 160, 130, 120] },
  ];
  const totals = months.map((_, m) => cats.reduce((s, c) => s + c.data[m], 0));
  const cur = cats.map((c) => c.data[5]);
  const curTotal = totals[5];

  let selected = -1;

  // ---------- Donut chart (June spending by category) ----------
  const DC = { x: -0.28, y: 0.30 };
  const R = 0.095, r = 0.058, gap = 0.03;
  const segs = [];
  const baseColors = [];
  let cum = 0;
  cats.forEach((c, i) => {
    const f = cur[i] / curTotal;
    const hi = Math.PI / 2 - cum * 2 * Math.PI - gap / 2;
    const lo = Math.PI / 2 - (cum + f) * 2 * Math.PI + gap / 2;
    cum += f;
    const shape = new THREE.Shape();
    shape.moveTo(Math.cos(lo) * R, Math.sin(lo) * R);
    shape.absarc(0, 0, R, lo, hi, false);
    shape.lineTo(Math.cos(hi) * r, Math.sin(hi) * r);
    shape.absarc(0, 0, r, hi, lo, true);
    shape.closePath();
    const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.016, bevelEnabled: false, curveSegments: 24 });
    geo.translate(0, 0, -0.008);
    const base = new THREE.Color(c.col);
    baseColors.push(base);
    const mat = new THREE.MeshStandardMaterial({
      color: base.clone(), roughness: 0.5, metalness: 0.1,
      emissive: base.clone(), emissiveIntensity: 0.0,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.name = 'Slice-' + c.name;
    mesh.position.set(DC.x, DC.y, 0);
    const mid = (lo + hi) / 2;
    mesh.userData = { bx: DC.x, by: DC.y, dx: Math.cos(mid), dy: Math.sin(mid), pop: 0 };
    root.add(mesh);
    traits(mesh, { onPress: () => select(i) });
    segs.push(mesh);
  });

  // ---------- Bar chart (last six months) ----------
  const CH = { cx: 0, base: 0.17, maxH: 0.21, spacing: 0.045 };
  const plate = new THREE.Mesh(
    new THREE.BoxGeometry(0.28, 0.26, 0.01),
    new THREE.MeshStandardMaterial({ color: 0x1c2026, roughness: 0.8 }),
  );
  plate.name = 'ChartPlate';
  plate.position.set(CH.cx, 0.28, -0.025);
  root.add(plate);

  const baseline = new THREE.Mesh(
    new THREE.BoxGeometry(0.27, 0.003, 0.02),
    new THREE.MeshStandardMaterial({ color: 0x8a919c, roughness: 0.6 }),
  );
  baseline.position.set(CH.cx, CH.base - 0.0015, 0);
  root.add(baseline);

  const ALLCOL = new THREE.Color('#cfd6e0');
  const barMat = new THREE.MeshStandardMaterial({ color: ALLCOL.clone(), roughness: 0.45, metalness: 0.05 });
  const targetColor = ALLCOL.clone();
  const barGeo = new THREE.BoxGeometry(0.032, 1, 0.03);
  barGeo.translate(0, 0.5, 0);
  const bars = [];
  const barTarget = [];
  for (let m = 0; m < 6; m++) {
    const b = new THREE.Mesh(barGeo, barMat);
    b.name = 'Bar-' + months[m];
    b.position.set(CH.cx + (m - 2.5) * CH.spacing, CH.base, 0);
    b.scale.y = 0.002;
    root.add(b);
    bars.push(b);
    barTarget.push(0.002);
  }

  // ---------- Savings ring ----------
  const RC = { x: 0.28, y: 0.31 };
  const ringR = 0.058;
  const N = 60;
  const goal = 3000, startSaved = 1650, step = 150;
  let saved = startSaved;
  let shown = 0;
  let lastFilled = -1;
  const TRACK = new THREE.Color('#3a3f47');
  const FILL = new THREE.Color('#3ddc84');
  const GOLD = new THREE.Color('#ffd24a');

  const ring = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.016, 0.0057, 0.012),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 }),
    N,
  );
  ring.name = 'SavingsRing';
  const dummy = new THREE.Object3D();
  for (let i = 0; i < N; i++) {
    const th = Math.PI / 2 - ((i + 0.5) / N) * Math.PI * 2;
    dummy.position.set(RC.x + Math.cos(th) * ringR, RC.y + Math.sin(th) * ringR, 0);
    dummy.rotation.set(0, 0, th);
    dummy.updateMatrix();
    ring.setMatrixAt(i, dummy.matrix);
    ring.setColorAt(i, TRACK);
  }
  ring.instanceMatrix.needsUpdate = true;
  root.add(ring);

  function paintRing(filled) {
    const c = filled >= N ? GOLD : FILL;
    for (let i = 0; i < N; i++) ring.setColorAt(i, i < filled ? c : TRACK);
    ring.instanceColor.needsUpdate = true;
  }

  // Coin in the ring's hole
  const coinPivot = new THREE.Group();
  coinPivot.position.set(RC.x, RC.y, 0);
  root.add(coinPivot);
  const coin = new THREE.Mesh(
    new THREE.CylinderGeometry(0.026, 0.026, 0.006, 32),
    new THREE.MeshStandardMaterial({ color: 0xffc83d, metalness: 0.3, roughness: 0.35, emissive: 0x553300, emissiveIntensity: 0.4 }),
  );
  coin.name = 'Coin';
  coin.rotation.x = Math.PI / 2;
  coinPivot.add(coin);
  const coinFace = new THREE.Mesh(
    new THREE.CylinderGeometry(0.018, 0.018, 0.0075, 32),
    new THREE.MeshStandardMaterial({ color: 0xe0a31f, metalness: 0.3, roughness: 0.45, emissive: 0x442800, emissiveIntensity: 0.4 }),
  );
  coinFace.rotation.x = Math.PI / 2;
  coinPivot.add(coinFace);
  let spin = 0.6;

  // ---------- UI panels ----------
  const titleCss = `
    <style>
      .t { width: 380px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
           padding-left: 10px; padding-right: 10px; border-radius: 14px; background-color: #1f2228; }
      .tt { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
    </style>`;
  const titleLeft = ui(`${titleCss}<div class="t"><span class="tt">June spending: $${curTotal}</span></div>`,
    { width: 0.235, position: [DC.x, 0.445, 0] });
  root.add(titleLeft.object3D);

  const titleRight = ui(`${titleCss}<div class="t"><span class="tt">Savings goal: Trip fund</span></div>`,
    { width: 0.235, position: [RC.x, 0.445, 0] });
  root.add(titleRight.object3D);

  const titleCenter = ui(`
    <style>
      .t { width: 396px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
           padding-left: 8px; padding-right: 8px; border-radius: 14px; background-color: #1f2228; }
      .tt { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
    </style>
    <div class="t"><span class="tt" id="ctitle">Last 6 months - All spending</span></div>`,
    { width: 0.27, position: [CH.cx, 0.445, 0] });
  root.add(titleCenter.object3D);

  // Month labels and values aligned under the bars (6 cells of 66px = 0.045 m each)
  const monthCells = months.map((m) => `<div class="cell"><span class="mon">${m}</span></div>`).join('');
  const valueCells = months.map((m, i) => `<div class="cell"><span class="val" id="v${i}">0</span></div>`).join('');
  const center = ui(`
    <style>
      .lp { width: 396px; flex-direction: column; gap: 4px; padding-top: 8px; padding-bottom: 8px;
            border-radius: 14px; background-color: #1f2228; }
      .lrow { flex-direction: row; }
      .cell { width: 66px; align-items: center; justify-content: center; }
      .mon { color: #aab2bf; font-size: 20px; }
      .val { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="lp">
      <div class="lrow">${monthCells}</div>
      <div class="lrow">${valueCells}</div>
    </div>`, { width: 0.27, position: [CH.cx, 0.112, 0.03] });
  root.add(center.object3D);

  // Category buttons + info
  const btnClasses = cats.map((c, i) => `.b${i} { background-color: ${c.col}; }`).join('\n');
  const mkBtn = (i) => `<button class="cbtn b${i}" id="c${i}"><span class="ctxt" id="t${i}">${cats[i].name}</span></button>`;
  const left = ui(`
    <style>
      .card { width: 380px; flex-direction: column; gap: 8px; padding-top: 10px; padding-bottom: 10px;
              padding-left: 10px; padding-right: 10px; border-radius: 16px; background-color: #1f2228; }
      .infobox { height: 84px; flex-direction: column; padding-left: 4px; padding-right: 4px; }
      .info { color: #e6e9ee; font-size: 21px; }
      .row { flex-direction: row; gap: 6px; }
      .cbtn { width: 112px; height: 40px; align-items: center; justify-content: center; border-radius: 10px; }
      .ctxt { color: #10131a; font-size: 20px; }
      ${btnClasses}
    </style>
    <div class="card">
      <div class="infobox"><span class="info" id="info">Tap a slice or a button to filter the bar chart.</span></div>
      <div class="row">${mkBtn(0)}${mkBtn(1)}${mkBtn(2)}</div>
      <div class="row">${mkBtn(3)}${mkBtn(4)}${mkBtn(5)}</div>
    </div>`, { width: 0.235, position: [DC.x, 0.095, 0.03] });
  root.add(left.object3D);

  const right = ui(`
    <style>
      .card { width: 380px; flex-direction: column; gap: 10px; padding-top: 10px; padding-bottom: 10px;
              padding-left: 10px; padding-right: 10px; border-radius: 16px; background-color: #1f2228; }
      .box { height: 110px; flex-direction: column; gap: 6px; padding-left: 4px; padding-right: 4px; }
      .big { color: #ffffff; font-size: 22px; font-weight: 700; }
      .note { color: #cdd3dc; font-size: 21px; }
      .gbtn { height: 50px; align-items: center; justify-content: center; border-radius: 12px; background-color: #3ddc84; }
      .gtxt { color: #0e1a12; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <div class="box">
        <span class="big" id="sav-text">$1650 of $3000 saved (55%)</span>
        <span class="note" id="sav-note">$1350 to go. Press the button to log a deposit.</span>
      </div>
      <button class="gbtn" id="dep"><span class="gtxt" id="dep-label">Log $150 deposit</span></button>
    </div>`, { width: 0.235, position: [RC.x, 0.095, 0.03] });
  root.add(right.object3D);

  // ---------- Behaviour ----------
  function refresh() {
    const series = selected < 0 ? totals : cats[selected].data;
    const mx = Math.max(...series);
    if (selected < 0) targetColor.copy(ALLCOL); else targetColor.copy(baseColors[selected]);
    for (let m = 0; m < 6; m++) {
      barTarget[m] = Math.max(0.004, (series[m] / (mx * 1.05)) * CH.maxH);
      center.set('v' + m, { text: String(series[m]) });
    }
    titleCenter.set('ctitle', {
      text: 'Last 6 months - ' + (selected < 0 ? 'All spending' : cats[selected].name),
    });

    for (let i = 0; i < cats.length; i++) {
      const active = selected < 0 || selected === i;
      left.set('c' + i, { backgroundColor: active ? cats[i].col : '#3a3f47' });
      left.set('t' + i, { color: active ? '#10131a' : '#8d94a0' });
      const mat = segs[i].material;
      if (active) mat.color.copy(baseColors[i]); else mat.color.copy(baseColors[i]).multiplyScalar(0.28);
      mat.emissive.copy(baseColors[i]);
      mat.emissiveIntensity = selected === i ? 0.3 : 0.0;
    }

    if (selected < 0) {
      left.set('info', { text: 'Tap a slice or a button to filter the bar chart.' });
    } else {
      const pct = Math.round((cur[selected] / curTotal) * 100);
      left.set('info', {
        text: cats[selected].name + ': $' + cur[selected] + ' in June (' + pct + '%). Tap again to show all.',
      });
    }
  }

  function select(i) {
    selected = selected === i ? -1 : i;
    refresh();
  }
  cats.forEach((c, i) => left.on('c' + i, 'click', () => select(i)));

  function refreshSavings(note) {
    const pct = Math.round((saved / goal) * 100);
    right.set('sav-text', { text: '$' + saved + ' of $' + goal + ' saved (' + pct + '%)' });
    right.set('sav-note', { text: note });
    right.set('dep-label', { text: saved >= goal ? 'Start over' : 'Log $' + step + ' deposit' });
  }

  right.on('dep', 'click', () => {
    if (saved >= goal) {
      saved = startSaved;
      refreshSavings('Restarted. $' + (goal - saved) + ' to go.');
    } else {
      saved = Math.min(goal, saved + step);
      spin = 14;
      if (saved >= goal) refreshSavings('Goal reached! Great job.');
      else refreshSavings('Deposit logged: +$' + step + '. $' + (goal - saved) + ' to go.');
    }
  });

  refresh();

  // ---------- Animation ----------
  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 8);

      for (let i = 0; i < segs.length; i++) {
        const s = segs[i];
        const u = s.userData;
        const target = selected === i ? 1 : 0;
        u.pop += (target - u.pop) * k;
        s.position.set(u.bx + u.dx * 0.008 * u.pop, u.by + u.dy * 0.008 * u.pop, 0.012 * u.pop);
      }

      for (let m = 0; m < 6; m++) {
        bars[m].scale.y += (barTarget[m] - bars[m].scale.y) * k;
      }
      barMat.color.lerp(targetColor, Math.min(1, delta * 6));

      shown += (saved / goal - shown) * Math.min(1, delta * 3);
      const filled = Math.round(shown * N);
      if (filled !== lastFilled) {
        lastFilled = filled;
        paintRing(filled);
      }

      spin += (0.6 - spin) * Math.min(1, delta * 1.5);
      coinPivot.rotation.y += spin * delta;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Map projection (real lon/lat -> table coordinates) ----------
  const S = 0.058;                 // meters of table per km of Paris
  const LON0 = 2.322, LAT0 = 48.869;
  const KM_LON = 73.3, KM_LAT = 111.2;   // km per degree at 48.9 N
  const MAP_CX = -0.22, MAP_CZ = 0.08;
  const MAPY = 0.0295;
  const mapX = (lon) => MAP_CX + (lon - LON0) * KM_LON * S;
  const mapZ = (lat) => MAP_CZ - (lat - LAT0) * KM_LAT * S;

  const LM = [
