    { name: 'Louvre', icon: 'louvre', lon: 2.3376, lat: 48.8606, meta: 'Visit time: about 3 h',
      text: "The world's most visited art museum and home of the Mona Lisa. Closed on Tuesdays." },
    { name: 'Notre-Dame', icon: 'notre', lon: 2.3499, lat: 48.8530, meta: 'Visit time: about 1 h',
      text: 'Gothic cathedral on the Ile de la Cite, begun in 1163. It reopened in December 2024 after the 2019 fire.' },
    { name: 'Arc de Triomphe', icon: 'arc', lon: 2.2950, lat: 48.8738, meta: 'Visit time: about 1 h',
      text: 'Ordered by Napoleon in 1806 and finished in 1836. Climb about 284 steps for a view down the Champs-Elysees.' },
    { name: 'Sacre-Coeur', icon: 'sacre', lon: 2.3431, lat: 48.8867, meta: 'Visit time: about 1.5 h',
      text: 'White basilica on Montmartre hill, built from 1875 to 1914. The steps and dome give a wide view of Paris.' },
    { name: "Musee d'Orsay", icon: 'orsay', lon: 2.3266, lat: 48.8600, meta: 'Visit time: about 2 h',
      text: 'Impressionist art inside a former railway station from 1900. Closed on Mondays.' },
  ];

  const DAY_HEX = [0x2f8bff, 0xff9a1f, 0x2ec27e];
  const DAY_TXT = ['#7db4ff', '#ffbf66', '#6fe0aa'];
  const NONE_HEX = 0xc9ccd3;

  // ---------- Table and map ----------
  const woodMat = new THREE.MeshStandardMaterial({ color: 0x5a4030, roughness: 0.8 });
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.33, 0.028, 0.31), woodMat);
  base.name = 'Map table';
  base.position.set(MAP_CX, 0.014, MAP_CZ);
  root.add(base);

  const mapPlane = new THREE.Mesh(
    new THREE.PlaneGeometry(0.30, 0.28),
    new THREE.MeshStandardMaterial({ color: 0xe9e2cf, roughness: 0.95 }),
  );
  mapPlane.name = 'Paris map';
  mapPlane.rotation.x = -Math.PI / 2;
  mapPlane.position.set(MAP_CX, MAPY, MAP_CZ);
  root.add(mapPlane);

  // Parks
  const parkMat = new THREE.MeshStandardMaterial({ color: 0xa9c99a, roughness: 1 });
  const champ = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.001, 0.016), parkMat);
  champ.name = 'Champ de Mars';
  champ.position.set(mapX(2.3000), 0.030, mapZ(48.8565));
  champ.rotation.y = -0.49;
  root.add(champ);
  const tuil = new THREE.Mesh(new THREE.BoxGeometry(0.046, 0.001, 0.014), parkMat);
  tuil.name = 'Tuileries';
  tuil.position.set(mapX(2.3280), 0.030, mapZ(48.8640));
  root.add(tuil);

  // Seine
  const riverLL = [[2.288, 48.8553], [2.2930, 48.8610], [2.3010, 48.8635], [2.3135, 48.8645],
    [2.3210, 48.8632], [2.3295, 48.8622], [2.3375, 48.8585], [2.3412, 48.8572],
    [2.3507, 48.8548], [2.356, 48.8525]];
  const riverPts = riverLL.map((p) => new THREE.Vector3(mapX(p[0]), 0, mapZ(p[1])));
  const river = new THREE.Mesh(
    new THREE.TubeGeometry(new THREE.CatmullRomCurve3(riverPts), 48, 0.006, 6, false),
    new THREE.MeshStandardMaterial({ color: 0x4a90d9, roughness: 0.3 }),
  );
  river.name = 'Seine';
  river.scale.y = 0.25;
  river.position.y = 0.0302;
  root.add(river);

  // ---------- Pins ----------
  const PIN_Y = 0.077;
  const headGeo = new THREE.SphereGeometry(0.016, 24, 12);
  const stemGeo = new THREE.ConeGeometry(0.008, 0.04, 12);
  const stemMat = new THREE.MeshStandardMaterial({ color: 0x444a55, roughness: 0.5, metalness: 0.4 });
  const iconMat = new THREE.MeshStandardMaterial({ color: 0xf4efe4, roughness: 0.6 });

  function buildIcon(kind) {
    const g = new THREE.Group();
    const add = (geo, x, y, z) => {
      const m = new THREE.Mesh(geo, iconMat);
      m.position.set(x, y, z);
      g.add(m);
      return m;
    };
    if (kind === 'eiffel') {
      add(new THREE.ConeGeometry(0.01, 0.034, 4), 0, 0, 0);
    } else if (kind === 'arc') {
      const pillar = new THREE.BoxGeometry(0.007, 0.022, 0.012);
      add(pillar, -0.009, -0.002, 0);
      add(pillar, 0.009, -0.002, 0);
      add(new THREE.BoxGeometry(0.026, 0.008, 0.012), 0, 0.013, 0);
    } else if (kind === 'louvre') {
      const m = add(new THREE.ConeGeometry(0.016, 0.02, 4), 0, 0, 0);
      m.rotation.y = Math.PI / 4;
    } else if (kind === 'notre') {
      const tower = new THREE.BoxGeometry(0.009, 0.028, 0.009);
      add(tower, -0.008, 0, 0);
      add(tower, 0.008, 0, 0);
    } else if (kind === 'sacre') {
      add(new THREE.CylinderGeometry(0.008, 0.009, 0.01, 16), 0, -0.008, 0);
      add(new THREE.SphereGeometry(0.011, 16, 8, 0, Math.PI * 2, 0, Math.PI / 2), 0, -0.003, 0);
    } else {
      add(new THREE.BoxGeometry(0.028, 0.008, 0.012), 0, -0.007, 0);
      const c = add(new THREE.CylinderGeometry(0.008, 0.008, 0.028, 16), 0, 0.002, 0);
      c.rotation.z = Math.PI / 2;
    }
    return g;
  }

  const pins = [], pinMats = [], icons = [], px = [], pz = [];
  const ring = new THREE.Mesh(
    new THREE.RingGeometry(0.022, 0.028, 32),
    new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }),
  );
  ring.name = 'Selection ring';
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.0312;
  ring.visible = false;
  root.add(ring);

  // ---------- Route lines (one pool per day) ----------
  const segGeo = new THREE.BoxGeometry(1, 0.003, 0.006);
  const segs = [[], [], []];
  for (let d = 0; d < 3; d++) {
    const mat = new THREE.MeshBasicMaterial({ color: DAY_HEX[d] });
    for (let k = 0; k < 5; k++) {
      const s = new THREE.Mesh(segGeo, mat);
      s.visible = false;
      root.add(s);
      segs[d].push(s);
    }
  }

  // ---------- State ----------
  const days = [[], [], []];
  let selected = -1;

  const dayOf = (i) => {
    for (let d = 0; d < 3; d++) if (days[d].indexOf(i) >= 0) return d;
    return -1;
  };
  const legKm = (a, b) => {
    const dx = (LM[a].lon - LM[b].lon) * KM_LON;
    const dz = (LM[a].lat - LM[b].lat) * KM_LAT;
    return Math.sqrt(dx * dx + dz * dz) * 1.25; // street detour factor
  };
  const fmtMin = (m) => (m < 60 ? m + ' min' : Math.floor(m / 60) + ' h ' + (m % 60) + ' min');

  // ---------- Detail panel ----------
  const detail = ui(`
    <style>
      .card { width: 500px; height: 340px; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .meta { color: #8fc1ff; font-size: 22px; }
      .body { color: #d7dbe2; font-size: 22px; }
      .status { color: #ffd166; font-size: 22px; font-weight: 700; }
      .btnrow { flex-direction: row; gap: 10px; }
      .add0 { width: 140px; height: 48px; border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .add1 { width: 140px; height: 48px; border-radius: 12px; background-color: #c46f05; align-items: center; justify-content: center; }
      .add2 { width: 140px; height: 48px; border-radius: 12px; background-color: #1a8a58; align-items: center; justify-content: center; }
      .bt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title" id="dt_title">Paris in 3 days</span>
      <span class="meta" id="dt_meta">6 landmarks, 3 days</span>
      <span class="body" id="dt_desc">Poke a pin on the map to read about it, then add it to a day. Walking time assumes 5 km/h.</span>
      <span class="status" id="dt_status">Tap a pin to start.</span>
      <div class="btnrow" id="dt_btns">
        <button class="add0" id="add0"><span class="bt">Add Day 1</span></button>
        <button class="add1" id="add1"><span class="bt">Add Day 2</span></button>
        <button class="add2" id="add2"><span class="bt">Add Day 3</span></button>
      </div>
