  root.add(detail.object3D);

  // ---------- Day panels ----------
  function dayMarkup(d) {
    let rows = '';
    for (let k = 0; k < 6; k++) {
      rows += `<div class="row" id="d${d}_row${k}">
        <div class="namebox"><span class="name" id="d${d}_name${k}">-</span></div>
        <button class="nav" id="d${d}_up${k}"><span class="mt">Up</span></button>
