  fCenter.position.set(0, 0.088, 0.002);
  flower.add(fCenter);
  const petalGeo = new THREE.SphereGeometry(0.01, 14, 10);
  const petalMat = new THREE.MeshStandardMaterial({ color: 0xff6fa8, roughness: 0.6 });
  for (let k = 0; k < 5; k++) {
    const a = (k * 2 * Math.PI) / 5;
    const petal = new THREE.Mesh(petalGeo, petalMat);
    petal.position.set(Math.sin(a) * 0.0175, 0.088 + Math.cos(a) * 0.0175, 0);
    flower.add(petal);
  }

  // ---------- clue interactions ----------
  const notes = [
    'A stopped clock. Digit 1 = the mark the short hand points at. Digit 2 = the mark the long hand points at. Marks count 1-12 clockwise from the top.',
    'A tidy stack of gold coins. Digit 3 = how many coins are in the stack.',
    'A paper flower. Digit 4 = how many petals it has.',
  ];
  const clueObjs = [clock, coinsGroup, flower];
  clueObjs.forEach((obj, idx) => {
    traits(obj, {
      grab: true,
      onPress: () => {
        readClues[idx] = true;
        updateStatus();
        if (!unlocked) setMsg(notes[idx]);
      },
    });
  });

  // ---------- hints ----------
  const hints = [
    'Hint 1/3: Each clue hides one or two digits. Pick the clues up, turn them around and count.',
    'Hint 2/3: Order is clock (2 digits), then coins, then flower. Read the clock hands as marks 1-12, not as minutes.',
    'Hint 3/3: The code is 4 - 2 - 7 - 5.',
  ];
  info.on('hint', 'click', () => {
    if (unlocked) { setMsg('The box is already open. Press Relock to play again.'); return; }
    hintCount = Math.min(3, hintCount + 1);
    setMsg(hints[hintCount - 1]);
    info.set('hint_t', { text: 'Hint (' + hintCount + '/3)' });
  });

  info.on('reset', 'click', () => {
    unlocked = false;
    hintCount = 0;
    readClues = [false, false, false];
    for (let i = 0; i < 4; i++) {
      digits[i] = 0;
      digitPanels[i].set('n', { text: '0', color: '#ffe9a8' });
    }
    info.set('hint_t', { text: 'Hint (0/3)' });
    updateStatus();
    setMsg('Relocked. Find the 4-digit code again. Press the clues for notes.');
  });

  // ---------- animation ----------
  return {
    root,
    update(time, delta) {
      // arrow press feedback
      for (let i = 0; i < 8; i++) {
        if (pulses[i] > 0) pulses[i] = Math.max(0, pulses[i] - delta * 4);
        arrows[i].scale.setScalar(1 + 0.3 * pulses[i]);
      }

      // opening sequence progress (reverses faster when relocking)
      prog = Math.min(3.2, Math.max(0, prog + (unlocked ? 1 : -2) * delta));

      const s = sm(clamp01(prog / 0.5));
      shackle.position.y = 0.015 + 0.009 * s;

      const f = sm(clamp01((prog - 0.5) / 0.6));
      padlock.position.set(0, 0.068 - 0.05 * f, 0.07 + 0.03 * f);
      padlock.rotation.x = 1.2 * f;

      const o = sm(clamp01((prog - 1.0) / 1.2));
      lidPivot.rotation.x = -1.75 * o;

      const g = sm(clamp01((prog - 1.8) / 1.2));
      gem.position.y = 0.04 + 0.16 * g;
      if (g > 0) {
        gem.rotation.y += delta * 1.5;
        gem.material.emissiveIntensity = 0.7 + 0.4 * Math.sin(time * 3);
      }

      // sparkle burst
      const bt = Math.min(1.4, Math.max(0, prog - 1.8));
      if (bt > 0.001 && bt < 1.39) {
        sparkles.visible = true;
        const sc = 1 - bt / 1.4;
        for (let i = 0; i < SP; i++) {
          dummy.position.set(
            -0.17 + spV[i * 3] * bt,
            0.17 + spV[i * 3 + 1] * bt - 0.075 * bt * bt,
            -0.1 + spV[i * 3 + 2] * bt,
          );
          dummy.scale.setScalar(sc);
          dummy.updateMatrix();
          sparkles.setMatrixAt(i, dummy.matrix);
        }
        sparkles.instanceMatrix.needsUpdate = true;
      } else {
        sparkles.visible = false;
      }
    },
  };
}

