  const tableGeo = new THREE.CylinderGeometry(0.185, 0.19, 0.014, 40);
  const dotGeo = new THREE.SphereGeometry(0.005, 12, 8);

  const bandMat = new THREE.MeshStandardMaterial({ color: 0x2b2e34, roughness: 0.55, metalness: 0.25 });
  const cushionMat = new THREE.MeshStandardMaterial({ color: 0x141519, roughness: 0.9 });
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x9aa0aa, roughness: 0.4, metalness: 0.6 });
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x353a42, roughness: 0.5, metalness: 0.3 });
  const tableMat = new THREE.MeshStandardMaterial({ color: 0x1e2126, roughness: 0.6, metalness: 0.2 });
  const ringMat = new THREE.MeshBasicMaterial({ color: 0x4ade80 });
  const ledMat = new THREE.MeshBasicMaterial({ color: 0x4ade80 });

  // large turntable floor
  const table = new THREE.Mesh(tableGeo, tableMat);
  table.position.set(0, 0.007, -0.03);
  table.name = "Turntable";
  root.add(table);

  const R = 0.12;
  const CENTER_Z = -0.03;
  const BASE_ANGLES = [0, (Math.PI * 2) / 3, (Math.PI * 4) / 3];

  let selectedIndex = 0;
  const selColor = [0, 2, 0];
  const selSize = [1, 1, 1];
  const cart = [];

  const anchors = [];
  const headGroups = [];
  const accentMats = [];
  const rings = [];

  function makeHeadphone(accentMat) {
    const g = new THREE.Group();
    const band = new THREE.Mesh(bandGeo, bandMat);
    band.name = "band";
    g.add(band);
    const pad = new THREE.Mesh(padGeo, cushionMat);
    pad.position.set(0, 0.036, 0);
    g.add(pad);
    const yL = new THREE.Mesh(yokeGeo, bandMat);
    yL.position.set(-0.042, -0.008, 0);
    g.add(yL);
    const yR = new THREE.Mesh(yokeGeo, bandMat);
    yR.position.set(0.042, -0.008, 0);
    g.add(yR);
    const cL = new THREE.Mesh(cupOuterGeo, accentMat);
    cL.rotation.z = Math.PI / 2;
    cL.position.set(-0.054, -0.02, 0);
    cL.name = "cupL";
    g.add(cL);
    const cR = new THREE.Mesh(cupOuterGeo, accentMat);
    cR.rotation.z = Math.PI / 2;
    cR.position.set(0.054, -0.02, 0);
    cR.name = "cupR";
    g.add(cR);
    const pL = new THREE.Mesh(cupInnerGeo, cushionMat);
    pL.rotation.z = Math.PI / 2;
    pL.position.set(-0.038, -0.02, 0);
    g.add(pL);
    const pR = new THREE.Mesh(cupInnerGeo, cushionMat);
    pR.rotation.z = Math.PI / 2;
    pR.position.set(0.038, -0.02, 0);
    g.add(pR);
    const led = new THREE.Mesh(dotGeo, ledMat);
    led.position.set(0.0, -0.02, 0.027);
    g.add(led);
    return g;
  }

  for (let i = 0; i < 3; i++) {
    const anchor = new THREE.Group();
    anchor.name = PRODUCTS[i].name;
    const accent = new THREE.MeshStandardMaterial({ color: COLORS[selColor[i]].hex, roughness: 0.35, metalness: 0.15 });
    accentMats.push(accent);

    const b = new THREE.Mesh(baseGeo, baseMat);
    b.position.set(0, 0.006, 0);
    anchor.add(b);

    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.set(0, 0.013, 0);
    ring.visible = (i === selectedIndex);
    anchor.add(ring);
    rings.push(ring);

    const pole = new THREE.Mesh(poleGeo, poleMat);
    pole.position.set(0, 0.055, 0);
    anchor.add(pole);

    const hg = makeHeadphone(accent);
    hg.position.set(0, 0.15, 0);
    hg.scale.setScalar(SIZE_SCALE[selSize[i]]);
    anchor.add(hg);
    headGroups.push(hg);

    root.add(anchor);
    anchors.push(anchor);
  }

  let carouselOffset = 0;
  let carouselTarget = 0;

  function placeAnchors() {
    for (let i = 0; i < 3; i++) {
      if (isGrabbed(anchors[i])) continue;
      const a = BASE_ANGLES[i] + carouselOffset;
      const x = Math.sin(a) * R;
      const z = Math.cos(a) * R + CENTER_Z;
      anchors[i].position.set(x, 0, z);
      anchors[i].rotation.y = a;
    }
  }
  placeAnchors();

  function money(n) {
    return "$" + n.toFixed(2);
  }

  // ---------- SHOP PANEL ----------
  const shop = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .price { color: #4ade80; font-size: 26px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .label { color: #9aa0aa; font-size: 19px; font-weight: 700; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: flex-start; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #333842; }
      .btn-text { color: #ffffff; font-size: 21px; font-weight: 700; }
      .pos { color: #ffffff; font-size: 21px; }
      .add { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; }
      .hint { color: #ffd166; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title" id="pname">Aero X1</span>
      <span class="price" id="pprice">$189.00</span>
      <span class="body" id="pdesc">Light wireless</span>
      <div class="row">
        <button class="btn" id="prev"><span class="btn-text">&lt; Prev</span></button>
        <span class="pos" id="ppos">1 / 3</span>
        <button class="btn" id="next"><span class="btn-text">Next &gt;</span></button>
      </div>
      <span class="label">COLOR</span>
      <div class="row">
        <button class="btn" id="c0"><span class="btn-text">Onyx</span></button>
        <button class="btn" id="c1"><span class="btn-text">Bone</span></button>
        <button class="btn" id="c2"><span class="btn-text">Cobalt</span></button>
      </div>
      <span class="label">SIZE (headband)</span>
      <div class="row">
        <button class="btn" id="s0"><span class="btn-text">S</span></button>
        <button class="btn" id="s1"><span class="btn-text">M</span></button>
        <button class="btn" id="s2"><span class="btn-text">L</span></button>
      </div>
      <button class="add" id="add"><span class="btn-text">Add to Cart</span></button>
      <span class="hint" id="msg">Tap a headphone to select. Pinch to grab.</span>
    </div>`, { width: 0.29, position: [-0.25, 0.27, -0.1], rotationY: 0.32 });
  root.add(shop.object3D);

  // ---------- CART PANEL ----------
  const cartUi = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 16px; background-color: #23262d; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 21px; }
      .line { flex-direction: row; gap: 6px; align-items: center; justify-content: flex-start; }
      .lname { color: #ffffff; font-size: 20px; }
      .qty { color: #ffffff; font-size: 21px; font-weight: 700; }
      .small { padding-top: 6px; padding-bottom: 6px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #333842; }
      .small-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .sum { color: #d7dbe2; font-size: 21px; }
      .total { color: #ffffff; font-size: 26px; font-weight: 700; }
      .pay { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #16a34a; }
      .msg { color: #ffd166; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Cart</span>
      <span class="body" id="empty">Cart is empty. Add a headphone.</span>
      <div class="line" id="line0">
        <span class="lname" id="lname0">-</span>
        <button class="small" id="m0"><span class="small-text">-</span></button>
        <span class="qty" id="q0">1</span>
        <button class="small" id="p0"><span class="small-text">+</span></button>
      </div>
      <div class="line" id="line1">
        <span class="lname" id="lname1">-</span>
        <button class="small" id="m1"><span class="small-text">-</span></button>
        <span class="qty" id="q1">1</span>
        <button class="small" id="p1"><span class="small-text">+</span></button>
      </div>
      <div class="line" id="line2">
        <span class="lname" id="lname2">-</span>
        <button class="small" id="m2"><span class="small-text">-</span></button>
        <span class="qty" id="q2">1</span>
        <button class="small" id="p2"><span class="small-text">+</span></button>
      </div>
      <div class="line" id="line3">
        <span class="lname" id="lname3">-</span>
        <button class="small" id="m3"><span class="small-text">-</span></button>
        <span class="qty" id="q3">1</span>
        <button class="small" id="p3"><span class="small-text">+</span></button>
      </div>
      <div class="line" id="line4">
        <span class="lname" id="lname4">-</span>
        <button class="small" id="m4"><span class="small-text">-</span></button>
        <span class="qty" id="q4">1</span>
        <button class="small" id="p4"><span class="small-text">+</span></button>
      </div>
      <span class="body" id="more">...</span>
      <span class="sum" id="sub">Subtotal: $0.00</span>
      <span class="sum" id="tax">Tax (8%): $0.00</span>
      <span class="total" id="tot">Total: $0.00</span>
      <button class="pay" id="checkout"><span class="small-text">Checkout</span></button>
      <span class="msg" id="cmsg">Tax 8%. Sizes S M L same price.</span>
    </div>`, { width: 0.29, position: [0.25, 0.27, -0.1], rotationY: -0.32 });
  root.add(cartUi.object3D);

  function refreshShop() {
    const p = PRODUCTS[selectedIndex];
    shop.set("pname", { text: (selectedIndex + 1) + ". " + p.name });
    shop.set("pprice", { text: money(p.price) });
    shop.set("pdesc", { text: p.desc });
    shop.set("ppos", { text: (selectedIndex + 1) + " / 3" });
    for (let k = 0; k < 3; k++) {
      shop.set("c" + k, { backgroundColor: (k === selColor[selectedIndex]) ? "#2f6fdb" : "#333842" });
      shop.set("s" + k, { backgroundColor: (k === selSize[selectedIndex]) ? "#2f6fdb" : "#333842" });
    }
    for (let i = 0; i < 3; i++) rings[i].visible = (i === selectedIndex);
  }

  function cartTotals() {
    let sub = 0;
    for (let i = 0; i < cart.length; i++) sub += PRODUCTS[cart[i].p].price * cart[i].qty;
    const tax = sub * TAX_RATE;
    return { sub: sub, tax: tax, tot: sub + tax };
  }

  function lineLabel(e) {
    return PRODUCTS[e.p].name + " " + COLORS[e.c].name + " " + SIZES[e.s];
  }

  function refreshCart() {
    const MAX = 5;
    if (cart.length === 0) {
      cartUi.set("empty", { text: "Cart is empty. Add a headphone." });
    } else {
      cartUi.set("empty", { text: cart.length + " item type(s) in cart:" });
    }
    for (let i = 0; i < MAX; i++) {
      if (i < cart.length && i < MAX) {
        cartUi.set("line" + i, { display: "flex" });
        cartUi.set("lname" + i, { text: lineLabel(cart[i]) });
        cartUi.set("q" + i, { text: "" + cart[i].qty });
      } else {
        cartUi.set("line" + i, { display: "none" });
      }
    }
    if (cart.length > MAX) {
      cartUi.set("more", { text: "+ " + (cart.length - MAX) + " more type(s)..." });
    } else {
      cartUi.set("more", { text: " " });
    }
    const t = cartTotals();
    cartUi.set("sub", { text: "Subtotal: " + money(t.sub) });
    cartUi.set("tax", { text: "Tax (8%): " + money(t.tax) });
    cartUi.set("tot", { text: "Total: " + money(t.tot) });
  }

  function select(i) {
    selectedIndex = i;
    let want = -BASE_ANGLES[i];
    while (want - carouselTarget > Math.PI) want -= Math.PI * 2;
    while (want - carouselTarget < -Math.PI) want += Math.PI * 2;
    carouselTarget = want;
    // apply stored variant to 3D
    accentMats[i].color.setHex(COLORS[selColor[i]].hex);
    headGroups[i].scale.setScalar(SIZE_SCALE[selSize[i]]);
    refreshShop();
  }

  shop.on("prev", "click", () => select((selectedIndex + 2) % 3));
  shop.on("next", "click", () => select((selectedIndex + 1) % 3));
  shop.on("c0", "click", () => { selColor[selectedIndex] = 0; accentMats[selectedIndex].color.setHex(COLORS[0].hex); refreshShop(); });
  shop.on("c1", "click", () => { selColor[selectedIndex] = 1; accentMats[selectedIndex].color.setHex(COLORS[1].hex); refreshShop(); });
  shop.on("c2", "click", () => { selColor[selectedIndex] = 2; accentMats[selectedIndex].color.setHex(COLORS[2].hex); refreshShop(); });
  shop.on("s0", "click", () => { selSize[selectedIndex] = 0; headGroups[selectedIndex].scale.setScalar(SIZE_SCALE[0]); refreshShop(); });
  shop.on("s1", "click", () => { selSize[selectedIndex] = 1; headGroups[selectedIndex].scale.setScalar(SIZE_SCALE[1]); refreshShop(); });
  shop.on("s2", "click", () => { selSize[selectedIndex] = 2; headGroups[selectedIndex].scale.setScalar(SIZE_SCALE[2]); refreshShop(); });
  shop.on("add", "click", () => {
    const p = selectedIndex;
    const c = selColor[p];
    const s = selSize[p];
    let found = -1;
    for (let i = 0; i < cart.length; i++) {
      if (cart[i].p === p && cart[i].c === c && cart[i].s === s) found = i;
    }
    if (found >= 0) cart[found].qty += 1;
    else cart.push({ p: p, c: c, s: s, qty: 1 });
    shop.set("msg", { text: "Added " + lineLabel({ p: p, c: c, s: s }) + "." });
    cartUi.set("cmsg", { text: "Added to cart." });
    refreshCart();
  });

  for (let li = 0; li < 5; li++) {
    const idx = li;
    cartUi.on("m" + idx, "click", () => {
      if (idx >= cart.length) return;
      cart[idx].qty -= 1;
      if (cart[idx].qty <= 0) cart.splice(idx, 1);
      refreshCart();
    });
    cartUi.on("p" + idx, "click", () => {
      if (idx >= cart.length) return;
      cart[idx].qty += 1;
      if (cart[idx].qty > 9) cart[idx].qty = 9;
      refreshCart();
    });
  }
  cartUi.on("checkout", "click", () => {
    if (cart.length === 0) {
      cartUi.set("cmsg", { text: "Cart is empty." });
      return;
    }
    const t = cartTotals();
    cartUi.set("cmsg", { text: "Order placed! Paid " + money(t.tot) + ". Thanks!" });
    cart.length = 0;
    refreshCart();
  });

  // traits on direct children only
  for (let i = 0; i < 3; i++) {
    const idx = i;
    traits(anchors[idx], {
      grab: true,
      onPress: () => select(idx)
    });
  }

  // init 3D variants
  for (let i = 0; i < 3; i++) {
    accentMats[i].color.setHex(COLORS[selColor[i]].hex);
    headGroups[i].scale.setScalar(SIZE_SCALE[selSize[i]]);
  }
  refreshShop();
  refreshCart();

  return {
    root,
    update(time, delta) {
      const d = Math.max(0, Math.min(delta, 0.05));
      const diff = carouselTarget - carouselOffset;
      if (Math.abs(diff) > 0.0005) {
        carouselOffset += diff * Math.min(1, d * 4);
      } else {
        carouselOffset = carouselTarget;
      }
      placeAnchors();
      for (let i = 0; i < 3; i++) {
        if (isGrabbed(anchors[i])) continue;
        if (i === selectedIndex) {
          headGroups[i].rotation.y += d * 0.7;
        } else {
          headGroups[i].rotation.y += d * 0.15;
        }
        const s = rings[i].scale;
        const k = 1 + Math.sin(time * 3) * 0.04;
        s.set(k, k, 1);
      }
      table.rotation.y = carouselOffset * 0.4;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- helpers ----------
  const std = (color, o) => new THREE.MeshStandardMaterial(Object.assign({ color: color, roughness: 0.7 }, o || {}));
  const unitBox = new THREE.BoxGeometry(1, 1, 1);
  function addBox(w, h, d, x, y, z, mat, name) {
    const m = new THREE.Mesh(unitBox, mat);
    m.scale.set(w, h, d);
    m.position.set(x, y, z);
    if (name) m.name = name;
    root.add(m);
    return m;
  }
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

  // ---------- apartment model ----------
  const ROOMS = [
    { name: 'Living Room', short: 'Living', cx: -0.29, cz: 0.06, w: 0.20, d: 0.14, max: 120, lv: 7, last: 7 },
    { name: 'Kitchen', short: 'Kitchen', cx: -0.29, cz: -0.07, w: 0.20, d: 0.12, max: 90, lv: 3, last: 3 },
    { name: 'Bedroom', short: 'Bed', cx: -0.12, cz: -0.07, w: 0.14, d: 0.12, max: 60, lv: 0, last: 6 },
    { name: 'Bathroom', short: 'Bath', cx: -0.12, cz: 0.06, w: 0.14, d: 0.14, max: 40, lv: 0, last: 5 },
  ];

  addBox(0.348, 0.006, 0.268, -0.22, 0.003, 0, std(0x23262c), 'Apartment base');
  const wallMat = std(0xd9d5cc);
  addBox(0.344, 0.036, 0.004, -0.22, 0.024, -0.13, wallMat, 'Back wall');
  addBox(0.344, 0.012, 0.004, -0.22, 0.012, 0.13, wallMat, 'Front wall');
  addBox(0.004, 0.036, 0.264, -0.39, 0.024, 0, wallMat, 'Left wall');
  addBox(0.004, 0.036, 0.264, -0.05, 0.024, 0, wallMat, 'Right wall');
  addBox(0.004, 0.016, 0.264, -0.19, 0.014, 0, wallMat, 'Partition A');
  addBox(0.344, 0.016, 0.004, -0.22, 0.014, -0.01, wallMat, 'Partition B');

  const cOff = new THREE.Color(0x30343b);
  const cOn = new THREE.Color(0xe6d8b8);
  const lampOff = new THREE.Color(0x555a63);
  const lampOn = new THREE.Color(0xffd28a);
  const lampGeo = new THREE.SphereGeometry(0.011, 20, 12);

  let selected = 0;
  ROOMS.forEach((r, i) => {
    r.floorMat = std(0x30343b, { emissive: 0xffb347, emissiveIntensity: 0 });
    const floor = new THREE.Mesh(new THREE.BoxGeometry(r.w - 0.006, 0.008, r.d - 0.006), r.floorMat);
    floor.position.set(r.cx, 0.010, r.cz);
    floor.name = 'Floor ' + r.name;
    root.add(floor);
    r.floor = floor;

    r.lampMat = std(0x555a63, { emissive: 0xffc46b, emissiveIntensity: 0, roughness: 0.4 });
    const lamp = new THREE.Mesh(lampGeo, r.lampMat);
    lamp.position.set(r.cx, 0.07, r.cz);
    lamp.name = 'Light ' + r.name;
    root.add(lamp);
    r.lamp = lamp;
  });

  // furniture (decor)
  addBox(0.09, 0.02, 0.032, -0.29, 0.024, 0.105, std(0x5b6f8a), 'Sofa');
  const tvMat = std(0x101114, { emissive: 0x4a7cff, emissiveIntensity: 0, roughness: 0.3 });
  addBox(0.07, 0.034, 0.004, -0.29, 0.031, 0.002, tvMat, 'TV');
  addBox(0.07, 0.014, 0.085, -0.12, 0.021, -0.065, std(0x8a5b5b), 'Bed');
  addBox(0.05, 0.008, 0.016, -0.12, 0.032, -0.1, std(0xeeeeee), 'Pillow');
  addBox(0.17, 0.022, 0.026, -0.29, 0.025, -0.113, std(0x6b7480), 'Kitchen counter');
  const table = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.016, 24), std(0x8b6b4a));
  table.position.set(-0.29, 0.022, -0.05);
  table.name = 'Table';
  root.add(table);
  addBox(0.04, 0.018, 0.09, -0.075, 0.023, 0.065, std(0xcfe3ee), 'Bathtub');

  // selection arrow
  const arrowGeo = new THREE.ConeGeometry(0.009, 0.022, 16);
  arrowGeo.rotateX(Math.PI);
  const arrow = new THREE.Mesh(arrowGeo, std(0x38d6ff, { emissive: 0x38d6ff, emissiveIntensity: 0.8 }));
  arrow.name = 'Selection arrow';
  arrow.position.set(ROOMS[0].cx, 0.1, ROOMS[0].cz);
  root.add(arrow);

  // ---------- thermostat ----------
  const TX = 0.325, TY = 0.12;
  const tg = new THREE.Group();
  tg.position.set(TX, TY, 0);
  tg.name = 'Thermostat';
  root.add(tg);

  const bodyGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.014, 40);
  bodyGeo.rotateX(Math.PI / 2);
  tg.add(new THREE.Mesh(bodyGeo, std(0x2b2f36, { roughness: 0.5 })));

  const diskGeo = new THREE.CylinderGeometry(0.022, 0.022, 0.004, 28);
  diskGeo.rotateX(Math.PI / 2);
  const disk = new THREE.Mesh(diskGeo, std(0x4a505a, { roughness: 0.4 }));
  disk.position.z = 0.008;
  tg.add(disk);

  const ringMat = std(0x4aa3ff, { emissive: 0x4aa3ff, emissiveIntensity: 0.7, roughness: 0.4 });
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.0435, 0.0025, 8, 64, Math.PI * 1.5), ringMat);
  ring.rotation.z = Math.PI * 1.75;
  ring.position.z = 0.0075;
  tg.add(ring);

  const ticks = new THREE.InstancedMesh(unitBox, std(0xb8c0cc), 13);
  const m4 = new THREE.Matrix4();
  const v3 = new THREE.Vector3();
  const s3 = new THREE.Vector3();
  const q = new THREE.Quaternion();
  const zAxis = new THREE.Vector3(0, 0, 1);
  for (let k = 0; k < 13; k++) {
    const th = ((-135 + k * 22.5) * Math.PI) / 180;
    v3.set(Math.sin(th) * 0.036, Math.cos(th) * 0.036, 0.0075);
    q.setFromAxisAngle(zAxis, -th);
    s3.set(0.002, 0.006, 0.002);
    m4.compose(v3, q, s3);
    ticks.setMatrixAt(k, m4);
  }
  ticks.instanceMatrix.needsUpdate = true;
  ticks.frustumCulled = false;
  tg.add(ticks);

  const needle = new THREE.Group();
  needle.position.z = 0.0105;
  tg.add(needle);
  const nb = new THREE.Mesh(unitBox, std(0xffffff, { emissive: 0xffffff, emissiveIntensity: 0.4 }));
  nb.scale.set(0.004, 0.028, 0.003);
  nb.position.y = 0.016;
  needle.add(nb);

  const marker = new THREE.Mesh(new THREE.SphereGeometry(0.004, 12, 8), std(0xffffff, { emissive: 0xffffff, emissiveIntensity: 0.9 }));
  marker.position.set(0, 0.0435, 0.0105);
  tg.add(marker);

  const stand = new THREE.Mesh(unitBox, std(0x2b2f36));
  stand.scale.set(0.012, 0.07, 0.012);
  stand.position.set(0, 0.04 - TY, -0.01);
  tg.add(stand);
  const base = new THREE.Mesh(unitBox, std(0x2b2f36));
  base.scale.set(0.1, 0.006, 0.05);
  base.position.set(0, 0.003 - TY, 0);
  tg.add(base);

  // thermostat +/- buttons
  const btnGeo = new THREE.CylinderGeometry(0.02, 0.02, 0.012, 28);
  btnGeo.rotateX(Math.PI / 2);
  const symMat = std(0xffffff, { emissive: 0xffffff, emissiveIntensity: 0.3 });
  const tempButtons = [];
  function makeTempButton(x, color, plus, step, name) {
    const g = new THREE.Group();
    g.name = name;
    g.position.set(x, 0.04, 0.012);
    g.add(new THREE.Mesh(btnGeo, std(color, { roughness: 0.4 })));
    const h = new THREE.Mesh(unitBox, symMat);
    h.scale.set(0.022, 0.005, 0.002);
    h.position.z = 0.007;
    g.add(h);
    if (plus) {
      const v = new THREE.Mesh(unitBox, symMat);
      v.scale.set(0.005, 0.022, 0.002);
      v.position.z = 0.007;
      g.add(v);
    }
    root.add(g);
    const entry = { g: g, press: 0 };
    tempButtons.push(entry);
    traits(g, { onPress: () => { entry.press = 0.18; changeTemp(step); } });
  }
  makeTempButton(TX - 0.03, 0x3b8fe8, false, -0.5, 'Temp down');
  makeTempButton(TX + 0.03, 0xe8743b, true, 0.5, 'Temp up');

  // ---------- energy chart ----------
  const CH_BASE = 0.28, CH_Z = -0.17, BAR_X0 = 0.05, PITCH = 0.32 / 24, NOW = 18;
  const HIST = [0.30, 0.28, 0.27, 0.27, 0.30, 0.45, 0.95, 1.30, 0.90, 0.50, 0.35, 0.33, 0.55, 0.45, 0.35, 0.40, 0.60, 0.95];
  let histSum = 0;
  HIST.forEach((v) => { histSum += v; });

  addBox(0.34, 0.13, 0.004, 0.21, CH_BASE + 0.06, CH_Z - 0.006, std(0x191c21, { roughness: 0.9 }), 'Chart backing');
  const gridMat = std(0x3a3f48, { roughness: 0.9 });
  addBox(0.33, 0.0009, 0.001, 0.21, CH_BASE + 0.055, CH_Z - 0.0035, gridMat, 'Grid 1 kWh');
  addBox(0.33, 0.0009, 0.001, 0.21, CH_BASE + 0.11, CH_Z - 0.0035, gridMat, 'Grid 2 kWh');
  addBox(0.33, 0.0012, 0.001, 0.21, CH_BASE, CH_Z - 0.0035, std(0x7b8492, { roughness: 0.9 }), 'Chart baseline');

  const bars = new THREE.InstancedMesh(unitBox, std(0xffffff, { roughness: 0.5 }), 24);
  bars.name = 'Energy bars';
  bars.frustumCulled = false;
  const col = new THREE.Color();
  function setBar(i, val, hex) {
    const h = Math.max(0.003, Math.min(2.2, val) / 2 * 0.11);
    v3.set(BAR_X0 + (i + 0.5) * PITCH, CH_BASE + h / 2, CH_Z);
    q.set(0, 0, 0, 1);
    s3.set(0.0098, h, 0.008);
    m4.compose(v3, q, s3);
    bars.setMatrixAt(i, m4);
    if (hex !== undefined) {
      col.setHex(hex);
      bars.setColorAt(i, col);
    }
  }
  for (let i = 0; i < 24; i++) {
    if (i < NOW) setBar(i, HIST[i], 0x2fb5a8);
    else if (i === NOW) setBar(i, 1, 0xffb02e);
    else setBar(i, 0, 0x3a3f48);
  }
  bars.instanceMatrix.needsUpdate = true;
  bars.instanceColor.needsUpdate = true;
  root.add(bars);

  // ---------- UI panels ----------
  const tabsHtml = ROOMS.map((r, i) => '<button class="tab" id="tab' + i + '"><span class="tabt">' + r.short + '</span></button>').join('');
  let segsHtml = '';
  for (let j = 0; j < 10; j++) segsHtml += '<div class="seg" id="seg' + j + '"></div>';

  const lights = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1f2228; }
      .head { color: #9aa3b0; font-size: 22px; }
      .name { color: #ffffff; font-size: 34px; font-weight: 700; }
      .row { flex-direction: row; gap: 8px; align-items: center; }
      .segrow { flex-direction: row; gap: 6px; align-items: center; }
      .tab { width: 100px; height: 44px; border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .tabt { color: #ffffff; font-size: 22px; font-weight: 700; }
      .seg { width: 36px; height: 22px; border-radius: 6px; background-color: #3a3f48; }
      .lvl { color: #ffffff; font-size: 26px; font-weight: 700; }
      .btn { height: 50px; border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btnt { color: #ffffff; font-size: 24px; font-weight: 700; }
      .hint { color: #b9c0cb; font-size: 22px; }
    </style>
    <div class="card">
      <span class="head">Lights</span>
      <span class="name" id="roomName">Living Room</span>
      <div class="row">${tabsHtml}</div>
      <div class="segrow">${segsHtml}</div>
      <span class="lvl" id="lvl">Brightness 70%</span>
      <div class="row">
        <button class="btn" id="dim" style="width:140px"><span class="btnt">- Dim</span></button>
        <button class="btn" id="bright" style="width:160px"><span class="btnt">+ Brighter</span></button>
        <button class="btn" id="toggle" style="width:100px"><span class="btnt" id="toggleT">Off</span></button>
      </div>
      <span class="hint">Press a room to select it, or its bulb to switch it.</span>
    </div>`, { width: 0.30, position: [-0.22, 0.2, -0.17] });
  root.add(lights.object3D);

  const SCENES = {
    movie: { label: 'Movie', lv: [1, 0, 0, 0], temp: 22, tv: true, color: '#6a4fd1' },
    dinner: { label: 'Dinner', lv: [4, 8, 0, 0], temp: 21.5, tv: false, color: '#d1803a' },
    away: { label: 'Away', lv: [0, 0, 0, 0], temp: 17, tv: false, color: '#3a8f6a' },
  };
  const SCENE_KEYS = ['movie', 'dinner', 'away'];

  const climate = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 18px; padding-bottom: 18px; padding-left: 22px; padding-right: 22px; border-radius: 20px; background-color: #1f2228; }
      .lab { color: #9aa3b0; font-size: 22px; }
      .big { color: #ffffff; font-size: 46px; font-weight: 700; }
      .val { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 10px; }
      .sbtn { width: 132px; height: 48px; border-radius: 12px; background-color: #3a3f48; align-items: center; justify-content: center; }
      .sbt { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="lab">Target (press + / - on the dial)</span>
      <span class="big" id="tTarget">22.0 °C</span>
      <span class="val" id="tNow">Now 21.0 °C - heating</span>
      <span class="lab" style="margin-top:6px">Scenes</span>
      <div class="row">
        <button class="sbtn" id="sc_movie"><span class="sbt">Movie</span></button>
        <button class="sbtn" id="sc_dinner"><span class="sbt">Dinner</span></button>
        <button class="sbtn" id="sc_away"><span class="sbt">Away</span></button>
      </div>
      <span class="val" id="sStatus">Scene: Custom</span>
    </div>`, { width: 0.28, position: [0.11, 0.115, 0.0] });
  root.add(climate.object3D);

  const chart = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 4px; padding-top: 10px; padding-bottom: 10px; padding-left: 15px; padding-right: 15px; border-radius: 16px; background-color: #1f2228; }
      .axrow { flex-direction: row; }
      .ax { width: 122px; }
      .axt { color: #9aa3b0; font-size: 22px; }
      .ttl { color: #ffffff; font-size: 28px; font-weight: 700; }
      .sub { color: #d7dbe2; font-size: 22px; }
    </style>
    <div class="card">
      <div class="axrow">
        <div class="ax"><span class="axt">0:00</span></div>
        <div class="ax"><span class="axt">6:00</span></div>
        <div class="ax"><span class="axt">12:00</span></div>
        <div class="ax"><span class="axt">18:00</span></div>
      </div>
      <span class="ttl" id="eTotal">Energy today: 9.9 kWh</span>
      <span class="sub" id="eNow">Now 0.95 kW (amber). Lines: 1 / 2 kWh</span>
    </div>`, { width: 0.34, position: [0.21, 0.225, -0.17] });
  root.add(chart.object3D);

  // ---------- state ----------
  let target = 22;
  let current = 21.0;
  let needleAngle = 0;
  let needleGoal = 0;
  let tv = false;
  let activeScene = null;
  let lastR10 = -999, lastMode = -1;
  const cCool = new THREE.Color(0x4aa3ff);
  const cWarm = new THREE.Color(0xff6a3d);
  const tmpC = new THREE.Color();
  const tempToAngle = (t) => ((-135 + (t - 16) / 12 * 270) * Math.PI) / 180;

  function powerKw() {
    let w = 0;
    ROOMS.forEach((r) => { w += (r.lv / 10) * r.max; });
    return w / 1000 + Math.max(0, target - 10) * 0.06 + (tv ? 0.12 : 0) + (activeScene === 'away' ? 0.06 : 0.12);
  }

  function refreshRoom(i) {
    const r = ROOMS[i];
    const f = r.lv / 10;
    r.floorMat.color.copy(cOff).lerp(cOn, f);
    r.floorMat.emissiveIntensity = f * 0.35;
    r.lampMat.color.copy(lampOff).lerp(lampOn, f);
    r.lampMat.emissiveIntensity = f * 1.8;
  }

  function refreshLights() {
    const r = ROOMS[selected];
    lights.set('roomName', { text: r.name });
    lights.set('lvl', { text: 'Brightness ' + (r.lv * 10) + '%' });
    lights.set('toggleT', { text: r.lv > 0 ? 'Off' : 'On' });
    for (let i = 0; i < ROOMS.length; i++) {
      lights.set('tab' + i, { backgroundColor: i === selected ? '#2f6fdb' : '#3a3f48' });
    }
    for (let j = 0; j < 10; j++) {
      lights.set('seg' + j, { backgroundColor: j < r.lv ? '#ffc46b' : '#3a3f48' });
    }
  }

  function refreshScenes() {
    SCENE_KEYS.forEach((k) => {
      climate.set('sc_' + k, { backgroundColor: activeScene === k ? SCENES[k].color : '#3a3f48' });
    });
    climate.set('sStatus', { text: 'Scene: ' + (activeScene ? SCENES[activeScene].label : 'Custom') });
  }

  function refreshEnergy() {
    const kw = powerKw();
    setBar(NOW, kw);
    bars.instanceMatrix.needsUpdate = true;
    chart.set('eTotal', { text: 'Energy today: ' + (histSum + kw * 0.5).toFixed(1) + ' kWh' });
    chart.set('eNow', { text: 'Now ' + kw.toFixed(2) + ' kW (amber). Lines: 1 / 2 kWh' });
  }

  function setTarget(t) {
    target = clamp(Math.round(t * 2) / 2, 16, 28);
    const f = (target - 16) / 12;
    tmpC.copy(cCool).lerp(cWarm, f);
    ringMat.color.copy(tmpC);
    ringMat.emissive.copy(tmpC);
    needleGoal = tempToAngle(target);
    climate.set('tTarget', { text: target.toFixed(1) + ' °C' });
    lastMode = -1;
  }

  function markCustom() {
    if (activeScene !== null) {
      activeScene = null;
      refreshScenes();
    }
  }

  function changeTemp(step) {
    setTarget(target + step);
    markCustom();
    refreshEnergy();
  }

  function selectRoom(i) {
    selected = i;
    refreshLights();
  }

  function changeLevel(step) {
    const r = ROOMS[selected];
    r.lv = clamp(r.lv + step, 0, 10);
    if (r.lv > 0) r.last = r.lv;
    markCustom();
    refreshRoom(selected);
    refreshLights();
    refreshEnergy();
  }

  function toggleRoom(i) {
    const r = ROOMS[i];
    if (r.lv > 0) { r.last = r.lv; r.lv = 0; } else { r.lv = r.last || 7; }
    markCustom();
    refreshRoom(i);
    refreshLights();
    refreshEnergy();
  }

  function applyScene(key) {
    const s = SCENES[key];
    ROOMS.forEach((r, i) => {
      r.lv = s.lv[i];
      if (r.lv > 0) r.last = r.lv;
      refreshRoom(i);
    });
    tv = s.tv;
    tvMat.emissiveIntensity = tv ? 1.3 : 0;
    setTarget(s.temp);
    activeScene = key;
    refreshLights();
    refreshScenes();
    refreshEnergy();
  }

  // ---------- wiring ----------
  ROOMS.forEach((r, i) => {
    traits(r.floor, { onPress: () => selectRoom(i) });
    traits(r.lamp, { onPress: () => { selectRoom(i); toggleRoom(i); } });
    lights.on('tab' + i, 'click', () => selectRoom(i));
  });
  lights.on('dim', 'click', () => changeLevel(-1));
  lights.on('bright', 'click', () => changeLevel(1));
  lights.on('toggle', 'click', () => toggleRoom(selected));
  SCENE_KEYS.forEach((k) => climate.on('sc_' + k, 'click', () => applyScene(k)));

  // ---------- initial state ----------
  ROOMS.forEach((r, i) => refreshRoom(i));
  setTarget(22);
  needleAngle = needleGoal;
  needle.rotation.z = -needleAngle;
  refreshLights();
  refreshScenes();
  refreshEnergy();

  const modeText = ['holding', 'heating', 'cooling down'];

  return {
    root,
    update(time, delta) {
      // room temperature drifts toward the target
      const diff = target - current;
      const step = 0.25 * delta;
      if (Math.abs(diff) <= step) current = target;
      else current += Math.sign(diff) * step;

      const cc = clamp(current, 16, 28);
      const a = tempToAngle(cc);
      marker.position.x = Math.sin(a) * 0.0435;
      marker.position.y = Math.cos(a) * 0.0435;

      const r10 = Math.round(current * 10);
      const d2 = target - current;
      const mode = d2 > 0.05 ? 1 : (d2 < -0.05 ? 2 : 0);
      if (r10 !== lastR10 || mode !== lastMode) {
        lastR10 = r10;
        lastMode = mode;
        climate.set('tNow', { text: 'Now ' + (r10 / 10).toFixed(1) + ' °C - ' + modeText[mode] });
      }

      // needle eases to target
      needleAngle += (needleGoal - needleAngle) * Math.min(1, delta * 10);
      needle.rotation.z = -needleAngle;

      // selection arrow
      const sr = ROOMS[selected];
      const k = Math.min(1, delta * 8);
      arrow.position.x += (sr.cx - arrow.position.x) * k;
      arrow.position.z += (sr.cz - arrow.position.z) * k;
      arrow.position.y = 0.1 + Math.sin(time * 3) * 0.004;

      // button press feedback
      for (let i = 0; i < tempButtons.length; i++) {
        const b = tempButtons[i];
        if (b.press > 0) {
          b.press = Math.max(0, b.press - delta);
          b.g.scale.setScalar(1 - 0.15 * (b.press / 0.18));
        }
      }
    },
  };
}

