  // --- UI: ingredients ---
  const ingUI = ui(`
    <style>
      .cardIng { width: 380px; display: flex; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 16px; padding-right: 16px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .sub { color: #b8bec9; font-size: 20px; }
      .row { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #2a2e35; }
      .rowtext { color: #ffffff; font-size: 22px; }
      .hint { color: #8f96a3; font-size: 18px; }
    </style>
    <div class="cardIng">
      <span class="title">Pancakes - Ingredients</span>
      <span class="sub" id="count">0 of 7 ready - tap to tick off</span>
      <button class="row" id="b0"><span class="rowtext" id="t0">[ ] 1 cup flour</span></button>
      <button class="row" id="b1"><span class="rowtext" id="t1">[ ] 2 tbsp sugar</span></button>
      <button class="row" id="b2"><span class="rowtext" id="t2">[ ] 1 tbsp baking powder</span></button>
      <button class="row" id="b3"><span class="rowtext" id="t3">[ ] 1/4 tsp salt</span></button>
      <button class="row" id="b4"><span class="rowtext" id="t4">[ ] 3/4 cup milk</span></button>
      <button class="row" id="b5"><span class="rowtext" id="t5">[ ] 1 egg</span></button>
      <button class="row" id="b6"><span class="rowtext" id="t6">[ ] 2 tbsp melted butter</span></button>
      <span class="hint">Pinch bowl + pancake to grab. Press pancake to flip.</span>
    </div>`, { width: 0.26, position: [-0.30, 0.26, 0.0], rotationY: 0.32 });
  root.add(ingUI.object3D);

  // --- UI: steps + timer + progress ---
  const mainUI = ui(`
    <style>
      .cardMain { width: 520px; display: flex; flex-direction: column; gap: 10px; padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .stepnum { color: #ffca28; font-size: 20px; font-weight: 700; }
      .steptitle { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .timerbox { display: flex; flex-direction: column; gap: 8px; padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #2a2e35; }
      .timer { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .timerrow { display: flex; flex-direction: row; gap: 10px; justify-content: center; }
      .tbtn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 10px; background-color: #2f6fdb; }
      .tbtn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 10px; background-color: #3a3f48; }
      .tbtntext { color: #ffffff; font-size: 22px; font-weight: 700; }
      .navrow { display: flex; flex-direction: row; gap: 10px; justify-content: space-between; }
      .navbtn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 10px; background-color: #3a3f48; }
      .navbtn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px; border-radius: 10px; background-color: #4caf50; }
      .progtxt { color: #b8bec9; font-size: 20px; }
      .bar { display: flex; flex-direction: row; gap: 6px; }
      .seg { width: 60px; height: 12px; border-radius: 6px; background-color: #3a3f48; }
    </style>
    <div class="cardMain">
      <span class="title">Pancake Coach</span>
      <span class="stepnum" id="stepnum">Step 1 of 7</span>
      <span class="steptitle" id="steptitle">Prep station</span>
      <span class="body" id="stepdetail">Get ready.</span>
      <div class="timerbox">
        <span class="timer" id="timerlabel">No timer</span>
        <div class="timerrow" id="trow">
          <button class="tbtn" id="startbtn"><span class="tbtntext" id="starttext">Start</span></button>
          <button class="tbtn2" id="resetbtn"><span class="tbtntext">Reset</span></button>
        </div>
      </div>
      <div class="navrow">
        <button class="navbtn" id="back"><span class="tbtntext">Back</span></button>
        <button class="navbtn2" id="next"><span class="tbtntext">Next -></span></button>
      </div>
      <span class="progtxt" id="progtxt">Progress 1 of 7</span>
      <div class="bar">
        <div class="seg" id="p0"></div>
        <div class="seg" id="p1"></div>
        <div class="seg" id="p2"></div>
        <div class="seg" id="p3"></div>
        <div class="seg" id="p4"></div>
        <div class="seg" id="p5"></div>
        <div class="seg" id="p6"></div>
      </div>
    </div>`, { width: 0.34, position: [0.26, 0.27, 0.0], rotationY: -0.32 });
  root.add(mainUI.object3D);

  const checked = [false, false, false, false, false, false, false];
  let checkedCount = 0;
  for (let i = 0; i < 7; i++) {
    ingUI.on("b" + i, "click", () => {
      checked[i] = !checked[i];
      checkedCount = 0;
      for (let k = 0; k < 7; k++) if (checked[k]) checkedCount++;
      const prefix = checked[i] ? "[X] " : "[ ] ";
      ingUI.set("t" + i, { text: prefix + ingNames[i] });
      ingUI.set("b" + i, { backgroundColor: checked[i] ? "#2e6b3a" : "#2a2e35" });
      ingUI.set("count", { text: checkedCount + " of 7 ready - tap to tick off" });
    });
  }

  function renderStep() {
    const s = steps[cur];
    mainUI.set("stepnum", { text: "Step " + (cur + 1) + " of " + steps.length });
    mainUI.set("steptitle", { text: s.title });
    mainUI.set("stepdetail", { text: s.detail });
    const pct = Math.round(((cur + 1) / steps.length) * 100);
    mainUI.set("progtxt", { text: "Progress " + (cur + 1) + " of " + steps.length + " - " + pct + "%" });
    for (let i = 0; i < 7; i++) {
      const c = i < cur ? "#4caf50" : (i === cur ? "#ffca28" : "#3a3f48");
      mainUI.set("p" + i, { backgroundColor: c });
    }
    mainUI.set("back", { backgroundColor: cur === 0 ? "#2a2e35" : "#3a3f48" });
    mainUI.set("next", { backgroundColor: cur === steps.length - 1 ? "#2a2e35" : "#4caf50" });
    if (s.secs === 0) {
      mainUI.set("timerlabel", { text: "No timer - press Next when ready" });
      mainUI.set("starttext", { text: "Start" });
      mainUI.set("trow", { display: "none" });
    } else {
      mainUI.set("trow", { display: "flex" });
      mainUI.set("starttext", { text: running ? "Pause" : "Start" });
      const left = Math.ceil(rems[cur]);
      if (rems[cur] <= 0) mainUI.set("timerlabel", { text: "Time is up! Well done!" });
      else mainUI.set("timerlabel", { text: fmt(left) + " left - press Start" });
    }
    lastSec = -1;
    const want = stackCounts[cur];
    for (let i = 0; i < 4; i++) stackMeshes[i].visible = i < want;
    heatMesh.visible = (cur === 4 || cur === 5);
    steamOn = (cur === 4 || cur === 5);
    batterMesh.visible = cur < 5;
  }

  mainUI.on("back", "click", () => {
    if (cur > 0) {
      running = false;
      cur--;
      renderStep();
    }
  });
  mainUI.on("next", "click", () => {
    if (cur < steps.length - 1) {
      running = false;
      cur++;
      renderStep();
    }
  });
  mainUI.on("startbtn", "click", () => {
    const s = steps[cur];
    if (s.secs === 0) return;
    if (rems[cur] <= 0) {
      rems[cur] = s.secs;
      running = true;
    } else {
      running = !running;
    }
    mainUI.set("starttext", { text: running ? "Pause" : "Start" });
    const left = Math.ceil(rems[cur]);
    mainUI.set("timerlabel", { text: running ? fmt(left) + " remaining..." : fmt(left) + " paused - press Start" });
    lastSec = left;
  });
  mainUI.on("resetbtn", "click", () => {
    const s = steps[cur];
    if (s.secs === 0) return;
    rems[cur] = s.secs;
    running = false;
    mainUI.set("starttext", { text: "Start" });
    mainUI.set("timerlabel", { text: fmt(s.secs) + " left - press Start" });
    lastSec = s.secs;
  });

  renderStep();

  return {
    root,
    update(time, delta) {
      if (delta > 0.1) delta = 0.1;
      // timer
      if (running) {
        const secs = steps[cur].secs;
        if (secs > 0) {
          rems[cur] -= delta;
          if (rems[cur] <= 0) {
            rems[cur] = 0;
            running = false;
            mainUI.set("starttext", { text: "Start" });
            mainUI.set("timerlabel", { text: "Time is up! Well done!" });
          } else {
            const sc = Math.ceil(rems[cur]);
            if (sc !== lastSec) {
              lastSec = sc;
              mainUI.set("timerlabel", { text: fmt(sc) + " remaining..." });
            }
          }
        } else {
          running = false;
        }
      }
      // flip animation
      if (flipT < 1 && !isGrabbed(pancake)) {
        flipT += delta / 0.6;
        if (flipT >= 1) {
          flipT = 1;
          pancake.rotation.x = 0;
          pancake.position.y = flipBaseY;
        } else {
          pancake.rotation.x = flipT * Math.PI;
          pancake.position.y = flipBaseY + Math.sin(flipT * Math.PI) * 0.06;
        }
      }
      // pancake color by doneness
      let done = 0;
      if (cur < 4) done = 0;
      else if (cur === 4) {
        const t = steps[4].secs;
        done = t > 0 ? (1 - rems[4] / t) * 0.6 : 0.6;
      } else if (cur === 5) {
        const t = steps[5].secs;
        const p = t > 0 ? 1 - rems[5] / t : 1;
        done = 0.6 + p * 0.4;
      } else done = 1;
      if (done < 0) done = 0;
      if (done > 1) done = 1;
      tmpCol.copy(rawCol).lerp(goldCol, done);
      pancakeMat.color.copy(tmpCol);
      // steam
      for (let i = 0; i < 3; i++) {
        const m = steams[i];
        m.visible = steamOn;
        if (steamOn) {
          const ph = phases[i];
          const h = (time * 0.04 + ph) % 0.09;
          m.position.set(
            pancake.position.x + Math.sin(time * 2 + i * 2.1) * 0.012,
            pancake.position.y + 0.02 + h,
            pancake.position.z + Math.cos(time * 1.7 + i) * 0.01
          );
        }
      }
      // gentle batter wobble when bowl held
      if (isGrabbed(bowlGroup)) {
        batterMesh.position.y = 0.022 + Math.sin(time * 6) * 0.001;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const LMIN = 0.12;
  const LMAX = 0.32;
  const TRACK_X = -0.04;
  const TRACK_Z = 0.02;
  const TRACK_Y0 = 0.03;
  const TRACK_Y1 = 0.23;
  const PIVOT = { x: -0.18, y: 0.38, z: -0.15 };
  const AMP = 0.45;

  let Lcur = 0.22;
  let Ltgt = 0.22;
  let grav = 9.81;
  let gravName = "Earth";
  let phase = 0;
  let prevCycle = 0;
  let paused = false;
  let swingCount = 0;
  let uiTimer = 1;

  const histT = new Float32Array(10);
  const histG = new Float32Array(10);
  let histN = 0;

  function periodFor(L, g) {
    return 2 * Math.PI * Math.sqrt(L / g);
  }
  function clamp(v, a, b) {
    return v < a ? a : (v > b ? b : v);
  }

  // ----- stand -----
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7, metalness: 0.3 });
  const steelMat = new THREE.MeshStandardMaterial({ color: 0x8a919c, roughness: 0.4, metalness: 0.7 });
  const brassMat = new THREE.MeshStandardMaterial({ color: 0xd9a441, roughness: 0.35, metalness: 0.7 });

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.012, 0.09), darkMat);
  base.position.set(-0.18, 0.006, -0.15);
  root.add(base);

  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.006, 0.006, 0.38, 12), steelMat);
  pole.position.set(-0.24, 0.19, -0.15);
  root.add(pole);

  const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.005, 0.005, 0.07, 12), steelMat);
  arm.rotation.z = Math.PI / 2;
  arm.position.set(-0.21, 0.38, -0.15);
  root.add(arm);

  const pivotCap = new THREE.Mesh(new THREE.SphereGeometry(0.012, 20, 12), brassMat);
  pivotCap.position.set(PIVOT.x, PIVOT.y, PIVOT.z);
  root.add(pivotCap);

  // protractor arc below pivot
  const arc = new THREE.Mesh(
    new THREE.TorusGeometry(0.10, 0.0016, 6, 32, 1.047),
    new THREE.MeshStandardMaterial({ color: 0x5a626e, roughness: 0.6 })
  );
  arc.position.set(PIVOT.x, PIVOT.y, PIVOT.z);
  arc.rotation.z = 4.18879;
  root.add(arc);

  // ----- pendulum string + bob -----
  const stringMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(0.0025, 0.0025, 1, 8),
    new THREE.MeshStandardMaterial({ color: 0xd7dbe2, roughness: 0.5 })
  );
  root.add(stringMesh);

  const bob = new THREE.Mesh(
    new THREE.SphereGeometry(0.025, 28, 14),
    new THREE.MeshStandardMaterial({ color: 0xd9a441, roughness: 0.3, metalness: 0.75 })
  );
  bob.name = "Pendulum Bob";
  root.add(bob);

  // ----- length slider track + knob (grabbable) -----
  const track = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.20, 10), darkMat);
  track.position.set(TRACK_X, 0.13, TRACK_Z);
  root.add(track);

  const trackBase = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.008, 0.05), darkMat);
  trackBase.position.set(TRACK_X, 0.004, TRACK_Z);
  root.add(trackBase);

  const knobGeo = new THREE.SphereGeometry(0.016, 24, 14);
  const knobMat = new THREE.MeshStandardMaterial({ color: 0xd9a441, roughness: 0.3, metalness: 0.6, emissive: 0x664400, emissiveIntensity: 0.25 });
  const knob = new THREE.Mesh(knobGeo, knobMat);
  knob.name = "Length Knob";
  knob.position.set(TRACK_X, TRACK_Y0 + (Lcur - LMIN) / (LMAX - LMIN) * (TRACK_Y1 - TRACK_Y0), TRACK_Z);
  root.add(knob);

  // ----- gravity planets (grabbable + pressable) -----
  const moonMat = new THREE.MeshStandardMaterial({ color: 0xb8bcc4, roughness: 0.8, emissive: 0x555555, emissiveIntensity: 0.0 });
  const earthMat = new THREE.MeshStandardMaterial({ color: 0x2f6fdb, roughness: 0.55, emissive: 0x1133aa, emissiveIntensity: 0.6 });
  const marsMat = new THREE.MeshStandardMaterial({ color: 0xd95f2b, roughness: 0.7, emissive: 0x662200, emissiveIntensity: 0.0 });
  const planetGeo = new THREE.SphereGeometry(0.022, 24, 14);

  const moon = new THREE.Mesh(planetGeo, moonMat);
  moon.name = "Moon";
  moon.position.set(0.0, 0.022, 0.12);
  root.add(moon);

  const earth = new THREE.Mesh(planetGeo, earthMat);
  earth.name = "Earth";
  earth.position.set(0.07, 0.022, 0.12);
  root.add(earth);

  const mars = new THREE.Mesh(planetGeo, marsMat);
  mars.name = "Mars";
  mars.position.set(0.14, 0.022, 0.12);
  root.add(mars);

  // ----- 3D bar chart -----
  const boardMat = new THREE.MeshStandardMaterial({ color: 0x1a1d22, roughness: 0.9 });
  const board = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.14, 0.005), boardMat);
  board.position.set(0.10, 0.07, -0.155);
  root.add(board);

  const chartBase = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.006, 0.035), darkMat);
  chartBase.position.set(0.10, 0.003, -0.14);
  root.add(chartBase);

  const barGeo = new THREE.BoxGeometry(0.018, 1, 0.018);
  barGeo.translate(0, 0.5, 0);
  const barMeshes = [];
  const startX = 0.10 - (9 * 0.025) / 2;
  for (let i = 0; i < 10; i++) {
    const m = new THREE.MeshStandardMaterial({ color: 0x35a0ff, roughness: 0.5 });
    const b = new THREE.Mesh(barGeo, m);
    b.position.set(startX + i * 0.025, 0.006, -0.14);
    b.scale.y = 0.001;
    b.visible = false;
    root.add(b);
    barMeshes.push(b);
  }

  // ----- UI panel -----
  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: center; }
      .period { color: #7dd7ff; font-size: 32px; font-weight: 700; text-align: center; }
      .sub { color: #d7dbe2; font-size: 21px; text-align: center; }
      .hist { color: #ffd166; font-size: 20px; text-align: center; }
      .hint { color: #9aa0ab; font-size: 19px; text-align: center; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .rowlabel { color: #ffffff; font-size: 22px; font-weight: 700; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .btng { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #333a44; }
      .btng-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .btn2 { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #3a404b; }
      .btn2-text { color: #ffffff; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Pendulum Lab</span>
      <span class="period" id="period">Period: 0.94 s</span>
      <span class="sub" id="detail">Length 22 cm | Gravity 9.81 m/s2 Earth</span>
      <div class="row">
        <span class="rowlabel">Length</span>
        <button class="btn" id="lenMinus"><span class="btn-text">- 2 cm</span></button>
        <button class="btn" id="lenPlus"><span class="btn-text">+ 2 cm</span></button>
      </div>
      <div class="row">
        <span class="rowlabel">Gravity</span>
        <button class="btng" id="gMoon"><span class="btng-text">Moon</span></button>
        <button class="btng" id="gEarth"><span class="btng-text">Earth</span></button>
        <button class="btng" id="gMars"><span class="btng-text">Mars</span></button>
      </div>
      <span class="hist" id="hist">History: swinging...</span>
      <span class="hint">Bars behind show last 10 periods. Grab planets for gravity. Drag brass knob for length.</span>
      <div class="row">
        <button class="btn2" id="pauseBtn"><span class="btn2-text" id="pauseLabel">Pause</span></button>
        <button class="btn2" id="resetBtn"><span class="btn2-text">Clear chart</span></button>
      </div>
    </div>`, { width: 0.30, position: [0.22, 0.245, 0.02], rotationY: -0.25 });
  root.add(info.object3D);

  function refreshPlanetGlow() {
    moonMat.emissiveIntensity = gravName === "Moon" ? 0.55 : 0.0;
    earthMat.emissiveIntensity = gravName === "Earth" ? 0.6 : 0.0;
    marsMat.emissiveIntensity = gravName === "Mars" ? 0.55 : 0.0;
  }

  function refreshGravityButtons() {
    info.set("gMoon", { backgroundColor: gravName === "Moon" ? "#2f6fdb" : "#333a44" });
    info.set("gEarth", { backgroundColor: gravName === "Earth" ? "#2f6fdb" : "#333a44" });
    info.set("gMars", { backgroundColor: gravName === "Mars" ? "#2f6fdb" : "#333a44" });
  }

  function setGravity(name, val) {
    gravName = name;
    grav = val;
    refreshPlanetGlow();
    refreshGravityButtons();
    const cm = Math.round(Lcur * 100);
    info.set("detail", { text: "Length " + cm + " cm | Gravity " + val.toFixed(2) + " m/s2 " + name + " | Swings " + swingCount });
  }

  function adjustLength(d) {
    Ltgt = clamp(Ltgt + d, LMIN, LMAX);
  }

  function updateBarsAndHist() {
    for (let i = 0; i < 10; i++) {
      const b = barMeshes[i];
      if (i < histN) {
        const T = histT[i];
        let h = 0.015 + (T / 3.0) * 0.12;
        if (h > 0.135) h = 0.135;
        b.scale.y = h;
        b.visible = true;
        const gv = histG[i];
        if (Math.abs(gv - 1.62) < 0.1) b.material.color.setHex(0xb8bcc4);
        else if (Math.abs(gv - 3.71) < 0.1) b.material.color.setHex(0xe06a2b);
        else b.material.color.setHex(0x35a0ff);
      } else {
        b.scale.y = 0.001;
        b.visible = false;
      }
    }
    if (histN === 0) {
      info.set("hist", { text: "History: swinging..." });
    } else {
      let s = "Last " + histN + ": ";
      for (let i = 0; i < histN; i++) {
        s += histT[i].toFixed(2);
        if (i < histN - 1) s += " ";
      }
      info.set("hist", { text: s });
    }
  }

  function recordPeriod(T) {
    if (histN < 10) {
      histT[histN] = T;
      histG[histN] = grav;
      histN++;
    } else {
      for (let i = 0; i < 9; i++) {
        histT[i] = histT[i + 1];
        histG[i] = histG[i + 1];
      }
      histT[9] = T;
      histG[9] = grav;
    }
    swingCount++;
    updateBarsAndHist();
    const cm = Math.round(Lcur * 100);
    info.set("detail", { text: "Length " + cm + " cm | Gravity " + grav.toFixed(2) + " m/s2 " + gravName + " | Swings " + swingCount });
  }

  info.on("lenMinus", "click", () => adjustLength(-0.02));
  info.on("lenPlus", "click", () => adjustLength(0.02));
  info.on("gMoon", "click", () => setGravity("Moon", 1.62));
  info.on("gEarth", "click", () => setGravity("Earth", 9.81));
  info.on("gMars", "click", () => setGravity("Mars", 3.71));
  info.on("pauseBtn", "click", () => {
    paused = !paused;
    info.set("pauseLabel", { text: paused ? "Resume" : "Pause" });
  });
  info.on("resetBtn", "click", () => {
    histN = 0;
    updateBarsAndHist();
  });

  traits(moon, { grab: true, onPress: () => setGravity("Moon", 1.62) });
  traits(earth, { grab: true, onPress: () => setGravity("Earth", 9.81) });
  traits(mars, { grab: true, onPress: () => setGravity("Mars", 3.71) });
  traits(knob, { grab: true });

  refreshPlanetGlow();
  refreshGravityButtons();
  updateBarsAndHist();
  info.set("period", { text: "Period: " + periodFor(Lcur, grav).toFixed(2) + " s" });

  return {
    root,
    update(time, delta) {
      if (delta > 0.05) delta = 0.05;
      if (delta < 0) delta = 0;

      // length handling with grab slider
      if (isGrabbed(knob)) {
        knob.position.x = TRACK_X;
        knob.position.z = TRACK_Z;
        const y = clamp(knob.position.y, TRACK_Y0, TRACK_Y1);
        knob.position.y = y;
        const L = LMIN + (y - TRACK_Y0) / (TRACK_Y1 - TRACK_Y0) * (LMAX - LMIN);
        Lcur = L;
        Ltgt = L;
      } else {
        const diff = Ltgt - Lcur;
        const step = 0.04 * delta;
        if (diff > step) Lcur += step;
        else if (diff < -step) Lcur -= step;
        else Lcur = Ltgt;
        knob.position.x = TRACK_X;
        knob.position.z = TRACK_Z;
        knob.position.y = TRACK_Y0 + (Lcur - LMIN) / (LMAX - LMIN) * (TRACK_Y1 - TRACK_Y0);
      }

      if (!paused) {
        const omega = Math.sqrt(grav / Lcur);
        phase += omega * delta;
        const cycle = Math.floor(phase / (Math.PI * 2));
        if (cycle > prevCycle) {
          const T = periodFor(Lcur, grav);
          recordPeriod(T);
          prevCycle = cycle;
        }
      }

      const theta = AMP * Math.cos(phase);
      const s = Math.sin(theta);
      const c = Math.cos(theta);
      const bx = PIVOT.x + Lcur * s;
      const by = PIVOT.y - Lcur * c;
      bob.position.set(bx, by, PIVOT.z);
      stringMesh.position.set(PIVOT.x + Lcur * s * 0.5, PIVOT.y - Lcur * c * 0.5, PIVOT.z);
      stringMesh.scale.set(1, Lcur, 1);
      stringMesh.rotation.z = theta;

      uiTimer += delta;
      if (uiTimer > 0.15) {
        uiTimer = 0;
        const T = periodFor(Lcur, grav);
        info.set("period", { text: (paused ? "Paused | " : "") + "Period: " + T.toFixed(2) + " s" });
        const cm = Math.round(Lcur * 100);
        info.set("detail", { text: "Length " + cm + " cm | Gravity " + grav.toFixed(2) + " m/s2 " + gravName + " | Swings " + swingCount });
      }
    }
  };
}

