  const dialGeo = new THREE.CylinderGeometry(0.022, 0.022, 0.014, 28);
  dialGeo.rotateX(Math.PI / 2);
  const dial = new THREE.Mesh(dialGeo, dialMat);
  dial.position.set(0.06, 0.045, 0.108);
  dial.name = 'ThermostatDial';
  root.add(dial);
  const pointer = new THREE.Mesh(new THREE.BoxGeometry(0.006, 0.016, 0.006), pointerMat);
  pointer.position.set(0, 0.011, 0.009);
  dial.add(pointer);

  const upBtn = new THREE.Mesh(new THREE.BoxGeometry(0.030, 0.018, 0.022), upMat);
  upBtn.position.set(0.005, 0.018, 0.10); upBtn.name = 'TempUp'; root.add(upBtn);
  const downBtn = new THREE.Mesh(new THREE.BoxGeometry(0.030, 0.018, 0.022), downMat);
  downBtn.position.set(0.115, 0.018, 0.10); downBtn.name = 'TempDown'; root.add(downBtn);

  // grabbable remote puck
  const remote = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 0.022, 24), remoteMat);
  remote.position.set(-0.02, 0.021, 0.16);
