  root.add(remote);
  const remoteDot = new THREE.Mesh(new THREE.SphereGeometry(0.009, 16, 10),
    new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xffffff, emissiveIntensity: 0.6 }));
  remoteDot.position.set(0, 0.013, 0);
  remote.add(remoteDot);

  // ---------- energy chart 3D ----------
  box(0.28, 0.01, 0.07, darkMat, 0.08, 0.005, -0.15);
  box(0.28, 0.14, 0.005, new THREE.MeshStandardMaterial({ color: 0x343a44, roughness: 0.9 }), 0.08, 0.07, -0.186);
  const barGeo = new THREE.BoxGeometry(0.032, 1, 0.045);
  const barColors = [0x3fb2ff, 0x3fb2ff, 0x3fb2ff, 0x3fb2ff, 0xff9f43, 0xff5a5a];
  const bars = [];
  const barMats = [];
  for (let i = 0; i < 6; i++) {
    const h = kwh[i] / 2.1 * 0.11 + 0.01;
    const mat = new THREE.MeshStandardMaterial({ color: barColors[i], emissive: barColors[i], emissiveIntensity: 0.25, roughness: 0.5 });
    const b = new THREE.Mesh(barGeo, mat);
    const x = -0.0275 + i * 0.043;
    b.position.set(x, 0.01 + h / 2, -0.15);
    b.scale.y = h;
    b.name = 'EnergyBar' + i;
    root.add(b);
    bars.push(b); barMats.push(mat);
  }

  // ---------- UI panel ----------
  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .hint { color: #aeb6c2; font-size: 22px; }
      .sect { color: #8fd0ff; font-size: 22px; font-weight: 700; }
      .row { flex-direction: row; align-items: center; justify-content: space-between; gap: 8px; }
      .room { color: #ffffff; font-size: 22px; }
      .val { color: #ffd27a; font-size: 22px; font-weight: 700; }
      .tval { color: #8ff0b3; font-size: 26px; font-weight: 700; }
      .btn { padding-top: 6px; padding-bottom: 6px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .sbtn { padding-top: 8px; padding-bottom: 8px; padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #343a44; }
      .sbtn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .foot { color: #aeb6c2; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Smart Home</span>
      <span class="hint">Pinch a lamp to toggle. Press bars for detail.</span>
      <span class="sect">LIGHTS</span>
