      <div class="row"><span class="room">Bedroom</span><button class="btn" id="bedDown"><span class="btn-text">-</span></button><span class="val" id="bedVal">40%</span><button class="btn" id="bedUp"><span class="btn-text">+</span></button></div>
      <div class="row"><span class="room">Kitchen</span><button class="btn" id="kitDown"><span class="btn-text">-</span></button><span class="val" id="kitVal">100%</span><button class="btn" id="kitUp"><span class="btn-text">+</span></button></div>
      <span class="sect">THERMOSTAT</span>
      <div class="row"><button class="btn" id="thDown"><span class="btn-text">-</span></button><span class="tval" id="thVal">21 C</span><button class="btn" id="thUp"><span class="btn-text">+</span></button></div>
      <span class="sect">SCENES</span>
      <div class="row"><button class="sbtn" id="scMovie"><span class="sbtn-text">Movie</span></button><button class="sbtn" id="scDinner"><span class="sbtn-text">Dinner</span></button><button class="sbtn" id="scAway"><span class="sbtn-text">Away</span></button></div>
      <span class="sect">TODAY ENERGY</span>
      <span class="body" id="energyDetail">16-20h: 2.1 kWh evening peak</span>
      <span class="foot" id="powerLine">Now 0.9 kW - Total 7.2 kWh</span>
      <span class="foot" id="sceneLine">Scene: Manual</span>
    </div>`, { width: 0.30, position: [0.22, 0.32, 0.02], rotationY: -0.30 });
  root.add(panel.object3D);

  function pct(v) { return Math.round(v * 100) + '%'; }
  function powerKW() {
    const l = state.living + state.bedroom + state.kitchen;
    let p = 0.25 + l * 0.18;
    if (state.thermo > 18) p += (state.thermo - 18) * 0.12;
    else p += (18 - state.thermo) * 0.06;
    return p;
  }
  function totalKwh() { let s = 0; for (let i = 0; i < 6; i++) s += kwh[i]; return s; }

  let dialTarget = 0;
  function calcDialTarget() {
    const t = (state.thermo - 15) / (28 - 15);
    dialTarget = -2.356 + t * 4.712;
  }
  calcDialTarget();

  function refreshLights() {
    lampLiving.mat.emissiveIntensity = 0.05 + state.living * 1.8;
    lampBed.mat.emissiveIntensity = 0.05 + state.bedroom * 1.8;
    lampKit.mat.emissiveIntensity = 0.05 + state.kitchen * 1.8;
