    spillBed.material.opacity = state.bedroom * 0.35;
    spillKit.material.opacity = state.kitchen * 0.35;
    panel.set('livVal', { text: pct(state.living) });
    panel.set('bedVal', { text: pct(state.bedroom) });
    panel.set('kitVal', { text: pct(state.kitchen) });
    refreshPower();
  }
  function refreshThermo() {
    calcDialTarget();
    panel.set('thVal', { text: state.thermo + ' C' });
    refreshPower();
  }
  function refreshPower() {
    panel.set('powerLine', { text: 'Now ' + powerKW().toFixed(1) + ' kW - Total ' + totalKwh().toFixed(1) + ' kWh' });
  }
  function refreshEnergy() {
    panel.set('energyDetail', { text: times[state.selected] + ': ' + kwh[state.selected].toFixed(1) + ' kWh ' + notes[state.selected] });
  }
  function refreshScene() {
    panel.set('sceneLine', { text: 'Scene: ' + state.scene });
    panel.set('scMovie', { backgroundColor: state.scene === 'Movie' ? '#2f6fdb' : '#343a44' });
    panel.set('scDinner', { backgroundColor: state.scene === 'Dinner' ? '#2f6fdb' : '#343a44' });
    panel.set('scAway', { backgroundColor: state.scene === 'Away' ? '#2f6fdb' : '#343a44' });
  }
  function markManual() { state.scene = 'Manual'; refreshScene(); }

  function changeLight(key, d) {
    let v = state[key] + d;
    if (v < 0) v = 0; if (v > 1) v = 1;
    state[key] = Math.round(v * 4) / 4;
    markManual(); refreshLights();
  }
  function toggleLight(key) {
    state[key] = state[key] > 0.05 ? 0 : 0.75;
    markManual(); refreshLights();
  }
  function changeThermo(d) {
    let v = state.thermo + d;
    if (v < 15) v = 15; if (v > 28) v = 28;
    state.thermo = v;
    markManual(); refreshThermo();
  }
  function applyScene(name) {
    state.scene = name;
    if (name === 'Movie') { state.living = 0.25; state.bedroom = 0; state.kitchen = 0; state.thermo = 22; }
    if (name === 'Dinner') { state.living = 0.75; state.bedroom = 0.25; state.kitchen = 1.0; state.thermo = 21; }
    if (name === 'Away') { state.living = 0; state.bedroom = 0; state.kitchen = 0; state.thermo = 16; }
    refreshLights(); refreshThermo(); refreshScene();
  }

  panel.on('livDown', 'click', () => changeLight('living', -0.25));
  panel.on('livUp', 'click', () => changeLight('living', 0.25));
  panel.on('bedDown', 'click', () => changeLight('bedroom', -0.25));
  panel.on('bedUp', 'click', () => changeLight('bedroom', 0.25));
  panel.on('kitDown', 'click', () => changeLight('kitchen', -0.25));
  panel.on('kitUp', 'click', () => changeLight('kitchen', 0.25));
  panel.on('thDown', 'click', () => changeThermo(-1));
  panel.on('thUp', 'click', () => changeThermo(1));
  panel.on('scMovie', 'click', () => applyScene('Movie'));
  panel.on('scDinner', 'click', () => applyScene('Dinner'));
  panel.on('scAway', 'click', () => applyScene('Away'));

  traits(lampLiving.bulb, { onPress: () => toggleLight('living') });
  traits(lampBed.bulb, { onPress: () => toggleLight('bedroom') });
  traits(lampKit.bulb, { onPress: () => toggleLight('kitchen') });
  traits(upBtn, { onPress: () => changeThermo(1) });
  traits(downBtn, { onPress: () => changeThermo(-1) });
  traits(dial, { onPress: () => changeThermo(1) });

  const sceneOrder = ['Movie', 'Dinner', 'Away'];
  let cycleIdx = 0;
  traits(remote, {
    grab: true,
    onPress: () => { applyScene(sceneOrder[cycleIdx % 3]); cycleIdx++; }
  });

  for (let i = 0; i < 6; i++) {
    const idx = i;
    traits(bars[idx], {
      onPress: () => { state.selected = idx; refreshEnergy(); }
    });
  }

  refreshLights(); refreshThermo(); refreshEnergy(); refreshScene();
  dial.rotation.z = dialTarget;

  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 6);
      let diff = dialTarget - dial.rotation.z;
      dial.rotation.z += diff * k;
      for (let i = 0; i < 6; i++) {
        if (i === state.selected) barMats[i].emissiveIntensity = 0.6 + 0.3 * Math.sin(time * 4);
        else barMats[i].emissiveIntensity = 0.25;
      }
      if (!isGrabbed(remote)) {
        remoteMat.emissiveIntensity = 0.3 + 0.15 * Math.sin(time * 2);
      }
    }
  };
}

