  mats.push(ulnMat);
  const ulnShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.008, 0.12, 16), ulnMat);
  ulna.add(ulnShaft);
  const ulnHook = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.028, 0.02), ulnMat);
  ulnHook.position.set(0, 0.068, -0.004);
  ulna.add(ulnHook);
  const ulnEnd = new THREE.Mesh(new THREE.SphereGeometry(0.011, 20, 12), ulnMat);
  ulnEnd.position.set(0, -0.064, 0);
  ulna.add(ulnEnd);
  root.add(ulna);
  boneGroups.push(ulna);

  // --- Carpals (8 wrist bones) ---
  const carpals = new THREE.Group();
  carpals.name = "Carpals";
  const carMat = boneMaterial();
  mats.push(carMat);
  const carGeo = new THREE.SphereGeometry(0.0078, 16, 12);
  const carX = [-0.0195, -0.0065, 0.0065, 0.0195];
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 4; c++) {
      const m = new THREE.Mesh(carGeo, carMat);
      m.position.set(carX[c], r === 0 ? 0.008 : -0.008, 0);
      m.name = "Carpal";
      carpals.add(m);
    }
  }
  root.add(carpals);
  boneGroups.push(carpals);

  // --- Metacarpals (palm) ---
  const metacarp = new THREE.Group();
  metacarp.name = "Metacarpals";
  const metMat = boneMaterial();
  mats.push(metMat);
  const metGeo = new THREE.CylinderGeometry(0.0055, 0.005, 0.045, 12);
  for (let i = 0; i < 4; i++) {
    const m = new THREE.Mesh(metGeo, metMat);
    m.position.set(carX[i], 0, 0);
    m.name = "Metacarpal";
    metacarp.add(m);
  }
  root.add(metacarp);
  boneGroups.push(metacarp);

  // --- Phalanges (fingers) ---
  const phal = new THREE.Group();
  phal.name = "Phalanges";
  const phaMat = boneMaterial();
  mats.push(phaMat);
  const phaTopGeo = new THREE.CylinderGeometry(0.0045, 0.0042, 0.02, 10);
  const phaLowGeo = new THREE.CylinderGeometry(0.004, 0.0036, 0.016, 10);
  for (let i = 0; i < 4; i++) {
    const a = new THREE.Mesh(phaTopGeo, phaMat);
    a.position.set(carX[i], 0.014, 0);
    a.name = "Phalanx";
    phal.add(a);
    const b = new THREE.Mesh(phaLowGeo, phaMat);
    b.position.set(carX[i], -0.012, 0);
    b.name = "Phalanx";
    phal.add(b);
  }
  root.add(phal);
  boneGroups.push(phal);

  const homes = [
    new THREE.Vector3(0, 0.36, -0.04),
    new THREE.Vector3(-0.024, 0.215, -0.04),
    new THREE.Vector3(0.024, 0.215, -0.04),
    new THREE.Vector3(0, 0.135, -0.04),
    new THREE.Vector3(0, 0.092, -0.04),
    new THREE.Vector3(0, 0.045, -0.04)
  ];
  const exps = [
    new THREE.Vector3(-0.15, 0.22, -0.04),
    new THREE.Vector3(-0.09, 0.22, -0.04),
    new THREE.Vector3(-0.03, 0.22, -0.04),
    new THREE.Vector3(0.03, 0.22, -0.04),
    new THREE.Vector3(0.09, 0.22, -0.04),
    new THREE.Vector3(0.15, 0.22, -0.04)
  ];
  const targets = homes.map((v) => v.clone());
  for (let i = 0; i < boneGroups.length; i++) boneGroups[i].position.copy(homes[i]);
  let auto = false;
  let selected = -1;

  // --- Info panel ---
  const info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .hint { color: #aeb6c2; font-size: 22px; }
      .bone { color: #ffdf9e; font-size: 26px; font-weight: 700; }
      .desc { color: #d7dbe2; font-size: 23px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f6fdb; flex-direction: row; justify-content: center; }
      .btn2 { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #3a404c; flex-direction: row; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Bones of the Arm</span>
      <span class="hint">Pinch a bone to pull it apart. Tap a bone for its story.</span>
      <span class="bone" id="boneName">Tap a bone to begin</span>
      <span class="desc" id="boneDesc">6 parts: humerus, radius, ulna, carpals, metacarpals, phalanges.</span>
      <button class="btn" id="explode"><span class="btn-text">Explode View</span></button>
      <button class="btn2" id="assemble"><span class="btn-text">Reassemble</span></button>
    </div>`, { width: 0.26, position: [-0.27, 0.28, 0.1], rotationY: 0.32 });
  root.add(info.object3D);

  // --- Quiz panel ---
  const quiz = ui(`
    <style>
      .qcard { width: 460px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .qtitle { color: #ffffff; font-size: 30px; font-weight: 700; }
      .qscore { color: #8fd0ff; font-size: 22px; font-weight: 700; }
      .q { color: #ffffff; font-size: 23px; }
      .opt { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2f3540; flex-direction: row; justify-content: center; }
      .opt-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .fb { color: #d7dbe2; font-size: 22px; }
      .next { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2e7d4f; flex-direction: row; justify-content: center; }
      .next-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="qcard">
      <span class="qtitle">Quiz: Test Yourself</span>
      <span class="qscore" id="qScore">Score: 0 / 5</span>
      <span class="q" id="qQuestion">Press Start to try 5 questions.</span>
      <button class="opt" id="opt0"><span class="opt-text" id="opt0t">-</span></button>
      <button class="opt" id="opt1"><span class="opt-text" id="opt1t">-</span></button>
      <button class="opt" id="opt2"><span class="opt-text" id="opt2t">-</span></button>
      <span class="fb" id="qFeedback">Good luck!</span>
      <button class="next" id="qNext"><span class="next-text" id="qNextT">Start Quiz</span></button>
    </div>`, { width: 0.26, position: [0.27, 0.28, 0.1], rotationY: -0.32 });
  root.add(quiz.object3D);

  function selectBone(i) {
    selected = i;
    for (let j = 0; j < mats.length; j++) mats[j].emissiveIntensity = (j === i ? 0.45 : 0);
    info.set("boneName", { text: infos[i].name });
    info.set("boneDesc", { text: infos[i].desc });
  }

  for (let i = 0; i < boneGroups.length; i++) {
    const idx = i;
    traits(boneGroups[i], { grab: true, onPress: () => selectBone(idx) });
  }

  info.on("explode", "click", () => {
    for (let i = 0; i < targets.length; i++) targets[i].copy(exps[i]);
    auto = true;
    info.set("boneName", { text: "Exploded view" });
    info.set("boneDesc", { text: "Bones spread in order: humerus, radius, ulna, carpals, metacarpals, phalanges. Grab any bone, then press Reassemble." });
  });
  info.on("assemble", "click", () => {
    for (let i = 0; i < targets.length; i++) targets[i].copy(homes[i]);
    auto = true;
    info.set("boneName", { text: "Reassembled" });
    info.set("boneDesc", { text: "Arm is back together. Tap any bone to learn what it does." });
  });

  const questions = [
    { q: "Which bone forms the upper arm?", opts: ["Humerus", "Radius", "Ulna"], correct: 0, why: "The humerus runs from shoulder to elbow." },
    { q: "Which forearm bone is on the thumb side?", opts: ["Ulna", "Humerus", "Radius"], correct: 2, why: "The radius is thumb-side and rotates to turn the palm." },
    { q: "Which bone makes the point of your elbow?", opts: ["Radius", "Ulna", "Carpals"], correct: 1, why: "The ulna hook (olecranon) forms the elbow point." },
    { q: "How many small bones form the wrist?", opts: ["5", "8", "14"], correct: 1, why: "8 carpals in two rows make the wrist flexible." },
    { q: "What are the finger bones called?", opts: ["Metacarpals", "Phalanges", "Carpals"], correct: 1, why: "14 phalanges bend the fingers; metacarpals are the palm." }
  ];
  let qIndex = 0, qScore = 0, qAnswered = false, qStarted = false, qFinished = false;

  function updateScore() {
    quiz.set("qScore", { text: "Score: " + qScore + " / 5" });
  }
  function resetOptColors() {
    quiz.set("opt0", { backgroundColor: "#2f3540" });
    quiz.set("opt1", { backgroundColor: "#2f3540" });
    quiz.set("opt2", { backgroundColor: "#2f3540" });
  }
  function showQ() {
    const qq = questions[qIndex];
    quiz.set("qQuestion", { text: "Q" + (qIndex + 1) + "/5: " + qq.q });
    quiz.set("opt0t", { text: qq.opts[0] });
    quiz.set("opt1t", { text: qq.opts[1] });
    quiz.set("opt2t", { text: qq.opts[2] });
    quiz.set("qFeedback", { text: "Tap an answer.", color: "#d7dbe2" });
    quiz.set("qNextT", { text: qIndex === 4 ? "Finish" : "Next" });
    resetOptColors();
  }
  function answer(k) {
    if (!qStarted || qFinished || qAnswered) return;
    const qq = questions[qIndex];
    if (k === qq.correct) {
      qScore++;
      quiz.set("qFeedback", { text: "Correct! " + qq.why, color: "#7ee2a8" });
    } else {
      quiz.set("qFeedback", { text: "Not quite. " + qq.why + " Correct: " + qq.opts[qq.correct] + ".", color: "#ff9a9a" });
    }
    for (let i = 0; i < 3; i++) {
      let col = "#2f3540";
      if (i === qq.correct) col = "#2e7d4f";
      else if (i === k) col = "#8a3a3a";
      quiz.set("opt" + i, { backgroundColor: col });
    }
    // highlight the right bone in 3D for Q1, Q2, Q3, Q5
    if (qIndex === 0) selectBone(k === 0 ? 0 : 0);
    if (qIndex === 1 && k === 2) selectBone(1);
    if (qIndex === 2 && k === 1) selectBone(2);
    qAnswered = true;
    updateScore();
    if (qIndex === 4) quiz.set("qNextT", { text: "See Result" });
  }

  quiz.on("opt0", "click", () => answer(0));
  quiz.on("opt1", "click", () => answer(1));
  quiz.on("opt2", "click", () => answer(2));
  quiz.on("qNext", "click", () => {
    if (!qStarted) {
      qStarted = true; qFinished = false; qIndex = 0; qScore = 0; qAnswered = false;
      updateScore(); showQ(); return;
    }
    if (qFinished) {
      qIndex = 0; qScore = 0; qAnswered = false; qFinished = false;
      updateScore(); showQ(); return;
    }
    if (!qAnswered) {
      quiz.set("qFeedback", { text: "Pick an answer above first.", color: "#ffd27d" });
      return;
    }
    qIndex++;
    if (qIndex >= 5) {
      qFinished = true;
      let msg = "Quiz done! Final score " + qScore + " / 5. ";
      if (qScore >= 4) msg += "Great work!";
      else if (qScore >= 3) msg += "Good try - review and retry.";
      else msg += "Keep exploring the bones and retry.";
      quiz.set("qQuestion", { text: msg });
      quiz.set("opt0t", { text: "-" });
      quiz.set("opt1t", { text: "-" });
      quiz.set("opt2t", { text: "-" });
      quiz.set("qFeedback", { text: "Press Restart to try again.", color: "#d7dbe2" });
      quiz.set("qNextT", { text: "Restart Quiz" });
      updateScore();
      return;
    }
    qAnswered = false;
    showQ();
  });

  return {
    root,
    update(time, delta) {
      if (auto) {
        const k = Math.min(1, delta * 3.5);
        let allClose = true;
        for (let i = 0; i < boneGroups.length; i++) {
          const g = boneGroups[i];
          if (isGrabbed(g)) {
            targets[i].copy(g.position);
            allClose = false;
            continue;
          }
          g.position.lerp(targets[i], k);
          if (g.position.distanceToSquared(targets[i]) > 0.000004) allClose = false;
        }
        if (allClose) auto = false;
      } else {
        for (let i = 0; i < boneGroups.length; i++) {
          if (isGrabbed(boneGroups[i])) targets[i].copy(boneGroups[i].position);
        }
      }
      if (selected >= 0 && selected < mats.length) {
        mats[selected].emissiveIntensity = 0.35 + 0.15 * Math.sin(time * 3.0);
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Data ----------
  const landmarks = [
    { name: "Eiffel Tower", color: 0xe14b4b, visit: 2.5, visitLabel: "Visit: 2.5 h",
