  // Real-ish walking minutes between each pair (symmetric)
  const WALK = [
    [0, 25, 30, 20, 45, 50],
    [25, 0, 30, 30, 45, 35],
    [30, 30, 0, 12, 20, 30],
    [20, 30, 12, 0, 25, 35],
    [45, 45, 20, 25, 35, 0],
    [50, 35, 30, 35, 35, 0]
  ];
  // Fix symmetric entry typo: keep symmetric
  WALK[4][5] = 35;
  const positions = [
    [-0.20, -0.005],
    [-0.18, -0.185],
    [-0.02, -0.125],
    [-0.085, -0.045],
    [0.12, -0.075],
    [0.09, -0.205]
  ];
  const MAX_PER_DAY = 4;

  let selected = 0;
  const days = [[], [], []];
  const dayNames = ["Day 1", "Day 2", "Day 3"];

  function walkBetween(a, b) { return WALK[a][b]; }
  function dayWalk(arr) {
    let t = 0;
    for (let i = 1; i < arr.length; i++) t += walkBetween(arr[i - 1], arr[i]);
    return t;
  }
  function dayVisit(arr) {
    let t = 0;
    for (let i = 0; i < arr.length; i++) t += landmarks[arr[i]].visit;
    return t;
  }

  // ---------- Map table ----------
