  }

  // ---------- UI: detail panel ----------
  const detail = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
