      .del { padding-top: 5px; padding-bottom: 5px; padding-left: 8px; padding-right: 8px; border-radius: 8px; background-color: #7a2e2e; }
      .clear { padding-top: 6px; padding-bottom: 6px; padding-left: 10px; padding-right: 10px; border-radius: 8px; background-color: #2a2e35; align-items: center; justify-content: center; }
      .clear-text { color: #aeb6c2; font-size: 20px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">${title}</span>
      <span class="total" id="total">Walk: 0 min</span>
      <span class="sub" id="sub">No stops yet</span>
      <div class="stoprow">
        <span class="sname" id="s0">- empty -</span>
        <button class="sm" id="u0"><span class="sm-text">Up</span></button>
        <button class="sm" id="d0"><span class="sm-text">Dn</span></button>
        <button class="del" id="x0"><span class="sm-text">X</span></button>
      </div>
      <div class="stoprow">
        <span class="sname" id="s1">- empty -</span>
        <button class="sm" id="u1"><span class="sm-text">Up</span></button>
        <button class="sm" id="d1"><span class="sm-text">Dn</span></button>
        <button class="del" id="x1"><span class="sm-text">X</span></button>
      </div>
      <div class="stoprow">
        <span class="sname" id="s2">- empty -</span>
        <button class="sm" id="u2"><span class="sm-text">Up</span></button>
        <button class="sm" id="d2"><span class="sm-text">Dn</span></button>
        <button class="del" id="x2"><span class="sm-text">X</span></button>
      </div>
      <div class="stoprow">
        <span class="sname" id="s3">- empty -</span>
        <button class="sm" id="u3"><span class="sm-text">Up</span></button>
        <button class="sm" id="d3"><span class="sm-text">Dn</span></button>
        <button class="del" id="x3"><span class="sm-text">X</span></button>
      </div>
      <button class="clear" id="clear"><span class="clear-text">Clear day</span></button>
    </div>`;
  }

  const dayHandles = [];
  const dayPos = [
    [-0.28, 0.20, 0.02],
    [0, 0.19, 0.06],
    [0.28, 0.20, 0.02]
  ];
  const dayRot = [0.35, 0, -0.35];
  for (let d = 0; d < 3; d++) {
    const h = ui(dayPanelMarkup(dayNames[d]), { width: 0.26, position: dayPos[d], rotationY: dayRot[d] });
    root.add(h.object3D);
    dayHandles.push(h);
  }

  // ---------- Render functions ----------
  function renderDetail(msg) {
    const L = landmarks[selected];
    detail.set("d-title", { text: L.name });
    detail.set("d-desc", { text: L.desc });
    detail.set("d-meta", { text: L.visitLabel + " - tap + Day to add" });
    if (msg !== undefined) detail.set("d-msg", { text: msg });
    for (let i = 0; i < 6; i++) {
      const on = (i === selected);
      heads[i].material.emissiveIntensity = on ? 0.95 : 0.25;
      rings[i].visible = on;
    }
  }

  function renderDays() {
    for (let d = 0; d < 3; d++) {
      const h = dayHandles[d];
      const arr = days[d];
      for (let s = 0; s < MAX_PER_DAY; s++) {
        if (s < arr.length) {
          const li = arr[s];
          h.set("s" + s, { text: (s + 1) + ". " + landmarks[li].name });
        } else {
          h.set("s" + s, { text: "- empty -" });
        }
      }
      const w = dayWalk(arr);
      const v = dayVisit(arr);
      h.set("total", { text: "Walk: " + w + " min" });
      if (arr.length === 0) h.set("sub", { text: "No stops yet" });
      else if (arr.length === 1) h.set("sub", { text: "1 stop - Visit " + v + " h" });
      else h.set("sub", { text: arr.length + " stops - Visit " + v + " h" });
    }
  }

  function addToDay(d) {
    if (selected === null || selected === undefined) return;
    const arr = days[d];
    const nm = landmarks[selected].name;
    if (arr.indexOf(selected) !== -1) {
      detail.set("d-msg", { text: nm + " is already in " + dayNames[d] });
      return;
    }
    if (arr.length >= MAX_PER_DAY) {
      detail.set("d-msg", { text: dayNames[d] + " is full (max 4). Remove one." });
      return;
    }
    arr.push(selected);
    detail.set("d-msg", { text: "Added " + nm + " to " + dayNames[d] });
    renderDays();
  }

  function moveStop(d, s, dir) {
    const arr = days[d];
    const t = s + dir;
    if (s < 0 || s >= arr.length) return;
    if (t < 0 || t >= arr.length) return;
    const tmp = arr[s];
    arr[s] = arr[t];
    arr[t] = tmp;
    renderDays();
  }

  function removeStop(d, s) {
    const arr = days[d];
    if (s < 0 || s >= arr.length) return;
    arr.splice(s, 1);
    renderDays();
  }

  // ---------- Events ----------
  function select(i) {
    selected = i;
    renderDetail("Selected " + landmarks[i].name + " - add it to a day");
  }
  for (let i = 0; i < 6; i++) {
    const idx = i;
    traits(pins[i], {
      grab: true,
      onPress: () => select(idx)
    });
  }

  detail.on("add1", "click", () => addToDay(0));
  detail.on("add2", "click", () => addToDay(1));
  detail.on("add3", "click", () => addToDay(2));

  for (let d = 0; d < 3; d++) {
    const dd = d;
    for (let s = 0; s < MAX_PER_DAY; s++) {
      const ss = s;
      dayHandles[d].on("u" + s, "click", () => moveStop(dd, ss, -1));
      dayHandles[d].on("d" + s, "click", () => moveStop(dd, ss, 1));
      dayHandles[d].on("x" + s, "click", () => removeStop(dd, ss));
    }
    dayHandles[d].on("clear", "click", () => { days[dd].length = 0; renderDays(); });
  }

  renderDetail("Tap a pin - then press + Day 1, 2 or 3");
  renderDays();

  return {
    root,
    update(time) {
      for (let i = 0; i < 6; i++) {
        if (isGrabbed(pins[i])) continue;
        const on = (i === selected);
        const s = on ? 1 + 0.12 * Math.sin(time * 3.2) : 1;
        heads[i].scale.set(s, s, s);
      }
      for (let d = 0; d < 3; d++) {
        const arr = days[d];
        const line = routeLines[d];
        const pos = routeArrays[d];
        if (arr.length < 2) {
          line.visible = false;
          line.geometry.setDrawRange(0, 0);
          continue;
        }
        for (let k = 0; k < arr.length; k++) {
          const pin = pins[arr[k]];
          pos[k * 3] = pin.position.x;
          pos[k * 3 + 1] = 0.135;
          pos[k * 3 + 2] = pin.position.z;
        }
        line.geometry.attributes.position.needsUpdate = true;
        line.geometry.setDrawRange(0, arr.length);
        line.visible = true;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------- Data ----------
  const cats = [
    { name: 'Housing', color: 0x4da3ff, nov: 1200 },
    { name: 'Food', color: 0xff8a5c, nov: 520 },
    { name: 'Transport', color: 0xffd23f, nov: 280 },
    { name: 'Fun', color: 0xb78cff, nov: 310 },
    { name: 'Utilities', color: 0x4fe3b0, nov: 190 }
  ];
  const monthly = [
    { m: 'Jun', v: [1150, 470, 250, 270, 180] },
    { m: 'Jul', v: [1180, 530, 300, 260, 180] },
    { m: 'Aug', v: [1150, 450, 240, 260, 180] },
    { m: 'Sep', v: [1200, 540, 280, 300, 190] },
    { m: 'Oct', v: [1180, 490, 260, 270, 190] },
    { m: 'Nov', v: [1200, 520, 280, 310, 190] }
  ];
  const totals = monthly.map(r => r.v[0] + r.v[1] + r.v[2] + r.v[3] + r.v[4]);
  let selected = -1;
  const GOAL = 2000;
  let saved = 1250;

  // ---------- Donut chart (Nov spending) ----------
  const donutCx = -0.24, donutCy = 0.28, donutCz = -0.08;
  const innerR = 0.05, outerR = 0.085;
  const novTotal = 2500;
  const slices = [];
  const midAngles = [];
  let acc = Math.PI / 2;
  for (let i = 0; i < cats.length; i++) {
    const share = cats[i].nov / novTotal;
    const tLen = share * Math.PI * 2;
    const gap = 0.035;
    const geo = new THREE.RingGeometry(innerR, outerR, 32, 1, acc + gap * 0.5, Math.max(0.12, tLen - gap));
    const mat = new THREE.MeshStandardMaterial({
      color: cats[i].color, roughness: 0.45, metalness: 0.1,
      side: THREE.DoubleSide, emissive: cats[i].color, emissiveIntensity: 0
    });
    const m = new THREE.Mesh(geo, mat);
    m.name = cats[i].name;
    m.position.set(donutCx, donutCy, donutCz);
    root.add(m);
    slices.push(m);
    midAngles.push(acc + tLen * 0.5);
    acc += tLen;
  }
  const hubGeo = new THREE.CylinderGeometry(0.03, 0.03, 0.02, 24);
  hubGeo.rotateX(Math.PI / 2);
  const hub = new THREE.Mesh(hubGeo, new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.6 }));
  hub.name = 'DonutHub';
  hub.position.set(donutCx, donutCy, donutCz + 0.005);
  root.add(hub);

  // ---------- Bar chart (last 6 months) ----------
  const barBaseY = 0.012, barZ = -0.06;
  const barXs = [-0.07, -0.022, 0.026, 0.074, 0.122, 0.17];
  const plat = new THREE.Mesh(
    new THREE.BoxGeometry(0.30, 0.012, 0.07),
    new THREE.MeshStandardMaterial({ color: 0x24282f, roughness: 0.8 })
  );
  plat.name = 'BarBase';
  plat.position.set(0.05, 0.006, -0.06);
  root.add(plat);
  const barGeo = new THREE.BoxGeometry(0.032, 1, 0.04);
  barGeo.translate(0, 0.5, 0);
  const bars = [];
  for (let i = 0; i < 6; i++) {
    const mat = new THREE.MeshStandardMaterial({ color: 0x5a8fe6, roughness: 0.5 });
    const b = new THREE.Mesh(barGeo, mat);
    b.name = monthly[i].m;
    b.position.set(barXs[i], barBaseY, barZ);
    b.scale.y = 0.15;
    root.add(b);
    bars.push(b);
  }

  // ---------- Savings goal ring ----------
  const savCx = 0.30, savCy = 0.28, savCz = -0.08;
  const bgRing = new THREE.Mesh(
    new THREE.RingGeometry(0.05, 0.066, 48),
    new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.7, side: THREE.DoubleSide })
  );
  bgRing.name = 'SavingsBG';
  bgRing.position.set(savCx, savCy, savCz);
  root.add(bgRing);
  let prog = saved / GOAL;
  const fgRing = new THREE.Mesh(
    new THREE.RingGeometry(0.05, 0.066, 48, 1, Math.PI / 2, prog * Math.PI * 2),
    new THREE.MeshStandardMaterial({ color: 0x4fe3b0, roughness: 0.4, side: THREE.DoubleSide, emissive: 0x4fe3b0, emissiveIntensity: 0.3 })
  );
  fgRing.name = 'SavingsProgress';
  fgRing.position.set(savCx, savCy, savCz + 0.001);
  root.add(fgRing);
  const savHub = new THREE.Mesh(
    new THREE.SphereGeometry(0.018, 20, 12),
    new THREE.MeshStandardMaterial({ color: 0xffd23f, roughness: 0.3, metalness: 0.6, emissive: 0x7a5a00, emissiveIntensity: 0.3 })
  );
  savHub.name = 'SavingsHub';
  savHub.position.set(savCx, savCy, savCz + 0.01);
  root.add(savHub);
  const orbitDot = new THREE.Mesh(
    new THREE.SphereGeometry(0.007, 12, 8),
    new THREE.MeshBasicMaterial({ color: 0x4fe3b0 })
  );
  orbitDot.name = 'OrbitDot';
  orbitDot.position.set(savCx + 0.058, savCy, savCz + 0.01);
  root.add(orbitDot);

  // coin stack showing saved amount
  const coinGeo = new THREE.CylinderGeometry(0.022, 0.022, 0.011, 24);
  const coinMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, roughness: 0.35, metalness: 0.5 });
  const stackCoins = [];
  for (let i = 0; i < 8; i++) {
    const c = new THREE.Mesh(coinGeo, coinMat);
    c.name = 'SavedCoin' + i;
    c.position.set(0.215, 0.018 + i * 0.012, -0.015);
    c.visible = i < 5;
    root.add(c);
    stackCoins.push(c);
  }
  // grabbable deposit coin
  const depositCoin = new THREE.Mesh(
    new THREE.CylinderGeometry(0.026, 0.026, 0.01, 28),
    new THREE.MeshStandardMaterial({ color: 0xffd23f, roughness: 0.3, metalness: 0.55, emissive: 0x6b4d00, emissiveIntensity: 0.4 })
  );
  depositCoin.name = 'Deposit Coin';
  depositCoin.position.set(0.30, 0.02, 0.02);
  root.add(depositCoin);

  // ---------- UI panels ----------
  const mainPanel = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .small { color: #9aa0ad; font-size: 19px; text-align: left; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: flex-start; }
      .btn { width: 144px; padding-top: 8px; padding-bottom: 8px; padding-left: 8px; padding-right: 8px; border-radius: 10px; background-color: #2a2e35; border-color: #3a3f47; border-width: 1px; }
      .btn-text { color: #ffffff; font-size: 19px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Budget Dashboard</span>
      <span class="body" id="totalLabel">Nov spending: $2500</span>
      <span class="body" id="filterLabel">Showing: All categories</span>
      <span class="small">Tap a donut slice to filter bars.</span>
      <div class="row">
        <button class="btn" id="fAll"><span class="btn-text">All</span></button>
        <button class="btn" id="f0"><span class="btn-text">Housing</span></button>
        <button class="btn" id="f1"><span class="btn-text">Food</span></button>
      </div>
      <div class="row">
        <button class="btn" id="f2"><span class="btn-text">Transport</span></button>
        <button class="btn" id="f3"><span class="btn-text">Fun</span></button>
        <button class="btn" id="f4"><span class="btn-text">Utilities</span></button>
      </div>
      <span class="small">Pinch a bar to grab it. Tap bar for exact $.</span>
    </div>`, { width: 0.30, position: [-0.24, 0.085, 0.08], rotationY: 0.28 });
  root.add(mainPanel.object3D);

  const savPanel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 29px; font-weight: 700; text-align: left; }
      .body { color: #d7dbe2; font-size: 22px; text-align: left; }
      .big { color: #4fe3b0; font-size: 26px; font-weight: 700; text-align: left; }
      .small { color: #9aa0ad; font-size: 19px; text-align: left; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px; border-radius: 12px; background-color: #2e9e72; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Savings Goal</span>
      <span class="big" id="goalText">$1250 of $2000</span>
      <span class="body" id="pctText">62 percent - Laptop fund</span>
      <button class="btn" id="deposit"><span class="btn-text">+ Deposit $100</span></button>
      <span class="small">Tap ring or gold coin = deposit.</span>
    </div>`, { width: 0.26, position: [0.30, 0.085, 0.08], rotationY: -0.3 });
  root.add(savPanel.object3D);

  const barPanel = ui(`
    <style>
      .card { width: 560px; flex-direction: column; gap: 6px; padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px; border-radius: 14px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
      .small { color: #9aa0ad; font-size: 19px; text-align: center; }
      .row { flex-direction: row; gap: 6px; align-items: center; justify-content: space-between; }
      .m { color: #9aa0ad; font-size: 18px; text-align: center; }
    </style>
    <div class="card">
      <span class="title" id="barTitle">Last 6 months: All spending</span>
      <span class="small" id="barDetail">Nov total $2500 - tap a bar for month</span>
      <div class="row">
        <span class="m">Jun</span>
        <span class="m">Jul</span>
        <span class="m">Aug</span>
        <span class="m">Sep</span>
        <span class="m">Oct</span>
        <span class="m">Nov</span>
      </div>
    </div>`, { width: 0.36, position: [0.05, 0.36, -0.14], rotationY: 0 });
  root.add(barPanel.object3D);

  // ---------- Logic ----------
  function refreshSavings() {
    const p = Math.min(1, saved / GOAL);
    const len = Math.max(0.06, p * Math.PI * 2);
    const old = fgRing.geometry;
    fgRing.geometry = new THREE.RingGeometry(0.05, 0.066, 48, 1, Math.PI / 2, len);
    old.dispose();
    fgRing.visible = p > 0.005;
    const pct = Math.round((saved / GOAL) * 100);
    savPanel.set('goalText', { text: '$' + saved + ' of $' + GOAL });
    savPanel.set('pctText', { text: pct + ' percent - Laptop fund' });
    const show = Math.min(8, Math.floor(saved / 250));
    for (let i = 0; i < stackCoins.length; i++) stackCoins[i].visible = i < show;
  }

  function applyFilter(idx) {
    selected = idx;
    for (let j = 0; j < slices.length; j++) {
      const mid = midAngles[j];
      const off = (idx === -1 ? 0 : (idx === j ? 0.014 : 0));
      slices[j].position.set(donutCx + Math.cos(mid) * off, donutCy + Math.sin(mid) * off, donutCz);
      slices[j].material.emissiveIntensity = (idx === j ? 0.5 : 0);
    }
    let vals, colHex;
    if (idx === -1) { vals = totals; colHex = 0x5a8fe6; }
    else { vals = monthly.map(r => r.v[idx]); colHex = cats[idx].color; }
    let mx = 1;
    for (let k = 0; k < vals.length; k++) if (vals[k] > mx) mx = vals[k];
    for (let i = 0; i < bars.length; i++) {
      const h = 0.035 + (vals[i] / mx) * 0.145;
      bars[i].scale.y = h;
      bars[i].material.color.setHex(colHex);
      if (!isGrabbed(bars[i])) bars[i].position.set(barXs[i], barBaseY, barZ);
    }
    const label = idx === -1 ? 'All categories' : cats[idx].name;
    mainPanel.set('filterLabel', { text: 'Showing: ' + label });
    barPanel.set('barTitle', { text: 'Last 6 months: ' + (idx === -1 ? 'All spending' : cats[idx].name) });
    if (idx === -1) barPanel.set('barDetail', { text: 'Nov total $2500 - tap a bar for month' });
    else barPanel.set('barDetail', { text: cats[idx].name + ' in Nov $' + cats[idx].nov });
    const ids = ['fAll', 'f0', 'f1', 'f2', 'f3', 'f4'];
    for (let b = 0; b < ids.length; b++) {
      const active = (b === 0 && idx === -1) || (b > 0 && idx === b - 1);
      mainPanel.set(ids[b], { backgroundColor: active ? '#2f6fdb' : '#2a2e35' });
    }
  }

  function onBarPress(i) {
    let txt;
    if (selected === -1) txt = monthly[i].m + ': $' + totals[i] + ' total';
    else txt = monthly[i].m + ' ' + cats[selected].name + ': $' + monthly[i].v[selected];
    barPanel.set('barDetail', { text: txt });
  }

  function doDeposit() {
    saved += 100;
    if (saved > 2400) saved = 2400;
    refreshSavings();
  }

  // initial paint
  applyFilter(-1);
  refreshSavings();

  // ---------- Interactions (direct children of root only) ----------
  for (let s = 0; s < slices.length; s++) {
    const idx = s;
    traits(slices[s], {
      onPress: () => {
        if (selected === idx) applyFilter(-1);
        else applyFilter(idx);
      }
    });
  }
  for (let b = 0; b < bars.length; b++) {
    const bi = b;
    traits(bars[b], { grab: true, onPress: () => onBarPress(bi) });
  }
  traits(depositCoin, { grab: true, onPress: () => doDeposit() });
  traits(fgRing, { onPress: () => doDeposit() });
  traits(bgRing, { onPress: () => doDeposit() });

  mainPanel.on('fAll', 'click', () => applyFilter(-1));
  mainPanel.on('f0', 'click', () => applyFilter(0));
  mainPanel.on('f1', 'click', () => applyFilter(1));
  mainPanel.on('f2', 'click', () => applyFilter(2));
  mainPanel.on('f3', 'click', () => applyFilter(3));
  mainPanel.on('f4', 'click', () => applyFilter(4));
  savPanel.on('deposit', 'click', () => doDeposit());

  return {
    root,
    update(time) {
      orbitDot.position.set(savCx + Math.cos(time * 0.9) * 0.058, savCy + Math.sin(time * 0.9) * 0.058, savCz + 0.012);
      fgRing.material.emissiveIntensity = 0.3 + Math.sin(time * 2.2) * 0.12;
      if (!isGrabbed(depositCoin)) depositCoin.rotation.y = time * 0.8;
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
