    info.set("navRow", { display: step <= 3 ? "flex" : "none" });
    info.set("backBtn", { display: step > 1 && step <= 3 ? "flex" : "none" });

    let nextLabel = "Next ->";
    if (step === 2) nextLabel = "Size ->";
    if (step === 3) nextLabel = "Review ->";
