    for (let i = 0; i < 3; i++) {
      info.set("t" + i, { backgroundColor: ticket === i ? "#2f6fdb" : "#2a2e35" });
      ticketMats[i].emissiveIntensity = ticket === i ? 0.55 : 0.0;
