    if (wsBlocked) {
      info.set("wsWarn", { text: "Too many: max 2. Uncheck one first.", color: "#ff9090" });
    } else if (c === 2) {
      info.set("wsWarn", { text: "2 of 2 picked - full.", color: "#7dffa9" });
    } else {
      info.set("wsWarn", { text: "Picked " + c + " of 2.", color: "#ffd37a" });
    }

    info.set("sizeLabel", { text: sizes[sizeIdx] });
    info.set("sizeHint", { text: "Size " + sizes[sizeIdx] + " - tap - or +. Grab shirt to inspect." });
    const scales = [0.75, 0.85, 1.0, 1.15, 1.3, 1.45];
    shirtTarget = scales[sizeIdx];

    const tText = ticket >= 0 ? ticketFull[ticket] : "none";
    let wText = "none";
