    for (let i = 0; i < 4; i++) if (wsSel[i]) picked.push(workshops[i]);
    if (picked.length > 0) wText = picked.join(", ");
    info.set("revTicket", { text: "Ticket: " + tText });
    info.set("revWork", { text: "Workshops: " + wText });
    info.set("revSize", { text: "Size: " + sizes[sizeIdx] });
    info.set("confirmT", { text: confirmed ? "Confirmed" : "Confirm Registration" });
