    for (let i = 0; i < 4; i++) {
      if (step === 2) wsMeshes[i].visible = true;
      else if (step === 4) wsMeshes[i].visible = wsSel[i];
      else wsMeshes[i].visible = false;
    }
    shirt.visible = step === 3 || step === 4;
    ring.visible = confirmed;
  }

  function selectTicket(i) {
    ticket = i;
    confirmed = false;
    wsBlocked = false;
    refresh();
  }
  function toggleWs(i) {
    if (wsSel[i]) {
      wsSel[i] = false;
      wsBlocked = false;
      confirmed = false;
      refresh();
    } else {
      if (wsCount() >= 2) {
        wsBlocked = true;
        refresh();
      } else {
        wsSel[i] = true;
        wsBlocked = false;
        confirmed = false;
        refresh();
      }
    }
  }

  info.on("t0", "click", () => selectTicket(0));
  info.on("t1", "click", () => selectTicket(1));
  info.on("t2", "click", () => selectTicket(2));
  info.on("w0", "click", () => toggleWs(0));
  info.on("w1", "click", () => toggleWs(1));
  info.on("w2", "click", () => toggleWs(2));
  info.on("w3", "click", () => toggleWs(3));
  info.on("minus", "click", () => {
    sizeIdx = (sizeIdx + sizes.length - 1) % sizes.length;
    confirmed = false;
    refresh();
  });
  info.on("plus", "click", () => {
    sizeIdx = (sizeIdx + 1) % sizes.length;
    confirmed = false;
    refresh();
  });
  info.on("backBtn", "click", () => {
    if (step > 1 && step <= 3) {
      step--;
      wsBlocked = false;
      refresh();
    }
  });
  info.on("nextBtn", "click", () => {
    if (step === 1) {
      if (ticket < 0) {
        info.set("stepSub", { text: "Pick a ticket to continue.", color: "#ff9090" });
        return;
      }
      step = 2;
    } else if (step === 2) {
      step = 3;
    } else if (step === 3) {
      step = 4;
    }
    wsBlocked = false;
    refresh();
  });
  info.on("e1", "click", () => { step = 1; confirmed = false; refresh(); });
  info.on("e2", "click", () => { step = 2; confirmed = false; refresh(); });
  info.on("e3", "click", () => { step = 3; confirmed = false; refresh(); });
  info.on("confirm", "click", () => {
    if (ticket < 0) {
      step = 1;
      refresh();
      return;
    }
    confirmed = true;
    refresh();
  });

  traits(ticketMeshes[0], { grab: true, onPress: () => selectTicket(0) });
  traits(ticketMeshes[1], { grab: true, onPress: () => selectTicket(1) });
  traits(ticketMeshes[2], { grab: true, onPress: () => selectTicket(2) });
  traits(wsMeshes[0], { grab: true, onPress: () => toggleWs(0) });
  traits(wsMeshes[1], { grab: true, onPress: () => toggleWs(1) });
  traits(wsMeshes[2], { grab: true, onPress: () => toggleWs(2) });
  traits(wsMeshes[3], { grab: true, onPress: () => toggleWs(3) });
  traits(shirt, {
    grab: true,
    onPress: () => {
      sizeIdx = (sizeIdx + 1) % sizes.length;
      confirmed = false;
      refresh();
    }
  });

  refresh();

  return {
    root,
    update(time) {
      if (!isGrabbed(shirt) && shirt.visible) {
        const cur = shirt.scale.x;
        const next = cur + (shirtTarget - cur) * 0.06;
        shirt.scale.set(next, next, 1);
      }
      if (ring.visible) {
        ring.rotation.y = time * 1.2;
        ring.rotation.x = Math.sin(time * 0.8) * 0.3;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
