  const info = ui(`
    <style>
      .card { width: 460px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #23262d; }
      .title { color: #ffd75e; font-size: 28px; font-weight: 700; text-align: center; }
      .body { color: #ffffff; font-size: 22px; text-align: center; }
      .fact { color: #aeb6c2; font-size: 20px; text-align: center; }
    </style>
    <div class="card">
      <span class="title" id="infoTitle">Welcome explorer</span>
      <span class="body" id="infoBody">Press Pause to freeze time. Try speed 4x.</span>
      <span class="fact" id="infoFact">Tap any planet to see its info card here.</span>
    </div>`, { width: 0.28, position: [0.28, 0.31, 0.02], rotationY: -0.32 });
  root.add(info.object3D);

  function updateStatus() {
    let t = (playing ? 'Playing' : 'Paused') + ' - Speed ' + speedMul + 'x';
    t += isCompare ? ' - Compare' : ' - Orbits';
    control.set('status', { text: t });
  }

  function showPlanetInfo(i) {
    selected = i;
    for (let j = 0; j < planetMeshes.length; j++) {
      planetMeshes[j].material.emissiveIntensity = (j === i ? 0.35 : 0);
    }
    const p = planets[i];
    info.set('infoTitle', { text: p.name });
    info.set('infoBody', { text: 'Dist ' + p.dist + ' - Year ' + p.year });
    info.set('infoFact', { text: p.diam + ' wide. ' + p.fact });
  }
  function showSunInfo() {
    selected = -1;
    for (let j = 0; j < planetMeshes.length; j++) planetMeshes[j].material.emissiveIntensity = 0;
    info.set('infoTitle', { text: 'Sun' });
    info.set('infoBody', { text: 'Star - 1.39M km wide - 99.8 percent of mass' });
    info.set('infoFact', { text: 'Not to scale in compare mode. True Sun is 109x Earth.' });
  }

  // Planet press
  for (let i = 0; i < planetMeshes.length; i++) {
    const idx = i;
    traits(planetMeshes[i], { onPress: () => showPlanetInfo(idx) });
  }
  traits(sun, { grab: true, onPress: () => showSunInfo() });

  // Labels (small panels that follow planets)
  const labelHandles = [];
  for (let i = 0; i < planets.length; i++) {
    const h = ui(`
      <style>
        .lab { width: 140px; align-items: center; justify-content: center; padding-top: 4px; padding-bottom: 4px; padding-left: 4px; padding-right: 4px; border-radius: 8px; background-color: #111418; }
        .ltxt { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      </style>
      <div class="lab"><span class="ltxt">${planets[i].name}</span></div>`,
      { width: 0.07, position: [0, 0.2, 0], rotationY: 0 });
    root.add(h.object3D);
    labelHandles.push(h);
  }

  // Control buttons
  control.on('playBtn', 'click', () => {
    playing = !playing;
    control.set('playTxt', { text: playing ? 'Pause' : 'Play' });
    control.set('playBtn', { backgroundColor: playing ? '#2f6fdb' : '#3a3f48' });
    updateStatus();
  });
  function setSpeed(v) {
    speedMul = v;
    control.set('sp05', { backgroundColor: v === 0.5 ? '#2f6fdb' : '#3a3f48' });
    control.set('sp1', { backgroundColor: v === 1 ? '#2f6fdb' : '#3a3f48' });
    control.set('sp4', { backgroundColor: v === 4 ? '#2f6fdb' : '#3a3f48' });
    control.set('sp10', { backgroundColor: v === 10 ? '#2f6fdb' : '#3a3f48' });
    if (!playing) {
      playing = true;
      control.set('playTxt', { text: 'Pause' });
      control.set('playBtn', { backgroundColor: '#2f6fdb' });
    }
    updateStatus();
  }
  control.on('sp05', 'click', () => setSpeed(0.5));
  control.on('sp1', 'click', () => setSpeed(1));
  control.on('sp4', 'click', () => setSpeed(4));
  control.on('sp10', 'click', () => setSpeed(10));

  control.on('orbitBtn', 'click', () => {
    showOrbits = !showOrbits;
    control.set('orbitTxt', { text: showOrbits ? 'Orbits ON' : 'Orbits OFF' });
    control.set('orbitBtn', { backgroundColor: showOrbits ? '#2f6fdb' : '#3a3f48' });
  });
  control.on('labelBtn', 'click', () => {
    showLabels = !showLabels;
    control.set('labelTxt', { text: showLabels ? 'Labels ON' : 'Labels OFF' });
    control.set('labelBtn', { backgroundColor: showLabels ? '#2f6fdb' : '#3a3f48' });
    for (let i = 0; i < labelHandles.length; i++) labelHandles[i].object3D.visible = showLabels;
  });
  control.on('modeBtn', 'click', () => {
    isCompare = !isCompare;
    blendTarget = isCompare ? 1 : 0;
    control.set('modeTxt', { text: isCompare ? 'Back to orbits' : 'Compare sizes' });
    control.set('modeBtn', { backgroundColor: isCompare ? '#b7791f' : '#2f6fdb' });
    if (isCompare) {
      info.set('infoTitle', { text: 'True sizes' });
      info.set('infoBody', { text: 'Planets lined up, bottoms on desk. Jupiter is 11x Earth.' });
      info.set('infoFact', { text: 'Sun not shown. It would be 109x Earth, far too big.' });
    } else {
      info.set('infoTitle', { text: 'Orbit mode' });
      info.set('infoBody', { text: 'Sizes exaggerated so small planets stay visible.' });
      info.set('infoFact', { text: 'Tap any planet to see its info card here.' });
    }
    updateStatus();
  });

  const TWO_PI = Math.PI * 2;

  return {
    root,
    update(time, delta) {
      if (delta > 0.05) delta = 0.05;
      // blend toward mode
      const bs = 2.2 * delta;
      if (blend < blendTarget) { blend += bs; if (blend > blendTarget) blend = blendTarget; }
      else if (blend > blendTarget) { blend -= bs; if (blend < blendTarget) blend = blendTarget; }
      const b = blend;
      const ib = 1 - b;

      if (playing && b < 0.5) simTime += delta * speedMul;

      if (!isGrabbed(sun)) sun.rotation.y += delta * 0.15;

      const cx = sun.position.x;
      const cy = sun.position.y;
      const cz = sun.position.z;

      for (let i = 0; i < orbitLines.length; i++) {
        orbitLines[i].position.set(cx, cy, cz);
        orbitLines[i].visible = showOrbits && b < 0.5;
      }

      for (let i = 0; i < planetMeshes.length; i++) {
        const p = planets[i];
        const ang = p.angle + simTime * TWO_PI / p.period;
        const ox = cx + Math.cos(ang) * p.orbitR;
        const oz = cz + Math.sin(ang) * p.orbitR;
        const oy = cy;
        const px = ox * ib + compX[i] * b;
        const py = oy * ib + compY[i] * b;
        const pz = oz * ib + compZ[i] * b;
        const m = planetMeshes[i];
        m.position.set(px, py, pz);
        const curR = p.displayR * ib + compR[i] * b;
        const s = curR / p.displayR;
        m.scale.set(s, s, s);
        m.rotation.y += delta * 0.3;
        const lh = labelHandles[i].object3D;
        lh.position.set(px, py + curR + 0.022, pz);
        lh.visible = showLabels;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- data
  const INGREDIENTS = [
    '120 g plain flour',
    '2 eggs',
    '300 ml milk',
    '1 tbsp sugar',
    '1 pinch of salt',
    'Butter for the pan',
  ];

  const STEPS = [
    { title: '1. Measure the dry mix', body: 'Whisk the flour, sugar and salt together in a large bowl.', seconds: 60 },
    { title: '2. Whisk eggs and milk', body: 'Beat the eggs in a jug, then whisk in the milk.', seconds: 60 },
    { title: '3. Make a smooth batter', body: 'Pour the wet mix in and whisk until no lumps are left.', seconds: 90 },
    { title: '4. Rest the batter', body: 'Let it stand for 5 minutes so the flour soaks up the milk.', seconds: 300 },
    { title: '5. Cook the pancakes', body: 'Butter a hot pan, add a ladle of batter, 1 min per side.', seconds: 120 },
  ];

  // ------------------------------------------------- 3D progress rail on desk
  const rail = new THREE.Group();
  rail.name = 'RecipeProgressRail';
  rail.position.set(0, 0.012, 0.14);
  root.add(rail);

  const track = new THREE.Mesh(
    new THREE.BoxGeometry(0.40, 0.012, 0.032),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.85 }),
  );
  track.name = 'ProgressTrack';
  rail.add(track);

  const fill = new THREE.Mesh(
    new THREE.BoxGeometry(0.40, 0.015, 0.030),
    new THREE.MeshStandardMaterial({ color: 0x3ddc84, emissive: 0x1f7a4a, emissiveIntensity: 0.6, roughness: 0.4 }),
  );
  fill.name = 'ProgressFill';
  fill.scale.x = 0.0005;
  fill.position.x = -0.1998;
  rail.add(fill);

  const tickGeo = new THREE.BoxGeometry(0.006, 0.020, 0.038);
  const tickMat = new THREE.MeshStandardMaterial({ color: 0x14171b, roughness: 1 });
  for (let i = 1; i < STEPS.length; i++) {
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.name = 'StepTick' + i;
    tick.position.set(-0.20 + 0.40 * (i / STEPS.length), 0.002, 0);
    rail.add(tick);
  }

  // ------------------------------------------------------------- left panel
  let ingRows = '';
  for (let i = 0; i < INGREDIENTS.length; i++) {
    ingRows += '<button class="row" id="i' + i + '"><span class="box" id="b' + i + '">[ ]</span><span class="item" id="t' + i + '">' + INGREDIENTS[i] + '</span></button>';
  }

  const leftPanel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .sub { color: #9aa3b0; font-size: 20px; }
      .row { flex-direction: row; align-items: center; gap: 12px; padding-top: 8px; padding-bottom: 8px;
             padding-left: 14px; padding-right: 14px; border-radius: 12px; background-color: #2a2e35; }
      .box { color: #8f98a6; font-size: 22px; }
      .item { color: #d7dbe2; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Ingredients</span>
      <span class="sub" id="ingCount">0 of ${INGREDIENTS.length} ticked - press a line</span>
      ${ingRows}
    </div>`, { width: 0.28, position: [-0.20, 0.17, 0.03], rotationY: 0.28 });
  root.add(leftPanel.object3D);

  // ------------------------------------------------------------ right panel
  let segs = '';
  for (let i = 0; i < STEPS.length; i++) {
    segs += '<div class="seg" id="p' + i + '"></div>';
  }

  const rightPanel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .head { flex-direction: row; align-items: center; justify-content: space-between; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .count { color: #9aa3b0; font-size: 20px; }
      .stepTitle { color: #ffffff; font-size: 28px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .timerBox { flex-direction: row; align-items: center; gap: 16px; padding-top: 6px; padding-bottom: 6px;
                  padding-left: 16px; padding-right: 16px; border-radius: 14px; background-color: #14171b; }
      .timer { color: #ffffff; font-size: 44px; font-weight: 700; }
      .tag { color: #9aa3b0; font-size: 20px; }
      .btnRow { flex-direction: row; gap: 10px; }
      .btn { width: 215px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btnGrey { width: 215px; align-items: center; justify-content: center; padding-top: 10px; padding-bottom: 10px;
                 border-radius: 12px; background-color: #343943; }
      .btnText { color: #ffffff; font-size: 22px; font-weight: 700; }
      .barRow { flex-direction: row; gap: 8px; }
      .seg { width: 88px; height: 14px; border-radius: 7px; background-color: #3a3f47; }
    </style>
    <div class="card">
      <div class="head">
        <span class="title">Pancake coach</span>
        <span class="count" id="count">Step 1 of ${STEPS.length}</span>
      </div>
      <span class="stepTitle" id="stepTitle">1. Measure the dry mix</span>
      <span class="body" id="stepBody">Whisk the flour, sugar and salt together in a large bowl.</span>
      <div class="timerBox">
        <span class="timer" id="timer">01:00</span>
        <span class="tag" id="timerTag">ready</span>
      </div>
      <div class="btnRow">
        <button class="btn" id="startBtn"><span class="btnText" id="startLabel">Start timer</span></button>
        <button class="btnGrey" id="resetBtn"><span class="btnText">Reset</span></button>
      </div>
      <div class="btnRow">
        <button class="btnGrey" id="back"><span class="btnText" id="backLabel">Back</span></button>
        <button class="btn" id="next"><span class="btnText" id="nextLabel">Next</span></button>
      </div>
      <div class="barRow">${segs}</div>
    </div>`, { width: 0.32, position: [0.21, 0.17, 0.03], rotationY: -0.28 });
  root.add(rightPanel.object3D);

  // ---------------------------------------------------------------- state
  let stepIndex = 0;
  let remaining = STEPS[0].seconds;
  let running = false;
  let done = false;
  let lastSecond = Math.ceil(remaining);
  let railTarget = 1 / STEPS.length;
  let railProgress = 0;

  function fmt(total) {
    const m = Math.floor(total / 60);
    const s = total % 60;
    const mm = m < 10 ? '0' + m : '' + m;
    const ss = s < 10 ? '0' + s : '' + s;
    return mm + ':' + ss;
  }

  function refreshProgress() {
    for (let i = 0; i < STEPS.length; i++) {
      let c = '#3a3f47';
      if (done || i < stepIndex) c = '#3ddc84';
      else if (i === stepIndex) c = '#2f6fdb';
      rightPanel.set('p' + i, { backgroundColor: c });
    }
    rightPanel.set('count', {
      text: done ? 'Recipe complete' : 'Step ' + (stepIndex + 1) + ' of ' + STEPS.length,
    });
  }

  function refreshStep() {
    if (done) {
      rightPanel.set('stepTitle', { text: 'All done - enjoy!' });
      rightPanel.set('stepBody', { text: 'Stack the pancakes, add lemon and sugar, and serve warm.' });
    } else {
      rightPanel.set('stepTitle', { text: STEPS[stepIndex].title });
      rightPanel.set('stepBody', { text: STEPS[stepIndex].body });
    }
    refreshProgress();
    rightPanel.set('backLabel', { color: (stepIndex === 0 && !done) ? '#6b7482' : '#ffffff' });
    rightPanel.set('nextLabel', {
      text: (stepIndex === STEPS.length - 1 && !done) ? 'Finish' : 'Next',
      color: done ? '#6b7482' : '#ffffff',
    });
    railTarget = done ? 1 : (stepIndex + 1) / STEPS.length;
  }

  function refreshTimer() {
    lastSecond = Math.ceil(remaining);
    rightPanel.set('timer', {
      text: fmt(lastSecond),
      color: remaining <= 0 ? '#ff8a6b' : '#ffffff',
    });
    let tag = 'ready';
    let tagColor = '#9aa3b0';
    let label = 'Start timer';
    if (done) {
      tag = 'finished'; tagColor = '#3ddc84'; label = 'Cook again';
    } else if (remaining <= 0) {
      tag = 'time is up'; tagColor = '#ffb02e'; label = 'Restart';
    } else if (running) {
      tag = 'running'; tagColor = '#3ddc84'; label = 'Pause';
    } else if (remaining < STEPS[stepIndex].seconds - 0.01) {
      tag = 'paused'; tagColor = '#ffb02e'; label = 'Resume';
    }
    rightPanel.set('timerTag', { text: tag, color: tagColor });
    rightPanel.set('startLabel', { text: label });
  }

  // ------------------------------------------------------------ checklist
  const ticked = [];
  for (let i = 0; i < INGREDIENTS.length; i++) ticked.push(false);

  for (let i = 0; i < INGREDIENTS.length; i++) {
    leftPanel.on('i' + i, 'click', () => {
      ticked[i] = !ticked[i];
      leftPanel.set('b' + i, { text: ticked[i] ? '[x]' : '[ ]', color: ticked[i] ? '#3ddc84' : '#8f98a6' });
      leftPanel.set('t' + i, { color: ticked[i] ? '#7fe0a8' : '#d7dbe2' });
      let n = 0;
      for (let k = 0; k < ticked.length; k++) if (ticked[k]) n++;
      leftPanel.set('ingCount', {
        text: n === INGREDIENTS.length
          ? 'All ' + n + ' ready - start cooking!'
          : n + ' of ' + INGREDIENTS.length + ' ticked',
      });
    });
  }

  // -------------------------------------------------------------- buttons
  rightPanel.on('startBtn', 'click', () => {
    if (done) {
      done = false;
      stepIndex = 0;
      remaining = STEPS[0].seconds;
      running = true;
      refreshStep();
      refreshTimer();
      return;
    }
    if (remaining <= 0) remaining = STEPS[stepIndex].seconds;
    running = !running;
    refreshTimer();
  });

  rightPanel.on('resetBtn', 'click', () => {
    if (done) return;
    running = false;
    remaining = STEPS[stepIndex].seconds;
    refreshTimer();
  });

  rightPanel.on('next', 'click', () => {
    if (done) return;
    if (stepIndex === STEPS.length - 1) {
      done = true;
      running = false;
      remaining = 0;
      refreshStep();
      refreshTimer();
      return;
    }
    stepIndex++;
    remaining = STEPS[stepIndex].seconds;
    running = false;
    refreshStep();
    refreshTimer();
  });

  rightPanel.on('back', 'click', () => {
    if (done) {
      done = false;
      stepIndex = STEPS.length - 1;
      remaining = STEPS[stepIndex].seconds;
      running = false;
      refreshStep();
      refreshTimer();
      return;
    }
    if (stepIndex === 0) return;
    stepIndex--;
    remaining = STEPS[stepIndex].seconds;
    running = false;
    refreshStep();
    refreshTimer();
  });

  // ---------------------------------------------------------- initial draw
  refreshStep();
  refreshTimer();

  return {
    root,
    update(time, delta) {
      if (running && !done) {
        remaining -= delta;
        if (remaining <= 0) {
          remaining = 0;
          running = false;
          lastSecond = 0;
          rightPanel.set('timer', { text: '00:00', color: '#ff8a6b' });
          rightPanel.set('timerTag', { text: 'time is up', color: '#ffb02e' });
          rightPanel.set('startLabel', { text: 'Restart' });
        } else {
          const s = Math.ceil(remaining);
          if (s !== lastSecond) {
            lastSecond = s;
            rightPanel.set('timer', { text: fmt(s) });
          }
        }
      }

      if (railProgress !== railTarget) {
        const k = Math.min(1, delta * 6);
        railProgress += (railTarget - railProgress) * k;
        if (Math.abs(railTarget - railProgress) < 0.002) railProgress = railTarget;
        const p = Math.max(0.0005, railProgress);
        fill.scale.x = p;
        fill.position.x = -0.20 + 0.20 * p;
      }
    },
  };
}

