    <button class="sw" id="c2"><span class="swt">Ocean</span></button>
  </div>
  <span class="plabel">Size</span>
  <div class="prow">
    <button class="sw" id="s0"><span class="swt">Small</span></button>
    <button class="sw" id="s1"><span class="swt">Medium</span></button>
    <button class="sw" id="s2"><span class="swt">Large</span></button>
