           padding-left: 20px; padding-right: 20px; border-radius: 20px; background-color: #1c1f25; }
  .ctitle { color: #ffffff; font-size: 28px; font-weight: 700; }
  .empty { color: #98a1ae; font-size: 21px; }
  .line { display: none; flex-direction: column; gap: 2px; padding-top: 6px; padding-bottom: 6px;
          padding-left: 12px; padding-right: 12px; border-radius: 12px; background-color: #262a31; }
  .lrow { flex-direction: row; justify-content: space-between; align-items: center; }
  .lname { color: #ffffff; font-size: 22px; font-weight: 700; }
  .lprice { color: #d7dbe2; font-size: 22px; }
  .lvar { color: #98a1ae; font-size: 21px; }
  .qty { flex-direction: row; gap: 6px; align-items: center; }
