        background-color: #3a424e; align-items: center; justify-content: center; }
  .qbt { color: #ffffff; font-size: 24px; font-weight: 700; }
  .qn { color: #ffffff; font-size: 22px; width: 34px; text-align: center; }
  .div { height: 2px; background-color: #343a43; }
