  <span class="ctitle">Your cart</span>
  <span class="empty" id="empty">Cart is empty - press Add to cart.</span>${linesMarkup}
  <div class="div"></div>
  <div class="srow"><span class="sk">Subtotal</span><span class="sv" id="sub">$0.00</span></div>
  <div class="srow"><span class="sk">Tax (8.25%)</span><span class="sv" id="tax">$0.00</span></div>
  <div class="srow"><span class="tk">Total</span><span class="tv" id="tot">$0.00</span></div>
