  function refreshHighlight() {
    for (let i = 0; i < 3; i++) {
      const on = i === selected;
      productObjs[i].ring.visible = on;
      productObjs[i].group.scale.setScalar(on ? 1.15 : 1);
    }
  }

  function selectProduct(i) {
    selected = i;
    refreshProduct();
    refreshHighlight();
  }

  function refreshProduct() {
    const p = PRODUCTS[selected];
    productPanel.set('pname', { text: p.name });
    productPanel.set('psub', { text: p.sub });
    productPanel.set('pprice', { text: money(p.price) });
