        cartPanel.set('l' + i + 'p', { text: money(PRODUCTS[i].price * qty[i]) });
        cartPanel.set('l' + i + 'v', {
          text: COLORS[lineColor[i]].name + ' / ' + SIZES[lineSize[i]],
