    }
    cartPanel.set('empty', { display: any ? 'none' : 'flex' });
    const tax = sub * TAX_RATE;
    cartPanel.set('sub', { text: money(sub) });
    cartPanel.set('tax', { text: money(tax) });
    cartPanel.set('tot', { text: money(sub + tax) });
  }

  /* ------------------------------------------------------------- events */
  for (let c = 0; c < 3; c++) {
    productPanel.on('c' + c, 'click', () => {
      cfgColor[selected] = c;
      applyColor(selected);
      refreshProduct();
    });
  }

  for (let s = 0; s < 3; s++) {
    productPanel.on('s' + s, 'click', () => {
      cfgSize[selected] = s;
      refreshProduct();
    });
  }

  productPanel.on('add', 'click', () => {
    qty[selected] += 1;
    lineColor[selected] = cfgColor[selected];
    lineSize[selected] = cfgSize[selected];
    refreshCart();
    cartPanel.set('msg', { text: 'Added ' + PRODUCTS[selected].name + ' to your cart.' });
  });

  for (let i = 0; i < 3; i++) {
    cartPanel.on('l' + i + 'm', 'click', () => {
      if (qty[i] > 0) { qty[i] -= 1; refreshCart(); }
    });
    cartPanel.on('l' + i + 'x', 'click', () => {
      if (qty[i] < 99) { qty[i] += 1; refreshCart(); }
    });
  }

  cartPanel.on('checkout', 'click', () => {
    let total = 0;
    for (let i = 0; i < 3; i++) total += PRODUCTS[i].price * qty[i];
    if (total <= 0) {
      cartPanel.set('msg', { text: 'Your cart is empty - add a headphone first.' });
      return;
    }
    for (let i = 0; i < 3; i++) qty[i] = 0;
    refreshCart();
    cartPanel.set('msg', { text: 'Order placed for ' + money(total * (1 + TAX_RATE)) + '. Ships in 2 days.' });
  });

  /* -------------------------------------------------------------- start */
  applyColor(0);
  applyColor(1);
  applyColor(2);
  refreshHighlight();
  refreshProduct();
  refreshCart();

  /* --------------------------------------------------------------- loop */
  return {
    root,
    update(time) {
      const a = time * 0.2;
      for (let i = 0; i < 3; i++) {
        const ang = a + i * ANG;
        const g = productObjs[i].group;
        g.position.set(Math.sin(ang) * R, 0.09, CZ + Math.cos(ang) * R);
        g.rotation.y = ang;
      }
    },
  };
}

