      s1: 'Radius 24,622 km (3.88 x Earth) | Moons: 16', s2: 'Distance 30.1 AU (4.5 billion km)', s3: 'Year 165 years | Day 16.1 hours',
      fact: 'The farthest planet, with winds over 2,000 km/h. Its existence was predicted with math before it was seen.' },
  ];
  const SUN_INFO = {
    name: 'The Sun',
    s1: 'Radius 696,000 km (109 x Earth)',
    s2: 'Surface 5,500°C | Core 15 million °C',
    s3: 'Spins about every 25 days at the equator',
    fact: 'Holds 99.8% of the Solar System mass. About 1.3 million Earths would fit inside it.',
  };

  const SPEEDS = [2, 10, 30, 90, 180, 365];
  const SPEED_LABELS = ['2 days/s', '10 days/s', '30 days/s', '3 months/s', '6 months/s', '1 year/s'];

  // ---------- state ----------
  let playing = true;
  let speedIdx = 1;
  let orbitsOn = true;
  let labelsOn = true;
  let compare = false;
  let cmpT = 0;
  let simDays = 0;
  let selected = -1; // -1 none, 0-7 planets, 8 sun
  let lastTimeKey = -1;

  // ---------- compare layout (true relative size, labels kept apart) ----------
  const n = PL.length;
  const cx = new Array(n);
  let acc = 0;
  cx[0] = 0;
  for (let i = 1; i < n; i++) {
    const a = PL[i - 1].rE * U, b = PL[i].rE * U;
    acc += Math.max(a + b + 0.012, 0.076);
    cx[i] = acc;
  }
  for (let i = 0; i < n; i++) cx[i] -= acc / 2;

  // ---------- sun ----------
  const sphereGeo = new THREE.SphereGeometry(1, 28, 14);
  const sunMat = new THREE.MeshStandardMaterial({ color: 0xffc23d, emissive: 0xff8a00, emissiveIntensity: 0.9 });
  const sun = new THREE.Mesh(sphereGeo, sunMat);
  sun.name = 'Sun';
  sun.position.set(0, CY, CZ);
  sun.scale.setScalar(SUN_R);
  root.add(sun);

  // ---------- orbit lines (one LineSegments for all orbits) ----------
  const SEG = 96;
  const pos = new Float32Array(n * SEG * 2 * 3);
  let k = 0;
  for (let i = 0; i < n; i++) {
    const R = PL[i].R;
    for (let s = 0; s < SEG; s++) {
      const a0 = (s / SEG) * TWO_PI, a1 = ((s + 1) / SEG) * TWO_PI;
      pos[k++] = Math.cos(a0) * R; pos[k++] = 0; pos[k++] = Math.sin(a0) * R * Z_SQ;
      pos[k++] = Math.cos(a1) * R; pos[k++] = 0; pos[k++] = Math.sin(a1) * R * Z_SQ;
    }
  }
  const orbitGeo = new THREE.BufferGeometry();
  orbitGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const orbitMat = new THREE.LineBasicMaterial({ color: 0x9fb4cc, transparent: true, opacity: 0.55 });
  const orbitLines = new THREE.LineSegments(orbitGeo, orbitMat);
  orbitLines.name = 'OrbitLines';
  orbitLines.position.set(0, CY, CZ);
  root.add(orbitLines);

  // ---------- selection ring ----------
  const selRing = new THREE.Mesh(
    new THREE.RingGeometry(1.0, 1.12, 40),
    new THREE.MeshBasicMaterial({ color: 0xffe066, side: THREE.DoubleSide }),
  );
  selRing.rotation.x = -0.6;
  selRing.visible = false;
  root.add(selRing);

  // ---------- info panel ----------
  const info = ui(`
    <style>
      .card { width: 640px; flex-direction: column; gap: 6px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 16px; padding-right: 16px; border-radius: 20px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .stat { color: #d7dbe2; font-size: 22px; }
      .fact { color: #ffd98a; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title" id="iname">Solar System</span>
      <span class="stat" id="is1">Tap a planet or its name for an info card.</span>
      <span class="stat" id="is2">Sizes and distances are squeezed to fit your desk.</span>
      <span class="stat" id="is3">Try Compare to see true relative planet sizes.</span>
      <span class="fact" id="ifact">Orbit periods are real: Mercury circles the Sun in 88 days, Neptune in 165 years.</span>
    </div>`, { width: 0.42, position: [0, 0.405, -0.24] });
  root.add(info.object3D);

  function showText(d) {
    info.set('iname', { text: d.name });
    info.set('is1', { text: d.s1 });
    info.set('is2', { text: d.s2 });
    info.set('is3', { text: d.s3 });
    info.set('ifact', { text: d.fact });
  }
  function showIntro() {
    if (compare) {
      showText({
        name: 'True relative sizes',
        s1: 'Planets lined up at true relative size.',
        s2: 'Jupiter is about 11 times wider than Earth.',
        s3: 'The Sun is about 10 times wider than Jupiter.',
        fact: 'The Sun is too big to show, and Saturn rings are hidden. Tap a planet or its name for details.',
      });
    } else {
      showText({
        name: 'Solar System',
        s1: 'Tap a planet or its name for an info card.',
        s2: 'Sizes and distances are squeezed to fit your desk.',
        s3: 'Try Compare to see true relative planet sizes.',
        fact: 'Orbit periods are real: Mercury circles the Sun in 88 days, Neptune in 165 years.',
      });
    }
  }

  // ---------- planets and labels ----------
  const bodies = [];
  const labelMarkup = (id, name) => `
    <style>
      .lb { width: 120px; padding-top: 6px; padding-bottom: 6px; padding-left: 6px; padding-right: 6px;
            border-radius: 10px; background-color: #1a1d22; align-items: center; justify-content: center; }
      .lt { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="lb" id="${id}"><span class="lt">${name}</span></div>`;

  function selectBody(i) {
    selected = i;
    for (let j = 0; j < n; j++) bodies[j].mat.emissiveIntensity = j === i ? 0.35 : 0;
    selRing.visible = true;
    showText(i === 8 ? SUN_INFO : PL[i]);
  }

  for (let i = 0; i < n; i++) {
    const d = PL[i];
    const mat = new THREE.MeshStandardMaterial({ color: d.color, emissive: d.color, emissiveIntensity: 0, roughness: 0.75 });
    const mesh = new THREE.Mesh(sphereGeo, mat);
    mesh.name = d.name;
    mesh.scale.setScalar(d.rO);
    root.add(mesh);
    traits(mesh, { onPress: () => selectBody(i) });

    let ring = null;
    if (d.name === 'Saturn') {
      ring = new THREE.Mesh(
        new THREE.RingGeometry(1.35, 2.0, 48),
        new THREE.MeshStandardMaterial({ color: 0xcdb98a, side: THREE.DoubleSide, transparent: true, opacity: 0.85, roughness: 0.9 }),
      );
      ring.name = 'SaturnRings';
      ring.rotation.x = -Math.PI / 2 + 0.4;
      mesh.add(ring);
    }

    const lid = 'lb' + i;
    const label = ui(labelMarkup(lid, d.name), { width: 0.07, position: [0, CY + 0.04, 0] });
    root.add(label.object3D);
    label.on(lid, 'click', () => selectBody(i));

    bodies.push({ mesh, mat, ring, label, d, rC: d.rE * U, cx: cx[i] });
  }

  traits(sun, { onPress: () => selectBody(8) });

  // ---------- control panel ----------
  const ctrl = ui(`
    <style>
      .panel { width: 560px; flex-direction: column; gap: 10px; padding-top: 16px; padding-bottom: 16px;
               padding-left: 16px; padding-right: 16px; border-radius: 20px; background-color: #1f2228; }
      .row { flex-direction: row; gap: 10px; align-items: center; justify-content: center; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 8px; padding-right: 8px; border-radius: 12px;
             background-color: #2f6fdb; align-items: center; justify-content: center; }
      .w150 { width: 150px; }
      .w190 { width: 190px; }
      .w60 { width: 60px; }
      .t { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .time { width: 528px; color: #aeb6c2; font-size: 22px; text-align: center; }
      .speed { width: 170px; color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="panel">
      <span class="time" id="timeTxt">Time elapsed: 0.0 years</span>
      <div class="row">
        <button class="btn w150" id="playBtn"><span class="t" id="playTxt">Pause</span></button>
        <button class="btn w60" id="slowBtn"><span class="t">-</span></button>
        <span class="speed" id="speedTxt">10 days/s</span>
        <button class="btn w60" id="fastBtn"><span class="t">+</span></button>
      </div>
      <div class="row">
        <button class="btn w150" id="orbBtn"><span class="t" id="orbTxt">Orbits: On</span></button>
        <button class="btn w150" id="lblBtn"><span class="t" id="lblTxt">Labels: On</span></button>
        <button class="btn w190" id="cmpBtn"><span class="t" id="cmpTxt">Compare: Off</span></button>
      </div>
    </div>`, { width: 0.42, position: [0, 0.065, 0.235] });
  root.add(ctrl.object3D);

  const ON = '#2f6fdb', OFF = '#3a3f48', CMP_ON = '#d97b1e';

  ctrl.on('playBtn', 'click', () => {
    playing = !playing;
    ctrl.set('playTxt', { text: playing ? 'Pause' : 'Play' });
    ctrl.set('playBtn', { backgroundColor: playing ? ON : '#2e9d57' });
  });
  ctrl.on('slowBtn', 'click', () => {
    speedIdx = Math.max(0, speedIdx - 1);
    ctrl.set('speedTxt', { text: SPEED_LABELS[speedIdx] });
  });
  ctrl.on('fastBtn', 'click', () => {
    speedIdx = Math.min(SPEEDS.length - 1, speedIdx + 1);
    ctrl.set('speedTxt', { text: SPEED_LABELS[speedIdx] });
  });
  ctrl.on('orbBtn', 'click', () => {
    orbitsOn = !orbitsOn;
    ctrl.set('orbTxt', { text: orbitsOn ? 'Orbits: On' : 'Orbits: Off' });
    ctrl.set('orbBtn', { backgroundColor: orbitsOn ? ON : OFF });
  });
  ctrl.on('lblBtn', 'click', () => {
    labelsOn = !labelsOn;
    ctrl.set('lblTxt', { text: labelsOn ? 'Labels: On' : 'Labels: Off' });
    ctrl.set('lblBtn', { backgroundColor: labelsOn ? ON : OFF });
  });
  ctrl.on('cmpBtn', 'click', () => {
    compare = !compare;
    ctrl.set('cmpTxt', { text: compare ? 'Compare: On' : 'Compare: Off' });
    ctrl.set('cmpBtn', { backgroundColor: compare ? CMP_ON : ON });
    if (compare && selected === 8) {
      selected = -1;
      selRing.visible = false;
      for (let j = 0; j < n; j++) bodies[j].mat.emissiveIntensity = 0;
    }
    if (selected === -1) showIntro();
  });

  // ---------- animation ----------
  return {
    root,
    update(time, delta) {
      if (playing) simDays += delta * SPEEDS[speedIdx];

      const target = compare ? 1 : 0;
      if (cmpT < target) cmpT = Math.min(target, cmpT + delta * 1.2);
      else if (cmpT > target) cmpT = Math.max(target, cmpT - delta * 1.2);
      const e = cmpT * cmpT * (3 - 2 * cmpT);

      // sun
      const sunS = Math.max(0.0001, SUN_R * (1 - e));
      sun.scale.setScalar(sunS);
      sun.visible = e < 0.98;
      sunMat.emissiveIntensity = 0.85 + 0.12 * Math.sin(time * 1.5);

      // orbit lines
      orbitMat.opacity = 0.55 * (1 - e);
      orbitLines.visible = orbitsOn && e < 0.98;

      // planets
      for (let i = 0; i < n; i++) {
        const b = bodies[i];
        const d = b.d;
        const ang = d.phase + (TWO_PI * simDays) / d.period;
        const ox = Math.cos(ang) * d.R;
        const oz = CZ - Math.sin(ang) * d.R * Z_SQ;
        const x = ox + (b.cx - ox) * e;
        const y = CY + (CYC - CY) * e;
        const z = oz + (CZ - oz) * e;
        const rd = d.rO + (b.rC - d.rO) * e;
        b.mesh.position.set(x, y, z);
        b.mesh.scale.setScalar(rd);
        if (b.ring) {
          b.ring.scale.setScalar(Math.max(0.0001, 1 - e));
          b.ring.visible = e < 0.98;
        }
        b.label.object3D.position.set(x, y + rd + 0.02, z);
        b.label.object3D.visible = labelsOn;
      }

      // selection ring
      if (selected >= 0) {
        if (selected < n) {
          const m = bodies[selected].mesh;
          selRing.position.copy(m.position);
          selRing.scale.setScalar(m.scale.x * 1.35 + 0.006);
        } else {
          selRing.position.copy(sun.position);
          selRing.scale.setScalar(sunS * 1.15 + 0.006);
        }
      }

      // time readout (only touch the panel when the displayed value changes)
      const key = Math.floor(simDays / 36.525);
      if (key !== lastTimeKey) {
        lastTimeKey = key;
        ctrl.set('timeTxt', { text: 'Time elapsed: ' + (key / 10).toFixed(1) + ' years' });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const COLS = ["TO DO", "IN PROGRESS", "REVIEW", "DONE"];
  const COL_X = [-0.27, -0.09, 0.09, 0.27];
  const HEADER_Y = 0.38;
  const CARD_Z = -0.12;

  const PRI_BG = { HIGH: "#e5484d", MED: "#f5a524", LOW: "#3fb950" };
  const PRI_BORDER = { HIGH: "#e5484d", MED: "#f5a524", LOW: "#3fb950" };

  const initCols = [0, 1, 2, 0, 1, 2];
  const defs = [
    { title: "Login crash fix", pri: "HIGH" },
    { title: "Checkout flow", pri: "HIGH" },
    { title: "Profile screen", pri: "MED" },
    { title: "Search polish", pri: "MED" },
    { title: "Docs update", pri: "LOW" },
    { title: "Dark mode", pri: "LOW" },
  ];

  // 3D desk board base
  const baseMat = new THREE.MeshStandardMaterial({ color: 0x23272f, roughness: 0.9 });
  const base = new THREE.Mesh(new THREE.BoxGeometry(0.72, 0.016, 0.22), baseMat);
  base.position.set(0, 0.008, -0.11);
  base.name = "BoardBase";
  root.add(base);

  const stripGeo = new THREE.BoxGeometry(0.155, 0.006, 0.19);
  const stripMats = [
    new THREE.MeshStandardMaterial({ color: 0x3a4356, roughness: 0.8 }),
    new THREE.MeshStandardMaterial({ color: 0x3a4356, roughness: 0.8 }),
    new THREE.MeshStandardMaterial({ color: 0x3a4356, roughness: 0.8 }),
    new THREE.MeshStandardMaterial({ color: 0x2e4a38, roughness: 0.8 }),
  ];
  for (let i = 0; i < 4; i++) {
    const s = new THREE.Mesh(stripGeo, stripMats[i]);
    s.position.set(COL_X[i], 0.018, -0.11);
    root.add(s);
  }

  // Burndown 3D base + bars
  const burnBase = new THREE.Mesh(
    new THREE.BoxGeometry(0.34, 0.012, 0.09),
    new THREE.MeshStandardMaterial({ color: 0x23272f, roughness: 0.9 })
  );
  burnBase.position.set(0.02, 0.006, 0.16);
  burnBase.name = "BurndownBase";
  root.add(burnBase);

  const barGeo = new THREE.BoxGeometry(0.032, 1, 0.05);
  barGeo.translate(0, 0.5, 0);
  const bars = [];
  for (let i = 0; i < 7; i++) {
    const m = new THREE.Mesh(
      barGeo,
      new THREE.MeshStandardMaterial({ color: 0xe5484d, roughness: 0.6 })
    );
    m.position.set(-0.11 + i * 0.043, 0.012, 0.16);
    m.scale.y = 0.001;
    m.visible = false;
    m.name = "BurnBar" + i;
    root.add(m);
    bars.push(m);
  }

  // Priority legend cubes (grabbable)
  const legendGeo = new THREE.BoxGeometry(0.032, 0.032, 0.032);
  const legendCols = [0xe5484d, 0xf5a524, 0x3fb950];
  const legendNames = ["HighPri", "MedPri", "LowPri"];
  for (let i = 0; i < 3; i++) {
    const c = new THREE.Mesh(
      legendGeo,
      new THREE.MeshStandardMaterial({ color: legendCols[i], roughness: 0.5 })
    );
    c.name = legendNames[i];
    c.position.set(-0.28 + i * 0.055, 0.03, 0.16);
    root.add(c);
    traits(c, { grab: true });
  }

  // Column header panels
  const headerHandles = [];
  for (let i = 0; i < 4; i++) {
    const h = ui(`
      <style>
        .h { width: 170px; display: flex; flex-direction: column; align-items: center; justify-content: center; padding-top: 8px; padding-bottom: 8px; padding-left: 8px; padding-right: 8px; border-radius: 12px; background-color: #22262e; }
        .ht { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      </style>
      <div class="h"><span class="ht" id="t">${COLS[i]}</span></div>
    `, { width: 0.15, position: [COL_X[i], HEADER_Y, -0.22], rotationY: 0 });
    root.add(h.object3D);
    headerHandles.push(h);
  }

  // Task card panels
  const tasks = [];
  for (let i = 0; i < 6; i++) {
    const d = defs[i];
    const bg = PRI_BG[d.pri];
    const bd = PRI_BORDER[d.pri];
    const handle = ui(`
      <style>
        .card { width: 250px; display: flex; flex-direction: column; gap: 6px; padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px; border-radius: 14px; background-color: #22262e; border-color: ${bd}; border-width: 4px; }
        .t { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
        .pb { color: #111111; font-size: 18px; font-weight: 700; text-align: center; background-color: ${bg}; border-radius: 8px; padding-top: 2px; padding-bottom: 2px; padding-left: 6px; padding-right: 6px; }
        .row { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 6px; }
        .abtn { padding-top: 6px; padding-bottom: 6px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #3a404b; }
        .ab { color: #ffffff; font-size: 22px; font-weight: 700; }
        .cl { color: #d7dbe2; font-size: 18px; font-weight: 700; }
      </style>
      <div class="card">
        <span class="t">${d.title}</span>
        <span class="pb">${d.pri} PRIORITY</span>
        <div class="row">
          <button class="abtn" id="left"><span class="ab">&lt;</span></button>
          <span class="cl" id="col">TO DO</span>
          <button class="abtn" id="right"><span class="ab">&gt;</span></button>
        </div>
      </div>
    `, { width: 0.155, position: [COL_X[initCols[i]], 0.27, CARD_Z], rotationY: 0 });
    root.add(handle.object3D);
    traits(handle.object3D, { grab: true });
    const t = {
      title: d.title,
      pri: d.pri,
      col: initCols[i],
      handle,
      target: new THREE.Vector3(COL_X[initCols[i]], 0.27, CARD_Z),
    };
    tasks.push(t);
  }

  // Control + burndown text panel (top, behind nothing)
  const control = ui(`
    <style>
      .board { width: 500px; display: flex; flex-direction: column; gap: 8px; padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px; border-radius: 16px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .sub { color: #d7dbe2; font-size: 20px; text-align: center; }
      .burn { color: #8aff9e; font-size: 20px; font-weight: 700; text-align: center; }
      .ctrl { display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 12px; }
      .fbtn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #2f6fdb; }
      .rbtn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px; border-radius: 10px; background-color: #3a404b; }
      .bt { color: #ffffff; font-size: 20px; font-weight: 700; }
      .leg { color: #aab0bb; font-size: 18px; text-align: center; }
    </style>
    <div class="board">
      <span class="title">Sprint 12 - Sprint Board</span>
      <span class="sub" id="status">0 done - showing ALL</span>
      <span class="burn" id="burn">Burndown: 6 left</span>
      <div class="ctrl">
        <button class="fbtn" id="filter"><span class="bt" id="filterT">Show HIGH only</span></button>
        <button class="rbtn" id="reset"><span class="bt">Reset</span></button>
      </div>
      <span class="leg">Red HIGH - Orange MED - Green LOW - arrows move cards</span>
    </div>
  `, { width: 0.4, position: [0, 0.485, -0.22], rotationY: 0 });
  root.add(control.object3D);

  let filterHighOnly = false;
  let history = [6];
  let lastDone = 0;

  function doneCount() {
    let n = 0;
    for (let i = 0; i < tasks.length; i++) if (tasks[i].col === 3) n++;
    return n;
  }
  function visibleInFilter(t) {
    return !filterHighOnly || t.pri === "HIGH";
  }

  function layoutTargets() {
    const slots = [0, 0, 0, 0];
    for (let i = 0; i < tasks.length; i++) {
      const t = tasks[i];
      const s = slots[t.col];
      slots[t.col] = s + 1;
      const y = 0.28 - s * 0.115;
      t.target.set(COL_X[t.col], y < 0.05 ? 0.05 : y, CARD_Z);
    }
  }

  function refreshHeaders() {
    for (let c = 0; c < 4; c++) {
      let n = 0;
      for (let i = 0; i < tasks.length; i++) {
        if (tasks[i].col === c && visibleInFilter(tasks[i])) n++;
      }
      headerHandles[c].set("t", { text: COLS[c] + " (" + n + ")" });
    }
  }

  function refreshBurndown() {
    const done = doneCount();
    const left = tasks.length - done;
    if (done !== lastDone) {
      lastDone = done;
      history.push(left);
      if (history.length > 7) history.shift();
    }
    for (let i = 0; i < bars.length; i++) {
      if (i < history.length) {
        const v = history[i];
        bars[i].visible = true;
        const h = 0.015 + (v / 6) * 0.11;
        bars[i].scale.y = h;
        const f = 1 - v / 6;
        const r = Math.round(229 - f * 140);
        const g = Math.round(72 + f * 110);
        const b = Math.round(77 + f * 30);
        bars[i].material.color.setRGB(r / 255, g / 255, b / 255);
      } else {
        bars[i].visible = false;
      }
    }
    const ftxt = filterHighOnly ? "HIGH only" : "ALL";
    control.set("status", { text: done + " done - " + left + " left - showing " + ftxt });
    control.set("burn", { text: "Burndown: " + left + " left - " + done + "/6 done" });
    control.set("filterT", { text: filterHighOnly ? "Show ALL" : "Show HIGH only" });
  }

  function refreshCards() {
    for (let i = 0; i < tasks.length; i++) {
      const t = tasks[i];
      t.handle.set("col", { text: COLS[t.col] });
      t.handle.object3D.visible = visibleInFilter(t);
    }
  }

  function refreshAll() {
    layoutTargets();
    refreshCards();
    refreshHeaders();
    refreshBurndown();
  }

  function moveTask(i, dir) {
    const t = tasks[i];
    const nc = t.col + dir;
    if (nc < 0 || nc > 3) return;
    t.col = nc;
    refreshAll();
  }

  for (let i = 0; i < tasks.length; i++) {
    const idx = i;
    tasks[i].handle.on("left", "click", () => moveTask(idx, -1));
    tasks[i].handle.on("right", "click", () => moveTask(idx, 1));
  }

  control.on("filter", "click", () => {
    filterHighOnly = !filterHighOnly;
    refreshAll();
  });
  control.on("reset", "click", () => {
    for (let i = 0; i < tasks.length; i++) tasks[i].col = initCols[i];
    filterHighOnly = false;
    history = [6];
    lastDone = 0;
    // force history refresh
    const d = doneCount();
    lastDone = d;
    history = [6 - d];
    layoutTargets();
    refreshCards();
    refreshHeaders();
    // rebuild bars
    for (let i = 0; i < bars.length; i++) bars[i].visible = false;
    bars[0].visible = true;
    bars[0].scale.y = 0.015 + (history[0] / 6) * 0.11;
    bars[0].material.color.setHex(0xe5484d);
    control.set("status", { text: d + " done - " + (6 - d) + " left - showing ALL" });
    control.set("burn", { text: "Burndown: " + (6 - d) + " left - " + d + "/6 done" });
    control.set("filterT", { text: "Show HIGH only" });
  });

  refreshAll();

  return {
    root,
    update(time, delta) {
      const k = 1 - Math.exp(-4 * delta);
      for (let i = 0; i < tasks.length; i++) {
        const o = tasks[i].handle.object3D;
        if (!o.visible) continue;
        if (isGrabbed(o)) continue;
        o.position.lerp(tasks[i].target, k);
        o.rotation.x += (0 - o.rotation.x) * k;
        o.rotation.y += (0 - o.rotation.y) * k;
        o.rotation.z += (0 - o.rotation.z) * k;
      }
      const p = 0.5 + 0.5 * Math.sin(time * 2.0);
      burnBase.position.y = 0.006 + p * 0.001;
    },
  };
}

