  function startConfetti() {
    for (let i = 0; i < CONF_N; i++) {
      confPos[i * 3] = 0;
      confPos[i * 3 + 1] = 0.18;
      confPos[i * 3 + 2] = -0.14;
      const ang = (i / CONF_N) * Math.PI * 2 + (i % 3) * 0.3;
      const sp = 0.12 + (i % 4) * 0.05;
      confVel[i * 3] = Math.cos(ang) * sp;
      confVel[i * 3 + 1] = 0.7 + (i % 5) * 0.12;
      confVel[i * 3 + 2] = Math.sin(ang) * sp * 0.6 + 0.05;
