      lock.set('d' + idx, { text: '' + guess[idx] });
    });
    lock.on('m' + idx, 'click', () => {
      if (unlocked) return;
      guess[idx] = (guess[idx] + 9) % 10;
      lock.set('d' + idx, { text: '' + guess[idx] });
    });
  }
  lock.on('reset', 'click', () => {
    if (unlocked) {
      lock.set('lockStatus', { text: 'Already open. Enjoy the treasure!' });
      return;
    }
    guess[0] = 0; guess[1] = 0; guess[2] = 0; guess[3] = 0;
    refreshDigits();
    lock.set('lockStatus', { text: 'Reset to 0-0-0-0.' });
  });
  lock.on('unlock', 'click', () => {
    if (unlocked) {
      lock.set('lockStatus', { text: 'Already open!' });
      return;
    }
    const ok = guess[0] === code[0] && guess[1] === code[1] && guess[2] === code[2] && guess[3] === code[3];
    if (ok) {
      doUnlock();
    } else {
      attempts += 1;
      lock.set('lockStatus', { text: 'Wrong code. Try ' + attempts + 'x. Check all 3 clues.' });
    }
  });

  // hints
  const hints = [
    'Hint 1: Each object hides a number. The book holds TWO numbers, the clock holds ONE, the plant holds ONE.',
    'Hint 2: Book = CHAPTER 4 PAGE 1 so digits are 4 and 1. Clock stopped at 7 so digit is 7. Count red blooms = 3.',
    'Hint 3: The code in order is 4 - 1 - 7 - 3. Set the wheels and press UNLOCK.'
  ];
  let hintIdx = 0;
  main.on('hintBtn', 'click', () => {
    if (hintIdx < 3) {
      main.set('hintText', { text: hints[hintIdx] });
      hintIdx += 1;
      main.set('hintCount', { text: 'Hint ' + hintIdx + ' of 3' });
      if (hintIdx === 3) main.set('hintBtn', { text: 'No more hints' });
    } else {
      main.set('hintText', { text: 'No more hints. Code is 4-1-7-3.' });
    }
  });

  // clue interactions (grab + press for details)
  traits(bookGroup, {
    grab: true,
    onPress: () => showClue('Clue 1: Dusty Logbook', 'Cover reads CHAPTER 4, PAGE 1. Two numbers in order: 4 then 1. Those are digits 1 and 2.')
  });
  traits(clockGroup, {
    grab: true,
    onPress: () => showClue('Clue 2: Stopped Clock', 'Hands froze at 7 o clock. Hour hand points at 7. That is digit 3 = 7.')
  });
  traits(plantGroup, {
    grab: true,
    onPress: () => showClue('Clue 3: Potted Plant', 'Count the red blooms: 1, 2, 3. Three flowers. That is digit 4 = 3. Full code 4-1-7-3.')
  });

  refreshDigits();

  return {
    root,
    update(time, delta) {
      if (!unlocked) return;
      if (openT < 1) openT = Math.min(1, openT + delta / 1.6);
      const e = 1 - Math.pow(1 - openT, 3);
      lidPivot.rotation.x = -e * 1.95;
      const gs = Math.min(1, Math.max(0, (openT - 0.2) / 0.5));
      const s = 0.001 + gs * 1.0;
      gemMesh.scale.setScalar(s);
      gemBase.scale.setScalar(s);
      gemMesh.position.y = 0.10 + e * 0.13;
      gemMesh.rotation.y = time * 1.4;
      gemMesh.position.x = Math.sin(time * 0.8) * 0.005 * e;
      glowMat.opacity = e * (0.55 + 0.2 * Math.sin(time * 4));
      lockBar.position.y = 0.08 - e * 0.05;
      lockBar.rotation.x = e * 0.9;
      if (confettiActive) {
        confettiT += delta;
        const grav = 1.4 * delta;
        for (let i = 0; i < CONF_N; i++) {
          confVel[i * 3 + 1] -= grav;
          confPos[i * 3] += confVel[i * 3] * delta;
          confPos[i * 3 + 1] += confVel[i * 3 + 1] * delta;
          confPos[i * 3 + 2] += confVel[i * 3 + 2] * delta;
          if (confPos[i * 3 + 1] < 0.012) {
            confPos[i * 3 + 1] = 0.012;
            confVel[i * 3] *= 0.9;
            confVel[i * 3 + 1] = 0;
            confVel[i * 3 + 2] *= 0.9;
          }
          dummy.position.set(confPos[i * 3], confPos[i * 3 + 1], confPos[i * 3 + 2]);
          dummy.rotation.set(time * 2 + i, i * 1.3, time * 1.5 + i * 0.7);
          dummy.scale.setScalar(1);
          dummy.updateMatrix();
          confetti.setMatrixAt(i, dummy.matrix);
        }
        confetti.instanceMatrix.needsUpdate = true;
        if (confettiT > 5) confettiActive = false;
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

  // ---------------- materials ----------------
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x262b33, roughness: 0.95, metalness: 0.05 });
  const sofaMat = new THREE.MeshStandardMaterial({ color: 0x55637a, roughness: 0.85 });
  const counterMat = new THREE.MeshStandardMaterial({ color: 0x7b8794, roughness: 0.8 });
  const bedMat = new THREE.MeshStandardMaterial({ color: 0x8794ad, roughness: 0.85 });
  const pillowMat = new THREE.MeshStandardMaterial({ color: 0xc3cddb, roughness: 0.9 });
  const tubMat = new THREE.MeshStandardMaterial({ color: 0xa9b8c8, roughness: 0.6 });
  const steelMat = new THREE.MeshStandardMaterial({ color: 0x5a6270, roughness: 0.5, metalness: 0.4 });

  // ---------------- state ----------------
  let temp = 21.0;
  let kitchenKwh = 0.8;
  let mediaKwh = 0.6;
  const otherKwh = 0.5;
  let modeName = 'Home';
  let selected = null;

  // ---------------- apartment model ----------------
  const APT_X = -0.19;
  const APT_Z = -0.05;

  const slab = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.012, 0.22), darkMat);
  slab.position.set(APT_X, 0.006, APT_Z);
  slab.name = 'ApartmentSlab';
  root.add(slab);

  const tileGeo = new THREE.BoxGeometry(0.145, 0.008, 0.095);
  const postGeo = new THREE.CylinderGeometry(0.0026, 0.0026, 0.03, 8);
  const bulbGeo = new THREE.SphereGeometry(0.0075, 12, 8);

  const roomDefs = [
    { id: 'living', name: 'Living room', dx: -0.0775, dz: 0.0525, level: 0.8 },
    { id: 'kitchen', name: 'Kitchen', dx: 0.0775, dz: 0.0525, level: 1.0 },
    { id: 'bedroom', name: 'Bedroom', dx: -0.0775, dz: -0.0525, level: 0.4 },
    { id: 'bath', name: 'Bathroom', dx: 0.0775, dz: -0.0525, level: 0.0 },
  ];

  const rooms = [];

  for (const def of roomDefs) {
    const wx = APT_X + def.dx;
    const wz = APT_Z + def.dz;

    const mat = new THREE.MeshStandardMaterial({
      color: 0x3b424c, roughness: 0.75, metalness: 0.05,
      emissive: 0xffc27a, emissiveIntensity: 0.05,
    });
    const tile = new THREE.Mesh(tileGeo, mat);
    tile.position.set(wx, 0.020, wz);
    tile.name = 'Room_' + def.id;
    root.add(tile);

    const furn = new THREE.Group();
    furn.position.set(wx, 0.024, wz);
    root.add(furn);

    if (def.id === 'living') {
      const sofa = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.016, 0.024), sofaMat);
      sofa.position.set(0, 0.008, -0.028);
      furn.add(sofa);
    } else if (def.id === 'kitchen') {
      const counter = new THREE.Mesh(new THREE.BoxGeometry(0.085, 0.02, 0.018), counterMat);
      counter.position.set(0, 0.01, -0.032);
      furn.add(counter);
      const hob = new THREE.Mesh(new THREE.BoxGeometry(0.022, 0.005, 0.014), steelMat);
      hob.position.set(-0.026, 0.0225, -0.032);
      furn.add(hob);
    } else if (def.id === 'bedroom') {
      const bed = new THREE.Mesh(new THREE.BoxGeometry(0.044, 0.012, 0.056), bedMat);
      bed.position.set(-0.028, 0.006, 0.004);
      furn.add(bed);
      const pillow = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.007, 0.012), pillowMat);
      pillow.position.set(-0.028, 0.0155, -0.018);
      furn.add(pillow);
    } else {
      const tub = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.014, 0.05), tubMat);
      tub.position.set(0.038, 0.007, 0.0);
      furn.add(tub);
    }

    const post = new THREE.Mesh(postGeo, darkMat);
    post.position.set(0.052, 0.015, -0.03);
    furn.add(post);

    const bulbMat = new THREE.MeshStandardMaterial({
      color: 0xfff3d6, emissive: 0xffdca0, emissiveIntensity: 1.0, roughness: 0.4,
    });
    const bulb = new THREE.Mesh(bulbGeo, bulbMat);
    bulb.position.set(0.052, 0.034, -0.03);
    bulb.name = 'Lamp_' + def.id;
    furn.add(bulb);

    const room = {
      id: def.id, name: def.name, dx: def.dx, dz: def.dz,
      level: def.level, shown: def.level, mat: mat, bulbMat: bulbMat,
    };
    rooms.push(room);

    traits(tile, { onPress: () => selectRoom(room) });
  }

  // selection frame under the active room
  const selMat = new THREE.MeshStandardMaterial({
    color: 0x0a2b3a, emissive: 0x4fd1ff, emissiveIntensity: 1.0, roughness: 0.4,
  });
  const selPlate = new THREE.Mesh(new THREE.BoxGeometry(0.157, 0.004, 0.107), selMat);
  selPlate.name = 'SelectedRoomFrame';
  root.add(selPlate);

  // ---------------- thermostat ----------------
  const TS_X = 0.26;
  const TS_Z = 0.145;

  const tsBase = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.008, 28), darkMat);
  tsBase.position.set(TS_X, 0.004, TS_Z);
  tsBase.name = 'ThermostatBase';
  root.add(tsBase);

  const towerMat = new THREE.MeshStandardMaterial({
    color: 0x3a4048, roughness: 0.45, metalness: 0.25,
    emissive: 0xff8a4c, emissiveIntensity: 0.5,
  });
  const tower = new THREE.Mesh(new THREE.CylinderGeometry(0.026, 0.03, 0.08, 28), towerMat);
  tower.position.set(TS_X, 0.048, TS_Z);
  tower.name = 'Thermostat';
  root.add(tower);

  const capMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, emissive: 0xff8a4c, emissiveIntensity: 1.2, roughness: 0.3,
  });
  const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.006, 28), capMat);
  cap.position.set(TS_X, 0.091, TS_Z);
  cap.name = 'ThermostatCap';
  root.add(cap);

  const btnMat = new THREE.MeshStandardMaterial({ color: 0x3d4450, roughness: 0.6, metalness: 0.15 });
  const iconMat = new THREE.MeshStandardMaterial({
    color: 0xeaf0f8, emissive: 0xdfe8f5, emissiveIntensity: 0.4, roughness: 0.4,
  });
  const btnGeo = new THREE.CylinderGeometry(0.018, 0.018, 0.012, 20);

  function makePad(x, z, plus) {
    const pad = new THREE.Mesh(btnGeo, btnMat);
    pad.position.set(x, 0.006, z);
    pad.name = plus ? 'TempUp' : 'TempDown';
    root.add(pad);
    const barH = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.004, 0.006), iconMat);
    barH.position.set(0, 0.0065, 0);
    pad.add(barH);
    if (plus) {
      const barV = new THREE.Mesh(new THREE.BoxGeometry(0.006, 0.004, 0.02), iconMat);
      barV.position.set(0, 0.0065, 0);
      pad.add(barV);
    }
    return pad;
  }

  const upPad = makePad(TS_X + 0.07, TS_Z, true);
  const downPad = makePad(TS_X - 0.07, TS_Z, false);
  traits(upPad, { onPress: () => setTemp(temp + 0.5) });
  traits(downPad, { onPress: () => setTemp(temp - 0.5) });

  const colCold = new THREE.Color(0x4f8fe0);
  const colWarm = new THREE.Color(0xff7a3c);
  const colNow = new THREE.Color();

  function setTemp(v) {
    temp = clamp(Math.round(v * 2) / 2, 16, 28);
    const t = (temp - 16) / 12;
    colNow.copy(colCold).lerp(colWarm, t);
    towerMat.emissive.copy(colNow);
    towerMat.emissiveIntensity = 0.55;
    capMat.emissive.copy(colNow);
    refreshPanel();
  }

  // ---------------- energy chart ----------------
  const CH_X = -0.245;
  const CH_Z = 0.165;

  const chartBase = new THREE.Mesh(new THREE.BoxGeometry(0.235, 0.008, 0.062), darkMat);
  chartBase.position.set(CH_X, 0.004, CH_Z);
  chartBase.name = 'EnergyBase';
  root.add(chartBase);

  const barGeo = new THREE.BoxGeometry(0.03, 1, 0.03);
  barGeo.translate(0, 0.5, 0);

  const barColors = [0xffd166, 0x6fb1ff, 0xff8a5c, 0xa78bfa, 0x6ee7b7];
  const bars = [];
  for (let i = 0; i < 5; i++) {
    const m = new THREE.MeshStandardMaterial({
      color: barColors[i], emissive: barColors[i], emissiveIntensity: 0.4,
      roughness: 0.45, metalness: 0.1,
    });
    const b = new THREE.Mesh(barGeo, m);
    b.position.set(CH_X - 0.09 + i * 0.045, 0.008, CH_Z);
    b.scale.y = 0.03;
    b.name = 'EnergyBar' + (i + 1);
    root.add(b);
    bars.push({ mesh: b, shown: 0.03 });
  }

  function lightsKwh() {
    let lit = 0;
    for (let i = 0; i < rooms.length; i++) lit += rooms[i].level;
    return 0.3 + 0.55 * lit;
  }
  function climateKwh() {
    return clamp(0.25 + (temp - 15) * 0.28, 0.2, 3.6);
  }
  function totalKwh() {
    return lightsKwh() + climateKwh() + kitchenKwh + mediaKwh + otherKwh;
  }
  function barHeight(v) {
    return clamp(v / 2.2, 0.06, 1) * 0.095;
  }

  // ---------------- control panel ----------------
  const panel = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 12px; padding-top: 20px; padding-bottom: 20px;
              padding-left: 24px; padding-right: 24px; border-radius: 20px; background-color: #1b1e24; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .sub { color: #8fa0b4; font-size: 22px; }
      .row { display: flex; flex-direction: row; align-items: center; justify-content: space-between; gap: 12px; }
      .label { color: #e8edf5; font-size: 24px; font-weight: 600; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 18px; padding-right: 18px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      .scene { background-color: #3a4150; }
      .energy { color: #ffd166; font-size: 22px; font-weight: 600; }
      .foot { color: #8fa0b4; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Smart Home</span>
      <span class="sub" id="mode">Mode: Home</span>
      <div class="row">
        <span class="label" id="room">Living room 80%</span>
        <button class="btn" id="dim"><span class="btn-text">Dim</span></button>
        <button class="btn" id="bright"><span class="btn-text">Bright</span></button>
      </div>
      <span class="label" id="temp">Heat set to 21.0 \u00b0C</span>
      <div class="row">
        <button class="btn scene" id="movie"><span class="btn-text">Movie</span></button>
        <button class="btn scene" id="dinner"><span class="btn-text">Dinner</span></button>
        <button class="btn scene" id="away"><span class="btn-text">Away</span></button>
      </div>
      <span class="energy" id="energy">Today: 5.3 kWh</span>
      <span class="foot">Bars: lights, heat, kitchen, media, other</span>
    </div>`, { width: 0.34, position: [0.21, 0.20, -0.06], rotationY: -0.3 });
  root.add(panel.object3D);

  function refreshPanel() {
    const pct = Math.round(selected.level * 100);
    panel.set('room', { text: selected.name + ' ' + pct + '%' });
    panel.set('mode', { text: 'Mode: ' + modeName });
    panel.set('temp', { text: 'Heat set to ' + temp.toFixed(1) + ' \u00b0C' });
    panel.set('energy', { text: 'Today: ' + totalKwh().toFixed(1) + ' kWh' });
  }

  function selectRoom(room) {
    selected = room;
    selPlate.position.set(APT_X + room.dx, 0.014, APT_Z + room.dz);
    refreshPanel();
  }

  function roomById(id) {
    for (let i = 0; i < rooms.length; i++) if (rooms[i].id === id) return rooms[i];
    return rooms[0];
  }

  function applyScene(name) {
    if (name === 'movie') {
      roomById('living').level = 0.15;
      roomById('kitchen').level = 0.0;
      roomById('bedroom').level = 0.0;
      roomById('bath').level = 0.0;
      temp = 22.5;
      kitchenKwh = 0.5;
      mediaKwh = 1.6;
      modeName = 'Movie';
    } else if (name === 'dinner') {
      roomById('living').level = 0.6;
      roomById('kitchen').level = 1.0;
      roomById('bedroom').level = 0.0;
      roomById('bath').level = 0.0;
      temp = 21.5;
      kitchenKwh = 1.9;
      mediaKwh = 0.7;
      modeName = 'Dinner';
    } else {
      roomById('living').level = 0.0;
      roomById('kitchen').level = 0.0;
      roomById('bedroom').level = 0.0;
      roomById('bath').level = 0.0;
      temp = 17.0;
      kitchenKwh = 0.25;
      mediaKwh = 0.2;
      modeName = 'Away';
    }
    setTemp(temp);
    refreshPanel();
  }

  panel.on('dim', 'click', () => {
    selected.level = Math.round(clamp(selected.level - 0.2, 0, 1) * 10) / 10;
    refreshPanel();
  });
  panel.on('bright', 'click', () => {
    selected.level = Math.round(clamp(selected.level + 0.2, 0, 1) * 10) / 10;
    refreshPanel();
  });
  panel.on('movie', 'click', () => applyScene('movie'));
  panel.on('dinner', 'click', () => applyScene('dinner'));
  panel.on('away', 'click', () => applyScene('away'));

  // ---------------- start ----------------
  selectRoom(rooms[0]);
  setTemp(21.0);

  const barVals = [0, 0, 0, 0, 0];

  return {
    root,
    update(time, delta) {
      const dt = delta || 0.016;
      const k = Math.min(1, dt * 9);

      for (let i = 0; i < rooms.length; i++) {
        const r = rooms[i];
        r.shown += (r.level - r.shown) * k;
        r.mat.emissiveIntensity = 0.03 + r.shown * 0.85;
        r.bulbMat.emissiveIntensity = 0.05 + r.shown * 2.2;
      }

      selMat.emissiveIntensity = 0.85 + 0.35 * Math.sin(time * 3.2);

      barVals[0] = lightsKwh();
      barVals[1] = climateKwh();
      barVals[2] = kitchenKwh;
      barVals[3] = mediaKwh;
      barVals[4] = otherKwh;

      for (let i = 0; i < bars.length; i++) {
        const target = barHeight(barVals[i]);
        bars[i].shown += (target - bars[i].shown) * k;
        bars[i].mesh.scale.y = bars[i].shown;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  /* ---------------------------------------------------------------- data */
  const PRI = { High: '#e5484d', Med: '#f5a524', Low: '#4cc38a' };
  const COL_NAMES = ['To do', 'In progress', 'Review', 'Done'];
  const DAYS = 6;

  const cards = [
    { t: 'Payments', p: 8, pr: 'High' },
    { t: 'Login bug', p: 3, pr: 'High' },
    { t: 'Onboarding', p: 2, pr: 'Low' },
    { t: 'Filters', p: 5, pr: 'Med' },
    { t: 'Dark mode', p: 3, pr: 'Low' },
    { t: 'Unit tests', p: 3, pr: 'High' },
  ];
  const NCARD = cards.length;
  const TOTAL = cards.reduce((a, c) => a + c.p, 0); // 24 story points

  const col = [0, 0, 0, 1, 1, 2]; // which column each card sits in
  let highOnly = false;
  let dayIndex = 0;
  const actual = [TOTAL, 0, 0, 0, 0, 0]; // remaining points logged per sprint day

  /* ------------------------------------------------------- board markup */
  let boardCols = '';
  for (let c = 0; c < 4; c++) {
    let slots = '';
    for (let k = 0; k < 6; k++) {
      const id = 's' + c + k;
      slots +=
        '<div class="card" id="' + id + '">' +
          '<div class="crow">' +
            '<div class="dot" id="' + id + 'd"></div>' +
            '<span class="ctitle" id="' + id + 't">Task</span>' +
          '</div>' +
          '<div class="crow2">' +
            '<button class="arw" id="' + id + 'l"><span class="arwt">&lt;</span></button>' +
            '<button class="arw" id="' + id + 'r"><span class="arwt">&gt;</span></button>' +
          '</div>' +
        '</div>';
    }
    boardCols +=
      '<div class="col">' +
        '<span class="colhead" id="ch' + c + '">' + COL_NAMES[c] + '</span>' +
        slots +
      '</div>';
  }

  const board = ui(`
    <style>
      .app { width: 720px; flex-direction: column; gap: 10px; padding-top: 14px; padding-bottom: 14px;
             padding-left: 16px; padding-right: 16px; background-color: #14171c; border-radius: 20px; }
      .hrow { flex-direction: row; align-items: center; justify-content: space-between; gap: 10px; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .done { color: #8b94a3; font-size: 22px; }
      .fbtn { padding-top: 8px; padding-bottom: 8px; padding-left: 14px; padding-right: 14px;
              border-radius: 10px; background-color: #2a2f38; }
      .fbtnt { color: #e6eaf0; font-size: 22px; font-weight: 700; }
      .legend { flex-direction: row; align-items: center; gap: 12px; }
      .ldot { width: 14px; height: 14px; border-radius: 7px; }
      .ph { background-color: #e5484d; }
      .pm { background-color: #f5a524; }
      .pl { background-color: #4cc38a; }
      .ltext { color: #8b94a3; font-size: 20px; }
      .board { flex-direction: row; align-items: flex-start; gap: 10px; }
      .col { width: 163px; flex-direction: column; align-items: center; gap: 6px; padding-top: 8px;
             padding-bottom: 10px; padding-left: 6px; padding-right: 6px; background-color: #1c2028;
             border-radius: 12px; }
      .colhead { color: #8b94a3; font-size: 22px; font-weight: 700; }
      .card { width: 148px; flex-direction: column; gap: 2px; padding-top: 3px; padding-bottom: 3px;
              padding-left: 5px; padding-right: 5px; background-color: #2a2f38; border-radius: 8px; }
      .crow { flex-direction: row; align-items: center; gap: 6px; height: 26px; }
      .dot { width: 8px; height: 22px; border-radius: 4px; background-color: #e5484d; }
      .ctitle { width: 118px; color: #eef1f5; font-size: 20px; }
      .crow2 { flex-direction: row; justify-content: center; gap: 6px; }
      .arw { width: 62px; height: 34px; border-radius: 6px; background-color: #39404e;
             align-items: center; justify-content: center; }
      .arwt { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="app">
      <div class="hrow">
        <span class="title">Sprint 12 board</span>
        <button class="fbtn" id="filter"><span class="fbtnt" id="filterText">All priorities</span></button>
        <span class="done" id="doneText">Done 0 of 6</span>
      </div>
      <div class="legend">
        <div class="ldot ph"></div><span class="ltext">High</span>
        <div class="ldot pm"></div><span class="ltext">Med</span>
        <div class="ldot pl"></div><span class="ltext">Low</span>
      </div>
      <div class="board">${boardCols}</div>
    </div>`, { width: 0.46, position: [-0.16, 0.26, 0.02], rotationY: 0.28 });
  root.add(board.object3D);

  /* -------------------------------------------------------- chart panel */
  const chartPanel = ui(`
    <style>
      .capp { width: 400px; flex-direction: column; gap: 6px; padding-top: 12px; padding-bottom: 12px;
              padding-left: 16px; padding-right: 16px; background-color: #14171c; border-radius: 16px; }
      .ct { color: #ffffff; font-size: 28px; font-weight: 700; }
      .cr { color: #4cc3ff; font-size: 26px; font-weight: 700; }
      .cd { color: #9aa3b0; font-size: 22px; }
      .cbtn { margin-top: 4px; height: 54px; padding-left: 14px; padding-right: 14px; border-radius: 10px;
              background-color: #2f6fdb; align-items: center; justify-content: center; }
      .cbtnt { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="capp">
      <span class="ct">Burndown</span>
      <span class="cr" id="remain">24 pts left</span>
      <span class="cd" id="dayText">Day 1 of 6</span>
      <span class="cd" id="idealText">Ideal line: 24 pts</span>
      <button class="cbtn" id="endDay"><span class="cbtnt" id="endDayText">End day -&gt;</span></button>
    </div>`, { width: 0.24, position: [0.24, 0.32, 0.0], rotationY: -0.3 });
  root.add(chartPanel.object3D);

  /* --------------------------------------------------- 3D burndown chart */
  const BASE_Y = 0.09;
  const CHART_CX = 0.24;
  const MPP = 0.125 / TOTAL; // metres per story point

  const base = new THREE.Mesh(
    new THREE.BoxGeometry(0.26, 0.014, 0.08),
    new THREE.MeshStandardMaterial({ color: 0x232a33, roughness: 0.85, metalness: 0.1 }),
  );
  base.name = 'ChartBase';
  base.position.set(CHART_CX, BASE_Y - 0.007, 0);
  root.add(base);

  const barGeo = new THREE.BoxGeometry(0.026, 1, 0.032);
  const markGeo = new THREE.BoxGeometry(0.028, 0.005, 0.008);
  const pastMat = new THREE.MeshStandardMaterial({ color: 0x2f7fb8, emissive: 0x123c58, emissiveIntensity: 0.6, roughness: 0.5 });
  const nowMat = new THREE.MeshStandardMaterial({ color: 0x4cc3ff, emissive: 0x1d7fb0, emissiveIntensity: 0.9, roughness: 0.4 });
  const markMat = new THREE.MeshStandardMaterial({ color: 0xc8d2de, emissive: 0x2a3038, emissiveIntensity: 0.5, roughness: 0.6 });

  const bars = [];
  const barTarget = [];
  for (let d = 0; d < DAYS; d++) {
    const x = CHART_CX - 0.12 + (d + 0.5) * 0.04;

    const bar = new THREE.Mesh(barGeo, pastMat);
    bar.name = 'DayBar' + (d + 1);
    bar.scale.y = 0.001;
    bar.position.set(x, BASE_Y + 0.0005, 0);
    root.add(bar);
    bars.push(bar);
    barTarget.push(0.001);

    // ghost marker = ideal remaining work at the start of that day
    const idealPts = TOTAL * (DAYS - d) / DAYS;
    const mark = new THREE.Mesh(markGeo, markMat);
    mark.name = 'IdealDay' + (d + 1);
    mark.position.set(x, BASE_Y + Math.max(0.002, idealPts * MPP), -0.026);
    root.add(mark);
  }

  /* ------------------------------------------------------------ helpers */
  const slotCard = [];
  for (let c = 0; c < 4; c++) slotCard.push([-1, -1, -1, -1, -1, -1]);

  function remainingPts() {
    let r = 0;
    for (let i = 0; i < NCARD; i++) if (col[i] !== 3) r += cards[i].p;
    return r;
  }

  function refreshChart() {
    const rem = remainingPts();
    actual[dayIndex] = rem;

    for (let d = 0; d < DAYS; d++) {
      barTarget[d] = Math.max(actual[d] * MPP, 0.0012);
      bars[d].visible = d <= dayIndex;
      bars[d].material = (d === dayIndex) ? nowMat : pastMat;
    }

    chartPanel.set('remain', { text: rem + ' pts left' });
    chartPanel.set('dayText', { text: 'Day ' + (dayIndex + 1) + ' of ' + DAYS });
    const idealPts = Math.round(TOTAL * (DAYS - dayIndex) / DAYS);
    chartPanel.set('idealText', { text: 'Ideal line: ' + idealPts + ' pts' });
    chartPanel.set('endDayText', { text: dayIndex >= DAYS - 1 ? 'Restart sprint' : 'End day ->' });
  }

  function render() {
    let doneCount = 0;
    for (let i = 0; i < NCARD; i++) if (col[i] === 3) doneCount++;

    board.set('doneText', { text: 'Done ' + doneCount + ' of ' + NCARD });
    board.set('filterText', { text: highOnly ? 'High only: on' : 'All priorities' });
    board.set('filter', { backgroundColor: highOnly ? '#2f6fdb' : '#2a2f38' });

    for (let c = 0; c < 4; c++) {
      let k = 0;
      for (let i = 0; i < NCARD; i++) {
        if (col[i] !== c) continue;
        if (highOnly && cards[i].pr !== 'High') continue;
        const id = 's' + c + k;
        slotCard[c][k] = i;
        board.set(id, { display: 'flex' });
        board.set(id + 't', { text: cards[i].t });
        board.set(id + 'd', { backgroundColor: PRI[cards[i].pr] });
        k++;
      }
      for (; k < 6; k++) {
        slotCard[c][k] = -1;
        board.set('s' + c + k, { display: 'none' });
      }
      board.set('ch' + c, { text: COL_NAMES[c] + ' ' + k });
    }

    refreshChart();
  }

  /* ---------------------------------------------------------- handlers */
  function move(c, k, dir) {
    const ci = slotCard[c][k];
    if (ci < 0) return;
    const nc = col[ci] + dir;
    if (nc < 0 || nc > 3) return;
    col[ci] = nc;
    render();
  }

  for (let c = 0; c < 4; c++) {
    for (let k = 0; k < 6; k++) {
      const cc = c;
      const kk = k;
      board.on('s' + c + k + 'l', 'click', () => move(cc, kk, -1));
      board.on('s' + c + k + 'r', 'click', () => move(cc, kk, 1));
    }
  }

  board.on('filter', 'click', () => {
    highOnly = !highOnly;
    render();
  });

  chartPanel.on('endDay', 'click', () => {
    actual[dayIndex] = remainingPts();
    if (dayIndex < DAYS - 1) {
      dayIndex++;
      actual[dayIndex] = remainingPts();
    } else {
      dayIndex = 0;
      for (let d = 0; d < DAYS; d++) actual[d] = 0;
      actual[0] = remainingPts();
    }
    refreshChart();
  });

  render();

  /* ------------------------------------------------------------ update */
  return {
    root,
    update(time, delta) {
      const k = Math.min(1, (delta || 0.016) * 9);
      for (let d = 0; d < DAYS; d++) {
        const m = bars[d];
        const h = m.scale.y + (barTarget[d] - m.scale.y) * k;
        m.scale.y = h;
        m.position.y = BASE_Y + h / 2;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  // ---------------------------------------------------------------- panel
  const info = ui(`
