             border-radius: 12px; background-color: #2a2e35; align-items: center; justify-content: center; }
      .ansText { color: #e8ecf2; font-size: 21px; }
    </style>
    <div class="card">
      <span class="title">Bones of the Human Arm</span>
      <span class="bname" id="bname">Tap a bone</span>
      <span class="body" id="bfact">Pinch a bone to lift it out of the arm. Tap a bone to learn its name and job. Press Reassemble to rebuild the arm.</span>
      <div class="row">
        <button class="btn" id="fix"><span class="btnText">Reassemble</span></button>
        <button class="btn" id="start"><span class="btnText" id="startLabel">Start quiz</span></button>
      </div>
      <span class="stat" id="score">Score: 0 of 0</span>
      <span class="qtext" id="question">Press Start quiz for 5 questions.</span>
      <div class="answers" id="answers">
        <button class="ans" id="a0"><span class="ansText" id="a0t">-</span></button>
        <button class="ans" id="a1"><span class="ansText" id="a1t">-</span></button>
        <button class="ans" id="a2"><span class="ansText" id="a2t">-</span></button>
      </div>
    </div>`, { width: 0.28, position: [0.26, 0.25, 0], rotationY: -0.3 });
  root.add(info.object3D);
  info.set('answers', { display: 'none' });

  // ---------------------------------------------------------------- bones
  const boneFacts = {
    Humerus: 'The only bone of the upper arm. It meets the scapula at the shoulder and the radius and ulna at the elbow.',
    Radius: 'The forearm bone on the thumb side. It swings over the ulna so you can turn your palm up.',
    Ulna: 'The forearm bone on the little-finger side. Its hook shapes the hinge of the elbow.',
    Carpals: 'Eight small wrist bones in two rows. They let the wrist and hand move smoothly.',
    'Hand bones': 'Five metacarpals form the palm and fourteen phalanges form the fingers.',
  };

  function makeBoneMaterial() {
    return new THREE.MeshStandardMaterial({
      color: 0xefe6d0, roughness: 0.75, metalness: 0.03,
      emissive: 0x000000, emissiveIntensity: 0,
    });
  }

  function boneGeometry(length, rMid, rTop, rBot) {
    const half = length / 2;
    const N = 10;
    const pts = [new THREE.Vector2(0.0002, -half)];
    for (let i = 0; i <= N; i++) {
      const t = i / N;
      const endR = rBot + (rTop - rBot) * t;
      const bulge = Math.pow(Math.abs(t - 0.5) * 2, 2.4);
      const r = Math.max(0.0008, rMid + (endR - rMid) * bulge);
      pts.push(new THREE.Vector2(r, -half + t * length));
    }
    pts.push(new THREE.Vector2(0.0002, half));
    return new THREE.LatheGeometry(pts, 16);
  }

  const boneGroups = [];

  function registerBone(name, group, pos, mat) {
    group.position.set(pos[0], pos[1], pos[2]);
    group.name = name;
    root.add(group);
    boneGroups.push({
      name, group, mat,
      home: group.position.clone(),
      homeQuat: group.quaternion.clone(),
    });
    traits(group, { grab: true, onPress: () => selectBone(name) });
  }

  function longBone(name, length, rMid, rTop, rBot, pos) {
    const mat = makeBoneMaterial();
    const g = new THREE.Group();
    const mesh = new THREE.Mesh(boneGeometry(length, rMid, rTop, rBot), mat);
    mesh.name = name;
    g.add(mesh);
    registerBone(name, g, pos, mat);
  }

  longBone('Humerus', 0.112, 0.0085, 0.0165, 0.0135, [-0.130, 0.305, 0]);
  longBone('Radius', 0.104, 0.0055, 0.0062, 0.0115, [-0.111, 0.190, 0]);
  longBone('Ulna', 0.108, 0.0055, 0.0118, 0.0058, [-0.148, 0.192, 0]);

  // hand: 8 carpals + 5 metacarpals + 14 phalanges, one grabbable group
  const handMat = makeBoneMaterial();
  const hand = new THREE.Group();

  const carpalGeo = new THREE.SphereGeometry(0.0062, 12, 10);
  for (let row = 0; row < 2; row++) {
    for (let col = 0; col < 4; col++) {
      const m = new THREE.Mesh(carpalGeo, handMat);
      m.position.set((col - 1.5) * 0.0175, 0.017 - row * 0.012, 0);
      hand.add(m);
    }
  }

  const metaGeo = new THREE.CylinderGeometry(0.0032, 0.0028, 0.030, 8, 1);
  const metaX = [0.030, 0.014, 0.000, -0.014, -0.029];
  for (let i = 0; i < 5; i++) {
    const m = new THREE.Mesh(metaGeo, handMat);
    m.position.set(metaX[i], -0.020, 0);
    hand.add(m);
  }

  const fingerData = [
    { x: 0.030, y: -0.030, dir: 0.55, segs: [0.012, 0.010], r: 0.0032 },
    { x: 0.014, y: -0.036, dir: 0.06, segs: [0.012, 0.009, 0.007], r: 0.0028 },
    { x: 0.000, y: -0.037, dir: 0.00, segs: [0.013, 0.010, 0.008], r: 0.0028 },
    { x: -0.014, y: -0.036, dir: -0.06, segs: [0.012, 0.009, 0.007], r: 0.0028 },
    { x: -0.029, y: -0.034, dir: -0.12, segs: [0.010, 0.008, 0.006], r: 0.0026 },
  ];
  for (let fi = 0; fi < fingerData.length; fi++) {
    const f = fingerData[fi];
    let px = f.x, py = f.y;
    const sx = Math.sin(f.dir), sy = Math.cos(f.dir);
    for (let s = 0; s < f.segs.length; s++) {
      const len = f.segs[s];
      const m = new THREE.Mesh(new THREE.CylinderGeometry(f.r, f.r * 0.88, len * 0.82, 8, 1), handMat);
      m.position.set(px + sx * len * 0.5, py - sy * len * 0.5, 0);
      m.rotation.z = f.dir;
      hand.add(m);
      px += sx * len;
      py -= sy * len;
    }
  }
  registerBone('Hand bones', hand, [-0.130, 0.113, 0], handMat);

  // ---------------------------------------------------------------- explore
  function selectBone(name) {
    info.set('bname', { text: name });
    info.set('bfact', { text: boneFacts[name] });
    for (let i = 0; i < boneGroups.length; i++) {
      const b = boneGroups[i];
      if (b.name === name) {
        b.mat.emissive.setHex(0x7a5a18);
        b.mat.emissiveIntensity = 0.9;
      } else {
        b.mat.emissive.setHex(0x000000);
        b.mat.emissiveIntensity = 0;
      }
    }
  }

  let reassembling = false;
  info.on('fix', 'click', () => { reassembling = true; });

  // ---------------------------------------------------------------- quiz
  const quiz = [
    {
      q: 'Which bone is the only bone in the upper arm?',
      a: ['Radius', 'Humerus', 'Ulna'], correct: 1,
      why: 'The humerus runs from the shoulder joint down to the elbow.',
    },
    {
      q: 'Which bone forms the bony point of the elbow?',
      a: ['Ulna', 'Radius', 'Carpals'], correct: 0,
      why: 'The olecranon of the ulna makes the point of the elbow.',
    },
    {
      q: 'Which forearm bone is on the thumb side?',
      a: ['Ulna', 'Radius', 'Humerus'], correct: 1,
      why: 'The radius lies on the thumb side, the ulna on the little-finger side.',
    },
    {
      q: 'How many carpal bones are in the wrist?',
      a: ['5', '8', '14'], correct: 1,
      why: '8 carpals. The palm has 5 metacarpals and the fingers 14 phalanges.',
    },
    {
      q: 'What happens when you turn your palm up?',
      a: ['Ulna rotates over radius', 'Radius rotates over ulna', 'Both bones stay still'], correct: 1,
      why: 'This is supination: the radius crosses over the ulna.',
    },
  ];

  let state = 'idle';
  let qIndex = -1;
  let correctCount = 0;
  let answeredCount = 0;

  function nextQuestion() {
    qIndex++;
    if (qIndex >= quiz.length) { finishQuiz(); return; }
    state = 'asking';
    const q = quiz[qIndex];
    info.set('question', { text: (qIndex + 1) + '. ' + q.q, color: '#e6ebf2' });
    for (let i = 0; i < 3; i++) {
      info.set('a' + i + 't', { text: q.a[i] });
      info.set('a' + i, { backgroundColor: '#2a2e35' });
    }
    info.set('answers', { display: 'flex' });
    info.set('start', { display: 'none' });
  }

  function answer(i) {
    if (state !== 'asking') return;
    const q = quiz[qIndex];
    state = 'feedback';
    answeredCount++;
    const right = i === q.correct;
    if (right) correctCount++;
    info.set('a' + q.correct, { backgroundColor: '#2e7d4f' });
    if (!right) info.set('a' + i, { backgroundColor: '#8c2f2f' });
    info.set('score', { text: 'Score: ' + correctCount + ' of ' + answeredCount });
    info.set('startLabel', { text: qIndex === quiz.length - 1 ? 'See result' : 'Next' });
    info.set('start', { display: 'flex' });
    info.set('question', {
      text: (right ? 'Correct! ' : 'Not quite. ') + q.why,
      color: right ? '#8fe0a4' : '#ffb4a8',
    });
  }

  function finishQuiz() {
    state = 'done';
    info.set('answers', { display: 'none' });
    info.set('startLabel', { text: 'Play again' });
    info.set('start', { display: 'flex' });
    info.set('question', {
      text: 'Quiz finished. You scored ' + correctCount + ' of ' + quiz.length + '. Tap bones to keep learning.',
      color: '#e6ebf2',
    });
  }

  info.on('a0', 'click', () => answer(0));
  info.on('a1', 'click', () => answer(1));
  info.on('a2', 'click', () => answer(2));
  info.on('start', 'click', () => {
    if (state === 'feedback') { nextQuestion(); return; }
    qIndex = -1;
    correctCount = 0;
    answeredCount = 0;
    info.set('score', { text: 'Score: 0 of 0' });
    nextQuestion();
  });

  // ---------------------------------------------------------------- loop
  return {
    root,
    update(time, delta) {
      if (!reassembling) return;
      const dt = Math.min(delta, 0.05);
      const k = 1 - Math.exp(-2.2 * dt);
      let moving = false;
      for (let i = 0; i < boneGroups.length; i++) {
        const b = boneGroups[i];
        if (isGrabbed(b.group)) { moving = true; continue; }
        b.group.position.lerp(b.home, k);
        b.group.quaternion.slerp(b.homeQuat, k);
        if (b.group.position.distanceToSquared(b.home) > 4e-6) moving = true;
      }
      if (!moving) reassembling = false;
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const twoPi = Math.PI * 2;

  // ------------------------------------------------------------------
  // Data (June is the "current" month, index 5)
  // ------------------------------------------------------------------
  const JUNE = 5;
  const juneTotal = 2200; // 1200 + 450 + 220 + 180 + 150
  const cats = [
    { key: 'Housing',   color: 0x4f8ef7, monthly: [1200, 1200, 1200, 1200, 1200, 1200] },
    { key: 'Food',      color: 0xf2b134, monthly: [430, 470, 400, 490, 455, 450] },
    { key: 'Transport', color: 0x5fd18a, monthly: [200, 240, 180, 230, 210, 220] },
    { key: 'Fun',       color: 0xc77dff, monthly: [170, 210, 130, 240, 190, 180] },
    { key: 'Other',     color: 0xff6b6b, monthly: [150, 160, 130, 160, 155, 150] },
  ];
  const totals = [2150, 2280, 2040, 2320, 2210, 2200];

  function fmt(n) {
    const s = String(Math.round(n));
    let out = '';
    for (let i = 0; i < s.length; i++) {
      if (i > 0 && (s.length - i) % 3 === 0) out += ',';
      out += s[i];
    }
    return out;
  }

  // ------------------------------------------------------------------
  // Donut chart of June spending (press a slice to filter the bars)
  // ------------------------------------------------------------------
  const donutPos = new THREE.Vector3(-0.25, 0.19, 0);

  const backDisc = new THREE.Mesh(
    new THREE.CircleGeometry(0.096, 40),
    new THREE.MeshBasicMaterial({ color: 0x14171b }),
  );
  backDisc.name = 'donut_back';
  backDisc.position.copy(donutPos);
  backDisc.position.z -= 0.008;
  root.add(backDisc);

  const segs = [];
  let acc = 0;
  for (let i = 0; i < cats.length; i++) {
    const frac = cats[i].monthly[JUNE] / juneTotal;
    acc += frac;
    const sweepStart = Math.PI / 2 - acc * twoPi;      // clockwise from the top
    const fullLen = frac * twoPi;
    const geo = new THREE.RingGeometry(
      0.046, 0.09, 40, 1,
      sweepStart + 0.016,
      Math.max(0.06, fullLen - 0.032),
    );
    const mat = new THREE.MeshStandardMaterial({
      color: cats[i].color,
      emissive: cats[i].color,
      emissiveIntensity: 0.22,
      roughness: 0.45,
      metalness: 0.15,
      side: THREE.DoubleSide,
    });
    const m = new THREE.Mesh(geo, mat);
    m.name = 'donut_' + cats[i].key;
    m.position.copy(donutPos);
    root.add(m);
    const idx = i;
    traits(m, { onPress: () => selectCategory(idx) });
    segs.push(m);
  }

  // ------------------------------------------------------------------
  // Bar chart of the last six months
  // ------------------------------------------------------------------
  const barBaseY = 0.102;
  const maxBarH = 0.17;
  const barGeo = new THREE.BoxGeometry(0.026, 1, 0.026);
  barGeo.translate(0, 0.5, 0); // scale.y grows the bar up from its base

  const barMat = new THREE.MeshStandardMaterial({
    color: 0x5aa9ff,
    emissive: 0x5aa9ff,
    emissiveIntensity: 0.25,
    roughness: 0.4,
    metalness: 0.2,
  });

  const bars = [];
  const barTargets = [0, 0, 0, 0, 0, 0];

  const basePlate = new THREE.Mesh(
    new THREE.BoxGeometry(0.25, 0.006, 0.05),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9 }),
  );
  basePlate.name = 'bar_baseline';
  basePlate.position.set(0.02, barBaseY - 0.003, 0);
  root.add(basePlate);

  for (let i = 0; i < 6; i++) {
    const b = new THREE.Mesh(barGeo, barMat);
    b.name = 'bar_' + i;
    b.position.set(0.02 + (i - 2.5) * 0.04, barBaseY, 0);
    b.scale.y = 0.001;
    root.add(b);
    bars.push(b);
  }

  // ------------------------------------------------------------------
  // Savings goal ring
  // ------------------------------------------------------------------
  const ringPos = new THREE.Vector3(0.28, 0.21, 0);
  const goal = 3000;
  let saved = 1850;
  let pulse = 0;

  const track = new THREE.Mesh(
    new THREE.RingGeometry(0.05, 0.062, 48),
    new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.9, side: THREE.DoubleSide }),
  );
  track.name = 'savings_track';
  track.position.copy(ringPos);
  root.add(track);

  const progressMat = new THREE.MeshStandardMaterial({
    color: 0x3ddc84,
    emissive: 0x3ddc84,
    emissiveIntensity: 0.35,
    roughness: 0.4,
    metalness: 0.2,
    side: THREE.DoubleSide,
  });

  let progressMesh = null;
  function setProgress(p) {
    if (progressMesh) {
      root.remove(progressMesh);
      progressMesh.geometry.dispose();
      progressMesh = null;
    }
    if (p <= 0.002) return;
    const geo = new THREE.RingGeometry(0.05, 0.062, 64, 1, Math.PI / 2 - p * twoPi, p * twoPi);
    progressMesh = new THREE.Mesh(geo, progressMat);
    progressMesh.name = 'savings_progress';
    progressMesh.position.copy(ringPos);
    root.add(progressMesh);
  }

  // ------------------------------------------------------------------
  // Panels
  // ------------------------------------------------------------------
  const status = ui(`
    <style>
      .card { width: 480px; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px;
              padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 24px; }
      .sel { color: #5aa9ff; font-size: 24px; font-weight: 700; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #2f6fdb; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Budget dashboard</span>
