    </div>`, { width: 0.32, position: [0.02, 0.38, 0] });
  root.add(status.object3D);

  const monthsUI = ui(`
    <style>
      .row { width: 480px; flex-direction: row; align-items: center; padding-top: 8px; padding-bottom: 8px;
             background-color: #1a1d22; border-radius: 10px; }
      .m { width: 80px; text-align: center; color: #8b939f; font-size: 24px; }
      .mcur { width: 80px; text-align: center; color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="row">
      <span class="m">Jan</span>
      <span class="m">Feb</span>
      <span class="m">Mar</span>
      <span class="m">Apr</span>
      <span class="m">May</span>
      <span class="mcur">Jun</span>
    </div>`, { width: 0.24, position: [0.02, 0.068, 0] });
  root.add(monthsUI.object3D);

  const savingsUI = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 8px; padding-top: 14px; padding-bottom: 14px;
              padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1f2228; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .line { color: #d7dbe2; font-size: 22px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
             border-radius: 12px; background-color: #2f9e63; align-items: center; justify-content: center; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Savings goal</span>
      <span class="line" id="save">$1,850 of $3,000 - 62%</span>
      <button class="btn" id="dep"><span class="btn-text" id="depText">Log $100 deposit</span></button>
    </div>`, { width: 0.24, position: [0.28, 0.08, 0] });
  root.add(savingsUI.object3D);

  // ------------------------------------------------------------------
  // State and interaction
  // ------------------------------------------------------------------
  let filter = -1; // -1 = all categories

  function applyFilter() {
    let vals, peak;
    if (filter < 0) {
      vals = totals;
      peak = 2320;
      status.set('sel', { text: 'Showing: All - peak $' + fmt(peak) });
    } else {
