    }
    for (let i = 0; i < 6; i++) barTargets[i] = (vals[i] / peak) * maxBarH;

    const col = filter < 0 ? 0x5aa9ff : cats[filter].color;
    barMat.color.setHex(col);
    barMat.emissive.setHex(col);

    for (let i = 0; i < segs.length; i++) {
      const sel = filter === i;
      segs[i].material.emissiveIntensity = sel ? 0.8 : (filter < 0 ? 0.22 : 0.08);
      const s = sel ? 1.07 : 1.0;
      segs[i].scale.set(s, s, 1);
    }
  }

  function selectCategory(i) {
    filter = (filter === i) ? -1 : i;
    applyFilter();
  }

  function updateSavings() {
    const p = Math.min(1, saved / goal);
    setProgress(p);
    if (saved >= goal) {
      progressMat.color.setHex(0xffd166);
      progressMat.emissive.setHex(0xffd166);
      savingsUI.set('save', { text: 'Goal reached: $' + fmt(goal) + ' saved!' });
      savingsUI.set('depText', { text: 'Goal complete' });
      savingsUI.set('dep', { backgroundColor: '#3a3f47' });
    } else {
      savingsUI.set('save', { text: '$' + fmt(saved) + ' of $' + fmt(goal) + ' - ' + Math.round(p * 100) + '%' });
    }
  }

  status.on('all', 'click', () => {
    filter = -1;
    applyFilter();
  });

  savingsUI.on('dep', 'click', () => {
    if (saved >= goal) return;
    saved = Math.min(goal, saved + 100);
    pulse = 1;
    updateSavings();
  });

  applyFilter();
  updateSavings();

  // ------------------------------------------------------------------
  // Animation
  // ------------------------------------------------------------------
  return {
    root,
    update(time, delta) {
      const k = Math.min(1, delta * 7);
      for (let i = 0; i < bars.length; i++) {
        const b = bars[i];
        const t = barTargets[i];
        if (t !== b.scale.y) {
          b.scale.y += (t - b.scale.y) * k;
          if (Math.abs(t - b.scale.y) < 0.0005) b.scale.y = t;
        }
      }
      if (pulse > 0) {
        pulse = Math.max(0, pulse - delta * 1.8);
        progressMat.emissiveIntensity = 0.35 + pulse * 1.5;
      }
    },
  };
}

