  const tickets = [
    { id: 'tk-0', name: 'Standard', price: '$199' },
    { id: 'tk-1', name: 'Pro', price: '$449' },
    { id: 'tk-2', name: 'Student', price: '$89' },
  ];
  const workshops = [
    { id: 'ws-0', title: 'Scaling Design Systems' },
    { id: 'ws-1', title: 'Practical AI Agents' },
    { id: 'ws-2', title: 'Zero-Trust Security' },
    { id: 'ws-3', title: 'Live Coding: WebGPU' },
  ];
  const sizes = ['S', 'M', 'L', 'XL', 'XXL'];
  const titles = [
    'Choose your ticket',
    'Pick up to two workshops',
    'Choose your t-shirt size',
    'Review and confirm',
    'Registration complete',
  ];
  const MAX_WORKSHOPS = 2;

  const state = { step: 1, ticket: -1, sizeIndex: 1 };
  const picked = [false, false, false, false];

  function pickedNames() {
    const out = [];
    for (let i = 0; i < workshops.length; i++) if (picked[i]) out.push(workshops[i].title);
    return out;
  }
  function pickedCount() {
    let n = 0;
    for (let i = 0; i < picked.length; i++) if (picked[i]) n++;
    return n;
  }
  function setMsg(t) {
    panel.set('msg', { text: t });
  }

  function render() {
    const s = state.step;
    panel.set('sec1', { display: s === 1 ? 'flex' : 'none' });
    panel.set('sec2', { display: s === 2 ? 'flex' : 'none' });
    panel.set('sec3', { display: s === 3 ? 'flex' : 'none' });
    panel.set('review', { display: s === 4 ? 'flex' : 'none' });
    panel.set('done', { display: s === 5 ? 'flex' : 'none' });
    panel.set('nav', { display: s <= 3 ? 'flex' : 'none' });
    panel.set('back', { display: s === 1 ? 'none' : 'flex' });
    panel.set('nextLabel', { text: s === 3 ? 'Review' : 'Next' });
    panel.set('title', { text: titles[s - 1] });
    panel.set('stepLabel', {
      text: s <= 3 ? 'Step ' + s + ' of 3' : (s === 4 ? 'Review' : 'Confirmed'),
    });

    for (let i = 0; i < tickets.length; i++) {
      panel.set(tickets[i].id, { backgroundColor: state.ticket === i ? '#2f6fdb' : '#262a32' });
    }
    for (let i = 0; i < workshops.length; i++) {
      const on = picked[i];
      panel.set(workshops[i].id, { backgroundColor: on ? '#2b3552' : '#262a32' });
      panel.set('box-' + i, { backgroundColor: on ? '#4ad991' : '#12151a' });
      panel.set('mark-' + i, { text: on ? 'X' : '' });
    }
    panel.set('sizeValue', { text: sizes[state.sizeIndex] });

    panel.set('rev-ticket', {
      text: state.ticket >= 0
        ? tickets[state.ticket].name + ' - ' + tickets[state.ticket].price
        : 'Not chosen',
    });
    const names = pickedNames();
    panel.set('rev-ws', { text: names.length ? names.join(', ') : 'None selected' });
    panel.set('rev-size', { text: sizes[state.sizeIndex] });
  }

  // Step 1 - ticket type
  for (let i = 0; i < tickets.length; i++) {
    panel.on(tickets[i].id, 'click', () => {
      state.ticket = i;
      setMsg('');
      render();
    });
  }

  // Step 2 - workshops with a two-item limit
  for (let i = 0; i < workshops.length; i++) {
    panel.on(workshops[i].id, 'click', () => {
      if (picked[i]) {
        picked[i] = false;
        setMsg('');
      } else if (pickedCount() >= MAX_WORKSHOPS) {
        setMsg('That is your second workshop already - uncheck one to swap.');
        return;
      } else {
        picked[i] = true;
        setMsg('');
      }
      render();
    });
  }

  // Step 3 - shirt size stepper
  panel.on('size-minus', 'click', () => {
    state.sizeIndex = Math.max(0, state.sizeIndex - 1);
    setMsg('');
    render();
  });
  panel.on('size-plus', 'click', () => {
    state.sizeIndex = Math.min(sizes.length - 1, state.sizeIndex + 1);
    setMsg('');
    render();
  });

  // Navigation
  panel.on('next', 'click', () => {
    if (state.step === 1) {
      if (state.ticket < 0) {
        setMsg('Choose a ticket first.');
        return;
      }
      state.step = 2;
    } else if (state.step === 2) {
      state.step = 3;
    } else if (state.step === 3) {
      state.step = 4;
    }
    setMsg('');
    render();
  });
  panel.on('back', 'click', () => {
    if (state.step > 1 && state.step <= 4) state.step -= 1;
    setMsg('');
    render();
  });

  // Review edit shortcuts
  panel.on('edit-ticket', 'click', () => { state.step = 1; setMsg(''); render(); });
  panel.on('edit-ws', 'click', () => { state.step = 2; setMsg(''); render(); });
  panel.on('edit-size', 'click', () => { state.step = 3; setMsg(''); render(); });

  // A lanyard badge that appears when the registration is confirmed.
  const badge = new THREE.Group();
  badge.name = 'ConferenceBadge';
  const badgeBody = new THREE.Mesh(
    new THREE.BoxGeometry(0.09, 0.062, 0.005),
    new THREE.MeshStandardMaterial({ color: 0xf1f4f9, roughness: 0.55, metalness: 0.05 }),
  );
  badgeBody.name = 'BadgeCard';
  badge.add(badgeBody);
  const stripe = new THREE.Mesh(
    new THREE.BoxGeometry(0.09, 0.016, 0.007),
    new THREE.MeshStandardMaterial({ color: 0x2f6fdb, roughness: 0.45 }),
  );
  stripe.position.y = 0.019;
  badge.add(stripe);
  const clip = new THREE.Mesh(
    new THREE.TorusGeometry(0.009, 0.003, 8, 20),
    new THREE.MeshStandardMaterial({ color: 0x9aa4b4, metalness: 0.8, roughness: 0.35 }),
  );
  clip.position.y = 0.037;
  badge.add(clip);
  badge.position.set(0.33, 0.14, 0.02);
  badge.visible = false;
  root.add(badge);
  traits(badge, { grab: true });

  let badgeGrow = 0;

  panel.on('confirm', 'click', () => {
    state.step = 5;
    const names = pickedNames();
    const wsText = names.length
      ? names.length + (names.length === 1 ? ' workshop' : ' workshops')
      : 'no workshops';
    panel.set('done-text', {
      text: tickets[state.ticket].name + ' ticket, size ' + sizes[state.sizeIndex] + ', ' +
        wsText + '. Your badge is on the right - pinch it to pick it up.',
    });
    setMsg('');
    render();
    badge.visible = true;
    badgeGrow = 0;
  });

  render();

  return {
    root,
    update(time, delta) {
      if (!badge.visible || isGrabbed(badge)) return;
      badgeGrow = Math.min(1, badgeGrow + delta * 2.5);
      const e = 1 - Math.pow(1 - badgeGrow, 3);
      badge.scale.setScalar(0.3 + 0.7 * e);
      badge.rotation.y = Math.sin(time * 0.6) * 0.35;
      badge.position.y = 0.14 + Math.sin(time * 0.9) * 0.006;
    },
  };
}

