        '<button class="mini" id="dn' + i + '"><span class="miniText">v</span></button>' +
        '<button class="mini" id="del' + i + '"><span class="miniText">X</span></button>' +
      '</div>';
  }

  const plan = ui(`
    <style>
      .card { width: 400px; flex-direction: column; gap: 6px; padding-top: 12px; padding-bottom: 12px;
              padding-left: 14px; padding-right: 14px; border-radius: 16px; background-color: #1a1d22; }
      .title { color: #ffffff; font-size: 24px; font-weight: 700; }
      .tabs { flex-direction: row; gap: 6px; }
      .tab { width: 120px; flex-direction: column; align-items: center; justify-content: center;
             padding-top: 4px; padding-bottom: 4px; border-radius: 10px; background-color: #23272e; }
      .tabDay { color: #ffffff; font-size: 20px; font-weight: 700; }
      .tabMin { color: #9aa4b2; font-size: 19px; }
      .hint { color: #9aa4b2; font-size: 19px; }
      .row { flex-direction: row; align-items: center; gap: 6px; height: 46px; }
      .num { width: 20px; color: #9aa4b2; font-size: 19px; }
      .stop { width: 158px; color: #eef1f5; font-size: 20px; }
      .mini { width: 56px; height: 44px; align-items: center; justify-content: center;
              border-radius: 10px; background-color: #2f353d; }
      .miniText { color: #ffffff; font-size: 20px; font-weight: 700; }
      .total { color: #d7dbe2; font-size: 19px; }
    </style>
    <div class="card">
      <span class="title" id="itTitle">Day 1 - 0 stops</span>
      <div class="tabs">
        <button class="tab" id="tab0"><span class="tabDay" id="tabD0">Day 1</span><span class="tabMin" id="tabM0">0 min</span></button>
        <button class="tab" id="tab1"><span class="tabDay" id="tabD1">Day 2</span><span class="tabMin" id="tabM1">0 min</span></button>
        <button class="tab" id="tab2"><span class="tabDay" id="tabD2">Day 3</span><span class="tabMin" id="tabM2">0 min</span></button>
      </div>
      <span class="hint" id="itHint">Tap a pin, then press Day 1, 2 or 3.</span>
      ${rowsHtml}
      <span class="total" id="itTotal">Total walking: 0 min</span>
    </div>`, { width: 0.26, position: [-0.25, 0.205, -0.13], rotationY: 0.3 });
  root.add(plan.object3D);

  // ------------------------------------------------------------------ state
  let selected = -1;
  let activeDay = 0;
  const days = [[], [], []];

  function dayOf(i) {
    for (let d = 0; d < 3; d++) if (days[d].indexOf(i) >= 0) return d;
    return -1;
  }

  function walkMinutes(d) {
    const arr = days[d];
    let t = 0;
    for (let i = 0; i + 1 < arr.length; i++) t += WALK[arr[i]][arr[i + 1]];
    return t;
  }

  function refresh() {
    // pins take the colour of their day
    for (let i = 0; i < 6; i++) {
      const d = dayOf(i);
      const m = pins[i].material;
      if (d >= 0) {
        m.color.setHex(DAY_COLORS[d]);
        m.emissive.setHex(DAY_COLORS[d]);
        m.emissiveIntensity = 0.45;
      } else {
        m.color.setHex(0xbfc7d2);
        m.emissive.setHex(0x6f8fd0);
        m.emissiveIntensity = 0;
      }
    }

    // details card
    if (selected >= 0) {
      const d = dayOf(selected);
      details.set('dName', { text: NAMES[selected] });
      details.set('dFact', { text: FACTS[selected] });
      details.set('dVisit', { text: VISIT[selected] });
      details.set('dStatus', { text: d >= 0 ? ('In Day ' + (d + 1) + ' - press another day to move it.') : 'Not in the plan yet.' });
      details.set('dStatus', { color: d >= 0 ? DAY_CSS[d] : '#8fe0a3' });
    } else {
      details.set('dName', { text: 'Paris in 3 days' });
      details.set('dFact', { text: 'Tap a pin on the map to open a landmark.' });
      details.set('dVisit', { text: 'Then press Day 1, 2 or 3 to add it.' });
      details.set('dStatus', { text: '' });
    }

    // day tabs with their walking totals
    for (let d = 0; d < 3; d++) {
      plan.set('tabM' + d, { text: walkMinutes(d) + ' min' });
      plan.set('tabM' + d, { color: d === activeDay ? '#eef1f5' : '#8b95a3' });
      plan.set('tabD' + d, { color: d === activeDay ? DAY_CSS[d] : '#9aa4b2' });
      plan.set('tab' + d, { backgroundColor: d === activeDay ? '#2c3340' : '#23272e' });
    }

    // itinerary rows
    const arr = days[activeDay];
    plan.set('itTitle', { text: 'Day ' + (activeDay + 1) + ' - ' + arr.length + (arr.length === 1 ? ' stop' : ' stops') });
    for (let i = 0; i < 6; i++) {
      if (i < arr.length) {
        plan.set('row' + i, { display: 'flex' });
        plan.set('num' + i, { text: (i + 1) + '.' });
        plan.set('name' + i, { text: SHORT[arr[i]] });
        plan.set('up' + i, { display: i === 0 ? 'none' : 'flex' });
        plan.set('dn' + i, { display: i === arr.length - 1 ? 'none' : 'flex' });
      } else {
        plan.set('row' + i, { display: 'none' });
      }
    }
    plan.set('itHint', { text: arr.length ? 'Use ^ v to reorder, X to remove.' : 'Tap a pin, then press Day 1, 2 or 3.' });
    plan.set('itTotal', { text: 'Total walking: ' + walkMinutes(activeDay) + ' min' });

    // dotted walking route for the active day
    let n = 0;
    trail.material.color.setHex(DAY_COLORS[activeDay]);
    trail.material.emissive.setHex(DAY_COLORS[activeDay]);
    for (let i = 0; i + 1 < arr.length && n < TRAIL_MAX; i++) {
      const a = POS[arr[i]];
      const b = POS[arr[i + 1]];
      const dx = b[0] - a[0];
      const dz = b[1] - a[1];
      const len = Math.sqrt(dx * dx + dz * dz);
      const steps = Math.max(1, Math.round(len / 0.016));
      for (let s = 0; s < steps && n < TRAIL_MAX; s++) {
        const t = (s + 0.5) / steps;
        dummy.position.set(a[0] + dx * t, 0.028, a[1] + dz * t);
        dummy.rotation.set(0, 0, 0);
        dummy.scale.set(1, 1, 1);
        dummy.updateMatrix();
        trail.setMatrixAt(n, dummy.matrix);
        n += 1;
      }
    }
    trail.count = n;
    trail.instanceMatrix.needsUpdate = true;
  }

  // --------------------------------------------------------------- actions
  function selectPin(i) {
    selected = i;
    const d = dayOf(i);
    if (d >= 0) activeDay = d;
    refresh();
  }

  function addStop(i, d) {
    const cur = dayOf(i);
    if (cur === d) { activeDay = d; refresh(); return; }
    if (cur >= 0) days[cur].splice(days[cur].indexOf(i), 1);
    days[d].push(i);
    activeDay = d;
    selected = i;
    refresh();
  }

  function removeStop(d, i) {
    const arr = days[d];
    if (i < 0 || i >= arr.length) return;
    arr.splice(i, 1);
    refresh();
  }

  function moveStop(d, i, dir) {
    const arr = days[d];
    const j = i + dir;
    if (j < 0 || j >= arr.length) return;
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
    refresh();
  }

  for (let i = 0; i < 6; i++) {
    plan.on('up' + i, 'click', () => moveStop(activeDay, i, -1));
    plan.on('dn' + i, 'click', () => moveStop(activeDay, i, 1));
    plan.on('del' + i, 'click', () => removeStop(activeDay, i));
  }
  for (let d = 0; d < 3; d++) {
    plan.on('tab' + d, 'click', () => { activeDay = d; refresh(); });
    details.on('add' + d, 'click', () => { if (selected >= 0) addStop(selected, d); });
  }

  refresh();

  return {
    root,
    update(time) {
      for (let i = 0; i < 6; i++) {
        const target = i === selected ? 1.28 : 1.0;
        const p = pins[i];
        p.scale.x += (target - p.scale.x) * 0.12;
        p.scale.y += (target - p.scale.y) * 0.12;
        p.scale.z += (target - p.scale.z) * 0.12;
      }
      if (selected >= 0) {
        pins[selected].material.emissiveIntensity = 0.35 + 0.25 * Math.sin(time * 3.5);
      }
    },
  };
}

