    const bandR = style === 1 ? 0.041 : style === 2 ? 0.036 : 0.038;
    const bandTube = style === 1 ? 0.0105 : style === 2 ? 0.006 : 0.0085;
    const bandY = 0.040;
    const startHex = COLORS[configs[idx].c].hex;

    const mainMat = new THREE.MeshStandardMaterial({
      color: startHex, roughness: 0.42, metalness: 0.18,
