    mainMats[idx] = mainMat;
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x17181c, roughness: 0.85 });
    const cushionMat = new THREE.MeshStandardMaterial({ color: 0x2e3238, roughness: 0.95 });
    const accentMat = new THREE.MeshStandardMaterial({
      color: style === 0 ? 0xffc23d : style === 1 ? 0xdfe6ee : 0x7bd3f7,
      roughness: 0.35, metalness: 0.35,
    });

    const g = new THREE.Group();
    g.name = products[idx].name;

    const band = new THREE.Mesh(new THREE.TorusGeometry(bandR, bandTube, 12, 28, Math.PI), mainMat);
    band.position.y = bandY;
    g.add(band);

    const pad = new THREE.Mesh(new THREE.TorusGeometry(bandR - 0.002, bandTube * 0.55, 10, 28, Math.PI), cushionMat);
    pad.position.y = bandY - 0.003;
    g.add(pad);

    for (const side of [-1, 1]) {
      const cup = new THREE.Mesh(new THREE.CylinderGeometry(cupR, cupR, 0.016, 24), mainMat);
      cup.rotation.z = Math.PI / 2;
      cup.position.set(side * bandR, 0.030, 0);
      g.add(cup);

      const outerRing = new THREE.Mesh(new THREE.TorusGeometry(cupR * 0.62, 0.0032, 8, 20), accentMat);
      outerRing.rotation.y = Math.PI / 2;
      outerRing.position.set(side * (bandR + 0.009), 0.030, 0);
      g.add(outerRing);

      const outerDot = new THREE.Mesh(new THREE.CylinderGeometry(cupR * 0.34, cupR * 0.34, 0.004, 16), accentMat);
      outerDot.rotation.z = Math.PI / 2;
      outerDot.position.set(side * (bandR + 0.009), 0.030, 0);
      g.add(outerDot);

      const cushion = new THREE.Mesh(new THREE.CylinderGeometry(cupR * 0.82, cupR * 0.82, 0.006, 20), darkMat);
      cushion.rotation.z = Math.PI / 2;
      cushion.position.set(side * (bandR - 0.009), 0.030, 0);
      g.add(cushion);

      const yoke = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.022, 0.008), darkMat);
      yoke.position.set(side * bandR, 0.045, 0);
      g.add(yoke);
    }

    if (style === 0) {
      const mic = new THREE.Mesh(new THREE.CylinderGeometry(0.003, 0.003, 0.04, 8), darkMat);
      mic.position.set(-bandR - 0.008, 0.014, 0.016);
      mic.rotation.z = 0.5;
      mic.rotation.x = 0.3;
      g.add(mic);
    } else if (style === 1) {
      const topPad = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.014, 0.022), cushionMat);
      topPad.position.set(0, bandY + bandR + bandTube - 0.004, 0);
      g.add(topPad);
    } else {
      const hinge = new THREE.Mesh(new THREE.BoxGeometry(0.014, 0.014, 0.014), accentMat);
      hinge.position.set(bandR, bandY, 0);
      g.add(hinge);
    }

    return g;
  }

  for (let i = 0; i < 3; i++) {
    const h = createHeadphone(i);
    h.position.set(0, 0.02, 0);
    h.scale.setScalar(SIZES[configs[i].s].scale);
    scales[i] = SIZES[configs[i].s].scale;
    root.add(h);
    headphones.push(h);
    const idx = i;
    traits(h, { onPress: () => selectProduct(idx) });
  }

  const marker = new THREE.Mesh(
    new THREE.CylinderGeometry(0.047, 0.047, 0.003, 32),
    new THREE.MeshStandardMaterial({ color: 0x2f6fdb, emissive: 0x2f6fdb, emissiveIntensity: 0.9, roughness: 0.4 })
  );
  marker.name = 'Selected marker';
  marker.position.set(0, 0.021, 0.005);
  root.add(marker);

  // Shop panel
  const shop = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 8px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .name { color: #ffffff; font-size: 28px; font-weight: 700; }
      .desc { color: #d7dbe2; font-size: 22px; }
      .row { display: flex; flex-direction: row; align-items: center; gap: 8px; }
      .label { color: #aeb6c2; font-size: 20px; font-weight: 700; width: 64px; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .navbtn { width: 110px; height: 44px; border-radius: 12px; background-color: #2a2e35; border-width: 1px; border-color: #454b55; }
      .colorbtn { width: 122px; height: 44px; border-radius: 12px; background-color: #2a2e35; border-width: 1px; border-color: #454b55; }
      .sizebtn { width: 96px; height: 44px; border-radius: 12px; background-color: #2a2e35; border-width: 1px; border-color: #454b55; }
      .addbtn { width: 460px; height: 48px; border-radius: 12px; background-color: #2f6fdb; border-width: 1px; border-color: #2f6fdb; }
      .pos { color: #ffffff; font-size: 20px; font-weight: 700; width: 80px; text-align: center; }
      .view { color: #ffd98a; font-size: 20px; font-weight: 700; }
      .msg { color: #9fd0ff; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Headphone Shop</span>
      <span class="name" id="pname">Aurora X1 - $149</span>
      <span class="desc" id="pdesc">Wireless over-ear. 40h battery and noise cancelling for clear calls and music.</span>
      <div class="row">
        <button class="navbtn" id="prev"><span class="btn-text">Prev</span></button>
        <span class="pos" id="pos">1 of 3</span>
        <button class="navbtn" id="next"><span class="btn-text">Next</span></button>
      </div>
      <div class="row">
        <span class="label">Color</span>
        <button class="colorbtn" id="c0"><span class="btn-text">Black</span></button>
        <button class="colorbtn" id="c1"><span class="btn-text">Blue</span></button>
        <button class="colorbtn" id="c2"><span class="btn-text">Red</span></button>
      </div>
      <div class="row">
        <span class="label">Size</span>
        <button class="sizebtn" id="s0"><span class="btn-text">S</span></button>
        <button class="sizebtn" id="s1"><span class="btn-text">M</span></button>
        <button class="sizebtn" id="s2"><span class="btn-text">L</span></button>
      </div>
      <span class="view" id="view">Black / Size M</span>
      <button class="addbtn" id="add"><span class="btn-text">Add to Cart</span></button>
      <span class="msg" id="msg">Pinch a headphone, or use Prev and Next.</span>
    </div>`, { width: 0.34, position: [-0.195, 0.31, 0.04], rotationY: 0.18 });
  root.add(shop.object3D);

  // Cart panel
  const cartPanel = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 7px; padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px; border-radius: 18px; background-color: #1f2228; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .desc { color: #d7dbe2; font-size: 20px; }
      .row { display: flex; flex-direction: row; align-items: center; gap: 8px; }
      .cartlabel { color: #ffffff; font-size: 20px; width: 252px; }
      .qty { color: #ffffff; font-size: 20px; font-weight: 700; width: 32px; text-align: center; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .smallbtn { width: 48px; height: 40px; border-radius: 10px; background-color: #2a2e35; border-width: 1px; border-color: #454b55; }
      .srow { display: flex; flex-direction: row; align-items: center; gap: 8px; }
      .slabel { color: #d7dbe2; font-size: 20px; width: 300px; }
      .svalue { color: #ffffff; font-size: 20px; font-weight: 700; width: 120px; text-align: right; }
      .totalvalue { color: #ffd98a; font-size: 22px; font-weight: 700; width: 120px; text-align: right; }
      .actionbtn { width: 224px; height: 44px; border-radius: 12px; background-color: #2a2e35; border-width: 1px; border-color: #454b55; }
      .checkoutbtn { width: 224px; height: 44px; border-radius: 12px; background-color: #1f9d63; border-width: 1px; border-color: #1f9d63; }
      .msg { color: #9fd0ff; font-size: 20px; }
    </style>
    <div class="card">
      <span class="title">Your Cart</span>
      <span class="desc" id="cartmsg">Cart is empty. Add a headphone.</span>
      <div class="row" id="row0">
        <span class="cartlabel" id="label0">Aurora X1 - Black / M</span>
        <button class="smallbtn" id="dec0"><span class="btn-text">-</span></button>
        <span class="qty" id="qty0">0</span>
        <button class="smallbtn" id="inc0"><span class="btn-text">+</span></button>
      </div>
      <div class="row" id="row1">
        <span class="cartlabel" id="label1">Aurora X1 - Black / M</span>
        <button class="smallbtn" id="dec1"><span class="btn-text">-</span></button>
        <span class="qty" id="qty1">0</span>
        <button class="smallbtn" id="inc1"><span class="btn-text">+</span></button>
      </div>
      <div class="row" id="row2">
        <span class="cartlabel" id="label2">Aurora X1 - Black / M</span>
        <button class="smallbtn" id="dec2"><span class="btn-text">-</span></button>
        <span class="qty" id="qty2">0</span>
        <button class="smallbtn" id="inc2"><span class="btn-text">+</span></button>
      </div>
      <div class="row" id="row3">
        <span class="cartlabel" id="label3">Aurora X1 - Black / M</span>
        <button class="smallbtn" id="dec3"><span class="btn-text">-</span></button>
        <span class="qty" id="qty3">0</span>
        <button class="smallbtn" id="inc3"><span class="btn-text">+</span></button>
      </div>
      <div class="row" id="row4">
        <span class="cartlabel" id="label4">Aurora X1 - Black / M</span>
        <button class="smallbtn" id="dec4"><span class="btn-text">-</span></button>
        <span class="qty" id="qty4">0</span>
        <button class="smallbtn" id="inc4"><span class="btn-text">+</span></button>
      </div>
      <div class="srow">
        <span class="slabel">Subtotal</span>
        <span class="svalue" id="sub">$0.00</span>
      </div>
      <div class="srow">
        <span class="slabel">Tax (8%)</span>
        <span class="svalue" id="tax">$0.00</span>
      </div>
      <div class="srow">
        <span class="slabel">Total</span>
        <span class="totalvalue" id="total">$0.00</span>
      </div>
      <div class="row">
        <button class="actionbtn" id="clear"><span class="btn-text">Clear Cart</span></button>
        <button class="checkoutbtn" id="checkout"><span class="btn-text">Checkout</span></button>
      </div>
      <span class="msg" id="checkoutmsg">Tax is 8%.</span>
    </div>`, { width: 0.34, position: [0.195, 0.31, 0.04], rotationY: -0.18 });
  root.add(cartPanel.object3D);

  function refreshShop() {
    const p = products[selected];
    const cfg = configs[selected];
    shop.set('pname', { text: p.name + ' - $' + p.price });
    shop.set('pdesc', { text: p.desc });
    shop.set('pos', { text: (selected + 1) + ' of 3' });
    shop.set('view', { text: COLORS[cfg.c].name + ' / Size ' + SIZES[cfg.s].name + ' - $' + p.price });
    for (let i = 0; i < 3; i++) {
      shop.set('c' + i, { backgroundColor: i === cfg.c ? '#2f6fdb' : '#2a2e35' });
      shop.set('s' + i, { backgroundColor: i === cfg.s ? '#2f6fdb' : '#2a2e35' });
    }
  }

  function renderCart() {
    let subtotal = 0;
    let totalQty = 0;
    for (let i = 0; i < cart.length; i++) {
      subtotal += products[cart[i].idx].price * cart[i].qty;
      totalQty += cart[i].qty;
    }
    for (let i = 0; i < 5; i++) {
      if (i < cart.length) {
        const e = cart[i];
        cartPanel.set('row' + i, { display: 'flex' });
        cartPanel.set('label' + i, { text: products[e.idx].name + ' - ' + COLORS[e.c].name + ' / ' + SIZES[e.s].name });
        cartPanel.set('qty' + i, { text: String(e.qty) });
      } else {
        cartPanel.set('row' + i, { display: 'none' });
      }
    }
    const tax = subtotal * 0.08;
    const total = subtotal + tax;
    cartPanel.set('sub', { text: '$' + subtotal.toFixed(2) });
    cartPanel.set('tax', { text: '$' + tax.toFixed(2) });
    cartPanel.set('total', { text: '$' + total.toFixed(2) });
    cartPanel.set('cartmsg', {
      text: cart.length === 0 ? 'Cart is empty. Add a headphone.' : totalQty + (totalQty === 1 ? ' item in cart.' : ' items in cart.'),
    });
  }

  function selectProduct(i) {
    selected = i;
    refreshShop();
    shop.set('msg', { text: 'Now viewing ' + products[i].name + '.' });
    snapTarget = -selected * (Math.PI * 2 / 3);
    pauseTime = 3.5;
  }

  shop.on('prev', 'click', () => selectProduct((selected + 2) % 3));
  shop.on('next', 'click', () => selectProduct((selected + 1) % 3));

  for (let i = 0; i < 3; i++) {
    const ci = i;
    shop.on('c' + i, 'click', () => {
      configs[selected].c = ci;
      mainMats[selected].color.setHex(COLORS[ci].hex);
      mainMats[selected].emissive.setHex(COLORS[ci].hex);
      refreshShop();
      shop.set('msg', { text: products[selected].name + ' in ' + COLORS[ci].name + '.' });
    });
    shop.on('s' + i, 'click', () => {
      configs[selected].s = ci;
      refreshShop();
      shop.set('msg', { text: products[selected].name + ' size ' + SIZES[ci].name + '.' });
    });
  }

  shop.on('add', 'click', () => {
    const cfg = configs[selected];
    let found = null;
    for (let i = 0; i < cart.length; i++) {
      if (cart[i].idx === selected && cart[i].c === cfg.c && cart[i].s === cfg.s) found = cart[i];
    }
    if (found) {
      found.qty += 1;
    } else if (cart.length >= 5) {
      shop.set('msg', { text: 'Cart list is full. Remove an item first.' });
      return;
    } else {
      cart.push({ idx: selected, c: cfg.c, s: cfg.s, qty: 1 });
    }
    renderCart();
    cartPanel.set('checkoutmsg', { text: 'Tax is 8%.' });
    shop.set('msg', { text: 'Added ' + products[selected].name + ' ' + COLORS[cfg.c].name + '/' + SIZES[cfg.s].name + ' to cart.' });
  });

  for (let i = 0; i < 5; i++) {
    const slot = i;
    cartPanel.on('inc' + i, 'click', () => {
      if (slot < cart.length) { cart[slot].qty += 1; renderCart(); }
    });
    cartPanel.on('dec' + i, 'click', () => {
      if (slot < cart.length) {
        cart[slot].qty -= 1;
        if (cart[slot].qty <= 0) cart.splice(slot, 1);
        renderCart();
      }
    });
  }

  cartPanel.on('clear', 'click', () => {
    cart.length = 0;
    renderCart();
    cartPanel.set('checkoutmsg', { text: 'Cart cleared.' });
  });

  cartPanel.on('checkout', 'click', () => {
    if (cart.length === 0) {
      cartPanel.set('checkoutmsg', { text: 'Add an item before checkout.' });
      return;
    }
    let subtotal = 0;
    for (let i = 0; i < cart.length; i++) subtotal += products[cart[i].idx].price * cart[i].qty;
    const total = subtotal + subtotal * 0.08;
    cart.length = 0;
    renderCart();
    cartPanel.set('checkoutmsg', { text: 'Order placed! Total $' + total.toFixed(2) + '. Thank you.' });
    shop.set('msg', { text: 'Order placed. Thank you for shopping.' });
  });

  refreshShop();
  renderCart();

  const CX = 0;
  const CZ = -0.08;
  const R = 0.085;

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta || 0.016, 0.05);

      if (snapTarget !== null) {
        let diff = snapTarget - carouselAngle;
        while (diff > Math.PI) diff -= Math.PI * 2;
        while (diff < -Math.PI) diff += Math.PI * 2;
        if (Math.abs(diff) < 0.015) {
          carouselAngle += diff;
          snapTarget = null;
        } else {
          carouselAngle += diff * Math.min(1, dt * 5);
        }
      } else if (pauseTime > 0) {
        pauseTime -= dt;
      } else {
        carouselAngle += dt * 0.18;
      }

      turntable.rotation.y = carouselAngle;

      for (let i = 0; i < 3; i++) {
        if (isGrabbed(headphones[i])) continue;
        const angle = carouselAngle + i * Math.PI * 2 / 3;
        const bob = i === selected ? Math.sin(time * 2.2) * 0.0015 : 0;
        headphones[i].position.set(
          CX + Math.sin(angle) * R,
          0.02 + bob,
          CZ + Math.cos(angle) * R
        );
        headphones[i].rotation.y = angle;
        const targetScale = SIZES[configs[i].s].scale * (i === selected ? 1.12 : 1.0);
        scales[i] += (targetScale - scales[i]) * Math.min(1, dt * 8);
        headphones[i].scale.setScalar(scales[i]);
        mainMats[i].emissiveIntensity = i === selected ? 0.22 : 0.04;
      }

      const selAngle = carouselAngle + selected * Math.PI * 2 / 3;
      marker.position.set(CX + Math.sin(selAngle) * R, 0.021, CZ + Math.cos(selAngle) * R);
      const pulse = 1 + Math.sin(time * 3) * 0.06;
      marker.scale.set(pulse, 1, pulse);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  const pivotX = -0.2;
  const pivotY = 0.395;
  const pivotZ = 0;
  const trackX = -0.28;
  const trackZ = 0.08;

  let L = 0.25;
  let g = 9.81;
  let gravName = 'Earth';
  let releaseDeg = 30;
  let theta = releaseDeg * Math.PI / 180;
  let omega = 0;
  let prevTheta = theta;
  let paused = false;
  let simTime = 0;
  let lastCrossTime = null;
  let lastMeasured = null;
  let wasGrabbed = false;
  let knobGrabStartL = L;
  let angleTimer = 0;
  let dragTimer = 0;

  const period = () => 2 * Math.PI * Math.sqrt(L / g);

  const matDark = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.85 });
  const matMetal = new THREE.MeshStandardMaterial({ color: 0xb8bec8, roughness: 0.35, metalness: 0.6 });
  const matOrange = new THREE.MeshStandardMaterial({ color: 0xff8a1a, roughness: 0.5 });
  const matBrass = new THREE.MeshStandardMaterial({ color: 0xd9a441, roughness: 0.3, metalness: 0.7, emissive: 0x221a00, emissiveIntensity: 0.6 });
  const matString = new THREE.MeshStandardMaterial({ color: 0xe8eaed, roughness: 0.6 });
  const matKnob = new THREE.MeshStandardMaterial({ color: 0xffd23d, roughness: 0.4, emissive: 0x664d00, emissiveIntensity: 0.5 });
  const matRed = new THREE.MeshStandardMaterial({ color: 0xd9382b, roughness: 0.45, emissive: 0x550000, emissiveIntensity: 0.5 });
  const matChartBase = new THREE.MeshStandardMaterial({ color: 0x23262c, roughness: 0.85 });
  const matBack = new THREE.MeshStandardMaterial({ color: 0x2f333a, roughness: 0.85 });
  const matOldBar = new THREE.MeshStandardMaterial({ color: 0x5b8fd6, roughness: 0.55 });
  const matNewBar = new THREE.MeshStandardMaterial({ color: 0xffb020, roughness: 0.45, emissive: 0x664400, emissiveIntensity: 0.5 });
  const matTick = new THREE.MeshBasicMaterial({ color: 0xffffff });

  const base = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.025, 0.2), matDark);
  base.name = 'Base';
  base.position.set(pivotX, 0.0125, -0.06);
  root.add(base);

  const post = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.008, 0.375, 16), matMetal);
  post.position.set(pivotX, 0.2125, -0.1);
  root.add(post);

  const arm = new THREE.Mesh(new THREE.BoxGeometry(0.022, 0.022, 0.12), matMetal);
  arm.position.set(pivotX, 0.395, -0.05);
  root.add(arm);

  const pivotCap = new THREE.Mesh(new THREE.SphereGeometry(0.012, 20, 12), matOrange);
  pivotCap.position.set(pivotX, pivotY, pivotZ);
  root.add(pivotCap);

  const disc = new THREE.Mesh(new THREE.CircleGeometry(0.14, 32, Math.PI, Math.PI), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.07, side: THREE.DoubleSide }));
  disc.position.set(pivotX, pivotY, -0.028);
  root.add(disc);

  const arc = new THREE.Mesh(new THREE.RingGeometry(0.118, 0.128, 32, 1, 3.927, 1.571), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.75, side: THREE.DoubleSide }));
  arc.position.set(pivotX, pivotY, -0.027);
  root.add(arc);

  const tickGeo = new THREE.BoxGeometry(0.003, 0.02, 0.002);
  const tickAngles = [-40, -20, 0, 20, 40];
  for (let i = 0; i < tickAngles.length; i++) {
    const a = tickAngles[i] * Math.PI / 180;
    const tick = new THREE.Mesh(tickGeo, matTick);
    tick.position.set(pivotX + Math.sin(a) * 0.124, pivotY - Math.cos(a) * 0.124, -0.026);
    tick.rotation.z = a;
    root.add(tick);
  }

  const pendulum = new THREE.Group();
  pendulum.name = 'Pendulum';
  pendulum.position.set(pivotX, pivotY, pivotZ);
  root.add(pendulum);

  const stringMesh = new THREE.Mesh(new THREE.CylinderGeometry(0.0018, 0.0018, 1, 8), matString);
  stringMesh.name = 'String';
  pendulum.add(stringMesh);

  const bob = new THREE.Mesh(new THREE.SphereGeometry(0.024, 24, 16), matBrass);
  bob.name = 'Bob';
  pendulum.add(bob);

  function applyLength() {
    stringMesh.scale.y = L;
    stringMesh.position.y = -L / 2;
    bob.position.y = -L;
  }
  applyLength();

  const foot = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.02, 0.07), matDark);
  foot.position.set(trackX, 0.01, trackZ);
  root.add(foot);

  const rail = new THREE.Mesh(new THREE.CylinderGeometry(0.004, 0.004, 0.28, 12), matMetal);
  rail.position.set(trackX, 0.17, trackZ);
  root.add(rail);

  const knob = new THREE.Mesh(new THREE.BoxGeometry(0.044, 0.028, 0.028), matKnob);
  knob.name = 'LengthKnob';
  knob.position.set(trackX, pivotY - L, trackZ);
  root.add(knob);

  const railTickGeo = new THREE.BoxGeometry(0.014, 0.002, 0.002);
  const railVals = [0.15, 0.2, 0.25, 0.3];
  for (let i = 0; i < railVals.length; i++) {
    const m = new THREE.Mesh(railTickGeo, matTick);
    m.position.set(trackX + 0.012, pivotY - railVals[i], trackZ);
    root.add(m);
  }

  const releaseBtn = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, 0.014, 20), matRed);
  releaseBtn.name = 'ReleaseButton';
  releaseBtn.position.set(pivotX, 0.032, 0.015);
  root.add(releaseBtn);

  const chartGroup = new THREE.Group();
  chartGroup.name = 'Chart';
  chartGroup.position.set(0.17, 0, 0.15);
  root.add(chartGroup);

  const chartBase = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.012, 0.09), matChartBase);
  chartBase.position.set(0, 0.006, 0);
  chartGroup.add(chartBase);

  const chartBack = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.095, 0.006), matBack);
  chartBack.position.set(0, 0.0595, -0.042);
  chartGroup.add(chartBack);

  const lineGeo = new THREE.BoxGeometry(0.24, 0.0015, 0.001);
  const line1 = new THREE.Mesh(lineGeo, matTick);
  line1.position.set(0, 0.044, -0.038);
  chartGroup.add(line1);
  const line2 = new THREE.Mesh(lineGeo, matTick);
  line2.position.set(0, 0.076, -0.038);
  chartGroup.add(line2);

  const barGeo = new THREE.BoxGeometry(0.015, 1, 0.038);
  const bars = [];
  for (let i = 0; i < 10; i++) {
    const bar = new THREE.Mesh(barGeo, matOldBar);
    bar.name = 'Bar' + i;
    bar.position.set(-0.099 + i * 0.022, 0.02, 0.002);
    chartGroup.add(bar);
    bars.push(bar);
  }

  const history = [];
  for (let i = 0; i < 10; i++) history.push(period());

  function refreshChart() {
    for (let i = 0; i < 10; i++) {
      const h = Math.max(0.012, history[i] * 0.032);
      bars[i].scale.y = h;
      bars[i].position.y = 0.012 + h / 2;
      bars[i].material = i === 9 ? matNewBar : matOldBar;
    }
  }

  const info = ui(`
    <style>
      .card { width: 520px; display: flex; flex-direction: column; gap: 7px; padding-top: 13px; padding-bottom: 13px; padding-left: 18px; padding-right: 18px; border-radius: 18px; background-color: #1a1d22; border-width: 2px; border-color: #3a3f47; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .small { color: #c8cdd5; font-size: 22px; }
      .label { color: #ffb020; font-size: 22px; font-weight: 700; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center; }
      .btn { padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; background-color: #2f3540; border-width: 1px; border-color: #4a5058; }
      .btnText { color: #ffffff; font-size: 22px; font-weight: 700; }
      .pill { color: #ffffff; font-size: 22px; font-weight: 700; background-color: #2a2e35; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; border-radius: 10px; text-align: center; }
      .hint { color: #aeb6c2; font-size: 22px; }
    </style>
    <div class="card">
      <span class="title">Pendulum Physics Lab</span>
      <span class="body" id="readout">L = 0.25 m  g = 9.81 m/s2 (Earth)  T = 1.00 s  f = 1.00 Hz</span>
      <span class="small" id="angleReadout">Angle now: 30 deg  Speed: 0.00 m/s</span>
      <span class="small" id="measureText">Last measured cycle: -- s (theory 1.00 s)</span>
      <span class="label">String length - presets (or drag yellow knob)</span>
      <div class="row">
        <button class="btn" id="len15"><span class="btnText">0.15 m</span></button>
        <button class="btn" id="len20"><span class="btnText">0.20 m</span></button>
        <button class="btn" id="len25"><span class="btnText">0.25 m</span></button>
        <button class="btn" id="len30"><span class="btnText">0.30 m</span></button>
      </div>
      <span class="label">Gravity preset</span>
      <div class="row">
        <button class="btn" id="gEarth"><span class="btnText">Earth</span></button>
        <button class="btn" id="gMoon"><span class="btnText">Moon</span></button>
        <button class="btn" id="gMars"><span class="btnText">Mars</span></button>
      </div>
      <span class="small" id="gravInfo">Earth: strong gravity, short periods.</span>
      <span class="label">Release angle</span>
      <div class="row">
        <button class="btn" id="angMinus"><span class="btnText">- 5 deg</span></button>
        <span class="pill" id="angleVal">30 deg</span>
        <button class="btn" id="angPlus"><span class="btnText">+ 5 deg</span></button>
      </div>
      <div class="row">
        <button class="btn" id="pauseBtn"><span class="btnText" id="pauseLabel">Pause</span></button>
        <button class="btn" id="resetBtn"><span class="btnText">Release again</span></button>
      </div>
      <span class="small" id="historyText">Last 10 periods (s): 1.00, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00, 1.00 Avg 1.00 s</span>
      <span class="hint">Chart on desk: left is oldest, right is newest. Longer L or weaker g gives a longer period T.</span>
    </div>`, { width: 0.31, position: [0.17, 0.29, -0.03], rotationY: -0.18 });
  root.add(info.object3D);

  function updatePanel() {
    const T = period();
    info.set('readout', { text: 'L = ' + L.toFixed(2) + ' m  g = ' + g.toFixed(2) + ' m/s2 (' + gravName + ')  T = ' + T.toFixed(2) + ' s  f = ' + (1 / T).toFixed(2) + ' Hz' });
    let gravText = 'Earth: strong gravity, short periods.';
    if (gravName === 'Moon') gravText = 'Moon: g = 1.62, about 1/6 of Earth, long periods.';
    if (gravName === 'Mars') gravText = 'Mars: g = 3.71, about 0.38 of Earth.';
    info.set('gravInfo', { text: gravText });
    info.set('angleVal', { text: releaseDeg + ' deg' });
    let sum = 0;
    for (let i = 0; i < history.length; i++) sum += history[i];
    const avg = sum / history.length;
    let list = '';
    for (let i = 0; i < history.length; i++) list += history[i].toFixed(2) + (i < history.length - 1 ? ', ' : '');
    info.set('historyText', { text: 'Last 10 periods (s): ' + list + ' Avg ' + avg.toFixed(2) + ' s' });
    if (lastMeasured === null) {
      info.set('measureText', { text: 'Last measured cycle: -- s (theory ' + T.toFixed(2) + ' s)' });
    } else {
      info.set('measureText', { text: 'Last measured cycle: ' + lastMeasured.toFixed(2) + ' s (theory ' + T.toFixed(2) + ' s)' });
    }
    info.set('len15', { backgroundColor: Math.abs(L - 0.15) < 0.006 ? '#2f6fdb' : '#2f3540' });
    info.set('len20', { backgroundColor: Math.abs(L - 0.2) < 0.006 ? '#2f6fdb' : '#2f3540' });
    info.set('len25', { backgroundColor: Math.abs(L - 0.25) < 0.006 ? '#2f6fdb' : '#2f3540' });
    info.set('len30', { backgroundColor: Math.abs(L - 0.3) < 0.006 ? '#2f6fdb' : '#2f3540' });
    info.set('gEarth', { backgroundColor: gravName === 'Earth' ? '#2f6fdb' : '#2f3540' });
    info.set('gMoon', { backgroundColor: gravName === 'Moon' ? '#7d8791' : '#2f3540' });
    info.set('gMars', { backgroundColor: gravName === 'Mars' ? '#c1442e' : '#2f3540' });
  }

  function pushPeriod() {
    history.shift();
    history.push(period());
    refreshChart();
  }

  function resetSwing() {
    theta = releaseDeg * Math.PI / 180;
    omega = 0;
    prevTheta = theta;
    simTime = 0;
    lastCrossTime = null;
    lastMeasured = null;
    updatePanel();
  }

  function setLength(v) {
    if (Math.abs(L - v) < 0.001) return;
    L = v;
    applyLength();
    lastCrossTime = null;
    lastMeasured = null;
    pushPeriod();
    updatePanel();
  }

  function setGravity(name, value) {
    if (gravName === name) return;
    gravName = name;
    g = value;
    lastCrossTime = null;
    lastMeasured = null;
    pushPeriod();
    updatePanel();
  }

  info.on('len15', 'click', () => setLength(0.15));
  info.on('len20', 'click', () => setLength(0.2));
  info.on('len25', 'click', () => setLength(0.25));
  info.on('len30', 'click', () => setLength(0.3));
  info.on('gEarth', 'click', () => setGravity('Earth', 9.81));
  info.on('gMoon', 'click', () => setGravity('Moon', 1.62));
  info.on('gMars', 'click', () => setGravity('Mars', 3.71));
  info.on('angMinus', 'click', () => { releaseDeg = Math.max(10, releaseDeg - 5); resetSwing(); });
  info.on('angPlus', 'click', () => { releaseDeg = Math.min(35, releaseDeg + 5); resetSwing(); });
  info.on('pauseBtn', 'click', () => { paused = !paused; info.set('pauseLabel', { text: paused ? 'Resume' : 'Pause' }); });
  info.on('resetBtn', 'click', () => resetSwing());

  traits(knob, { grab: true });
  traits(releaseBtn, { onPress: () => resetSwing() });

  refreshChart();
  updatePanel();

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta || 0.016, 0.05);
      const grabbed = isGrabbed(knob);
      if (grabbed) {
        if (!wasGrabbed) knobGrabStartL = L;
        knob.position.x = trackX;
        knob.position.z = trackZ;
        knob.position.y = Math.max(0.075, Math.min(0.275, knob.position.y));
        const newL = Math.max(0.12, Math.min(0.32, pivotY - knob.position.y));
        if (Math.abs(newL - L) > 0.0005) {
          L = newL;
          applyLength();
          lastCrossTime = null;
          dragTimer += dt;
          if (dragTimer >= 0.08) {
            dragTimer = 0;
            updatePanel();
          }
        }
      } else {
        if (wasGrabbed) {
          if (Math.abs(L - knobGrabStartL) >= 0.01) pushPeriod();
          updatePanel();
        }
        const targetY = pivotY - L;
        const dy = targetY - knob.position.y;
        const maxStep = 0.04 * dt;
        if (Math.abs(dy) > 0.0001) {
          knob.position.y += Math.max(-maxStep, Math.min(maxStep, dy));
        }
        knob.position.x = trackX;
        knob.position.z = trackZ;
      }
      wasGrabbed = grabbed;

      if (!paused) {
        prevTheta = theta;
        simTime += dt;
        const steps = 4;
        const sdt = dt / steps;
        for (let s = 0; s < steps; s++) {
          const alpha = -(g / L) * Math.sin(theta) - 0.03 * omega;
          omega += alpha * sdt;
          theta += omega * sdt;
        }
        if (prevTheta <= 0 && theta > 0 && omega > 0) {
          if (lastCrossTime !== null) {
            lastMeasured = simTime - lastCrossTime;
            info.set('measureText', { text: 'Last measured cycle: ' + lastMeasured.toFixed(2) + ' s (theory ' + period().toFixed(2) + ' s)' });
          }
          lastCrossTime = simTime;
        }
      }
      pendulum.rotation.z = theta;

      angleTimer += dt;
      if (angleTimer >= 0.12) {
        angleTimer = 0;
        info.set('angleReadout', { text: 'Angle now: ' + Math.round(theta * 180 / Math.PI) + ' deg  Speed: ' + Math.abs(omega * L).toFixed(2) + ' m/s' });
      }
    }
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const wallMat = new THREE.MeshStandardMaterial({ color: 0xd9d2c2, roughness: 0.85 });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.6 });
  const sofaMat = new THREE.MeshStandardMaterial({ color: 0x4a7d8c, roughness: 0.85 });
  const counterMat = new THREE.MeshStandardMaterial({ color: 0xe8e6df, roughness: 0.5 });
  const fridgeMat = new THREE.MeshStandardMaterial({ color: 0xb8c0c8, roughness: 0.45 });
  const bedMat = new THREE.MeshStandardMaterial({ color: 0x7a5c9e, roughness: 0.9 });
  const pillowMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
  const tvMat = new THREE.MeshStandardMaterial({ color: 0x18202c, emissive: 0x2f6fdb, emissiveIntensity: 0.35, roughness: 0.4 });
  const windowMat = new THREE.MeshStandardMaterial({ color: 0xbfe3ff, emissive: 0x9fd4ff, emissiveIntensity: 0.7, roughness: 0.2 });
  const blueMat = new THREE.MeshStandardMaterial({ color: 0x2f6fdb, roughness: 0.5 });
  const grayMat = new THREE.MeshStandardMaterial({ color: 0x3a3f47, roughness: 0.5 });
  const whiteMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5 });
  const screenMat = new THREE.MeshStandardMaterial({ color: 0x103b3a, emissive: 0x1f8a80, emissiveIntensity: 0.6, roughness: 0.3 });

  function box(parent, w, h, d, mat, x, y, z) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    mesh.position.set(x, y, z);
    parent.add(mesh);
    return mesh;
  }

  function cylinder(parent, rTop, rBottom, h, mat, x, y, z) {
    const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBottom, h, 20), mat);
    mesh.position.set(x, y, z);
    parent.add(mesh);
    return mesh;
  }

  // Apartment model, centre-left at the back.
  const apt = new THREE.Group();
  apt.name = 'Apartment';
  apt.position.set(-0.19, 0, -0.14);
  root.add(apt);

  box(apt, 0.38, 0.012, 0.26, new THREE.MeshStandardMaterial({ color: 0x8a7a65, roughness: 0.9 }), 0, 0.006, 0);
  box(apt, 0.185, 0.003, 0.255, new THREE.MeshStandardMaterial({ color: 0xb08968, roughness: 0.8 }), -0.095, 0.0135, 0);
  box(apt, 0.185, 0.003, 0.125, new THREE.MeshStandardMaterial({ color: 0x93a3b5, roughness: 0.7 }), 0.095, 0.0135, -0.065);
  box(apt, 0.185, 0.003, 0.125, new THREE.MeshStandardMaterial({ color: 0x7e8aa0, roughness: 0.85 }), 0.095, 0.0135, 0.065);

  box(apt, 0.38, 0.12, 0.01, wallMat, 0, 0.072, -0.125);
  box(apt, 0.01, 0.12, 0.26, wallMat, -0.185, 0.072, 0);
  box(apt, 0.01, 0.12, 0.26, wallMat, 0.185, 0.072, 0);
  box(apt, 0.38, 0.045, 0.01, wallMat, 0, 0.0345, 0.125);
  box(apt, 0.008, 0.09, 0.25, wallMat, 0, 0.057, 0);
  box(apt, 0.185, 0.09, 0.008, wallMat, 0.095, 0.057, 0);
  box(apt, 0.09, 0.04, 0.004, windowMat, -0.08, 0.082, -0.118);

  box(apt, 0.11, 0.035, 0.04, sofaMat, -0.11, 0.033, -0.085);
  box(apt, 0.11, 0.04, 0.012, sofaMat, -0.11, 0.055, -0.104);
  box(apt, 0.09, 0.05, 0.008, tvMat, -0.11, 0.045, 0.065);
  box(apt, 0.12, 0.045, 0.05, counterMat, 0.06, 0.0375, -0.10);
  box(apt, 0.05, 0.09, 0.05, fridgeMat, 0.155, 0.06, -0.10);
  box(apt, 0.13, 0.03, 0.09, bedMat, 0.09, 0.03, 0.075);
  box(apt, 0.05, 0.015, 0.03, pillowMat, 0.09, 0.052, 0.05);

  cylinder(apt, 0.004, 0.007, 0.055, darkMat, -0.16, 0.0425, 0.10);
  cylinder(apt, 0.002, 0.002, 0.025, darkMat, 0.16, 0.107, -0.02);
  cylinder(apt, 0.004, 0.007, 0.04, darkMat, 0.165, 0.035, 0.095);

  const livingGlowMat = new THREE.MeshBasicMaterial({ color: 0xffd27a, transparent: true, opacity: 0.22, depthWrite: false });
  const kitchenGlowMat = new THREE.MeshBasicMaterial({ color: 0xffd27a, transparent: true, opacity: 0.12, depthWrite: false });
  const bedroomGlowMat = new THREE.MeshBasicMaterial({ color: 0xffd27a, transparent: true, opacity: 0.12, depthWrite: false });

  function glow(w, d, x, z, mat) {
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, d), mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(x, 0.016, z);
    apt.add(mesh);
    return mesh;
  }
  glow(0.17, 0.24, -0.095, 0, livingGlowMat);
  glow(0.17, 0.11, 0.095, -0.065, kitchenGlowMat);
  glow(0.17, 0.11, 0.095, 0.065, bedroomGlowMat);

  const livingLampMat = new THREE.MeshStandardMaterial({ color: 0xfff2cc, emissive: 0xffc954, emissiveIntensity: 1.2, roughness: 0.3 });
  const kitchenLampMat = new THREE.MeshStandardMaterial({ color: 0xfff2cc, emissive: 0xffc954, emissiveIntensity: 0.6, roughness: 0.3 });
  const bedroomLampMat = new THREE.MeshStandardMaterial({ color: 0xfff2cc, emissive: 0xffc954, emissiveIntensity: 0.6, roughness: 0.3 });

  const livingBulb = new THREE.Mesh(new THREE.SphereGeometry(0.016, 24, 12), livingLampMat);
  livingBulb.name = 'LivingLamp';
  livingBulb.position.set(-0.35, 0.078, -0.04);
  root.add(livingBulb);

  const kitchenBulb = new THREE.Mesh(new THREE.SphereGeometry(0.016, 24, 12), kitchenLampMat);
  kitchenBulb.name = 'KitchenLamp';
  kitchenBulb.position.set(-0.03, 0.092, -0.16);
  root.add(kitchenBulb);

  const bedroomBulb = new THREE.Mesh(new THREE.SphereGeometry(0.016, 24, 12), bedroomLampMat);
  bedroomBulb.name = 'BedroomLamp';
  bedroomBulb.position.set(-0.025, 0.067, -0.045);
  root.add(bedroomBulb);

  // Energy chart for today: 12 bars, kWh per 2 hours.
  const chart = new THREE.Group();
  chart.name = 'EnergyChart';
  chart.position.set(-0.19, 0, 0.155);
  root.add(chart);
  box(chart, 0.30, 0.008, 0.07, darkMat, 0, 0.004, 0);

  const barValues = [0.4, 0.3, 0.25, 0.5, 0.8, 1.1, 0.9, 0.7, 0.6, 0.85, 1.0, 0.7];
  const barMats = [
    new THREE.MeshStandardMaterial({ color: 0x5b7aa6, roughness: 0.6 }),
    new THREE.MeshStandardMaterial({ color: 0xf2a541, roughness: 0.6 }),
    new THREE.MeshStandardMaterial({ color: 0x2f6fdb, roughness: 0.6 }),
    new THREE.MeshStandardMaterial({ color: 0xe85d75, roughness: 0.6 }),
  ];
  const barGeo = new THREE.BoxGeometry(0.018, 1, 0.04);
  let lastBar = null;
  for (let i = 0; i < barValues.length; i++) {
    const h = Math.max(0.015, (barValues[i] / 1.2) * 0.085);
    const bar = new THREE.Mesh(barGeo, barMats[Math.floor(i / 3)]);
    bar.name = 'EnergyBar';
    bar.scale.y = h;
    bar.position.set(-0.132 + i * 0.024, 0.008 + h / 2, 0);
    chart.add(bar);
    lastBar = bar;
  }
  const marker = new THREE.Mesh(new THREE.SphereGeometry(0.007, 16, 8), new THREE.MeshBasicMaterial({ color: 0xff8a3d }));
  marker.name = 'NowMarker';
  marker.position.set(0.132, 0.065, 0);
  chart.add(marker);

  // Thermostat dial, centre front.
  const stand = box(root, 0.05, 0.024, 0.02, darkMat, 0.055, 0.012, 0.145);
  stand.name = 'ThermostatStand';

  const thermostat = new THREE.Group();
  thermostat.name = 'Thermostat';
  thermostat.position.set(0.055, 0.06, 0.145);
  root.add(thermostat);
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.018, 32), new THREE.MeshStandardMaterial({ color: 0x22262e, roughness: 0.4 }));
  body.rotation.x = Math.PI / 2;
