  root.add(info.object3D);

  const levelNames = ['Off', 'Low', 'Mid', 'Bright'];
  const lampKW = [0, 0.02, 0.05, 0.09];
  const levelGlow = [0, 0.12, 0.22, 0.35];
  const glowIntensity = [0.05, 0.6, 1.2, 2.0];

  const rooms = {
    living: { level: 2, lampMat: livingLampMat, glowMat: livingGlowMat },
    kitchen: { level: 1, lampMat: kitchenLampMat, glowMat: kitchenGlowMat },
    bedroom: { level: 1, lampMat: bedroomLampMat, glowMat: bedroomGlowMat },
  };

  let sceneName = 'Home';
  let temp = 20;
  let liveKW = 0.92;
  let liveExtra = 0;
  let displayedTotal = 8.1;

  function todayKwh() {
    return 8.1 + liveExtra;
  }

  function applyRoom(key) {
    const room = rooms[key];
    room.lampMat.emissiveIntensity = glowIntensity[room.level];
    room.glowMat.opacity = levelGlow[room.level];
    info.set(key + '-level', { text: levelNames[room.level] });
  }

  function computeLiveKW() {
    const heating = sceneName === 'Away' ? 0.1 : Math.max(0, (temp - 16) * 0.12);
    const base = sceneName === 'Away' ? 0.12 : 0.35;
    liveKW = lampKW[rooms.living.level] + lampKW[rooms.kitchen.level] + lampKW[rooms.bedroom.level] + heating + base;
  }

  function refresh() {
    applyRoom('living');
    applyRoom('kitchen');
    applyRoom('bedroom');
    pointerGroup.rotation.z = ((temp - 21) / 5) * 2.094;
    computeLiveKW();
    info.set('status', { text: 'Scene: ' + sceneName + ' - Living ' + levelNames[rooms.living.level] + ', Kitchen ' + levelNames[rooms.kitchen.level] + ', Bedroom ' + levelNames[rooms.bedroom.level] + ', Heat ' + temp.toFixed(1) + ' C' });
    info.set('temp-value', { text: temp.toFixed(1) + ' C' });
    info.set('energy', { text: 'Today ' + todayKwh().toFixed(2) + ' kWh - now ' + liveKW.toFixed(2) + ' kW' });
    displayedTotal = todayKwh();
  }

  function changeRoom(key, delta) {
    const room = rooms[key];
    room.level = Math.max(0, Math.min(3, room.level + delta));
    sceneName = 'Custom';
    refresh();
  }

  function cycleRoom(key) {
    rooms[key].level = (rooms[key].level + 1) % 4;
    sceneName = 'Custom';
    refresh();
  }

  function changeTemp(delta) {
    temp = Math.max(16, Math.min(26, temp + delta));
    sceneName = 'Custom';
    refresh();
  }

  function setScene(name, living, kitchen, bedroom, newTemp) {
    sceneName = name;
    rooms.living.level = living;
    rooms.kitchen.level = kitchen;
    rooms.bedroom.level = bedroom;
    temp = newTemp;
    refresh();
  }

  info.on('living-down', 'click', () => changeRoom('living', -1));
  info.on('living-up', 'click', () => changeRoom('living', 1));
  info.on('kitchen-down', 'click', () => changeRoom('kitchen', -1));
  info.on('kitchen-up', 'click', () => changeRoom('kitchen', 1));
  info.on('bedroom-down', 'click', () => changeRoom('bedroom', -1));
  info.on('bedroom-up', 'click', () => changeRoom('bedroom', 1));
  info.on('temp-down', 'click', () => changeTemp(-0.5));
  info.on('temp-up', 'click', () => changeTemp(0.5));
  info.on('scene-movie', 'click', () => setScene('Movie', 1, 0, 0, 19));
  info.on('scene-dinner', 'click', () => setScene('Dinner', 3, 3, 1, 21.5));
  info.on('scene-away', 'click', () => setScene('Away', 0, 0, 0, 16));

  traits(livingBulb, { onPress: () => cycleRoom('living') });
  traits(kitchenBulb, { onPress: () => cycleRoom('kitchen') });
  traits(bedroomBulb, { onPress: () => cycleRoom('bedroom') });
  traits(thermostat, { grab: true, onPress: () => changeTemp(0.5) });
  traits(plusBtn, { onPress: () => changeTemp(0.5) });
  traits(minusBtn, { onPress: () => changeTemp(-0.5) });

  function updateLastBar() {
    const value = 0.7 + liveExtra;
    const h = Math.max(0.015, (value / 1.2) * 0.085);
    lastBar.scale.y = h;
    lastBar.position.y = 0.008 + h / 2;
    marker.position.set(0.132, 0.008 + h + 0.012, 0);
  }

  refresh();
  updateLastBar();

  const energyUpdate = { text: '' };

  return {
    root,
    update(time, delta) {
      // Demo runs at 30x speed so the live bar grows visibly.
      liveExtra += liveKW * delta * 30 / 3600;
      updateLastBar();
      marker.position.y += Math.sin(time * 3) * 0.002;
      tvMat.emissiveIntensity = 0.35 + Math.sin(time * 2) * 0.08;
      const total = todayKwh();
      if (Math.abs(total - displayedTotal) >= 0.02) {
        energyUpdate.text = 'Today ' + total.toFixed(2) + ' kWh - now ' + liveKW.toFixed(2) + ' kW';
        info.set('energy', energyUpdate);
        displayedTotal = total;
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
