      const kb = Math.min(1, delta * 6);
      remainingBar.scale.y += (remainingTarget - remainingBar.scale.y) * kb;
      doneBar.scale.y += (doneTarget - doneBar.scale.y) * kb;
      remainingKnob.position.y = chartBaseY + 0.003 + remainingBar.scale.y;
      doneKnob.position.y = chartBaseY + 0.003 + doneBar.scale.y;
    }
  };
}

