  const carpalGeo = new THREE.SphereGeometry(0.010, 20, 14);
  const carpalData = [
    ['Scaphoid', [-0.203, 0.180, 0], [-0.27, 0.20, 0.03], 'Scaphoid - Thumb-side wrist bone that bridges the two wrist rows. It helps the wrist bend and is a common fracture after a fall on the hand.'],
    ['Lunate', [-0.183, 0.181, 0], [-0.23, 0.205, 0.03], 'Lunate - Crescent-shaped wrist bone next to the scaphoid. It forms the main wrist joint with the radius.'],
    ['Triquetrum', [-0.163, 0.181, 0], [-0.11, 0.205, 0.03], 'Triquetrum - Pinky-side wrist bone. It helps the wrist move side to side and stay stable.'],
    ['Pisiform', [-0.143, 0.180, 0], [-0.07, 0.20, 0.03], 'Pisiform - Smallest carpal, on the pinky side. It sits in a wrist tendon and helps move the hand toward the pinky side.'],
    ['Trapezium', [-0.196, 0.160, 0], [-0.26, 0.155, 0.03], 'Trapezium - Thumb-side wrist bone. It forms the base of the thumb joint for gripping and pinching.'],
