    ['Metacarpal 4 - ring finger', 3, [-0.143, 0.120, 0], [-0.08, 0.105, 0.025], 0.08, 0.22, 'Metacarpal 4 - One of five metacarpals, one per finger. They form the palm and support grip and pinching.'],
    ['Metacarpal 5 - pinky finger', 4, [-0.126, 0.124, 0], [-0.04, 0.115, 0.03], 0.20, 0.40, 'Metacarpal 5 - One of five metacarpals, one per finger. They form the palm and support grip and pinching.']
