  const fingerText = 'Phalanx - Finger bone. There are 14 phalanges in a hand: two in the thumb and three in each other finger. They let fingers bend and grip.';
  const phalangeData = [
    ['Proximal phalanx - thumb', 0, [-0.206, 0.087, 0], [-0.30, 0.08, 0.03], -0.45, -0.65, thumbText],
    ['Distal phalanx - thumb', 2, [-0.214, 0.065, 0], [-0.33, 0.055, 0.03], -0.45, -0.65, thumbText],
    ['Proximal phalanx - index finger', 0, [-0.180, 0.077, 0], [-0.26, 0.065, 0.025], -0.10, -0.25, fingerText],
    ['Middle phalanx - index finger', 1, [-0.182, 0.053, 0], [-0.275, 0.04, 0.025], -0.10, -0.25, fingerText],
    ['Distal phalanx - index finger', 2, [-0.184, 0.032, 0], [-0.285, 0.023, 0.025], -0.10, -0.25, fingerText],
    ['Proximal phalanx - middle finger', 0, [-0.160, 0.073, 0], [-0.16, 0.06, 0.02], 0, 0, fingerText],
    ['Middle phalanx - middle finger', 1, [-0.160, 0.049, 0], [-0.16, 0.037, 0.02], 0, 0, fingerText],
    ['Distal phalanx - middle finger', 2, [-0.160, 0.028, 0], [-0.16, 0.02, 0.02], 0, 0, fingerText],
    ['Proximal phalanx - ring finger', 0, [-0.140, 0.077, 0], [-0.06, 0.065, 0.025], 0.10, 0.25, fingerText],
    ['Middle phalanx - ring finger', 1, [-0.137, 0.053, 0], [-0.045, 0.04, 0.025], 0.10, 0.25, fingerText],
    ['Distal phalanx - ring finger', 2, [-0.135, 0.032, 0], [-0.04, 0.023, 0.025], 0.10, 0.25, fingerText],
    ['Proximal phalanx - pinky finger', 0, [-0.119, 0.087, 0], [-0.02, 0.077, 0.03], 0.22, 0.40, fingerText],
    ['Middle phalanx - pinky finger', 1, [-0.114, 0.063, 0], [-0.005, 0.055, 0.03], 0.22, 0.40, fingerText],
    ['Distal phalanx - pinky finger', 2, [-0.110, 0.043, 0], [0.005, 0.035, 0.03], 0.22, 0.40, fingerText]
  ];
  for (const p of phalangeData) {
    addBone(p[0], phalangeGeos[p[1]], matPhalanx, p[2], p[3], p[4], p[5], p[6]);
  }

  info.on('explodeBtn', 'click', () => {
    setTargets('exploded');
    if (quizState === 'explore') info.set('selected', { text: 'Pulling apart - bones are moving to an exploded view. Pinch any bone to move it.' });
  });
  info.on('reassembleBtn', 'click', () => {
    setTargets('home');
    if (quizState === 'explore') info.set('selected', { text: 'Reassembling - bones are moving home. Pinch any bone to move it.' });
  });

  return {
    root,
    update(time, delta) {
      if (!animating) return;
      const step = 0.05 * Math.min(delta, 0.05);
      let allDone = true;
      for (const b of bones) {
        if (isGrabbed(b.mesh)) { allDone = false; continue; }
        const dx = b.target.x - b.mesh.position.x;
        const dy = b.target.y - b.mesh.position.y;
        const dz = b.target.z - b.mesh.position.z;
        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz);
        if (dist > 0.001) {
          allDone = false;
          if (dist <= step) {
            b.mesh.position.copy(b.target);
          } else {
            const s = step / dist;
            b.mesh.position.x += dx * s;
            b.mesh.position.y += dy * s;
            b.mesh.position.z += dz * s;
          }
        }
        const dr = b.targetRotZ - b.mesh.rotation.z;
        if (Math.abs(dr) > 0.001) {
          allDone = false;
          b.mesh.rotation.z += dr * Math.min(1, delta * 4);
        }
      }
      if (allDone) animating = false;
    }
  };
}

