  const wallLeft = new THREE.Mesh(sideWallGeo, woodMat);
  wallLeft.position.set(BX - BW / 2 + 0.006, 0.056, BZ);
  wallLeft.name = 'BoxWallLeft';
  root.add(wallLeft);

  const wallRight = new THREE.Mesh(sideWallGeo, woodMat);
  wallRight.position.set(BX + BW / 2 - 0.006, 0.056, BZ);
