        <div class="row"><span class="sum" id="sum_shirt">T-Shirt: Size M</span><button class="small-btn" id="edit3"><span class="small-text">Edit</span></button></div>
        <button class="confirm-btn" id="confirm_btn"><span class="confirm-text">Confirm Registration</span></button>
        <span class="msg" id="reviewMsg">Check your choices, then tap Confirm.</span>
      </div>

      <div class="sec" id="secDone">
        <span class="title" id="doneTitle">Registration Confirmed!</span>
        <span class="body" id="done_text">Welcome to the conference.</span>
        <span class="body">Pinch the white badge on the desk to pick it up.</span>
        <button class="opt" id="again_btn"><span class="opt-text">Register Another Person</span></button>
      </div>

      <div class="nav">
        <button class="nav-btn" id="back_btn"><span class="nav-text">Back</span></button>
        <button class="nav-primary" id="next_btn"><span class="nav-text" id="next_label">Next</span></button>
      </div>
    </div>`, { width: 0.44, position: [0, 0.27, 0.02], rotationY: 0 });
  root.add(info.object3D);

  let step = 1;
  let ticketName = '';
  let ticketPrice = 0;
  let selectedWorkshops = [];
  let sizeIndex = 1;

  const sizes = ['S', 'M', 'L', 'XL'];
  const ticketDefs = [
    { id: 't_general', name: 'General', price: 120 },
    { id: 't_student', name: 'Student', price: 60 },
    { id: 't_vip', name: 'VIP', price: 250 }
  ];
  const workshopDefs = [
    { id: 'w_ai', spanId: 'w_ai_t', label: 'AI Basics' },
    { id: 'w_design', spanId: 'w_design_t', label: 'Design Thinking' },
    { id: 'w_data', spanId: 'w_data_t', label: 'Data Science' },
    { id: 'w_lead', spanId: 'w_lead_t', label: 'Leadership Skills' }
  ];

  function refreshTickets() {
    for (const def of ticketDefs) {
      const selected = def.name === ticketName;
      info.set(def.id, { backgroundColor: selected ? '#2f6fdb' : '#2a2e35' });
    }
  }

  function refreshWorkshops() {
    for (const def of workshopDefs) {
      const selected = selectedWorkshops.includes(def.label);
      info.set(def.spanId, { text: (selected ? '[x] ' : '[ ] ') + def.label });
      info.set(def.id, { backgroundColor: selected ? '#1f7a4d' : '#2a2e35' });
    }
    info.set('ws_count', { text: 'Selected: ' + selectedWorkshops.length + ' of 2' });
  }

  function refreshSize() {
    info.set('size_value', { text: sizes[sizeIndex] });
    info.set('size_msg', { text: 'Size ' + sizes[sizeIndex] + ' - free with every ticket.', color: '#a8e6c3' });
  }

  function updateSummary() {
    const wsText = selectedWorkshops.length > 0 ? selectedWorkshops.join(', ') : 'None';
    info.set('sum_ticket', { text: ticketName ? 'Ticket: ' + ticketName + ' - $' + ticketPrice : 'Ticket: None' });
    info.set('sum_workshops', { text: 'Workshops: ' + wsText });
    info.set('sum_shirt', { text: 'T-Shirt: Size ' + sizes[sizeIndex] });
  }

  function showStep(nextStep) {
    step = nextStep;
    const titles = {
      1: 'Step 1 of 3 - Ticket Type',
      2: 'Step 2 of 3 - Workshops',
      3: 'Step 3 of 3 - T-Shirt Size',
      4: 'Review Your Registration',
      5: 'Done - You Are Registered'
    };
    const hints = {
      1: 'Choose one ticket. Tap a button to select it.',
      2: 'Pick up to 2 workshops. Tap a button to check or uncheck it.',
      3: 'Use - and + to choose your size. Pinch a token below to jump steps.',
      4: 'Check your choices. Use Edit to change a step.',
      5: 'Your badge is on the desk. Pinch it to pick it up.'
    };
    info.set('stepTitle', { text: titles[step] });
    info.set('stepHint', { text: hints[step] });
    info.set('sec1', { display: step === 1 ? 'flex' : 'none' });
    info.set('sec2', { display: step === 2 ? 'flex' : 'none' });
    info.set('sec3', { display: step === 3 ? 'flex' : 'none' });
    info.set('secReview', { display: step === 4 ? 'flex' : 'none' });
    info.set('secDone', { display: step === 5 ? 'flex' : 'none' });
    info.set('back_btn', { display: (step > 1 && step < 5) ? 'flex' : 'none' });
    info.set('next_btn', { display: (step >= 1 && step <= 3) ? 'flex' : 'none' });
    if (step >= 1 && step <= 3) {
      info.set('next_label', { text: step === 3 ? 'Go to Review' : 'Next' });
    }
    if (step === 4) updateSummary();
    tokens.forEach((token, index) => {
      const active = step === index + 1;
      token.material.emissiveIntensity = active ? 0.75 : 0.15;
      token.scale.setScalar(active ? 1.18 : 1.0);
    });
  }

  function selectTicket(def) {
    ticketName = def.name;
    ticketPrice = def.price;
    info.set('ticketMsg', { text: 'Selected: ' + def.name + ' - $' + def.price + '. Tap Next to continue.', color: '#a8e6c3' });
    refreshTickets();
  }

  function toggleWorkshop(label) {
    const idx = selectedWorkshops.indexOf(label);
    if (idx >= 0) {
      selectedWorkshops.splice(idx, 1);
      info.set('ws_msg', { text: 'Select up to 2 workshops.', color: '#d7dbe2' });
    } else if (selectedWorkshops.length >= 2) {
      info.set('ws_msg', { text: 'Too many! You can pick only 2 workshops. Tap a selected workshop to remove it.', color: '#ffb3ab' });
      return;
    } else {
      selectedWorkshops.push(label);
      info.set('ws_msg', { text: 'Good choice. Keep going or tap Next.', color: '#a8e6c3' });
    }
    refreshWorkshops();
  }

  for (const def of ticketDefs) {
    info.on(def.id, 'click', () => selectTicket(def));
  }
  for (const def of workshopDefs) {
    info.on(def.id, 'click', () => toggleWorkshop(def.label));
  }

  info.on('size_minus', 'click', () => {
    if (sizeIndex <= 0) {
      info.set('size_msg', { text: 'Size S is the smallest size.', color: '#ffb3ab' });
      return;
    }
    sizeIndex--;
    refreshSize();
  });

  info.on('size_plus', 'click', () => {
    if (sizeIndex >= sizes.length - 1) {
      info.set('size_msg', { text: 'Size XL is the largest size.', color: '#ffb3ab' });
      return;
    }
    sizeIndex++;
    refreshSize();
  });

  info.on('next_btn', 'click', () => {
    if (step === 1 && !ticketName) {
      info.set('ticketMsg', { text: 'Please choose a ticket first, then tap Next.', color: '#ffb3ab' });
      return;
    }
    if (step >= 1 && step <= 3) showStep(step + 1);
  });

  info.on('back_btn', 'click', () => {
    if (step > 1 && step < 5) showStep(step - 1);
  });

  info.on('edit1', 'click', () => showStep(1));
  info.on('edit2', 'click', () => showStep(2));
  info.on('edit3', 'click', () => showStep(3));

  info.on('confirm_btn', 'click', () => {
    if (!ticketName) {
      showStep(1);
      return;
    }
    const wsText = selectedWorkshops.length > 0 ? selectedWorkshops.join(', ') : 'None';
    info.set('done_text', { text: 'Ticket: ' + ticketName + ' - $' + ticketPrice + ' | Workshops: ' + wsText + ' | T-Shirt: Size ' + sizes[sizeIndex] + ' | Total: $' + ticketPrice });
    badge.material.emissiveIntensity = 0.6;
    showStep(5);
  });

  info.on('again_btn', 'click', () => {
    ticketName = '';
    ticketPrice = 0;
    selectedWorkshops = [];
    sizeIndex = 1;
    badge.material.emissiveIntensity = 0.15;
    info.set('ticketMsg', { text: 'No ticket selected yet. Choose one above.', color: '#ffd9a0' });
    info.set('ws_msg', { text: 'Select up to 2 workshops.', color: '#d7dbe2' });
    refreshTickets();
    refreshWorkshops();
    refreshSize();
    showStep(1);
  });

  tokens.forEach((token, index) => {
    traits(token, { grab: true, onPress: () => showStep(index + 1) });
  });
  traits(badge, { grab: true });

  refreshTickets();
  refreshWorkshops();
  refreshSize();
  showStep(1);

  return {
    root,
    update(time) {
      decor.rotation.y = time * 0.4;
      decor.position.y = 0.032 + Math.sin(time * 1.5) * 0.004;
      if (step === 5 && !isGrabbed(badge)) {
        badge.rotation.y = -0.2 + Math.sin(time * 1.2) * 0.25;
        badge.material.emissiveIntensity = 0.55 + Math.sin(time * 3) * 0.15;
      }
    }
  };
}

