  photoGroup.add(photoStrip);
  const sqGeo = new THREE.BoxGeometry(0.038, 0.002, 0.024);
  const sq1 = new THREE.Mesh(sqGeo, new THREE.MeshStandardMaterial({ color: 0xff9ec4, roughness: 0.8 }));
  sq1.position.set(0, 0.005, -0.03);
  photoGroup.add(sq1);
  const sq2 = new THREE.Mesh(sqGeo, new THREE.MeshStandardMaterial({ color: 0x8ec9ff, roughness: 0.8 }));
  sq2.position.set(0, 0.005, 0);
  photoGroup.add(sq2);
  const sq3 = new THREE.Mesh(sqGeo, new THREE.MeshStandardMaterial({ color: 0xa8e6a3, roughness: 0.8 }));
  sq3.position.set(0, 0.005, 0.03);
  photoGroup.add(sq3);
  const candleGeo = new THREE.CylinderGeometry(0.0035, 0.0035, 0.009, 10);
  const candleMat = new THREE.MeshStandardMaterial({ color: 0xfff3b0, roughness: 0.6 });
  const candleXs = [-0.0135, -0.0045, 0.0045, 0.0135];
  for (let i = 0; i < 4; i++) {
    const candle = new THREE.Mesh(candleGeo, candleMat);
    candle.position.set(candleXs[i], 0.009, -0.03);
    photoGroup.add(candle);
  }
  traits(photoGroup, { grab: true, onPress: () => showClue(2) });

  const sparkleGeo = new THREE.SphereGeometry(0.004, 8, 6);
  const sparkleMat = new THREE.MeshBasicMaterial({ color: 0xffe89a });
  const sparkles = new THREE.InstancedMesh(sparkleGeo, sparkleMat, 24);
  sparkles.name = "Sparkles";
  sparkles.position.set(BOX_X, 0, -0.05);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < 24; i++) {
    const angle = i * 2.4;
    const radius = 0.04 + (i % 6) * 0.012;
    dummy.position.set(Math.cos(angle) * radius, 0.15 + (i % 5) * 0.01, Math.sin(angle) * radius);
    dummy.scale.setScalar(0.7 + (i % 3) * 0.3);
    dummy.updateMatrix();
    sparkles.setMatrixAt(i, dummy.matrix);
  }
  sparkles.instanceMatrix.needsUpdate = true;
  root.add(sparkles);

  info.on("d0", "click", () => changeDigit(0));
  info.on("d1", "click", () => changeDigit(1));
  info.on("d2", "click", () => changeDigit(2));
  info.on("d3", "click", () => changeDigit(3));
  info.on("try", "click", tryUnlock);
  info.on("reset", "click", resetPuzzle);
  info.on("hint", "click", () => {
    if (opened) {
      info.set("message", { text: "The box is open. Press Reset to play again." });
      return;
    }
    if (hintLevel >= 3) {
      info.set("message", { text: "No more hints. You have all the clues you need." });
      return;
    }
    hintLevel++;
    info.set("hintt", { text: hintLevel >= 3 ? "Hints done" : "Hint (" + hintLevel + "/3)" });
    info.set("message", { text: hints[hintLevel - 1] });
  });

  return {
    root,
    update(time, delta) {
      sparkles.rotation.y = time * (opened ? 0.55 : 0.15);
      if (opened && openAnim < 1) {
        openAnim = Math.min(1, openAnim + delta * 0.9);
        const eased = 1 - Math.pow(1 - openAnim, 3);
        lidGroup.rotation.x = -1.95 * eased;
        if (openAnim > 0.1) {
          gemsGroup.visible = true;
          gemsGroup.scale.setScalar(0.4 + 0.6 * eased);
        }
      }
      if (gemsGroup.visible) {
        gemsGroup.rotation.y += delta * 1.0;
        gemsGroup.position.y = 0.125 + Math.sin(time * 2.2) * 0.006;
        glowMat.emissiveIntensity = 1.2 + Math.sin(time * 4) * 0.3;
      }
      let sx = 0;
      if (shakeTimer > 0) {
        shakeTimer -= delta;
        sx = Math.sin(time * 55) * 0.005 * (shakeTimer / 0.5);
      }
      base.position.x = BOX_X + sx;
      lidGroup.position.x = BOX_X + sx;
      plate.position.x = BOX_X + sx;
      gemsGroup.position.x = BOX_X + sx;
      for (let i = 0; i < bands.length; i++) bands[i].position.x = BOX_X + sx;
      for (let i = 0; i < 4; i++) drumGroups[i].position.x = drumXs[i] + sx;
      if (isGrabbed(ticketGroup)) {
        if (!prevTicket) showClue(0);
        prevTicket = true;
      } else prevTicket = false;
      if (isGrabbed(watchGroup)) {
        if (!prevWatch) showClue(1);
        prevWatch = true;
      } else prevWatch = false;
      if (isGrabbed(photoGroup)) {
        if (!prevPhoto) showClue(2);
        prevPhoto = true;
      } else prevPhoto = false;
    }
  };
}

