      <button class="ingredient" id="ingredient1"><span class="ingredient-text" id="ingredientText1">[ ] 2 tbsp sugar</span></button>
      <button class="ingredient" id="ingredient2"><span class="ingredient-text" id="ingredientText2">[ ] 2 tsp baking powder</span></button>
      <button class="ingredient" id="ingredient3"><span class="ingredient-text" id="ingredientText3">[ ] 1/2 tsp fine salt</span></button>
      <button class="ingredient" id="ingredient4"><span class="ingredient-text" id="ingredientText4">[ ] 300 ml (1 1/4 cups) milk</span></button>
      <button class="ingredient" id="ingredient5"><span class="ingredient-text" id="ingredientText5">[ ] 1 large egg</span></button>
      <button class="ingredient" id="ingredient6"><span class="ingredient-text" id="ingredientText6">[ ] 45 g (3 tbsp) melted butter</span></button>
      <button class="ingredient" id="ingredient7"><span class="ingredient-text" id="ingredientText7">[ ] 1 tsp vanilla (optional)</span></button>
