  `, { width: 0.28, position: [-0.235, 0.302, 0], rotationY: 0.15 });
  root.add(checklist.object3D);

  const coach = ui(`
    <style>
      .coach-card { width: 520px; flex-direction: column; gap: 9px;
        padding-top: 16px; padding-bottom: 16px; padding-left: 20px; padding-right: 20px;
        border-radius: 18px; background-color: #20242a; border-width: 1px; border-color: #46505c; }
      .coach-title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .step-counter { color: #ffcf78; font-size: 22px; font-weight: 700; }
      .step-title { color: #ffffff; font-size: 28px; font-weight: 700; }
      .step-body { color: #dbe1e8; font-size: 23px; }
      .progress-track { width: 480px; height: 18px; border-radius: 9px; background-color: #343b45; }
      .progress-fill { width: 0px; height: 18px; border-radius: 9px; background-color: #f3ad3d; }
      .progress-caption { color: #bdc7d3; font-size: 20px; }
      .timer-box { flex-direction: column; align-items: center; gap: 5px;
        padding-top: 9px; padding-bottom: 9px; padding-left: 12px; padding-right: 12px;
        border-radius: 12px; background-color: #191c21; }
      .timer { color: #fff1ce; font-size: 46px; font-weight: 700; text-align: center; }
      .timer-note { color: #bfc8d2; font-size: 19px; text-align: center; }
