      <span class="step-body" id="stepText">Whisk the flour, sugar, baking powder and salt in a large bowl until evenly mixed.</span>
      <div class="progress-track"><div class="progress-fill" id="recipeProgress"></div></div>
      <span class="progress-caption" id="progressCaption">0% complete - step 1 of 6</span>
      <div class="timer-box">
        <span class="timer" id="timerText">01:00</span>
        <span class="timer-note" id="timerNote">1:00 mixing guide - paused</span>
      </div>
      <div class="button-row">
        <button class="timer-button" id="startPause"><span class="button-text" id="startPauseText">Start timer</span></button>
        <button class="nav-button" id="resetTimer"><span class="button-text">Reset timer</span></button>
      </div>
      <div class="button-row">
        <button class="nav-button" id="back"><span class="button-text">Back</span></button>
        <button class="primary-button" id="next"><span class="button-text" id="nextText">Next step</span></button>
      </div>
      <span class="coach-note">Stoves vary - use sight and touch, not time alone.</span>
    </div>
  `, { width: 0.4, position: [0.19, 0.302, 0], rotationY: -0.15 });
  root.add(coach.object3D);

  let currentStep = 0;
  let remaining = steps[0].duration;
  let timerRunning = false;
  let timerExpired = false;
  let furthestStep = 0;

  function formatTime(seconds) {
    const whole = Math.max(0, Math.ceil(seconds));
    const minutes = Math.floor(whole / 60);
    const secs = whole % 60;
    return String(minutes).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
  }

  function renderTimer() {
    const step = steps[currentStep];
    coach.set('timerText', {
      text: formatTime(remaining),
      color: timerExpired ? '#8fe3a4' : (timerRunning ? '#ffffff' : '#fff1ce'),
    });
    coach.set('timerNote', {
      text: step.timerLabel + (timerExpired ? ' - time is up' : (timerRunning ? ' - running' : ' - paused')),
      color: timerExpired ? '#8fe3a4' : '#bfc8d2',
    });
    coach.set('startPauseText', {
      text: timerExpired ? 'Restart timer' : (timerRunning ? 'Pause timer' : (remaining < step.duration ? 'Resume timer' : 'Start timer')),
    });
    coach.set('startPause', { backgroundColor: timerRunning ? '#9a5b24' : '#22796c' });
  }

  function renderStep() {
    const step = steps[currentStep];
    const percent = Math.round((currentStep / steps.length) * 100);
    coach.set('stepCounter', { text: 'STEP ' + (currentStep + 1) + ' OF ' + steps.length });
    coach.set('stepTitle', { text: step.title });
    coach.set('stepText', { text: step.text });
    coach.set('recipeProgress', { width: Math.round(480 * currentStep / steps.length) + 'px' });
    coach.set('progressCaption', { text: percent + '% complete - step ' + (currentStep + 1) + ' of ' + steps.length });
    coach.set('backText', { text: currentStep === 0 ? 'Start' : 'Back' });
    coach.set('back', { backgroundColor: currentStep === 0 ? '#2a3038' : '#3a434f' });
    coach.set('nextText', { text: currentStep === steps.length - 1 ? 'Finish recipe' : 'Next step' });
    renderTimer();
  }

  function loadStep(index) {
    currentStep = Math.max(0, Math.min(steps.length - 1, index));
    furthestStep = Math.max(furthestStep, currentStep);
    remaining = steps[currentStep].duration;
    timerRunning = false;
    timerExpired = false;
    renderStep();
  }

  coach.on('back', 'click', () => {
    if (currentStep > 0) loadStep(currentStep - 1);
  });

  coach.on('next', 'click', () => {
    if (currentStep < steps.length - 1) {
      loadStep(currentStep + 1);
    } else {
      timerRunning = false;
      timerExpired = false;
      coach.set('stepCounter', { text: 'RECIPE COMPLETE' });
      coach.set('stepTitle', { text: 'Serve and enjoy' });
