  });

  coach.on('startPause', 'click', () => {
    if (currentStep >= steps.length) return;
    if (timerExpired) {
      remaining = steps[currentStep].duration;
      timerExpired = false;
      timerRunning = true;
    } else {
      timerRunning = !timerRunning;
    }
    renderTimer();
  });

  coach.on('resetTimer', 'click', () => {
    if (currentStep >= steps.length) currentStep = steps.length - 1;
    remaining = steps[currentStep].duration;
    timerRunning = false;
    timerExpired = false;
