  const plate = new THREE.Mesh(new THREE.CylinderGeometry(0.068, 0.062, 0.008, 32), ceramic);
  plate.name = 'Serving plate';
  plate.position.set(-0.09, 0.005, 0.015);
  display.add(plate);

  const pancakeGeometry = new THREE.CylinderGeometry(0.049, 0.051, 0.009, 32);
  const pancakeStack = [];
  for (let i = 0; i < 3; i++) {
    const pancake = new THREE.Mesh(pancakeGeometry, pancakeMaterial);
