    pancake.position.set(-0.09, 0.014 + i * 0.008, 0.015);
    pancake.rotation.y = i * 0.35;
    display.add(pancake);
    pancakeStack.push(pancake);
  }

  const butter = new THREE.Mesh(new THREE.BoxGeometry(0.019, 0.007, 0.016), butterMaterial);
  butter.name = 'Butter on pancakes';
  butter.position.set(-0.09, 0.039, 0.015);
  butter.rotation.y = 0.25;
  display.add(butter);

  const pan = new THREE.Group();
  pan.name = 'Frying pan';
  pan.position.set(0.07, 0.009, 0.005);
  display.add(pan);

  const panBase = new THREE.Mesh(new THREE.CylinderGeometry(0.057, 0.052, 0.012, 32), darkMetal);
  pan.add(panBase);

  const panRim = new THREE.Mesh(new THREE.TorusGeometry(0.054, 0.004, 8, 32), darkMetal);
  panRim.rotation.x = Math.PI / 2;
  panRim.position.y = 0.007;
  pan.add(panRim);

  const handle = new THREE.Mesh(new THREE.BoxGeometry(0.075, 0.009, 0.018), darkMetal);
  handle.position.set(0.087, 0, 0);
  pan.add(handle);

  const cookingPancake = new THREE.Mesh(pancakeGeometry, pancakeMaterial);
  cookingPancake.name = 'Pancake in pan';
  cookingPancake.scale.set(0.86, 0.7, 0.86);
  cookingPancake.position.y = 0.011;
  pan.add(cookingPancake);

  const heatMaterial = new THREE.MeshStandardMaterial({
    color: 0xf6a43a,
    emissive: 0xe56b16,
    emissiveIntensity: 0.45,
    roughness: 0.5,
  });
  const bubbleGeometry = new THREE.SphereGeometry(0.004, 12, 8);
  const bubbles = [];
  for (let i = 0; i < 5; i++) {
    const bubble = new THREE.Mesh(bubbleGeometry, heatMaterial);
    const angle = i * 2.399;
    const radius = 0.012 + (i % 2) * 0.009;
    bubble.position.set(Math.cos(angle) * radius, 0.016, Math.sin(angle) * radius);
    pan.add(bubble);
    bubbles.push(bubble);
  }

  return {
    root,
    update(time, delta) {
      if (currentStep < steps.length && timerRunning && remaining > 0) {
        remaining = Math.max(0, remaining - Math.min(delta, 0.25));
        if (remaining === 0) {
          timerRunning = false;
          timerExpired = true;
        }
        renderTimer();
      }

      const finished = currentStep >= steps.length;
      const cooking = !finished && (currentStep === 4 || currentStep === 5);
      const sizzling = cooking && timerRunning;

      bubbles.forEach((bubble, index) => {
        bubble.visible = cooking;
        const pulse = sizzling ? 0.75 + 0.35 * Math.sin(time * 5 + index * 1.7) : 0.8;
        bubble.scale.setScalar(pulse);
      });

      butter.rotation.y = finished ? 0.25 + Math.sin(time * 0.8) * 0.06 : 0.25;
      heatMaterial.emissiveIntensity = sizzling ? 0.65 + Math.sin(time * 4) * 0.15 : 0.3;
    },
  };
}

