    { name: 'Uranus', color: 0x7fd1d9, orbitRadius: 0.200, sizeRadius: 0.011, visualPeriod: 60, phase: 0.3, diameterKm: 50724, diameter: 'Diameter: 50,724 km', distance: 'Distance from Sun: 2.87 billion km', period: 'Orbital period: 84 Earth years', fact: 'Tilted about 98 degrees on its side.' },
    { name: 'Neptune', color: 0x4466d6, orbitRadius: 0.220, sizeRadius: 0.0105, visualPeriod: 78, phase: 2.9, diameterKm: 49244, diameter: 'Diameter: 49,244 km', distance: 'Distance from Sun: 4.50 billion km', period: 'Orbital period: 164.8 Earth years', fact: 'Fastest winds in the Solar System.' }
  ];

  const sphereGeo = new THREE.SphereGeometry(1, 32, 16);
  const hitGeo = new THREE.SphereGeometry(1, 16, 10);
  const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });

  // Star background
  const starPoints = [];
  for (let i = 0; i < 140; i++) {
    const sx = Math.sin(i * 12.9898) * 0.36;
    const sy = 0.06 + 0.42 * (0.5 + 0.5 * Math.sin(i * 78.233 + 1.7));
    starPoints.push(new THREE.Vector3(sx, sy, -0.235));
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setFromPoints(starPoints);
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xdde6ff, size: 0.004, transparent: true, opacity: 0.8, sizeAttenuation: true }));
  stars.name = 'Stars';
  root.add(stars);

  // Orbit lines
  const orbitLineMat = new THREE.LineBasicMaterial({ color: 0x93a5c4, transparent: true, opacity: 0.55 });
  for (let i = 0; i < planetData.length; i++) {
    const pts = [];
    for (let j = 0; j < 96; j++) {
      const a = (j / 96) * Math.PI * 2;
      pts.push(new THREE.Vector3(orbitCX + Math.cos(a) * planetData[i].orbitRadius, orbitCY, orbitCZ + Math.sin(a) * planetData[i].orbitRadius));
    }
    const geo = new THREE.BufferGeometry();
    geo.setFromPoints(pts);
    const line = new THREE.LineLoop(geo, orbitLineMat);
    line.name = planetData[i].name + ' orbit';
    root.add(line);
    orbitLines.push(line);
  }

  // Sun and glow
  const sun = new THREE.Mesh(sphereGeo, new THREE.MeshStandardMaterial({ color: 0xffd23d, emissive: 0xff8a00, emissiveIntensity: 0.9, roughness: 0.4 }));
  sun.name = 'Sun';
  root.add(sun);
  const sunGlow = new THREE.Mesh(sphereGeo, new THREE.MeshBasicMaterial({ color: 0xffb347, transparent: true, opacity: 0.15, depthWrite: false }));
  sunGlow.name = 'Sun glow';
  root.add(sunGlow);

  // Info panel, top
  const infoPanel = ui(`
    <style>
      .card { width: 440px; flex-direction: column; gap: 6px; padding-top: 14px; padding-bottom: 14px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1a1d22; border-width: 2px; border-color: #3a4048; }
      .title { color: #ffffff; font-size: 28px; font-weight: 700; text-align: center; }
      .line { color: #d7dbe2; font-size: 20px; text-align: center; }
      .fact { color: #f5d67a; font-size: 20px; text-align: center; }
    </style>
    <div class="card">
      <span class="title" id="infoTitle">Tap a planet</span>
      <span class="line" id="infoDia">Tap a planet for its facts.</span>
      <span class="line" id="infoDist">Play, pause and change speed below.</span>
      <span class="line" id="infoPeriod">Compare sizes shows true sizes.</span>
      <span class="fact" id="infoFact">Orbits and labels can be toggled.</span>
    </div>`, { width: 0.36, position: [0, 0.415, 0.08], rotationY: 0 });
  root.add(infoPanel.object3D);

  // Control panel, bottom front
  const controls = ui(`
    <style>
      .card { width: 520px; flex-direction: column; gap: 6px; padding-top: 12px; padding-bottom: 12px; padding-left: 18px; padding-right: 18px; border-radius: 16px; background-color: #1a1d22; border-width: 2px; border-color: #3a4048; }
      .title { color: #ffffff; font-size: 26px; font-weight: 700; text-align: center; }
      .status { color: #a8d8ff; font-size: 20px; text-align: center; }
      .row { flex-direction: row; gap: 8px; align-items: center; justify-content: center; }
      .btn { background-color: #2f6fdb; border-radius: 10px; border-width: 1px; border-color: #2f6fdb; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; }
      .btn-grey { background-color: #343a44; border-radius: 10px; border-width: 1px; border-color: #4a515c; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; }
      .btn-purple { background-color: #7a4fb0; border-radius: 10px; border-width: 1px; border-color: #7a4fb0; padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .hint { color: #d7dbe2; font-size: 18px; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Solar System Simulator</span>
      <span class="status" id="status">Running at 1x</span>
      <div class="row">
        <button class="btn" id="playBtn"><span class="btn-text" id="playText">Pause</span></button>
        <button class="btn-grey" id="sp05"><span class="btn-text">0.5x</span></button>
        <button class="btn-grey" id="sp1"><span class="btn-text">1x</span></button>
        <button class="btn-grey" id="sp2"><span class="btn-text">2x</span></button>
        <button class="btn-grey" id="sp4"><span class="btn-text">4x</span></button>
        <button class="btn-grey" id="sp8"><span class="btn-text">8x</span></button>
      </div>
      <div class="row">
        <button class="btn-grey" id="orbitBtn"><span class="btn-text" id="orbitText">Orbits: On</span></button>
        <button class="btn-grey" id="labelBtn"><span class="btn-text" id="labelText">Labels: On</span></button>
        <button class="btn-purple" id="compareBtn"><span class="btn-text" id="compareText">Compare sizes</span></button>
      </div>
      <span class="hint">Tap a planet for facts. Motion is sped up.</span>
    </div>`, { width: 0.42, position: [0, 0.095, 0.20], rotationY: 0 });
  root.add(controls.object3D);

  function refreshStatus() {
    controls.set('status', { text: playing ? 'Running at ' + speed + 'x' : 'Paused' });
  }
  function updateSpeedButtons() {
    controls.set('sp05', { backgroundColor: speed === 0.5 ? '#2f6fdb' : '#343a44' });
    controls.set('sp1', { backgroundColor: speed === 1 ? '#2f6fdb' : '#343a44' });
    controls.set('sp2', { backgroundColor: speed === 2 ? '#2f6fdb' : '#343a44' });
    controls.set('sp4', { backgroundColor: speed === 4 ? '#2f6fdb' : '#343a44' });
    controls.set('sp8', { backgroundColor: speed === 8 ? '#2f6fdb' : '#343a44' });
  }
  function highlightLabels() {
    for (let i = 0; i < labels.length; i++) {
      labels[i].set('lab', { backgroundColor: i === selectedIndex ? '#2f6fdb' : '#20242b' });
    }
  }
  function showPlanet(index) {
    selectedIndex = index;
    const p = planetData[index];
    infoPanel.set('infoTitle', { text: p.name });
    infoPanel.set('infoDia', { text: p.diameter });
    infoPanel.set('infoDist', { text: p.distance });
    infoPanel.set('infoPeriod', { text: p.period });
    infoPanel.set('infoFact', { text: p.fact });
    highlightLabels();
  }
  function showSun() {
    selectedIndex = -1;
    highlightLabels();
    infoPanel.set('infoTitle', { text: 'Sun' });
    infoPanel.set('infoDia', { text: 'Diameter: 1,392,700 km' });
    infoPanel.set('infoDist', { text: 'Center of the Solar System' });
    infoPanel.set('infoPeriod', { text: 'Rotation: about 27 Earth days' });
    infoPanel.set('infoFact', { text: 'The Sun holds 99.86 percent of the mass.' });
  }
  function showHome() {
    selectedIndex = -1;
    highlightLabels();
    infoPanel.set('infoTitle', { text: 'Tap a planet' });
    infoPanel.set('infoDia', { text: 'Tap a planet for its facts.' });
    infoPanel.set('infoDist', { text: 'Play, pause and change speed below.' });
    infoPanel.set('infoPeriod', { text: 'Compare sizes shows true sizes.' });
    infoPanel.set('infoFact', { text: 'Orbits and labels can be toggled.' });
  }
  function showCompare() {
    selectedIndex = -1;
    highlightLabels();
    infoPanel.set('infoTitle', { text: 'Compare sizes' });
    infoPanel.set('infoDia', { text: 'True relative diameters, side by side.' });
    infoPanel.set('infoDist', { text: 'Jupiter is 28.7x wider than Mercury.' });
    infoPanel.set('infoPeriod', { text: 'Earth is 11.0x narrower than Jupiter.' });
    infoPanel.set('infoFact', { text: 'Sun would be 10 Jupiter widths across.' });
  }

  // Planets, hit areas and labels
  let cursorX = -0.27;
  for (let i = 0; i < planetData.length; i++) {
    const p = planetData[i];
    const compareRadius = (p.diameterKm * (0.105 / 139820)) / 2;
    const compareX = cursorX + compareRadius;
    cursorX = compareX + compareRadius + 0.035;

    const mesh = new THREE.Mesh(sphereGeo, new THREE.MeshStandardMaterial({ color: p.color, roughness: 0.55, metalness: 0.05 }));
    mesh.name = p.name;
    root.add(mesh);

    const hit = new THREE.Mesh(hitGeo, hitMat);
    hit.name = p.name + ' hit area';
    root.add(hit);

    const hitOrbit = p.name === 'Saturn' ? 0.032 : Math.max(p.sizeRadius, 0.0115);
    const hitCompare = Math.max(compareRadius, 0.0095);
    planets.push({ data: p, mesh: mesh, hit: hit, compareX: compareX, compareRadius: compareRadius, hitOrbit: hitOrbit, hitCompare: hitCompare, currentRadius: p.sizeRadius });

    const idx = i;
    traits(mesh, { onPress: () => showPlanet(idx) });
    traits(hit, { onPress: () => showPlanet(idx) });

    if (p.name === 'Saturn') {
      saturnRing = new THREE.Mesh(new THREE.RingGeometry(1.35, 2.35, 48, 1), new THREE.MeshStandardMaterial({ color: 0xd9c48a, roughness: 0.7, metalness: 0.05, side: THREE.DoubleSide, transparent: true, opacity: 0.95 }));
      saturnRing.name = 'Saturn rings';
      saturnRing.rotation.set(-1.15, 0, 0.2);
      root.add(saturnRing);
    }

    const lbl = ui(`
      <style>
        .label { width: 160px; flex-direction: column; align-items: center; padding-top: 6px; padding-bottom: 6px; padding-left: 6px; padding-right: 6px; border-radius: 10px; background-color: #20242b; border-width: 1px; border-color: #3a4048; }
        .txt { color: #ffffff; font-size: 32px; font-weight: 700; text-align: center; }
      </style>
      <div class="label" id="lab"><span class="txt">${p.name}</span></div>`, { width: 0.065, position: [0, 0.3, 0] });
    root.add(lbl.object3D);
    labels.push(lbl);
  }

  traits(sun, { onPress: () => showSun() });

  // Control handlers
  controls.on('playBtn', 'click', () => {
    playing = !playing;
    controls.set('playText', { text: playing ? 'Pause' : 'Play' });
    refreshStatus();
  });
  function setSpeed(v) {
    speed = v;
    refreshStatus();
    updateSpeedButtons();
  }
  controls.on('sp05', 'click', () => setSpeed(0.5));
  controls.on('sp1', 'click', () => setSpeed(1));
  controls.on('sp2', 'click', () => setSpeed(2));
  controls.on('sp4', 'click', () => setSpeed(4));
  controls.on('sp8', 'click', () => setSpeed(8));
  controls.on('orbitBtn', 'click', () => {
    showOrbits = !showOrbits;
    controls.set('orbitText', { text: showOrbits ? 'Orbits: On' : 'Orbits: Off' });
  });
  controls.on('labelBtn', 'click', () => {
    showLabels = !showLabels;
    controls.set('labelText', { text: showLabels ? 'Labels: On' : 'Labels: Off' });
  });
  controls.on('compareBtn', 'click', () => {
    compareMode = !compareMode;
    controls.set('compareText', { text: compareMode ? 'Back to orbits' : 'Compare sizes' });
    controls.set('compareBtn', { backgroundColor: compareMode ? '#2f6fdb' : '#7a4fb0' });
    if (compareMode) {
      showCompare();
    } else if (selectedIndex >= 0) {
      showPlanet(selectedIndex);
    } else {
      showHome();
    }
  });

  function update(time, delta) {
    const targetBlend = compareMode ? 1 : 0;
    if (blend < targetBlend) {
      blend = Math.min(targetBlend, blend + delta / 1.3);
    } else if (blend > targetBlend) {
      blend = Math.max(targetBlend, blend - delta / 1.3);
    }
    const eased = blend * blend * (3 - 2 * blend);
    if (playing && blend < 0.01) {
      simTime += delta * speed;
    }

    for (let i = 0; i < planets.length; i++) {
      const entry = planets[i];
      const p = entry.data;
      const angle = p.phase + simTime * (Math.PI * 2 / p.visualPeriod);
      const orbitX = orbitCX + Math.cos(angle) * p.orbitRadius;
      const orbitZ = orbitCZ + Math.sin(angle) * p.orbitRadius;
      const orbitY = orbitCY;
      const px = orbitX + (entry.compareX - orbitX) * eased;
      const py = orbitY + ((compareBaseY + entry.compareRadius) - orbitY) * eased;
      const pz = orbitZ + (compareZ - orbitZ) * eased;
      const radius = p.sizeRadius + (entry.compareRadius - p.sizeRadius) * eased;
      entry.currentRadius = radius;
      entry.mesh.position.set(px, py, pz);
      entry.mesh.scale.setScalar(radius);
      const hitRadius = entry.hitOrbit + (entry.hitCompare - entry.hitOrbit) * eased;
      entry.hit.position.set(px, py, pz);
      entry.hit.scale.setScalar(hitRadius);

      const lbl = labels[i];
      lbl.object3D.visible = showLabels;
      const stagger = (i < 4 && i % 2 === 1) ? 0.038 : 0;
      const labelY = py + radius + 0.018 + stagger * eased;
      lbl.object3D.position.set(px, labelY, pz);
    }

    if (saturnRing) {
      saturnRing.visible = eased < 0.5;
      saturnRing.position.copy(planets[5].mesh.position);
      saturnRing.scale.setScalar(planets[5].currentRadius);
    }

    const sunX = orbitCX + (compareSunX - orbitCX) * eased;
    const sunY = orbitCY + (compareSunY - orbitCY) * eased;
    const sunZ = orbitCZ + (compareSunZ - orbitCZ) * eased;
    const sunRadius = 0.035 + (0.024 - 0.035) * eased;
    sun.position.set(sunX, sunY, sunZ);
    sun.scale.setScalar(sunRadius);
    sunGlow.position.set(sunX, sunY, sunZ);
    sunGlow.scale.setScalar(sunRadius * (1.7 + 0.08 * Math.sin(time * 2)));

    for (let j = 0; j < orbitLines.length; j++) {
      orbitLines[j].visible = showOrbits && eased < 0.5;
    }
  }

  refreshStatus();
  updateSpeedButtons();
  update(0, 0);

  return { root, update };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const columnNames = ['To do', 'In progress', 'Review', 'Done'];
  const priorityLabels = { high: 'HIGH', medium: 'MED', low: 'LOW' };
  const tasks = [
    { id: 0, title: 'Login flow', priority: 'high', column: 0, start: 0 },
    { id: 1, title: 'API errors', priority: 'high', column: 1, start: 1 },
    { id: 2, title: 'Board UI', priority: 'medium', column: 2, start: 2 },
    { id: 3, title: 'Unit tests', priority: 'medium', column: 0, start: 0 },
    { id: 4, title: 'User guide', priority: 'low', column: 3, start: 3 },
    { id: 5, title: 'Demo script', priority: 'low', column: 0, start: 0 },
  ];

  let highOnly = false;
  const MAX_POINTS = 7;
  const history = [6, 5];

  function doneCount() {
    return tasks.reduce((count, task) => count + (task.column === 3 ? 1 : 0), 0);
  }

  function remainingCount() {
    return tasks.length - doneCount();
  }

  // 3D burndown chart.
  const chartBacking = new THREE.Mesh(
    new THREE.BoxGeometry(0.2, 0.24, 0.012),
    new THREE.MeshStandardMaterial({ color: 0x171b22, roughness: 0.9, metalness: 0.04 }),
  );
  chartBacking.name = 'Burndown chart backing';
  chartBacking.position.set(0.285, 0.195, 0);
  root.add(chartBacking);

  const chart = new THREE.Group();
  chart.name = 'Burndown chart';
  chart.position.set(0.285, 0.195, 0.008);
  root.add(chart);

  const plotWidth = 0.15;
  const plotHeight = 0.15;
  const plotLeft = -0.075;
  const plotBottom = -0.075;
  const unitBox = new THREE.BoxGeometry(1, 1, 1);
  const gridMaterial = new THREE.MeshBasicMaterial({ color: 0x35404d });
  const axisMaterial = new THREE.MeshBasicMaterial({ color: 0x748091 });

  function addBar(name, width, height, x, y, material) {
    const bar = new THREE.Mesh(unitBox, material);
    bar.name = name;
    bar.scale.set(width, height, 0.002);
    bar.position.set(x, y, 0);
    chart.add(bar);
    return bar;
  }

  addBar('Burndown horizontal axis', plotWidth, 0.0018, 0, plotBottom, axisMaterial);
  addBar('Burndown vertical axis', 0.0018, plotHeight, plotLeft, 0, axisMaterial);
  addBar('Three tasks grid line', plotWidth, 0.001, 0, 0, gridMaterial);
  addBar('Six tasks grid line', plotWidth, 0.001, 0, plotBottom + plotHeight, gridMaterial);

  const segmentStart = new THREE.Vector3();
  const segmentEnd = new THREE.Vector3();
  const segmentDirection = new THREE.Vector3();
  const up = new THREE.Vector3(0, 1, 0);

  function setSegment(mesh, x1, y1, x2, y2, z) {
    segmentStart.set(x1, y1, z);
    segmentEnd.set(x2, y2, z);
    segmentDirection.subVectors(segmentEnd, segmentStart);
    const length = segmentDirection.length();
    mesh.position.copy(segmentStart).add(segmentEnd).multiplyScalar(0.5);
    mesh.scale.set(1, length, 1);
    mesh.quaternion.setFromUnitVectors(up, segmentDirection.normalize());
  }

  const idealMaterial = new THREE.MeshBasicMaterial({ color: 0x737e8c });
  const idealSegment = new THREE.Mesh(
    new THREE.CylinderGeometry(0.001, 0.001, 1, 6),
    idealMaterial,
  );
  idealSegment.name = 'Ideal burndown';
  setSegment(
    idealSegment,
    plotLeft,
    plotBottom + plotHeight,
    plotLeft + plotWidth,
    plotBottom,
    0.002,
  );
  chart.add(idealSegment);

  const actualMaterial = new THREE.MeshStandardMaterial({
    color: 0x58d7ff,
    emissive: 0x147a9e,
    emissiveIntensity: 0.65,
    roughness: 0.35,
  });
  const actualSegmentGeometry = new THREE.CylinderGeometry(0.0018, 0.0018, 1, 8);
  const actualSegments = [];
  const actualPoints = [];
  const pointGeometry = new THREE.SphereGeometry(0.0045, 12, 8);

  for (let i = 0; i < MAX_POINTS - 1; i++) {
    const segment = new THREE.Mesh(actualSegmentGeometry, actualMaterial);
    segment.name = `Actual burndown segment ${i + 1}`;
    actualSegments.push(segment);
    chart.add(segment);
  }

  for (let i = 0; i < MAX_POINTS; i++) {
    const point = new THREE.Mesh(pointGeometry, actualMaterial);
    point.name = `Actual remaining point ${i + 1}`;
    actualPoints.push(point);
    chart.add(point);
  }

  const pointX = new Float32Array(MAX_POINTS);
  const pointY = new Float32Array(MAX_POINTS);

  const chartInfo = ui(`
    <style>
      .chart-card { width: 240px; flex-direction: column; gap: 5px; padding-top: 12px;
                    padding-bottom: 12px; padding-left: 12px; padding-right: 12px;
                    border-radius: 14px; background-color: #1c2027; border-width: 1px;
                    border-color: #3b4552; }
      .chart-title { color: #ffffff; font-size: 26px; font-weight: 700; }
      .chart-metric { color: #58d7ff; font-size: 22px; font-weight: 700; }
      .legend { flex-direction: row; gap: 10px; }
      .actual-label { color: #58d7ff; font-size: 16px; }
      .ideal-label { color: #b4bdc9; font-size: 16px; }
      .chart-scale { color: #c9d0d9; font-size: 16px; }
    </style>
    <div class="chart-card">
      <span class="chart-title">Burndown</span>
      <span class="chart-metric" id="remaining">1 of 6 done - 5 left</span>
      <div class="legend">
        <span class="actual-label">Cyan: actual</span>
        <span class="ideal-label">Gray: ideal</span>
      </div>
      <span class="chart-scale">Scale 0 to 6 tasks</span>
    </div>`, { width: 0.2, position: [0.285, 0.405, 0.05] });
  root.add(chartInfo.object3D);

  function refreshChart() {
    const count = Math.min(history.length, MAX_POINTS);

    for (let i = 0; i < count; i++) {
      pointX[i] = plotLeft + (i / (MAX_POINTS - 1)) * plotWidth;
      pointY[i] = plotBottom + (Math.max(0, Math.min(6, history[i])) / 6) * plotHeight;
    }

    for (let i = 0; i < MAX_POINTS; i++) {
      const point = actualPoints[i];
      point.visible = i < count;
      if (i < count) {
        point.position.set(pointX[i], pointY[i], 0.008);
      }
    }

    for (let i = 0; i < MAX_POINTS - 1; i++) {
      const segment = actualSegments[i];
      segment.visible = i < count - 1;
      if (i < count - 1) {
        setSegment(segment, pointX[i], pointY[i], pointX[i + 1], pointY[i + 1], 0.005);
      }
    }

    chartInfo.set('remaining', {
      text: `${doneCount()} of 6 done - ${remainingCount()} left`,
    });
  }

  let boardPanel = null;

  function renderBoard() {
    if (boardPanel) {
      root.remove(boardPanel.object3D);
    }

    const visibleTasks = tasks.filter(task => !highOnly || task.priority === 'high');
    const summary = highOnly
      ? `${visibleTasks.length} of 6 shown - ${doneCount()} done`
      : `6 cards - ${doneCount()} done`;

    const columnsMarkup = columnNames.map((columnName, columnIndex) => {
      const columnTasks = visibleTasks.filter(task => task.column === columnIndex);
      const cardsMarkup = columnTasks.length
        ? columnTasks.map(task => {
            const leftControl = task.column > 0
              ? `<button class="arrow" id="left-${task.id}"><span class="arrow-text">&lt;</span></button>`
              : '<span class="arrow-placeholder"></span>';
            const rightControl = task.column < 3
              ? `<button class="arrow" id="right-${task.id}"><span class="arrow-text">&gt;</span></button>`
              : '<span class="arrow-placeholder"></span>';

            return `
              <div class="task ${task.priority}">
                <span class="task-title">${task.title}</span>
                <div class="task-actions">
                  ${leftControl}
                  <span class="priority ${task.priority}-text">${priorityLabels[task.priority]}</span>
                  ${rightControl}
                </div>
              </div>`;
          }).join('')
        : '<span class="empty">No cards</span>';

      return `
        <div class="column">
          <span class="column-title">${columnName}</span>
          ${cardsMarkup}
        </div>`;
    }).join('');

    boardPanel = ui(`
      <style>
        .board { width: 600px; flex-direction: column; gap: 8px; padding-top: 8px;
                 padding-bottom: 8px; padding-left: 8px; padding-right: 8px;
