        .summary { color: #d8dee7; font-size: 15px; }
        .tools { flex-direction: row; gap: 8px; }
        .tool-button { padding-top: 6px; padding-bottom: 6px; padding-left: 10px;
                       padding-right: 10px; border-radius: 8px; background-color: #303844;
                       border-width: 1px; border-color: #526071; }
        .filter-on { background-color: #9b3f4b; border-color: #ff8290; }
        .tool-text { color: #ffffff; font-size: 15px; font-weight: 700; }
        .columns { flex-direction: row; gap: 6px; align-items: flex-start; }
        .column { width: 131px; flex-direction: column; align-items: stretch; gap: 4px;
                  padding-top: 4px; padding-bottom: 4px; padding-left: 4px; padding-right: 4px;
                  border-radius: 10px; background-color: #242a32; border-width: 1px;
                  border-color: #3b4653; }
        .column-title { color: #f2f5f8; font-size: 19px; font-weight: 700; text-align: center; }
        .task { flex-direction: column; gap: 2px; padding-top: 3px; padding-bottom: 3px;
                padding-left: 3px; padding-right: 3px; border-radius: 8px; border-width: 1px; }
        .high { background-color: #55262e; border-color: #ff7180; }
        .medium { background-color: #4c3b22; border-color: #eab04f; }
        .low { background-color: #1e4236; border-color: #56d69e; }
        .task-title { color: #f5f7fa; font-size: 20px; font-weight: 700; }
        .task-actions { flex-direction: row; align-items: center; justify-content: space-between; }
        .arrow { width: 36px; height: 28px; padding-top: 0px; padding-bottom: 0px;
                 padding-left: 0px; padding-right: 0px; align-items: center;
                 justify-content: center; border-radius: 7px; background-color: #3a4553;
                 border-width: 1px; border-color: #6c7b8e; }
        .arrow-text { color: #ffffff; font-size: 22px; font-weight: 700; }
        .arrow-placeholder { width: 36px; height: 28px; }
        .priority { font-size: 14px; font-weight: 700; }
        .high-text { color: #ff98a2; }
        .medium-text { color: #f3c66f; }
        .low-text { color: #79dfae; }
        .empty { color: #9da8b5; font-size: 14px; text-align: center; }
      </style>
      <div class="board">
        <div class="top">
          <span class="title">Sprint board</span>
          <span class="subtitle">Arrows move cards. Filter shows high priority only.</span>
        </div>
        <div class="toolbar">
          <span class="summary">${summary}</span>
          <div class="tools">
            <button class="tool-button ${highOnly ? 'filter-on' : ''}" id="high-filter">
              <span class="tool-text">High only: ${highOnly ? 'On' : 'Off'}</span>
            </button>
            <button class="tool-button" id="reset-board">
              <span class="tool-text">Reset</span>
            </button>
          </div>
        </div>
        <div class="columns">${columnsMarkup}</div>
      </div>`, { width: 0.52, position: [-0.12, 0.255, 0.06] });

    root.add(boardPanel.object3D);

    boardPanel.on('high-filter', 'click', () => {
      highOnly = !highOnly;
      renderBoard();
    });

    boardPanel.on('reset-board', 'click', () => {
      for (const task of tasks) {
        task.column = task.start;
      }
      highOnly = false;
      history.splice(0, history.length, 6, remainingCount());
      refreshChart();
      renderBoard();
    });

    for (const task of visibleTasks) {
      if (task.column > 0) {
        boardPanel.on(`left-${task.id}`, 'click', () => moveTask(task.id, -1));
      }
      if (task.column < 3) {
        boardPanel.on(`right-${task.id}`, 'click', () => moveTask(task.id, 1));
      }
    }
  }

  function moveTask(taskId, direction) {
    const task = tasks.find(item => item.id === taskId);
    if (!task) return;

    const previousColumn = task.column;
    const nextColumn = Math.max(0, Math.min(3, previousColumn + direction));
    if (nextColumn === previousColumn) return;

    task.column = nextColumn;
    const wasDone = previousColumn === 3;
    const isDone = nextColumn === 3;

    if (wasDone !== isDone) {
      history.push(remainingCount());
      if (history.length > MAX_POINTS) {
        history.shift();
      }
    }

    refreshChart();
    renderBoard();
  }

  refreshChart();
  renderBoard();

  return { root };
}

