  function changeTemperature(amount) {
    const next = Math.max(16, Math.min(28, Math.round((state.temperature + amount) * 2) / 2));
    state.temperature = next;
    state.activeScene = 'Custom';
    state.message = 'Custom - thermostat set to ' + next.toFixed(1) + ' C.';
