  }

  function applyScene(name) {
    const preset = presets[name];
    for (let i = 0; i < rooms.length; i++) {
      state.lights[i] = preset.lights[i];
      if (preset.lights[i] > 0) state.lastOn[i] = preset.lights[i];
    }
    state.temperature = preset.temperature;
    state.activeScene = name;
    state.message = preset.message;
    refresh();
  }

  function refresh() {
    rooms.forEach((room, index) => {
      controls.set(room.id + 'Value', { text: state.lights[index] + '%' });
    });
    controls.set('tempValue', { text: state.temperature.toFixed(1) + ' C' });
    controls.set('mode', { text: state.message });

    const sceneNames = ['Movie', 'Dinner', 'Away'];
    const activeColors = { Movie: '#7256b8', Dinner: '#9b672e', Away: '#34727b' };
    sceneNames.forEach((name) => {
      controls.set('scene' + name, {
        backgroundColor: state.activeScene === name ? activeColors[name] : '#33404c',
      });
    });

    let lightWatts = 0;
    for (let i = 0; i < rooms.length; i++) {
      lightWatts += rooms[i].watts * state.lights[i] / 100;
    }
    const heatingWatts = Math.max(0, state.temperature - 16) * 45;
    const currentWatts = Math.round(38 + lightWatts + heatingWatts);
    energy.set('livePower', {
      text: 'Now ' + currentWatts + ' W',
      color: currentWatts < 150 ? '#91e2ad' : '#8edcec',
    });
  }

  rooms.forEach((room, index) => {
    controls.on(room.id + 'Down', 'click', () => setLight(index, state.lights[index] - 10));
    controls.on(room.id + 'Up', 'click', () => setLight(index, state.lights[index] + 10));
  });
  controls.on('tempDown', 'click', () => changeTemperature(-0.5));
  controls.on('tempUp', 'click', () => changeTemperature(0.5));
  controls.on('sceneMovie', 'click', () => applyScene('Movie'));
  controls.on('sceneDinner', 'click', () => applyScene('Dinner'));
  controls.on('sceneAway', 'click', () => applyScene('Away'));

  function paintRoom(index, level) {
    const amount = Math.max(0, level) / 100;
    floorMeshes[index].material.emissiveIntensity = amount * 0.42;
    bulbMaterials[index].emissiveIntensity = amount * 3.2;
    bulbMaterials[index].color.setHex(level > 0.2 ? 0xffe4a8 : 0x62676c);
    poolMaterials[index].opacity = amount * 0.22;
  }

  for (let i = 0; i < rooms.length; i++) paintRoom(i, visualLevels[i]);
  refresh();

  return {
    root,
    update(time, delta) {
      const blend = Math.min(1, delta * 9);
      for (let i = 0; i < rooms.length; i++) {
        visualLevels[i] += (state.lights[i] - visualLevels[i]) * blend;
        paintRoom(i, visualLevels[i]);
      }
    },
  };
}

