  arc.name = 'Angle scale';
  root.add(arc);

  const tickPoints = [];
  const tickAngles = [-30, -15, 0, 15, 30];
  for (let i = 0; i < tickAngles.length; i++) {
    const a = tickAngles[i] * Math.PI / 180;
    tickPoints.push(
      pivotX + 0.071 * Math.sin(a), pivotY - 0.071 * Math.cos(a), 0.007,
