  runButton.name = 'Run pause button';
  runButton.position.set(-0.22, 0.047, 0.061);
  root.add(runButton);

  // Chart bars share a fixed three-second scale.
  const chartCenterX = 0.17;
  const chartBaseline = 0.014;
  const chartMaxHeight = 0.078;
  const chartBoardMaterial = new THREE.MeshStandardMaterial({
    color: 0x20262e,
    metalness: 0.15,
    roughness: 0.72,
  });
  addBox('Period chart backing', chartBoardMaterial, chartCenterX, 0.055, -0.04, 0.346, 0.094, 0.008);

  const gridMaterial = new THREE.MeshBasicMaterial({ color: 0x46515e });
  for (let seconds = 1; seconds <= 3; seconds++) {
    addBox(
      `Chart ${seconds} second gridline`,
