      0.326,
      0.0014,
      0.002,
    );
  }

  const barMaterial = new THREE.MeshStandardMaterial({
    color: 0x55b8e8,
    emissive: 0x123e55,
    emissiveIntensity: 0.35,
    roughness: 0.42,
  });
  const latestBarMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd166,
    emissive: 0x72500d,
    emissiveIntensity: 0.45,
    roughness: 0.38,
  });

  const history = [];
  for (let i = 0; i < 10; i++) {
    history.push({ period: 0, length: 0.24, gravity: 9.81, name: 'Earth' });
  }
  let sampleCount = 0;
  let sampleHead = 0;
  const bars = [];

  const chartUI = ui(`
    <style>
      .caption { width: 460px; display: flex; flex-direction: column; gap: 4px;
                 padding-top: 8px; padding-bottom: 8px; padding-left: 12px; padding-right: 12px;
                 border-radius: 12px; background-color: #20242b; border-color: #46515e; border-width: 1px; }
      .caption-title { color: #f1f5f9; font-size: 22px; font-weight: 700; text-align: center; }
      .caption-detail { color: #b9c7d6; font-size: 20px; text-align: center; }
    </style>
    <div class="caption">
      <span class="caption-title">Last 10 periods - oldest to newest</span>
      <span class="caption-detail" id="chartDetail">0-3 s scale | press bars for details</span>
    </div>`, {
    width: 0.34,
    position: [0.17, 0.14, 0.085],
    rotationY: -0.04,
  });
  root.add(chartUI.object3D);

  function updateChart() {
    const oldest = (sampleHead - sampleCount + 20) % 10;
    for (let i = 0; i < 10; i++) {
      const bar = bars[i];
      const valid = i < sampleCount;
      bar.visible = valid;
      if (!valid) {
        bar.userData.sampleIndex = -1;
        continue;
      }
      const index = (oldest + i) % 10;
      const sample = history[index];
      const height = Math.max(0.003, chartMaxHeight * sample.period / 3);
      bar.userData.sampleIndex = index;
      bar.scale.set(0.03, height, 0.024);
      bar.position.y = chartBaseline + height / 2;
      bar.material = i === sampleCount - 1 ? latestBarMaterial : barMaterial;
    }
    chartUI.set('chartDetail', {
      text: `0-3 s | ${sampleCount}/10 logged | press bars`,
    });
  }

  for (let i = 0; i < 10; i++) {
    const bar = new THREE.Mesh(unitBox, barMaterial);
    bar.name = `Period bar ${i + 1}`;
    bar.position.set(0.026 + i * 0.032, chartBaseline, -0.02);
    bar.scale.set(0.03, 0.003, 0.024);
    bar.userData.sampleIndex = -1;
    bar.visible = false;
    root.add(bar);
    bars.push(bar);
    traits(bar, {
      onPress: () => {
        const index = bar.userData.sampleIndex;
        if (index < 0) {
          chartUI.set('chartDetail', { text: 'No period logged in this slot yet.' });
          return;
        }
        const sample = history[index];
        chartUI.set('chartDetail', {
          text: `${sample.name}, L ${sample.length.toFixed(2)} m, T ${sample.period.toFixed(2)} s`,
        });
      },
    });
  }

  const panel = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 16px; padding-right: 16px;
              border-radius: 18px; background-color: #1f232a; border-color: #46515e; border-width: 2px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .period { color: #ffd166; font-size: 32px; font-weight: 700; }
      .readout { color: #dce5ee; font-size: 21px; }
      .timer { color: #9fc8e5; font-size: 21px; }
      .hint { color: #b7c2ce; font-size: 20px; }
      .row { display: flex; flex-direction: row; gap: 8px; align-items: center;
             justify-content: space-between; }
      .btn { width: 146px; padding-top: 9px; padding-bottom: 9px; padding-left: 6px; padding-right: 6px;
             border-radius: 11px; background-color: #31506f; border-color: #64809b; border-width: 1px; }
      .warn { background-color: #6f3b42; }
      .btn-text { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Pendulum physics lab</span>
      <span class="period" id="period">Period now: 0.98 s</span>
      <span class="readout" id="settings">Earth | L = 0.24 m | g = 9.81 m/s^2</span>
      <span class="timer" id="timer">Running | swing timer 0.00 s</span>
      <div class="row">
        <button class="btn" id="lenDown"><span class="btn-text">- 2 cm</span></button>
        <button class="btn" id="lenUp"><span class="btn-text">+ 2 cm</span></button>
        <button class="btn" id="logNow"><span class="btn-text">Log now</span></button>
      </div>
      <div class="row">
        <button class="btn" id="gEarth"><span class="btn-text">Earth</span></button>
        <button class="btn" id="gMoon"><span class="btn-text">Moon</span></button>
        <button class="btn" id="gMars"><span class="btn-text">Mars</span></button>
      </div>
      <div class="row">
        <button class="btn" id="pause"><span class="btn-text" id="pauseText">Pause</span></button>
        <button class="btn" id="restart"><span class="btn-text">Restart</span></button>
        <button class="btn warn" id="clear"><span class="btn-text">Clear chart</span></button>
      </div>
      <span class="hint">Ideal small-angle T = 2 pi sqrt(L / g). Full swings and changes add bars.</span>
    </div>`, {
    width: 0.36,
    position: [0.17, 0.337, 0.095],
    rotationY: -0.06,
  });
  root.add(panel.object3D);

  function period() {
    return twoPi * Math.sqrt(length / gravity);
  }

  function updateRunLight() {
    if (running) {
      runMaterial.color.setHex(0x4ade80);
      runMaterial.emissive.setHex(0x16a34a);
      runMaterial.emissiveIntensity = 0.8;
    } else {
      runMaterial.color.setHex(0xf59e0b);
      runMaterial.emissive.setHex(0xb45309);
      runMaterial.emissiveIntensity = 0.5;
    }
  }

  function updateTimer() {
    panel.set('timer', {
      text: `${running ? 'Running' : 'Paused'} | swing timer ${cycleTime.toFixed(2)} s`,
    });
  }

  function refreshPanel() {
    panel.set('period', { text: `Period now: ${period().toFixed(2)} s` });
    panel.set('settings', {
      text: `${gravityName} | L = ${length.toFixed(2)} m | g = ${gravity.toFixed(2)} m/s^2`,
    });
    panel.set('pauseText', { text: running ? 'Pause' : 'Resume' });
    panel.set('lenDown', { backgroundColor: length <= 0.12 ? '#252a31' : '#31506f' });
    panel.set('lenUp', { backgroundColor: length >= 0.30 ? '#252a31' : '#31506f' });
    panel.set('gEarth', { backgroundColor: gravityName === 'Earth' ? '#2f6fdb' : '#343c48' });
    panel.set('gMoon', { backgroundColor: gravityName === 'Moon' ? '#686078' : '#343c48' });
    panel.set('gMars', { backgroundColor: gravityName === 'Mars' ? '#9b4d32' : '#343c48' });
    updateTimer();
  }

  function addSample() {
    const sample = history[sampleHead];
    sample.period = period();
    sample.length = length;
    sample.gravity = gravity;
    sample.name = gravityName;
    sampleHead = (sampleHead + 1) % 10;
    sampleCount = Math.min(10, sampleCount + 1);
    updateChart();
  }

  function restartMotion() {
    phase = 0;
    cycleTime = 0;
  }

  function changeLength(direction) {
    const next = Math.round((length + direction * 0.02) * 100) / 100;
    if (next < 0.12 || next > 0.30) {
      chartUI.set('chartDetail', {
        text: direction < 0 ? 'Minimum string length is 0.12 m.' : 'Maximum string length is 0.30 m.',
      });
      return;
    }
    length = next;
    restartMotion();
    addSample();
    refreshPanel();
  }

  function setGravity(name, value) {
    if (gravityName === name) {
      chartUI.set('chartDetail', { text: `${name} gravity is already selected.` });
      return;
    }
    gravityName = name;
    gravity = value;
    restartMotion();
    addSample();
    refreshPanel();
  }

  function toggleRunning() {
    running = !running;
    updateRunLight();
    refreshPanel();
  }

  panel.on('lenDown', 'click', () => changeLength(-1));
  panel.on('lenUp', 'click', () => changeLength(1));
  panel.on('gEarth', 'click', () => setGravity('Earth', 9.81));
  panel.on('gMoon', 'click', () => setGravity('Moon', 1.62));
  panel.on('gMars', 'click', () => setGravity('Mars', 3.71));
  panel.on('logNow', 'click', addSample);
  panel.on('pause', 'click', toggleRunning);
  panel.on('restart', 'click', () => {
    running = true;
    restartMotion();
    updateRunLight();
    refreshPanel();
  });
  panel.on('clear', 'click', () => {
    sampleCount = 0;
    sampleHead = 0;
    updateChart();
    chartUI.set('chartDetail', { text: 'History cleared. The next full swing will log.' });
  });
  traits(runButton, { onPress: toggleRunning });

  function updatePendulum() {
    const angle = amplitude * Math.cos(phase);
    const sin = Math.sin(angle);
    const cos = Math.cos(angle);
    bob.position.set(
      pivotX + length * sin,
      pivotY - length * cos,
      pendulumZ,
    );
    string.position.set(
      pivotX + 0.5 * length * sin,
      pivotY - 0.5 * length * cos,
      pendulumZ,
    );
    string.scale.set(1, length, 1);
    string.rotation.z = angle;
  }

  addSample();
  refreshPanel();
  updatePendulum();

  return {
    root,
    update(time, delta) {
      const dt = Math.min(Math.max(delta, 0), 0.1);
      const currentPeriod = period();

      if (running) {
        cycleTime += dt;
        phase += twoPi * dt / currentPeriod;
        if (cycleTime >= currentPeriod) {
          cycleTime -= currentPeriod;
          if (cycleTime >= currentPeriod) cycleTime %= currentPeriod;
          addSample();
        }
        if (phase >= twoPi) phase %= twoPi;
      }

      updatePendulum();

      uiClock += dt;
      if (uiClock >= 0.1) {
        uiClock = 0;
        updateTimer();
      }
    },
  };
}

