        <button class="add add-one" id="add0"><span class="add-text">+ Day 1</span></button>
        <button class="add add-two" id="add1"><span class="add-text">+ Day 2</span></button>
        <button class="add add-three" id="add2"><span class="add-text">+ Day 3</span></button>
      </div>
      <span class="status" id="status">Tap a map pin, then add it to a day.</span>
      <span class="note">Walk totals are approximate, between stops only.</span>
    </div>`, {
    width: 0.22,
    position: [-0.282, 0.35, -0.12],
    rotationY: 0.29,
  });
  root.add(details.object3D);

  function makeDayPanel(day) {
    let rows = '';
    for (let slot = 0; slot < 6; slot++) {
      rows += `
        <div class="stop" id="d${day}s${slot}">
          <span class="stop-name" id="d${day}n${slot}">Stop</span>
          <div class="controls">
            <button class="mini" id="d${day}u${slot}"><span class="mini-text">Up</span></button>
            <button class="mini" id="d${day}v${slot}"><span class="mini-text">Down</span></button>
            <button class="remove" id="d${day}r${slot}"><span class="mini-text">Remove</span></button>
          </div>
        </div>`;
    }

    const panel = ui(`
      <style>
        .day { width: 300px; height: 620px; flex-direction: column; gap: 8px; padding-top: 12px;
               padding-bottom: 12px; padding-left: 10px; padding-right: 10px; border-radius: 16px;
               background-color: #20242b; border-width: 2px; border-color: ${dayColors[day].css}; }
        .day-title { color: ${dayColors[day].css}; font-size: 30px; font-weight: 700; text-align: center; }
        .count { color: #d8dde4; font-size: 22px; text-align: center; }
        .walk { color: #ffffff; font-size: 24px; font-weight: 700; text-align: center; }
        .stop { flex-direction: column; gap: 4px; padding-top: 4px; padding-bottom: 4px;
                padding-left: 6px; padding-right: 6px; border-radius: 10px; background-color: #2b313a; }
        .stop-name { color: #f2f4f7; font-size: 22px; font-weight: 700; }
        .controls { flex-direction: row; gap: 6px; }
        .mini { padding-top: 4px; padding-bottom: 4px; padding-left: 8px; padding-right: 8px;
                border-radius: 8px; border-width: 0px; background-color: #435264; }
        .remove { padding-top: 4px; padding-bottom: 4px; padding-left: 8px; padding-right: 8px;
                  border-radius: 8px; border-width: 0px; background-color: #78434d; }
        .mini-text { color: #ffffff; font-size: 22px; font-weight: 700; }
      </style>
      <div class="day">
        <span class="day-title">Day ${day + 1}</span>
        <span class="count" id="count${day}">No stops yet</span>
        <span class="walk" id="walk${day}">Walk: 0 min</span>
        ${rows}
      </div>`, {
      width: 0.168,
      position: [
        [-0.068, 0.12, 0.308][day],
        0.30,
        -0.12,
      ],
      rotationY: [0.05, -0.12, -0.29][day],
    });

    root.add(panel.object3D);
    dayPanels[day] = panel;

    for (let slot = 0; slot < 6; slot++) {
      panel.on(`d${day}u${slot}`, 'click', () => moveStop(day, slot, -1));
      panel.on(`d${day}v${slot}`, 'click', () => moveStop(day, slot, 1));
      panel.on(`d${day}r${slot}`, 'click', () => removeStop(day, slot));
    }
  }

  makeDayPanel(0);
  makeDayPanel(1);
  makeDayPanel(2);

  function formatWalk(minutes) {
    if (minutes < 60) return minutes + ' min';
    const hours = Math.floor(minutes / 60);
    const remainder = minutes % 60;
    return hours + ' h ' + remainder + ' min';
  }

  function totalWalk(order) {
    let total = 0;
    for (let i = 1; i < order.length; i++) {
      total += walkTimes[order[i - 1]][order[i]];
    }
    return total;
  }

  function assignedDay(index) {
    for (let day = 0; day < 3; day++) {
      if (days[day].indexOf(index) !== -1) return day;
    }
    return -1;
  }

  function refreshPins() {
    for (let i = 0; i < pins.length; i++) {
      const pin = pins[i];
      const day = assignedDay(i);
      const color = day >= 0 ? dayColors[day].hex : 0x66717d;
      pin.userData.ringMaterial.color.setHex(color);
      pin.userData.ringMaterial.emissive.setHex(color);
      pin.userData.ringMaterial.emissiveIntensity = i === selected ? 0.8 : 0.18;
      pin.userData.headMaterial.emissiveIntensity = i === selected ? 0.58 : 0.12;
      pin.userData.ring.scale.set(1, 1, 1);
    }
  }

  function renderDay(day) {
    const panel = dayPanels[day];
    const order = days[day];
    const count = order.length;

    panel.set(`count${day}`, {
      text: count === 0 ? 'No stops yet' : count + (count === 1 ? ' stop' : ' stops'),
    });
    panel.set(`walk${day}`, { text: 'Walk: ' + formatWalk(totalWalk(order)) });

    for (let slot = 0; slot < 6; slot++) {
      if (slot < count) {
        panel.set(`d${day}s${slot}`, { display: 'flex' });
        panel.set(`d${day}n${slot}`, { text: landmarks[order[slot]].name });
        panel.set(`d${day}u${slot}`, {
          backgroundColor: slot === 0 ? '#303640' : '#435d79',
        });
        panel.set(`d${day}v${slot}`, {
          backgroundColor: slot === count - 1 ? '#303640' : '#435d79',
        });
      } else {
        panel.set(`d${day}s${slot}`, { display: 'none' });
      }
    }
  }

  function setDefaultStatus() {
    const day = assignedDay(selected);
    if (day >= 0) {
      details.set('status', {
        text: landmarks[selected].name + ' is in Day ' + (day + 1) + '. Use another day button to move it.',
      });
    } else {
      details.set('status', {
        text: 'Selected ' + landmarks[selected].name + '. Add it to a day.',
      });
    }
  }

  function selectLandmark(index) {
    selected = index;
    const landmark = landmarks[index];
    details.set('place', { text: landmark.name });
    details.set('description', { text: landmark.description });
    details.set('meta', { text: landmark.meta });
    setDefaultStatus();
    refreshPins();
  }

  function addSelected(targetDay) {
    const landmarkIndex = selected;
    const previousDay = assignedDay(landmarkIndex);

    if (previousDay === targetDay) {
      details.set('status', {
        text: landmarks[landmarkIndex].name + ' is already in Day ' + (targetDay + 1) + '.',
      });
      return;
    }

    if (previousDay >= 0) {
      days[previousDay].splice(days[previousDay].indexOf(landmarkIndex), 1);
    }
    days[targetDay].push(landmarkIndex);

    if (previousDay >= 0) renderDay(previousDay);
    renderDay(targetDay);
    refreshPins();

    details.set('status', {
      text: previousDay >= 0
        ? 'Moved ' + landmarks[landmarkIndex].name + ' from Day ' + (previousDay + 1) + ' to Day ' + (targetDay + 1) + '.'
        : 'Added ' + landmarks[landmarkIndex].name + ' to Day ' + (targetDay + 1) + '.',
    });
  }

  function moveStop(day, slot, direction) {
    const order = days[day];
    const destination = slot + direction;
    if (slot < 0 || slot >= order.length || destination < 0 || destination >= order.length) return;

    const moved = order[slot];
    order[slot] = order[destination];
    order[destination] = moved;
    renderDay(day);

    details.set('status', {
      text: landmarks[moved].name + ' moved ' + (direction < 0 ? 'up' : 'down') + ' in Day ' + (day + 1) + '. Walk total updated.',
    });
  }

  function removeStop(day, slot) {
    if (slot < 0 || slot >= days[day].length) return;
    const removed = days[day].splice(slot, 1)[0];
    renderDay(day);
    refreshPins();
    details.set('status', {
      text: landmarks[removed].name + ' removed from Day ' + (day + 1) + '. It remains on the map.',
    });
  }

  details.on('add0', 'click', () => addSelected(0));
  details.on('add1', 'click', () => addSelected(1));
  details.on('add2', 'click', () => addSelected(2));

  renderDay(0);
  renderDay(1);
  renderDay(2);
  selectLandmark(0);

  return {
    root,
    update(time) {
      const ring = pins[selected].userData.ring;
      const scale = 1 + 0.12 * Math.sin(time * 3.2);
      ring.scale.set(scale, scale, scale);
    },
  };
}

