      id: 'student',
      name: 'Student',
      price: '$149',
      color: 0x397f78,
      emissive: 0x123c38,
    },
  ];

  const workshops = [
    { id: 'hands', name: 'Hand tracking essentials' },
    { id: 'spatial', name: 'Natural spatial interfaces' },
    { id: 'passthrough', name: 'Passthrough prototyping' },
    { id: 'performance', name: 'Headset performance lab' },
  ];

  const sizes = ['XS', 'S', 'M', 'L', 'XL', '2XL'];
  const screenIds = ['ticketScreen', 'workshopScreen', 'shirtScreen', 'reviewScreen', 'confirmedScreen'];

  let selectedTicket = null;
  const selectedWorkshops = new Set();
  let sizeIndex = 2;
  let editingFromReview = false;

  function setProgress(active, complete) {
    for (let i = 1; i <= 3; i += 1) {
      let color = '#343b46';
      if (i <= active) color = complete ? '#58bd87' : '#4b8ee8';
      panel.set('progress' + i, { backgroundColor: color });
    }
  }

  function hideScreens() {
    screenIds.forEach((id) => panel.set(id, { display: 'none' }));
  }

  function updateBadge() {
    if (selectedTicket) {
      ticketMaterial.color.setHex(selectedTicket.color);
      ticketMaterial.emissive.setHex(selectedTicket.emissive);
      lampMaterial.color.setHex(0x9dc2ff);
      lampMaterial.emissive.setHex(0x3976c8);
    } else {
      ticketMaterial.color.setHex(0x7b8794);
      ticketMaterial.emissive.setHex(0x27303a);
      lampMaterial.color.setHex(0xb5c0cc);
      lampMaterial.emissive.setHex(0x52606e);
    }
  }

  function paintTickets() {
    tickets.forEach((ticket) => {
      const selected = selectedTicket && selectedTicket.id === ticket.id;
      panel.set('ticket_' + ticket.id, {
        backgroundColor: selected ? '#204564' : '#252a32',
      });
      panel.set('mark_' + ticket.id, {
        text: selected ? '[x]' : '[ ]',
        color: selected ? '#ffffff' : '#9dc2ff',
      });
    });
  }

  function selectTicket(ticket) {
    selectedTicket = ticket;
    paintTickets();
    updateBadge();
    panel.set('ticketStatus', {
      text: 'Selected: ' + ticket.name + ' - ' + ticket.price,
      color: '#9dc2ff',
    });
  }

  function paintWorkshops() {
    workshops.forEach((workshop) => {
      const selected = selectedWorkshops.has(workshop.id);
      panel.set('ws_' + workshop.id, {
        backgroundColor: selected ? '#235044' : '#252a32',
      });
      panel.set('mark_' + workshop.id, {
        text: selected ? '[x]' : '[ ]',
        color: selected ? '#ffffff' : '#9dc2ff',
      });
    });
  }

  function showWorkshopCount() {
    const count = selectedWorkshops.size;
    let text = count + ' of 2 selected. ';
    if (count === 0) text += 'You may continue with none.';
    else if (count === 1) text += 'Choose one more or continue.';
    else text += 'Selection limit reached.';
    panel.set('workshopStatus', { text, color: '#b9c4d0' });
  }

  function toggleWorkshop(workshop) {
    if (selectedWorkshops.has(workshop.id)) {
      selectedWorkshops.delete(workshop.id);
      paintWorkshops();
      showWorkshopCount();
      return;
    }

    if (selectedWorkshops.size >= 2) {
      panel.set('workshopStatus', {
        text: 'Too many: choose up to 2 workshops. Remove one before adding another.',
        color: '#ff9b8f',
      });
      return;
    }

    selectedWorkshops.add(workshop.id);
    paintWorkshops();
    showWorkshopCount();
  }

  function paintSize(message) {
    panel.set('sizeValue', { text: sizes[sizeIndex] });
    panel.set('sizeCount', { text: 'Size ' + (sizeIndex + 1) + ' of 6' });
    panel.set('sizeStatus', {
      text: message || 'Unisex fit. Use - or + to change size.',
      color: '#b9c4d0',
    });
    const modelScale = 0.78 + sizeIndex * 0.088;
    shirt.scale.setScalar(modelScale);
  }

  function selectedWorkshopNames() {
    const chosen = workshops.filter((workshop) => selectedWorkshops.has(workshop.id));
    if (chosen.length === 0) return 'No workshops selected';
    return chosen.map((workshop) => workshop.name).join('; ');
  }

  function showStep(step, fromReview) {
    editingFromReview = fromReview === true;
    hideScreens();

    if (step === 'ticket') {
      panel.set('ticketScreen', { display: 'flex' });
      panel.set('stepLabel', { text: 'STEP 1 OF 3' });
      panel.set('heading', { text: 'Choose a ticket' });
      panel.set('subtitle', { text: 'Select one ticket. No keyboard needed.' });
      panel.set('ticketNextText', { text: editingFromReview ? 'Save and review' : 'Continue' });
      panel.set('ticketBack', { display: editingFromReview ? 'flex' : 'none' });
      setProgress(1, false);
    } else if (step === 'workshops') {
      panel.set('workshopScreen', { display: 'flex' });
      panel.set('stepLabel', { text: 'STEP 2 OF 3' });
      panel.set('heading', { text: 'Pick your workshops' });
      panel.set('subtitle', { text: 'Choose up to two. Tap a selected workshop to remove it.' });
      panel.set('workshopNextText', { text: editingFromReview ? 'Save and review' : 'Continue' });
      panel.set('workshopBackText', { text: editingFromReview ? 'Back to review' : 'Back' });
      showWorkshopCount();
      setProgress(2, false);
    } else {
      panel.set('shirtScreen', { display: 'flex' });
      panel.set('stepLabel', { text: 'STEP 3 OF 3' });
      panel.set('heading', { text: 'Choose a T-shirt size' });
      panel.set('subtitle', { text: 'Use the stepper to select your unisex T-shirt size.' });
      panel.set('shirtNextText', { text: editingFromReview ? 'Save and review' : 'Review registration' });
      panel.set('shirtBackText', { text: editingFromReview ? 'Back to review' : 'Back' });
      paintSize();
      setProgress(3, false);
    }
  }

  function showReview() {
    editingFromReview = false;
    hideScreens();
    panel.set('reviewScreen', { display: 'flex' });
    panel.set('stepLabel', { text: 'REVIEW' });
    panel.set('heading', { text: 'Review your registration' });
    panel.set('subtitle', { text: 'Check each item. Use Edit to make a change.' });
    panel.set('reviewTicket', {
      text: selectedTicket.name + ' - ' + selectedTicket.price,
    });
    panel.set('reviewWorkshops', { text: selectedWorkshopNames() });
    panel.set('reviewShirt', { text: sizes[sizeIndex] + ' - Unisex fit' });
    setProgress(3, false);
  }

  function showConfirmation() {
    hideScreens();
    panel.set('confirmedScreen', { display: 'flex' });
    panel.set('stepLabel', { text: 'COMPLETE' });
    panel.set('heading', { text: 'Registration confirmed' });
    panel.set('subtitle', { text: 'Show this screen at the welcome desk.' });
    panel.set('confirmedTicket', {
      text: selectedTicket.name + ' ticket - ' + selectedTicket.price,
    });
    panel.set('confirmedWorkshops', { text: selectedWorkshopNames() });
    panel.set('confirmedShirt', { text: 'T-shirt: ' + sizes[sizeIndex] });
    ticketMaterial.color.setHex(0x39956a);
    ticketMaterial.emissive.setHex(0x145438);
    lampMaterial.color.setHex(0x76dca1);
    lampMaterial.emissive.setHex(0x38bd76);
    setProgress(3, true);
  }

  tickets.forEach((ticket) => {
    panel.on('ticket_' + ticket.id, 'click', () => selectTicket(ticket));
  });

  workshops.forEach((workshop) => {
    panel.on('ws_' + workshop.id, 'click', () => toggleWorkshop(workshop));
  });

  panel.on('ticketNext', 'click', () => {
    if (!selectedTicket) {
      panel.set('ticketStatus', {
        text: 'Choose one ticket before continuing.',
        color: '#ff9b8f',
      });
      return;
    }
    if (editingFromReview) showReview();
    else showStep('workshops', false);
  });

  panel.on('ticketBack', 'click', showReview);

  panel.on('workshopNext', 'click', () => {
    if (editingFromReview) showReview();
    else showStep('shirt', false);
  });

  panel.on('workshopBack', 'click', () => {
    if (editingFromReview) showReview();
    else showStep('ticket', false);
  });

  panel.on('sizeDown', 'click', () => {
    if (sizeIndex === 0) {
      paintSize('XS is the smallest available size.');
      return;
    }
    sizeIndex -= 1;
    paintSize('Unisex fit. ' + sizes[sizeIndex] + ' selected.');
  });

  panel.on('sizeUp', 'click', () => {
    if (sizeIndex === sizes.length - 1) {
      paintSize('2XL is the largest available size.');
      return;
    }
    sizeIndex += 1;
    paintSize('Unisex fit. ' + sizes[sizeIndex] + ' selected.');
  });

  panel.on('shirtNext', 'click', showReview);

  panel.on('shirtBack', 'click', () => {
    if (editingFromReview) showReview();
    else showStep('workshops', false);
  });

  panel.on('editTicket', 'click', () => showStep('ticket', true));
  panel.on('editWorkshops', 'click', () => showStep('workshops', true));
  panel.on('editShirt', 'click', () => showStep('shirt', true));
  panel.on('confirmButton', 'click', showConfirmation);

  panel.on('startOver', 'click', () => {
    selectedTicket = null;
    selectedWorkshops.clear();
    sizeIndex = 2;
    paintTickets();
    paintWorkshops();
    paintSize();
    updateBadge();
    panel.set('ticketStatus', {
      text: 'Choose one ticket to continue.',
      color: '#b9c4d0',
    });
    showStep('ticket', false);
  });

  paintTickets();
  paintWorkshops();
  paintSize();
  updateBadge();
  showStep('ticket', false);

  return {
    root,
    update(time) {
      if (!isGrabbed(badge)) {
        badge.position.y = 0.18 + Math.sin(time * 1.15) * 0.004;
        badge.rotation.y = 0.06 + Math.sin(time * 0.7) * 0.05;
      }
      if (!isGrabbed(shirt)) {
        shirt.position.y = 0.18 + Math.sin(time * 1.15 + 1.4) * 0.004;
        shirt.rotation.y = -0.06 + Math.sin(time * 0.7 + 1.4) * 0.05;
      }
    },
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();

  const months = ['Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb'];
  const categories = [
    { name: 'Housing', color: 0x5b8def, values: [1200, 1200, 1250, 1250, 1250, 1250] },
    { name: 'Food', color: 0x43c59e, values: [460, 505, 480, 560, 510, 520] },
    { name: 'Transport', color: 0xf0a34a, values: [210, 260, 225, 245, 230, 240] },
    { name: 'Leisure', color: 0xb084e8, values: [145, 200, 165, 260, 150, 180] },
    { name: 'Other', color: 0x8b98ad, values: [180, 220, 195, 235, 190, 210] },
  ];
  const totals = [2195, 2385, 2315, 2550, 2330, 2400];

  function money(value) {
    const s = String(Math.round(value));
    return '$' + (s.length > 3 ? s.slice(0, -3) + ',' + s.slice(-3) : s);
  }

  const backing = new THREE.Mesh(
    new THREE.BoxGeometry(0.382, 0.368, 0.018),
    new THREE.MeshStandardMaterial({ color: 0x151a22, roughness: 0.92 }),
  );
  backing.name = 'Dashboard backing';
  backing.position.set(0.185, 0.245, -0.026);
  root.add(backing);

  // February spending donut. Each slice is directly pressable.
  const donutX = 0.073;
  const donutY = 0.35;
  const slices = [];
  let angle = Math.PI / 2;
  const gap = 0.035;

  categories.forEach((category, index) => {
    category.material = new THREE.MeshStandardMaterial({
      color: category.color,
      emissive: category.color,
      emissiveIntensity: 0.06,
      roughness: 0.48,
      metalness: 0.05,
    });

    const span = (category.values[5] / totals[5]) * Math.PI * 2;
    const start = angle + gap / 2;
    const end = angle + span - gap / 2;
    const middle = (start + end) / 2;
    const shape = new THREE.Shape();
    shape.absarc(0, 0, 0.074, start, end, false);
    shape.absarc(0, 0, 0.041, end, start, true);
    shape.closePath();

    const slice = new THREE.Mesh(
      new THREE.ExtrudeGeometry(shape, {
        depth: 0.02,
        bevelEnabled: false,
        curveSegments: 24,
      }),
      category.material,
    );
    slice.name = category.name + ' spending';
    slice.position.set(donutX, donutY, 0);
    slice.userData.dx = Math.cos(middle);
    slice.userData.dy = Math.sin(middle);
    slice.userData.lift = 0;
    slice.userData.categoryIndex = index;
    root.add(slice);
    slices.push(slice);
    angle += span;
  });

  // Six animated bars with quiet grid lines behind them.
  const bars = [];
  const currentHeights = new Float32Array(6);
  const targetHeights = new Float32Array(6);
  const barBase = 0.074;
  const barMaxHeight = 0.16;
  const unitBox = new THREE.BoxGeometry(1, 1, 1);
  const allBarsMaterial = new THREE.MeshStandardMaterial({
    color: 0x78a6ff,
    emissive: 0x315a9d,
    emissiveIntensity: 0.08,
    roughness: 0.5,
  });

  const gridMaterial = new THREE.MeshBasicMaterial({ color: 0x303947 });
  const gridGeometry = new THREE.BoxGeometry(0.336, 0.0015, 0.002);
  for (let i = 1; i <= 4; i++) {
    const line = new THREE.Mesh(gridGeometry, gridMaterial);
    line.position.set(0.178, barBase + (barMaxHeight * i) / 4, -0.011);
    root.add(line);
  }

  for (let i = 0; i < 6; i++) {
    const bar = new THREE.Mesh(unitBox, allBarsMaterial);
    bar.name = months[i] + ' spending bar';
    bar.position.set(0.033 + i * 0.058, barBase + 0.0005, 0.008);
    bar.scale.set(0.041, 0.001, 0.024);
    root.add(bar);
    bars.push(bar);
  }

  const baseline = new THREE.Mesh(
    new THREE.BoxGeometry(0.346, 0.004, 0.014),
    new THREE.MeshStandardMaterial({ color: 0x596579, roughness: 0.7 }),
  );
  baseline.position.set(0.178, barBase - 0.003, -0.003);
  root.add(baseline);

  const separator = new THREE.Mesh(
    new THREE.BoxGeometry(0.344, 0.002, 0.003),
    new THREE.MeshBasicMaterial({ color: 0x354052 }),
  );
  separator.position.set(0.178, 0.255, -0.008);
  root.add(separator);

  // Savings goal ring, starting at $3,600 of $6,000.
  const goal = 6000;
  const depositAmount = 200;
  let saved = 3600;
  let pulse = 0;
  const ringX = 0.286;
  const ringY = 0.35;
  const ringRadius = 0.058;

  const ringTrack = new THREE.Mesh(
    new THREE.TorusGeometry(ringRadius, 0.0075, 10, 64),
    new THREE.MeshStandardMaterial({ color: 0x34404c, roughness: 0.72 }),
  );
  ringTrack.name = 'Savings goal track';
  ringTrack.position.set(ringX, ringY, 0.008);
  root.add(ringTrack);

  const ringMaterial = new THREE.MeshStandardMaterial({
    color: 0x58d68d,
    emissive: 0x238a55,
    emissiveIntensity: 0.22,
    roughness: 0.42,
  });
  const progressRing = new THREE.Mesh(
    new THREE.TorusGeometry(ringRadius, 0.0085, 10, 40, Math.PI * 2 * (saved / goal)),
    ringMaterial,
  );
  progressRing.name = 'Savings goal progress';
  progressRing.position.set(ringX, ringY, 0.009);
  progressRing.rotation.z = Math.PI / 2;
  root.add(progressRing);

  const coin = new THREE.Mesh(
    new THREE.CylinderGeometry(0.024, 0.024, 0.007, 28),
    new THREE.MeshStandardMaterial({
      color: 0xf2c14e,
      emissive: 0x6f4e0d,
      emissiveIntensity: 0.12,
      metalness: 0.35,
      roughness: 0.4,
    }),
  );
  coin.name = 'Savings coin';
  coin.rotation.x = Math.PI / 2;
  coin.position.set(ringX, ringY, 0.005);
  root.add(coin);

  const chartLabels = ui(`
    <style>
      .labels { width: 400px; display: flex; flex-direction: column; padding-top: 10px;
                padding-bottom: 10px; padding-left: 16px; padding-right: 16px;
                background-color: #1a1d22; border-radius: 14px; }
      .row { width: 368px; display: flex; flex-direction: row; gap: 8px; }
      .label { width: 180px; color: #e5e9f0; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="labels">
      <div class="row">
        <span class="label">Spending: Feb</span>
        <span class="label">Savings goal</span>
      </div>
    </div>`, { width: 0.37, position: [0.185, 0.475, 0.02] });
  root.add(chartLabels.object3D);

  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 8px;
              padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px;
              background-color: #1f232b; border-radius: 18px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .help { color: #c4cbd6; font-size: 22px; }
      .selection { color: #ffffff; font-size: 26px; font-weight: 700; }
      .detail { color: #9fc2ff; font-size: 22px; font-weight: 700; }
      .month-row { width: 464px; display: flex; flex-direction: row; justify-content: space-between; }
      .month { width: 150px; color: #d7dce5; font-size: 20px; }
      .note { color: #aeb7c5; font-size: 20px; }
      .filter-row { width: 464px; display: flex; flex-direction: row; gap: 8px; }
      .filter { display: flex; justify-content: center; padding-top: 9px; padding-bottom: 9px;
                padding-left: 13px; padding-right: 13px; border-radius: 11px; }
      .all { background-color: #3a4658; }
      .housing { background-color: #3e64b5; }
      .food { background-color: #23775f; }
      .transport { background-color: #92561e; }
      .leisure { background-color: #694b96; }
      .other { background-color: #4d596b; }
      .button-text { color: #ffffff; font-size: 20px; font-weight: 700; }
      .savings { color: #83e5ae; font-size: 22px; font-weight: 700; }
      .deposit { width: 464px; display: flex; justify-content: center; padding-top: 10px;
                 padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
                 border-radius: 12px; background-color: #287a58; }
      .deposit-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Personal budget</span>
      <span class="help">Sample USD data. Tap a donut slice or category to filter the Sep-Feb bars.</span>
      <span class="selection" id="selection">All categories</span>
      <span class="detail" id="detail">February total: $2,400</span>
      <div class="month-row">
        <span class="month" id="m0">Sep $2,195</span>
        <span class="month" id="m1">Oct $2,385</span>
        <span class="month" id="m2">Nov $2,315</span>
      </div>
      <div class="month-row">
        <span class="month" id="m3">Dec $2,550</span>
        <span class="month" id="m4">Jan $2,330</span>
        <span class="month" id="m5">Feb $2,400</span>
      </div>
      <span class="note">Bar heights auto-scale to this view.</span>
      <div class="filter-row">
        <button class="filter all" id="filter-all"><span class="button-text" id="all-label">&gt; All</span></button>
        <button class="filter housing" id="cat0"><span class="button-text" id="cat-label0">Housing</span></button>
        <button class="filter food" id="cat1"><span class="button-text" id="cat-label1">Food</span></button>
      </div>
      <div class="filter-row">
        <button class="filter transport" id="cat2"><span class="button-text" id="cat-label2">Transport</span></button>
        <button class="filter leisure" id="cat3"><span class="button-text" id="cat-label3">Leisure</span></button>
        <button class="filter other" id="cat4"><span class="button-text" id="cat-label4">Other</span></button>
      </div>
      <span class="savings" id="savings-text">Emergency fund: $3,600 of $6,000 (60%)</span>
      <button class="deposit" id="deposit"><span class="deposit-text" id="deposit-label">Log $200 deposit</span></button>
    </div>`, { width: 0.36, position: [-0.21, 0.25, 0.025] });
  root.add(info.object3D);

  let selectedIndex = -1;

  function selectCategory(index) {
    selectedIndex = index;
    const values = index < 0 ? totals : categories[index].values;
    const label = index < 0 ? 'All categories' : categories[index].name;

    info.set('selection', { text: label });
    info.set('detail', { text: 'February total: ' + money(values[5]) });
    info.set('all-label', { text: index < 0 ? '> All' : 'All' });

    let peak = 0;
    for (let i = 0; i < 6; i++) {
      peak = Math.max(peak, values[i]);
      info.set('m' + i, { text: months[i] + ' ' + money(values[i]) });
    }

    for (let i = 0; i < 6; i++) {
      targetHeights[i] = Math.max(0.015, (values[i] / peak) * barMaxHeight);
      bars[i].material = index < 0 ? allBarsMaterial : categories[index].material;
    }

    categories.forEach((category, i) => {
      info.set('cat-label' + i, { text: i === index ? '> ' + category.name : category.name });
    });
  }

  slices.forEach((slice, index) => {
    traits(slice, { onPress: () => selectCategory(index) });
  });

  info.on('filter-all', 'click', () => selectCategory(-1));
  categories.forEach((category, index) => {
    info.on('cat' + index, 'click', () => selectCategory(index));
  });

  function updateSavings() {
    const fraction = Math.min(1, saved / goal);
    const percent = Math.round(fraction * 100);
    info.set('savings-text', {
      text: 'Emergency fund: ' + money(saved) + ' of ' + money(goal) + ' (' + percent + '%)',
    });

    const oldGeometry = progressRing.geometry;
    progressRing.geometry = new THREE.TorusGeometry(
      ringRadius,
      0.0085,
      10,
      Math.max(8, Math.ceil(64 * fraction)),
      Math.PI * 2 * fraction,
    );
    oldGeometry.dispose();

    if (saved >= goal) {
      info.set('deposit-label', { text: 'Goal reached' });
      info.set('deposit', { backgroundColor: '#285b47' });
    } else {
      info.set('deposit-label', { text: 'Log $200 deposit' });
    }
  }

  info.on('deposit', 'click', () => {
    if (saved >= goal) return;
    saved = Math.min(goal, saved + depositAmount);
    pulse = 1;
    updateSavings();
  });

  selectCategory(-1);

  return {
    root,
    update(time, delta) {
      const smoothing = 1 - Math.exp(-delta * 10);

      for (let i = 0; i < bars.length; i++) {
        currentHeights[i] += (targetHeights[i] - currentHeights[i]) * smoothing;
        const height = Math.max(0.001, currentHeights[i]);
        bars[i].scale.y = height;
        bars[i].position.y = barBase + height / 2;
      }

      for (let i = 0; i < slices.length; i++) {
        const slice = slices[i];
        const targetLift = i === selectedIndex ? 0.006 : 0;
        slice.userData.lift += (targetLift - slice.userData.lift) * smoothing;
        const lift = slice.userData.lift;
        slice.position.x = donutX + slice.userData.dx * lift;
        slice.position.y = donutY + slice.userData.dy * lift;
        slice.position.z = lift * 1.4;
      }

      if (pulse > 0) {
        pulse = Math.max(0, pulse - delta * 2.8);
        const scale = 1 + Math.sin((1 - pulse) * Math.PI) * 0.06;
        progressRing.scale.setScalar(scale);
      } else {
        progressRing.scale.setScalar(1);
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const brass = new THREE.MeshStandardMaterial({
    color: 0xb88a3b,
    metalness: 0.72,
    roughness: 0.32,
  });
  const darkBrass = new THREE.MeshStandardMaterial({
    color: 0x735126,
    metalness: 0.65,
    roughness: 0.4,
  });
  const wood = new THREE.MeshStandardMaterial({
    color: 0x39251f,
    roughness: 0.72,
  });
  const black = new THREE.MeshStandardMaterial({
    color: 0x11161b,
    metalness: 0.25,
    roughness: 0.55,
  });

  // The box and its hinged lid.
  const boxBody = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.12, 0.18), wood);
  boxBody.position.set(-0.09, 0.066, -0.04);
  boxBody.name = 'Locked box';
  root.add(boxBody);

  const innerWell = new THREE.Mesh(
    new THREE.BoxGeometry(0.228, 0.012, 0.148),
    new THREE.MeshStandardMaterial({ color: 0x130e12, roughness: 0.9 }),
  );
  innerWell.position.set(-0.09, 0.127, -0.04);
  root.add(innerWell);

  const rimLong = new THREE.BoxGeometry(0.266, 0.012, 0.009);
  const rimShort = new THREE.BoxGeometry(0.009, 0.012, 0.172);
  [-0.128, 0.048].forEach((z) => {
    const rim = new THREE.Mesh(rimLong, brass);
    rim.position.set(-0.09, 0.13, z);
    root.add(rim);
  });
  [-0.218, 0.038].forEach((x) => {
    const rim = new THREE.Mesh(rimShort, brass);
    rim.position.set(x, 0.13, -0.04);
    root.add(rim);
  });

  const lid = new THREE.Group();
  lid.position.set(-0.09, 0.137, -0.13);
  lid.name = 'Opening lid';
  root.add(lid);

  const lidPanel = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.024, 0.192), wood);
  lidPanel.position.set(0, 0.006, 0.096);
  lid.add(lidPanel);

  const lidInset = new THREE.Mesh(new THREE.BoxGeometry(0.228, 0.008, 0.15), darkBrass);
  lidInset.position.set(0, 0.021, 0.096);
  lid.add(lidInset);

  const latchMaterial = new THREE.MeshStandardMaterial({
    color: 0xc99c4b,
    metalness: 0.75,
    roughness: 0.28,
    emissive: 0x000000,
    emissiveIntensity: 0,
  });
  const latch = new THREE.Mesh(new THREE.BoxGeometry(0.034, 0.038, 0.009), latchMaterial);
  latch.position.set(0, -0.003, 0.187);
  lid.add(latch);

  // A reward revealed by the opening animation.
  const gem = new THREE.Mesh(
    new THREE.IcosahedronGeometry(0.026, 1),
    new THREE.MeshStandardMaterial({
      color: 0x58e6ef,
      emissive: 0x16aabc,
      emissiveIntensity: 1.2,
      metalness: 0.15,
      roughness: 0.2,
    }),
  );
  gem.position.set(-0.09, 0.104, -0.035);
  gem.visible = false;
  gem.name = 'Jewel inside the box';
  root.add(gem);

  const glowRing = new THREE.Mesh(
    new THREE.TorusGeometry(0.038, 0.0025, 8, 32),
    new THREE.MeshStandardMaterial({
      color: 0x9df9ff,
      emissive: 0x3ac9e8,
      emissiveIntensity: 1.1,
      roughness: 0.35,
    }),
  );
  glowRing.rotation.x = Math.PI / 2;
  glowRing.position.set(-0.09, 0.132, -0.035);
  glowRing.visible = false;
  root.add(glowRing);

  // Tiny pixel-font textures make four genuinely three-dimensional digit readouts.
  const digitRows = [
    ['01110', '10001', '10011', '10101', '11001', '10001', '01110'],
    ['00100', '01100', '00100', '00100', '00100', '00100', '01110'],
    ['01110', '10001', '00001', '00010', '00100', '01000', '11111'],
    ['11110', '00001', '00001', '01110', '00001', '00001', '11110'],
    ['00010', '00110', '01010', '10010', '11111', '00010', '00010'],
    ['11111', '10000', '10000', '11110', '00001', '00001', '11110'],
    ['01110', '10000', '10000', '11110', '10001', '10001', '01110'],
    ['11111', '00001', '00010', '00100', '01000', '01000', '01000'],
    ['01110', '10001', '10001', '01110', '10001', '10001', '01110'],
    ['01110', '10001', '10001', '01111', '00001', '00001', '01110'],
  ];

  function makeDigitTexture(rows) {
    const data = new Uint8Array(5 * 7 * 4);
    for (let y = 0; y < 7; y++) {
      const row = rows[6 - y];
      for (let x = 0; x < 5; x++) {
        const offset = (y * 5 + x) * 4;
        const lit = row[x] === '1';
        data[offset] = lit ? 255 : 7;
        data[offset + 1] = lit ? 255 : 13;
        data[offset + 2] = lit ? 255 : 16;
        data[offset + 3] = 255;
      }
    }
    const texture = new THREE.DataTexture(data, 5, 7, THREE.RGBAFormat);
    texture.magFilter = THREE.NearestFilter;
    texture.minFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.needsUpdate = true;
    return texture;
  }

  const digitTextures = digitRows.map(makeDigitTexture);
  const values = [0, 0, 0, 0];
  const solution = [7, 1, 4, 2];
  const digitMaterials = [];
  let unlocked = false;
  let unlockClock = 0;
  let openProgress = 0;
  let hintCount = 0;

  const lockCase = new THREE.Mesh(new THREE.BoxGeometry(0.226, 0.112, 0.012), darkBrass);
  lockCase.position.set(-0.09, 0.077, 0.058);
  lockCase.name = 'Four-digit combination lock';
  root.add(lockCase);

  const info = ui(`
    <style>
      .card { width: 500px; display: flex; flex-direction: column; gap: 12px;
              padding-top: 20px; padding-bottom: 20px; padding-left: 22px; padding-right: 22px;
              border-radius: 18px; background-color: #1b1f25;
              border-color: #806539; border-width: 2px; }
      .title { color: #ffe0a0; font-size: 30px; font-weight: 700; }
      .status { color: #9fb4ca; font-size: 22px; font-weight: 700; }
      .body { color: #e1e5eb; font-size: 22px; }
      .row { display: flex; flex-direction: row; gap: 12px; }
      .btn { padding-top: 11px; padding-bottom: 11px; padding-left: 16px; padding-right: 16px;
             border-radius: 12px; background-color: #755525; border-color: #b38b4b; border-width: 1px; }
      .reset { background-color: #303844; border-color: #566474; border-width: 1px; }
      .btntext { color: #ffffff; font-size: 21px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">The Brassbound Box</span>
      <span class="status" id="status">LOCKED - 0 0 0 0</span>
      <span class="body" id="message">Pick up a clue, or press it to inspect. Press a digit to raise it; use the small triangle below a digit to lower it. The box opens by itself.</span>
      <div class="row">
        <button class="btn" id="hint"><span class="btntext" id="hintText">Hint 1 of 3</span></button>
        <button class="btn reset" id="reset"><span class="btntext">Reset box</span></button>
      </div>
    </div>`, {
    width: 0.32,
    position: [0.235, 0.265, 0.015],
    rotationY: -0.28,
  });
  root.add(info.object3D);

  function showMessage(text) {
    info.set('message', { text });
  }

  function updateCodeStatus() {
    if (!unlocked) {
      info.set('status', {
        text: 'LOCKED - ' + values.join(' '),
        color: '#9fb4ca',
      });
    }
  }

  function unlockBox() {
    unlocked = true;
    unlockClock = 0;
    info.set('status', { text: 'OPEN - CODE 7142', color: '#83efae' });
    showMessage('Click! The combination is right. The lid is opening and something is glowing inside.');
    info.set('hintText', { text: 'Solved' });
    info.set('hint', { backgroundColor: '#355743' });
    latchMaterial.emissive.setHex(0x36d399);
    digitMaterials.forEach((material) => material.color.setHex(0x75ffac));
  }

  function checkCode() {
    for (let i = 0; i < 4; i++) {
      if (values[i] !== solution[i]) return;
    }
    unlockBox();
  }

  const digitGeometry = new THREE.PlaneGeometry(0.032, 0.044);
  const digitBackGeometry = new THREE.BoxGeometry(0.04, 0.051, 0.01);
  const arrowPlateGeometry = new THREE.BoxGeometry(0.032, 0.022, 0.009);
  const arrowGeometry = new THREE.ConeGeometry(0.008, 0.01, 3);

  function changeDigit(index, amount) {
    if (unlocked) return;
    values[index] = (values[index] + amount + 10) % 10;
    const material = digitMaterials[index];
    material.map = digitTextures[values[index]];
    material.needsUpdate = true;
    updateCodeStatus();
    checkCode();
  }

  for (let i = 0; i < 4; i++) {
    const x = -0.165 + i * 0.05;

    const wheel = new THREE.Group();
    wheel.position.set(x, 0.077, 0.069);
    wheel.name = 'Digit ' + (i + 1) + ' - press to increase';
    root.add(wheel);

    const wheelBack = new THREE.Mesh(digitBackGeometry, black);
    wheel.add(wheelBack);

    const digitMaterial = new THREE.MeshBasicMaterial({
      map: digitTextures[0],
      color: 0xffd369,
      toneMapped: false,
    });
    digitMaterials.push(digitMaterial);

    const digitFace = new THREE.Mesh(digitGeometry, digitMaterial);
    digitFace.position.z = 0.006;
    wheel.add(digitFace);

    traits(wheel, { onPress: () => changeDigit(i, 1) });

    const up = new THREE.Group();
    up.position.set(x, 0.118, 0.075);
    up.name = 'Digit ' + (i + 1) + ' up';
    root.add(up);
    up.add(new THREE.Mesh(arrowPlateGeometry, black));
    const upTriangle = new THREE.Mesh(arrowGeometry, brass);
    upTriangle.position.z = 0.006;
    up.add(upTriangle);
    traits(up, { onPress: () => changeDigit(i, 1) });

    const down = new THREE.Group();
    down.position.set(x, 0.036, 0.075);
    down.name = 'Digit ' + (i + 1) + ' down';
    root.add(down);
    down.add(new THREE.Mesh(arrowPlateGeometry, black));
    const downTriangle = new THREE.Mesh(arrowGeometry, brass);
    downTriangle.rotation.z = Math.PI;
    downTriangle.position.z = 0.006;
    down.add(downTriangle);
    traits(down, { onPress: () => changeDigit(i, -1) });
  }

  // Clue 1: a four-and-three domino. Its arithmetic yields 7 and 1.
  const domino = new THREE.Group();
  domino.position.set(-0.29, 0, 0.08);
  domino.rotation.y = 0.1;
  domino.name = 'Domino clue - four and three';
  root.add(domino);

  const dominoBase = new THREE.Mesh(
    new THREE.BoxGeometry(0.07, 0.016, 0.11),
    new THREE.MeshStandardMaterial({ color: 0xe6dfc9, roughness: 0.52 }),
  );
  dominoBase.position.y = 0.008;
  domino.add(dominoBase);

  const divider = new THREE.Mesh(new THREE.BoxGeometry(0.059, 0.002, 0.002), black);
  divider.position.set(0, 0.017, 0);
  domino.add(divider);

  const pipPositions = [
    [-0.015, 0.020, -0.043],
    [0.015, 0.020, -0.043],
    [-0.015, 0.020, -0.017],
    [0.015, 0.020, -0.017],
    [-0.015, 0.020, 0.014],
    [0, 0.020, 0.030],
    [0.015, 0.020, 0.045],
  ];
  const pips = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.0038, 12, 8),
    new THREE.MeshStandardMaterial({ color: 0x17232a, roughness: 0.4 }),
    pipPositions.length,
  );
  const instanceMatrix = new THREE.Matrix4();
  pipPositions.forEach((p, index) => {
    instanceMatrix.makeTranslation(p[0], p[1], p[2]);
    pips.setMatrixAt(index, instanceMatrix);
  });
  pips.instanceMatrix.needsUpdate = true;
  domino.add(pips);

  // Clue 2: exactly four rectangular teeth on a brass key.
  const key = new THREE.Group();
  key.position.set(-0.145, 0, 0.16);
  key.rotation.y = -0.28;
  key.name = 'Brass key clue - four teeth';
  root.add(key);

  const keyBow = new THREE.Mesh(new THREE.TorusGeometry(0.021, 0.005, 10, 28), brass);
  keyBow.rotation.x = Math.PI / 2;
  keyBow.position.y = 0.008;
  key.add(keyBow);

  const keyShaft = new THREE.Mesh(new THREE.BoxGeometry(0.01, 0.009, 0.058), brass);
  keyShaft.position.set(0, 0.008, 0.047);
  key.add(keyShaft);

  const teeth = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.019, 0.009, 0.007),
    brass,
    4,
  );
  [0.030, 0.042, 0.054, 0.066].forEach((z, index) => {
    instanceMatrix.makeTranslation(0.013, 0.008, z);
    teeth.setMatrixAt(index, instanceMatrix);
  });
  teeth.instanceMatrix.needsUpdate = true;
  key.add(teeth);

  // Clue 3: an open shell holding two pearls.
  const shell = new THREE.Group();
  shell.position.set(0.015, 0, 0.16);
  shell.rotation.y = 0.12;
  shell.name = 'Shell clue - two pearls';
  root.add(shell);

  const shellMaterial = new THREE.MeshStandardMaterial({
    color: 0xd58e85,
    roughness: 0.58,
    metalness: 0.05,
  });
  const shellGeometry = new THREE.SphereGeometry(0.05, 24, 12);

  const lowerShell = new THREE.Mesh(shellGeometry, shellMaterial);
  lowerShell.scale.set(1, 0.25, 0.78);
  lowerShell.position.y = 0.014;
  shell.add(lowerShell);

  const upperShell = new THREE.Mesh(
    shellGeometry,
    new THREE.MeshStandardMaterial({ color: 0xe3a49a, roughness: 0.6 }),
  );
  upperShell.scale.set(1, 0.24, 0.78);
  upperShell.rotation.x = -0.85;
  upperShell.position.set(0, 0.046, -0.029);
  shell.add(upperShell);

  const pearls = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.008, 16, 10),
    new THREE.MeshStandardMaterial({
      color: 0xfff3d7,
      metalness: 0.2,
      roughness: 0.22,
    }),
    2,
  );
  instanceMatrix.makeTranslation(-0.016, 0.033, 0.008);
  pearls.setMatrixAt(0, instanceMatrix);
  instanceMatrix.makeTranslation(0.014, 0.034, 0.012);
  pearls.setMatrixAt(1, instanceMatrix);
  pearls.instanceMatrix.needsUpdate = true;
  shell.add(pearls);

  const clues = [
    {
      object: domino,
      held: false,
      note: 'Domino rule: add every pip for digit 1. Then subtract the smaller half from the larger half for digit 2.',
    },
    {
      object: key,
      held: false,
      note: 'Key rule: count only the rectangular teeth beside the shaft, not the round bow. That count is digit 3.',
    },
    {
      object: shell,
      held: false,
      note: 'Shell rule: count each pearl resting inside once. The number of pearls is digit 4.',
    },
  ];

  clues.forEach((clue) => {
    traits(clue.object, {
      grab: true,
      onPress: () => {
        if (!unlocked) showMessage(clue.note);
      },
    });
  });

  const hints = [
    'Hint 1: Inspect all three objects. The domino makes two digits, the key one, and the shell one - in that order.',
    'Hint 2: The domino shows 4 and 3. Since 4 + 3 = 7 and 4 - 3 = 1, the code starts 71.',
    'Hint 3: The key has 4 teeth and the shell holds 2 pearls. The full code is 7142.',
  ];

  info.on('hint', 'click', () => {
    if (unlocked || hintCount >= 3) return;
    showMessage(hints[hintCount]);
    hintCount++;
    if (hintCount < 3) {
      info.set('hintText', { text: 'Hint ' + (hintCount + 1) + ' of 3' });
    } else {
      info.set('hintText', { text: 'No hints left' });
      info.set('hint', { backgroundColor: '#3a3e46' });
    }
  });

  info.on('reset', 'click', () => {
    unlocked = false;
    unlockClock = 0;
    hintCount = 0;
    for (let i = 0; i < 4; i++) {
      values[i] = 0;
      digitMaterials[i].map = digitTextures[0];
      digitMaterials[i].color.setHex(0xffd369);
      digitMaterials[i].needsUpdate = true;
    }
    latchMaterial.emissive.setHex(0x000000);
    latchMaterial.emissiveIntensity = 0;
    info.set('status', { text: 'LOCKED - 0 0 0 0', color: '#9fb4ca' });
    info.set('hintText', { text: 'Hint 1 of 3' });
    info.set('hint', { backgroundColor: '#755525' });
    showMessage('The box is locked again. Inspect the domino, key, and shell, then enter a new four-digit code.');
  });

  return {
    root,
    update(time, delta) {
      for (let i = 0; i < clues.length; i++) {
        const clue = clues[i];
        const held = isGrabbed(clue.object);
        if (held && !clue.held && !unlocked) showMessage(clue.note);
        clue.held = held;
      }

      if (unlocked) {
        unlockClock += delta;
        if (unlockClock > 0.35) {
          openProgress = Math.min(1, openProgress + delta * 0.72);
        }
      } else {
        openProgress = Math.max(0, openProgress - delta * 1.4);
      }

      const eased = openProgress * openProgress * (3 - 2 * openProgress);
      lid.rotation.x = -1.48 * eased;

      const reveal = openProgress > 0.04;
      gem.visible = reveal;
      glowRing.visible = reveal;
      gem.position.y = 0.104 + 0.06 * eased;
      gem.rotation.y = time * 0.8;
      gem.rotation.z = Math.sin(time * 0.9) * 0.18;
      glowRing.position.y = 0.132 + 0.01 * eased;

      const pulse = 1 + Math.sin(time * 2.2) * 0.07 * eased;
      glowRing.scale.set(pulse, pulse, pulse);
      latchMaterial.emissiveIntensity = unlocked ? 0.65 + Math.sin(time * 4) * 0.25 : 0;
    },
  };
}

export default function build({ THREE, traits, ui }) {
  const root = new THREE.Group();

  const FILES = 'abcdefgh';
  const SQUARE = 0.048;
  const BOARD_X = -0.11;
  const BOARD_Z = 0;
  const PIECE_Y = 0.026;
  const TYPE_NAMES = { k: 'King', q: 'Queen', r: 'Rook', b: 'Bishop', n: 'Knight', p: 'Pawn' };

  const ROOK_DIRS = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const BISHOP_DIRS = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
  const QUEEN_DIRS = ROOK_DIRS.concat(BISHOP_DIRS);
  const KNIGHT_STEPS = [[1, 2], [2, 1], [2, -1], [1, -2], [-1, -2], [-2, -1], [-2, 1], [-1, 2]];

  function coords(square) {
    return [FILES.indexOf(square[0]), Number(square[1]) - 1];
  }

  function squareName(file, rank) {
    return FILES[file] + String(rank + 1);
  }

  function onBoard(file, rank) {
    return file >= 0 && file < 8 && rank >= 0 && rank < 8;
  }

  function placeAtSquare(object, square, y) {
    const file = FILES.indexOf(square[0]);
    const rank = Number(square[1]) - 1;
    object.position.set(
      BOARD_X + (file - 3.5) * SQUARE,
      y,
      BOARD_Z + (3.5 - rank) * SQUARE
    );
  }

  // The board uses two instanced meshes, leaving plenty of mesh budget for pieces.
  const frame = new THREE.Mesh(
    new THREE.BoxGeometry(SQUARE * 8 + 0.022, 0.016, SQUARE * 8 + 0.022),
    new THREE.MeshStandardMaterial({ color: 0x30251f, roughness: 0.72 })
  );
  frame.name = 'Chess board frame';
  frame.position.set(BOARD_X, 0.008, BOARD_Z);
  root.add(frame);

  const tileGeometry = new THREE.BoxGeometry(SQUARE * 0.985, 0.008, SQUARE * 0.985);
  const lightTileMaterial = new THREE.MeshStandardMaterial({ color: 0xc9b995, roughness: 0.78 });
  const darkTileMaterial = new THREE.MeshStandardMaterial({ color: 0x526b79, roughness: 0.75 });
  const lightTiles = new THREE.InstancedMesh(tileGeometry, lightTileMaterial, 32);
  const darkTiles = new THREE.InstancedMesh(tileGeometry, darkTileMaterial, 32);
  lightTiles.name = 'Light squares';
  darkTiles.name = 'Dark squares';

  const tileTransform = new THREE.Object3D();
  let lightIndex = 0;
  let darkIndex = 0;
  for (let rank = 0; rank < 8; rank++) {
    for (let file = 0; file < 8; file++) {
      tileTransform.position.set(
        BOARD_X + (file - 3.5) * SQUARE,
        0.020,
        BOARD_Z + (3.5 - rank) * SQUARE
      );
      tileTransform.updateMatrix();
      if ((file + rank) % 2 === 0) {
        darkTiles.setMatrixAt(darkIndex++, tileTransform.matrix);
      } else {
        lightTiles.setMatrixAt(lightIndex++, tileTransform.matrix);
      }
    }
  }
  lightTiles.instanceMatrix.needsUpdate = true;
  darkTiles.instanceMatrix.needsUpdate = true;
  lightTiles.computeBoundingSphere();
  darkTiles.computeBoundingSphere();
  root.add(lightTiles, darkTiles);

  const whiteMaterial = new THREE.MeshStandardMaterial({
    color: 0xeee5cf,
    roughness: 0.42,
    metalness: 0.08
  });
  const blackMaterial = new THREE.MeshStandardMaterial({
    color: 0x343b49,
    roughness: 0.38,
    metalness: 0.22
  });

  const baseGeometry = new THREE.CylinderGeometry(0.018, 0.020, 0.008, 20);
  const majorBodyGeometry = new THREE.CylinderGeometry(0.010, 0.015, 0.026, 20);
  const pawnBodyGeometry = new THREE.CylinderGeometry(0.007, 0.012, 0.022, 16);
  const collarGeometry = new THREE.CylinderGeometry(0.014, 0.014, 0.006, 20);
  const headGeometry = new THREE.SphereGeometry(0.010, 20, 12);
  const rookCrownGeometry = new THREE.CylinderGeometry(0.017, 0.016, 0.009, 20);
  const battlementGeometry = new THREE.BoxGeometry(0.006, 0.008, 0.006);
  const crossVerticalGeometry = new THREE.BoxGeometry(0.005, 0.018, 0.005);
  const crossHorizontalGeometry = new THREE.BoxGeometry(0.015, 0.005, 0.005);

  function addPart(group, geometry, material, x, y, z) {
    const part = new THREE.Mesh(geometry, material);
    part.position.set(x, y, z);
    group.add(part);
    return part;
  }

  function createPieceGroup(type, color, label) {
    const group = new THREE.Group();
    const material = color === 'w' ? whiteMaterial : blackMaterial;
    group.name = (color === 'w' ? 'White ' : 'Black ') + TYPE_NAMES[type] + ' ' + label;

    addPart(group, baseGeometry, material, 0, 0.004, 0);

    if (type === 'p') {
      addPart(group, pawnBodyGeometry, material, 0, 0.019, 0);
      addPart(group, headGeometry, material, 0, 0.041, 0);
    } else if (type === 'r') {
      addPart(group, majorBodyGeometry, material, 0, 0.021, 0);
      addPart(group, rookCrownGeometry, material, 0, 0.0375, 0);
      for (const x of [-0.011, 0.011]) {
        for (const z of [-0.011, 0.011]) {
          addPart(group, battlementGeometry, material, x, 0.046, z);
        }
      }
    } else if (type === 'k') {
      addPart(group, majorBodyGeometry, material, 0, 0.021, 0);
      addPart(group, collarGeometry, material, 0, 0.037, 0);
      addPart(group, headGeometry, material, 0, 0.047, 0);
      addPart(group, crossVerticalGeometry, material, 0, 0.064, 0);
      addPart(group, crossHorizontalGeometry, material, 0, 0.065, 0);
    }

    return group;
  }

  const pieces = [];
  const initialPosition = [
    { id: 'whiteKing', type: 'k', color: 'w', square: 'g1' },
    { id: 'whiteRook', type: 'r', color: 'w', square: 'a1' },
    { id: 'blackKing', type: 'k', color: 'b', square: 'g8' },
    { id: 'blackPawnF', type: 'p', color: 'b', square: 'f7' },
    { id: 'blackPawnG', type: 'p', color: 'b', square: 'g7' },
    { id: 'blackPawnH', type: 'p', color: 'b', square: 'h7' }
  ];

  function setPieceSquare(piece, square) {
    piece.square = square;
    piece.group.visible = square !== null;
    if (square !== null) {
      placeAtSquare(piece.group, square, PIECE_Y);
    }
  }

  for (const definition of initialPosition) {
    const piece = {
      id: definition.id,
      type: definition.type,
      color: definition.color,
      square: definition.square,
      group: createPieceGroup(definition.type, definition.color, definition.square)
    };
    pieces.push(piece);
    root.add(piece.group);
    setPieceSquare(piece, definition.square);
    traits(piece.group, { onPress: () => pressPiece(piece) });
  }

  function pieceAt(square) {
    for (const piece of pieces) {
      if (piece.square === square) return piece;
    }
    return null;
  }

  function opposing(color) {
    return color === 'w' ? 'b' : 'w';
  }

  function directionsFor(type) {
    if (type === 'r') return ROOK_DIRS;
    if (type === 'b') return BISHOP_DIRS;
    return QUEEN_DIRS;
  }

  function isSquareAttacked(target, byColor) {
    const targetCoords = coords(target);
    const targetFile = targetCoords[0];
    const targetRank = targetCoords[1];

    for (const piece of pieces) {
      if (piece.color !== byColor || piece.square === null) continue;
      const source = coords(piece.square);
      const df = targetFile - source[0];
      const dr = targetRank - source[1];

      if (piece.type === 'p') {
        const direction = piece.color === 'w' ? 1 : -1;
        if (dr === direction && Math.abs(df) === 1) return true;
      } else if (piece.type === 'n') {
        if ((Math.abs(df) === 1 && Math.abs(dr) === 2) ||
            (Math.abs(df) === 2 && Math.abs(dr) === 1)) return true;
      } else if (piece.type === 'k') {
        if (Math.max(Math.abs(df), Math.abs(dr)) === 1) return true;
      } else if (piece.type === 'r' || piece.type === 'b' || piece.type === 'q') {
        const directions = directionsFor(piece.type);
        for (const direction of directions) {
          let file = source[0] + direction[0];
          let rank = source[1] + direction[1];
          while (onBoard(file, rank)) {
            const square = squareName(file, rank);
            if (square === target) return true;
            if (pieceAt(square)) break;
            file += direction[0];
            rank += direction[1];
          }
        }
      }
    }
    return false;
  }

  function isKingInCheck(color) {
    let king = null;
    for (const piece of pieces) {
      if (piece.color === color && piece.type === 'k' && piece.square !== null) {
        king = piece;
        break;
      }
    }
    return king ? isSquareAttacked(king.square, opposing(color)) : false;
  }

  function addRayMoves(piece, directions, moves) {
    const source = coords(piece.square);
    for (const direction of directions) {
      let file = source[0] + direction[0];
      let rank = source[1] + direction[1];
      while (onBoard(file, rank)) {
        const square = squareName(file, rank);
        const occupant = pieceAt(square);
        if (!occupant) {
          moves.push(square);
        } else {
          if (occupant.color !== piece.color && occupant.type !== 'k') {
            moves.push(square);
          }
          break;
        }
        file += direction[0];
        rank += direction[1];
      }
    }
  }

  function getPseudoMoves(piece) {
    const moves = [];
    if (!piece.square) return moves;
    const source = coords(piece.square);
    const file = source[0];
    const rank = source[1];

    if (piece.type === 'r') {
      addRayMoves(piece, ROOK_DIRS, moves);
    } else if (piece.type === 'b') {
      addRayMoves(piece, BISHOP_DIRS, moves);
    } else if (piece.type === 'q') {
      addRayMoves(piece, QUEEN_DIRS, moves);
    } else if (piece.type === 'n') {
      for (const step of KNIGHT_STEPS) {
        const targetFile = file + step[0];
        const targetRank = rank + step[1];
        if (!onBoard(targetFile, targetRank)) continue;
        const square = squareName(targetFile, targetRank);
        const occupant = pieceAt(square);
        if (!occupant || (occupant.color !== piece.color && occupant.type !== 'k')) {
          moves.push(square);
        }
      }
    } else if (piece.type === 'k') {
      for (let df = -1; df <= 1; df++) {
        for (let dr = -1; dr <= 1; dr++) {
          if (df === 0 && dr === 0) continue;
          const targetFile = file + df;
          const targetRank = rank + dr;
          if (!onBoard(targetFile, targetRank)) continue;
          const square = squareName(targetFile, targetRank);
          const occupant = pieceAt(square);
          if (!occupant || (occupant.color !== piece.color && occupant.type !== 'k')) {
            moves.push(square);
          }
        }
      }
    } else if (piece.type === 'p') {
      const direction = piece.color === 'w' ? 1 : -1;
      const startRank = piece.color === 'w' ? 1 : 6;
      const oneRank = rank + direction;

      if (onBoard(file, oneRank)) {
        const oneSquare = squareName(file, oneRank);
        if (!pieceAt(oneSquare)) {
          moves.push(oneSquare);
          const twoRank = rank + direction * 2;
          if (rank === startRank && onBoard(file, twoRank) &&
              !pieceAt(squareName(file, twoRank))) {
            moves.push(squareName(file, twoRank));
          }
        }
      }

      for (const df of [-1, 1]) {
        const targetFile = file + df;
        if (!onBoard(targetFile, oneRank)) continue;
        const square = squareName(targetFile, oneRank);
        const occupant = pieceAt(square);
        if (occupant && occupant.color !== piece.color && occupant.type !== 'k') {
          moves.push(square);
        }
      }
    }

    return moves;
  }

  function getLegalMoves(piece) {
    if (!piece.square) return [];
    const legal = [];
    const pseudo = getPseudoMoves(piece);

    for (const destination of pseudo) {
      const origin = piece.square;
      const captured = pieceAt(destination);
      const capturedSquare = captured ? captured.square : null;

      piece.square = destination;
      if (captured) captured.square = null;
      const leavesKingInCheck = isKingInCheck(piece.color);
      piece.square = origin;
      if (captured) captured.square = capturedSquare;

      if (!leavesKingInCheck) legal.push(destination);
    }
    return legal;
  }

  function sideHasLegalMove(color) {
    for (const piece of pieces) {
      if (piece.color === color && piece.square !== null && getLegalMoves(piece).length > 0) {
        return true;
      }
    }
    return false;
  }

  const info = ui(`
    <style>
      .card { width: 500px; flex-direction: column; gap: 12px; padding-top: 18px; padding-bottom: 18px;
              padding-left: 22px; padding-right: 22px; border-radius: 18px; background-color: #1c2026;
              border-color: #4b5664; border-width: 2px; }
      .title { color: #ffffff; font-size: 34px; font-weight: 700; }
      .meta { color: #c7d0db; font-size: 22px; }
      .body { color: #e0e5eb; font-size: 24px; }
      .status { color: #e5ebf2; background-color: #29313a; font-size: 24px; font-weight: 700;
                padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
                border-radius: 10px; }
      .row { flex-direction: row; gap: 12px; }
      .hint { background-color: #72591d; border-radius: 12px; padding-top: 10px; padding-bottom: 10px;
              padding-left: 24px; padding-right: 24px; }
      .undo { background-color: #315c82; border-radius: 12px; padding-top: 10px; padding-bottom: 10px;
              padding-left: 24px; padding-right: 24px; }
      .buttonText { color: #ffffff; font-size: 24px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Mate in One</span>
      <span class="meta">White to move. Black has Kg8 and pawns on f7, g7, h7.</span>
      <span class="body">Select a white piece, then press a glowing square. Only legal moves glow.</span>
      <span class="status" id="status">Find checkmate in one move.</span>
      <div class="row">
        <button class="hint" id="hint"><span class="buttonText">Hint</span></button>
        <button class="undo" id="undo"><span class="buttonText">Undo</span></button>
      </div>
      <span class="meta">Board guide: a1 is near-left; h8 is far-right.</span>
    </div>`, { width: 0.28, position: [0.292, 0.25, 0.01], rotationY: -0.28 });
  root.add(info.object3D);

  const moveGeometry = new THREE.BoxGeometry(SQUARE * 0.90, 0.002, SQUARE * 0.90);
  const moveMaterial = new THREE.MeshBasicMaterial({
    color: 0x54f2ba,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const captureMaterial = new THREE.MeshBasicMaterial({
    color: 0xffa43b,
    transparent: true,
    opacity: 0.58,
    depthWrite: false
  });
  const selectionMaterial = new THREE.MeshBasicMaterial({
    color: 0xffe06b,
    transparent: true,
    opacity: 0.50,
    depthWrite: false
  });

  const moveMarkers = [];
  for (let i = 0; i < 16; i++) {
    const marker = new THREE.Mesh(moveGeometry, moveMaterial);
    marker.name = 'Legal move destination';
    marker.visible = false;
    marker.renderOrder = 3;
    marker.userData.to = null;
    root.add(marker);
    traits(marker, {
      onPress: () => {
        if (marker.visible && marker.userData.to) moveSelected(marker.userData.to);
      }
    });
    moveMarkers.push(marker);
  }

  const selectionMarker = new THREE.Mesh(moveGeometry, selectionMaterial);
  selectionMarker.name = 'Selected piece square';
  selectionMarker.visible = false;
  selectionMarker.renderOrder = 2;
  root.add(selectionMarker);

  const mateHalo = new THREE.Mesh(
    new THREE.TorusGeometry(0.024, 0.003, 8, 32),
    new THREE.MeshBasicMaterial({ color: 0x72ff9d })
  );
  mateHalo.name = 'Checkmate halo';
  mateHalo.rotation.x = Math.PI / 2;
  mateHalo.visible = false;
  root.add(mateHalo);

  let selectedId = null;
  let currentMoves = [];
  let history = [];
  let locked = false;
  let solved = false;
  let hintClicks = 0;

  function setStatus(text, kind) {
    const styles = {
      normal: { color: '#e5ebf2', backgroundColor: '#29313a' },
      info: { color: '#b5e1ff', backgroundColor: '#223849' },
      success: { color: '#a4ffb8', backgroundColor: '#173b2a' },
      error: { color: '#ffb5ac', backgroundColor: '#462629' },
      hint: { color: '#ffe39d', backgroundColor: '#44391f' }
    };
    const style = styles[kind || 'normal'];
    info.set('status', { text: text, color: style.color, backgroundColor: style.backgroundColor });
  }

  function clearHighlights() {
    for (const marker of moveMarkers) {
      marker.visible = false;
      marker.userData.to = null;
    }
  }

  function clearSelection() {
    selectedId = null;
    currentMoves = [];
    selectionMarker.visible = false;
    clearHighlights();
  }

  function selectPiece(piece) {
    clearSelection();
    selectedId = piece.id;
    currentMoves = getLegalMoves(piece);

    placeAtSquare(selectionMarker, piece.square, 0.0255);
    selectionMarker.visible = true;

    const count = Math.min(currentMoves.length, moveMarkers.length);
    for (let i = 0; i < count; i++) {
      const destination = currentMoves[i];
      const marker = moveMarkers[i];
      marker.userData.to = destination;
      marker.material = pieceAt(destination) ? captureMaterial : moveMaterial;
      placeAtSquare(marker, destination, 0.0255);
      marker.visible = true;
    }

    if (currentMoves.length === 0) {
      setStatus(TYPE_NAMES[piece.type] + ' on ' + piece.square + ' has no legal moves.', 'info');
    } else {
      setStatus(
        TYPE_NAMES[piece.type] + ' selected on ' + piece.square + '. Press one of ' +
        currentMoves.length + ' glowing squares.',
        'info'
      );
    }
  }

  function pressPiece(piece) {
    if (solved) {
      setStatus('Checkmate! Puzzle solved. Use Undo to play it again.', 'success');
      return;
    }
    if (locked) {
      setStatus('That was not mate. Press Undo, then try again.', 'error');
      return;
    }

    if (piece.color === 'b') {
      if (selectedId && currentMoves.indexOf(piece.square) !== -1) {
        moveSelected(piece.square);
      } else {
        setStatus('White to move. Select the white king or the white rook.', 'info');
      }
      return;
    }

    if (selectedId === piece.id) {
      clearSelection();
      setStatus('Selection cleared. Choose a white piece.', 'normal');
    } else {
      selectPiece(piece);
    }
  }

  function moveSelected(destination) {
    if (!selectedId || locked || solved) return;

    let mover = null;
    for (const piece of pieces) {
      if (piece.id === selectedId) {
        mover = piece;
        break;
      }
    }
    if (!mover) return;

    const legalMoves = getLegalMoves(mover);
    if (legalMoves.indexOf(destination) === -1) return;

    history.push(pieces.map(piece => piece.square));

    const captured = pieceAt(destination);
    const piecePrefix = mover.type === 'p' ? '' : mover.type.toUpperCase();
    const notation = piecePrefix + (captured ? 'x' : '') + destination;

    setPieceSquare(mover, destination);
    if (captured) setPieceSquare(captured, null);

    clearSelection();

    const blackInCheck = isKingInCheck('b');
    const blackCanMove = sideHasLegalMove('b');

    if (blackInCheck && !blackCanMove) {
      solved = true;
      mateHalo.visible = true;
      placeAtSquare(mateHalo, 'g8', 0.029);
      setStatus('Checkmate! ' + notation + ' wins in one move. Excellent!', 'success');
    } else {
      locked = true;
      if (blackInCheck) {
        setStatus(notation + ' gives check, but Black can escape. Try again - press Undo.', 'error');
      } else {
        setStatus(notation + ' is not mate. Try again - press Undo.', 'error');
      }
    }
  }

  info.on('hint', 'click', () => {
    if (solved) return;
    hintClicks++;
    if (hintClicks % 2 === 1) {
      setStatus('Hint: The black king is boxed in by its pawns. Give check along rank 8.', 'hint');
    } else {
      setStatus('Stronger hint: Select the a1 rook, then move it to a8, the far-left corner.', 'hint');
    }
  });

  info.on('undo', 'click', () => {
    if (history.length === 0) {
      setStatus('Nothing to undo yet. White to move: find mate in one.', 'normal');
      return;
    }

    const snapshot = history.pop();
    for (let i = 0; i < pieces.length; i++) {
      setPieceSquare(pieces[i], snapshot[i]);
    }
    locked = false;
    solved = false;
    mateHalo.visible = false;
    clearSelection();
    setStatus('Move undone. White to move - try a different idea.', 'info');
  });

  return {
    root,
    update(time) {
      const pulse = 0.5 + 0.5 * Math.sin(time * 4.2);
      moveMaterial.opacity = 0.34 + pulse * 0.24;
      captureMaterial.opacity = 0.44 + pulse * 0.25;
      selectionMaterial.opacity = 0.34 + pulse * 0.25;

      if (mateHalo.visible) {
        const scale = 1 + Math.sin(time * 4) * 0.08;
        mateHalo.scale.set(scale, scale, scale);
      }
    }
  };
}

