    checkoutMessage = 'Demo order placed for ' + money(paidTotal) + '. The cart is now empty. No payment was collected.';
    cartMessage = '';
    updateCartBadge();
    refreshSummary();
  });

  traits(dial, {
    onPress: () => {
      spinToken = { start: carouselAngle };
      spinVelocity = 4.8;
      selected = (selected + 1) % products.length;
      refreshShop();
      if (mode !== 'shop') showMode('shop');
      panel.set('shop-message', { text: 'Turntable spinning. The front headphone is selected.' });
    },
  });

  traits(cartBadge, {
    onPress: () => showMode(mode === 'cart' ? 'shop' : 'cart'),
  });

  productHits.forEach((hit, index) => {
    traits(hit, {
      onPress: () => {
        const step = Math.PI * 2 / 3;
        const current = nearestStep(carouselAngle);
        const productAtFront = ((Math.round(-current / step) % 3) + 3) % 3;
        if (productAtFront === index && Math.abs(carouselAngle - current) < 0.12) {
          selectProduct(index);
          panel.set('shop-message', { text: products[index].name + ' selected. Configure it on the right.' });
        } else {
          selectProduct(index);
        }
      },
    });
  });

  refreshShop();
  showMode('shop');
  updateCartBadge();

  return {
    root,
    update(time, delta) {
      if (spinToken && !isGrabbed(dial)) {
        carouselAngle += spinVelocity * delta;
        spinVelocity *= Math.exp(-2.2 * delta);
        if (spinVelocity < 0.85) {
          spinToken = null;
          targetAngle = nearestStep(carouselAngle);
        }
      } else if (!spinToken) {
        const difference = targetAngle - carouselAngle;
        carouselAngle += difference * Math.min(1, delta * 7);
        if (Math.abs(difference) < 0.001) carouselAngle = targetAngle;
      }

      carouselAngle = nearestStep(carouselAngle) + (carouselAngle - nearestStep(carouselAngle));
      rotatingDeck.rotation.y = carouselAngle;
      dial.rotation.y += delta * (spinToken ? 5 : 0.25);

      const step = Math.PI * 2 / 3;
      const frontIndex = ((Math.round(-carouselAngle / step) % 3) + 3) % 3;
      if (!spinToken && Math.abs(targetAngle - carouselAngle) < 0.03 && frontIndex !== selected) {
        selected = frontIndex;
        refreshShop();
      }

      for (let i = 0; i < productModels.length; i += 1) {
        const model = productModels[i];
        const isFront = i === selected;
        const targetScale = isFront ? 1.08 : 0.91;
        const scale = model.scale.x + (targetScale - model.scale.x) * Math.min(1, delta * 7);
        model.scale.setScalar(scale);
      }

      deckRing.material.emissiveIntensity = 0.85 + Math.sin(time * 2.2) * 0.18;
      cartScaleTarget += (1 - cartScaleTarget) * Math.min(1, delta * 6);
      const badgeScale = cartBadge.scale.x + (cartScaleTarget - cartBadge.scale.x) * Math.min(1, delta * 12);
      cartBadge.scale.setScalar(badgeScale);
    },
  };
}

