      fact: 'Tipped on its side, it orbits the Sun lying down. 50,724 km across.' },
    { name: 'Neptune', km: 49244, r: 0.0070, orbit: 0.178, days: 60190, color: 0x3f5fd6, phase: 0.3,
      fact: 'Windiest world: gusts near 2,000 km/h. 49,244 km across.' },
  ];
  const SUN_FACT = 'The star at the center: 99.8% of the Solar System mass, 1,392,700 km across.';

  const sphereGeo = new THREE.SphereGeometry(1, 24, 16);
  const hitGeo = new THREE.SphereGeometry(1, 10, 8);
  const hitMat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });

  let playing = true;
  let speedIdx = 1;
  let showOrbits = true;
  let showLabels = false;
  let compare = false;
  let labelsShown = false;
  let simDays = 0;
  let saturnRingMesh = null;

  const planets = [];
  let cursor = -0.29;

  for (let i = 0; i < DATA.length; i++) {
    const d = DATA[i];

    const mat = new THREE.MeshStandardMaterial({
      color: d.color, roughness: 0.8, metalness: 0.0,
      emissive: d.color, emissiveIntensity: 0.22,
    });
    const mesh = new THREE.Mesh(sphereGeo, mat);
    mesh.name = d.name;
    mesh.position.set(CX + d.orbit, CY, CZ);
    root.add(mesh);

    if (d.name === 'Saturn') {
      const ringMat = new THREE.MeshBasicMaterial({
        color: 0xe8d6a8, transparent: true, opacity: 0.6,
        side: THREE.DoubleSide, depthWrite: false,
      });
      const ring = new THREE.Mesh(new THREE.RingGeometry(1.3, 2.1, 48), ringMat);
      ring.name = 'SaturnRings';
      ring.rotation.x = -Math.PI / 2 + 0.34;
      ring.rotation.z = 0.2;
      mesh.add(ring);
      saturnRingMesh = ring;
    }

    // invisible press target, always big enough for a hand ray
    const hit = new THREE.Mesh(hitGeo, hitMat);
    hit.name = 'Hit_' + d.name;
    hit.position.copy(mesh.position);
    hit.scale.setScalar(0.008);
    root.add(hit);

    // true-relative-size row slot
    const rowR = JUP_ROW * d.km / 139820;
    const rowX = cursor + rowR;
    cursor = rowX + rowR + GAP;

    const p = {
      name: d.name, fact: d.fact, r: d.r, orbit: d.orbit, days: d.days,
      phase: d.phase, mat, mesh, hit, rowR, rowX, blend: 0, label: null,
    };
    planets.push(p);

    traits(hit, { onPress: () => showInfo(p.name, p.fact, p.mat) });

    // floating name label (hidden until toggled on)
    const label = ui(`
      <style>
        .lbl { width: 170px; flex-direction: column; padding-top: 6px; padding-bottom: 6px;
               padding-left: 10px; padding-right: 10px; border-radius: 10px; background-color: #12151a; }
        .t { color: #d8e6ff; font-size: 34px; font-weight: 700; }
      </style>
      <div class="lbl"><span class="t">${d.name}</span></div>`, { width: 0.075 });
    label.object3D.visible = false;
    root.add(label.object3D);
    p.label = label;
  }

  // ---- the Sun ----
  const sunMat = new THREE.MeshStandardMaterial({
    color: 0xffc23d, emissive: 0xff9a10, emissiveIntensity: 1.5, roughness: 0.5,
  });
  const sun = new THREE.Mesh(new THREE.SphereGeometry(0.02, 32, 16), sunMat);
  sun.name = 'Sun';
  sun.position.set(CX, CY, CZ);
  root.add(sun);

  const glowMat = new THREE.MeshBasicMaterial({
    color: 0xffa733, transparent: true, opacity: 0.18,
    depthWrite: false, blending: THREE.AdditiveBlending,
  });
  const glow = new THREE.Mesh(new THREE.SphereGeometry(0.032, 24, 12), glowMat);
  glow.position.set(CX, CY, CZ);
  root.add(glow);

  const sunHit = new THREE.Mesh(hitGeo, hitMat);
  sunHit.name = 'Hit_Sun';
  sunHit.position.set(CX, CY, CZ);
  sunHit.scale.setScalar(0.028);
  root.add(sunHit);
  traits(sunHit, { onPress: () => showInfo('Sun', SUN_FACT, sunMat) });

  // ---- orbit rings ----
  const orbitGroup = new THREE.Group();
  orbitGroup.name = 'Orbits';
  root.add(orbitGroup);
  const lineMat = new THREE.LineBasicMaterial({ color: 0x5a7fb8, transparent: true, opacity: 0.55 });
  for (let i = 0; i < DATA.length; i++) {
    const pts = [];
    const N = 128;
    for (let j = 0; j <= N; j++) {
      const a = (j / N) * Math.PI * 2;
      pts.push(new THREE.Vector3(CX + Math.cos(a) * DATA[i].orbit, CY, CZ - Math.sin(a) * DATA[i].orbit));
    }
    orbitGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), lineMat));
  }

  // ---- control panel ----
  const panel = ui(`
    <style>
      .card { width: 430px; flex-direction: column; gap: 12px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px;
              border-radius: 20px; background-color: #1b1f26; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .name { color: #ffd479; font-size: 26px; font-weight: 700; }
      .body { color: #d7dbe2; font-size: 22px; }
      .row { flex-direction: row; gap: 12px; }
      .btn { padding-top: 10px; padding-bottom: 10px; padding-left: 12px; padding-right: 12px;
             border-radius: 12px; background-color: #2f6fdb; }
      .btn-text { color: #ffffff; font-size: 22px; font-weight: 700; }
    </style>
    <div class="card">
      <span class="title">Solar System</span>
      <span class="name" id="pname">Tap a planet</span>
      <span class="body" id="pinfo">Press any planet, or the Sun, to read about it.</span>
      <div class="row">
        <button class="btn" id="play"><span class="btn-text" id="playtxt">Pause</span></button>
        <button class="btn" id="speed"><span class="btn-text" id="speedtxt">Speed 1x</span></button>
      </div>
      <div class="row">
        <button class="btn" id="orbits"><span class="btn-text" id="orbitstxt">Orbits on</span></button>
        <button class="btn" id="labels"><span class="btn-text" id="labelstxt">Labels off</span></button>
      </div>
      <button class="btn" id="compare"><span class="btn-text" id="comparetxt">Compare sizes</span></button>
    </div>`, { width: 0.30, position: [0.30, 0.215, 0.0], rotationY: -0.30 });
  root.add(panel.object3D);

  const BLUE = '#2f6fdb';
  const GREY = '#343a44';
  const AMBER = '#c98a2b';

  let lastInfo = { name: 'Tap a planet', fact: 'Press any planet, or the Sun, to read about it.' };

  function showInfo(name, fact, target) {
    for (let i = 0; i < planets.length; i++) planets[i].mat.emissiveIntensity = 0.22;
    sunMat.emissiveIntensity = 1.5;
    if (target) target.emissiveIntensity = (target === sunMat) ? 2.2 : 0.85;
    panel.set('pname', { text: name });
    panel.set('pinfo', { text: fact });
    lastInfo = { name: name, fact: fact };
  }

  function refreshLabels() {
    const want = showLabels && !compare;
    if (want === labelsShown) return;
    labelsShown = want;
    for (let i = 0; i < planets.length; i++) planets[i].label.object3D.visible = want;
  }

  panel.on('play', 'click', () => {
    playing = !playing;
    panel.set('playtxt', { text: playing ? 'Pause' : 'Play' });
    panel.set('play', { backgroundColor: playing ? BLUE : GREY });
  });

  panel.on('speed', 'click', () => {
    speedIdx = (speedIdx + 1) % SPEEDS.length;
    panel.set('speedtxt', { text: 'Speed ' + SPEEDS[speedIdx] + 'x' });
  });

  panel.on('orbits', 'click', () => {
    showOrbits = !showOrbits;
    panel.set('orbitstxt', { text: showOrbits ? 'Orbits on' : 'Orbits off' });
    panel.set('orbits', { backgroundColor: showOrbits ? BLUE : GREY });
  });

  panel.on('labels', 'click', () => {
    showLabels = !showLabels;
    panel.set('labelstxt', { text: showLabels ? 'Labels on' : 'Labels off' });
    panel.set('labels', { backgroundColor: showLabels ? BLUE : GREY });
    refreshLabels();
  });

  panel.on('compare', 'click', () => {
    compare = !compare;
    panel.set('comparetxt', { text: compare ? 'Back to orbits' : 'Compare sizes' });
    panel.set('compare', { backgroundColor: compare ? AMBER : BLUE });
    if (compare) {
      panel.set('pname', { text: 'True sizes' });
      panel.set('pinfo', { text: 'All 8 planets on one scale, Mercury on the left to Neptune. Tap one for its diameter.' });
    } else {
      panel.set('pname', { text: lastInfo.name });
      panel.set('pinfo', { text: lastInfo.fact });
    }
    refreshLabels();
  });

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta || 0.016, 0.05);
      if (playing) simDays += dt * BASE_RATE * SPEEDS[speedIdx];

      const target = compare ? 1 : 0;
      const step = dt * 2.6;

      for (let i = 0; i < planets.length; i++) {
        const p = planets[i];

        if (p.blend < target) p.blend = Math.min(target, p.blend + step);
        else if (p.blend > target) p.blend = Math.max(target, p.blend - step);
        const e = p.blend * p.blend * (3 - 2 * p.blend);

        const ang = p.phase - Math.PI / 2 + (simDays / p.days) * Math.PI * 2;
        const ox = CX + Math.cos(ang) * p.orbit;
        const oz = CZ - Math.sin(ang) * p.orbit;

        const px = ox + (p.rowX - ox) * e;
        const py = CY + (ROW_Y - CY) * e;
        const pz = oz + (CZ - oz) * e;

        p.mesh.position.set(px, py, pz);
        const rad = p.r + (p.rowR - p.r) * e;
        p.mesh.scale.setScalar(rad);

        const hitR = Math.max(0.0045, Math.min(rad * 1.7 + 0.001, rad + 0.006));
        p.hit.position.set(px, py, pz);
        p.hit.scale.setScalar(hitR);

        if (labelsShown) {
          p.label.object3D.position.set(px, py + 0.030 + (i % 2) * 0.030, pz);
        }
      }

      if (saturnRingMesh) {
        const sb = planets[5].blend;
        const e5 = sb * sb * (3 - 2 * sb);
        saturnRingMesh.material.opacity = 0.6 * (1 - e5);
        saturnRingMesh.visible = e5 < 0.97;
      }

      orbitGroup.visible = showOrbits && !compare;
      sun.visible = !compare;
      glow.visible = !compare;
      sunHit.position.set(CX, compare ? -5 : CY, CZ);
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();
  root.name = 'Interactive arm bones';

  const boneMaterial = new THREE.MeshStandardMaterial({
    color: 0xe8dcc5,
    roughness: 0.72,
    metalness: 0,
  });
  const highlightMaterial = new THREE.MeshStandardMaterial({
    color: 0xffd47a,
    emissive: 0x8a4c12,
    emissiveIntensity: 0.35,
    roughness: 0.58,
    metalness: 0,
  });

  const sphereGeometry = new THREE.SphereGeometry(1, 20, 12);
  const capsuleCache = {};
  const bones = [];

  function capsuleGeometry(radius, length) {
    const key = radius + ':' + length;
    if (!capsuleCache[key]) {
      capsuleCache[key] = new THREE.CapsuleGeometry(radius, length, 4, 12);
    }
    return capsuleCache[key];
  }

  function ellipsoid(rx, ry, rz) {
    const mesh = new THREE.Mesh(sphereGeometry, boneMaterial);
    mesh.scale.set(rx, ry, rz);
    return mesh;
  }

  let selectedBone = null;
  let infoPanel;

  function selectBone(bone) {
    if (selectedBone) {
      selectedBone.traverse((child) => {
        if (child.isMesh && child.userData.defaultMaterial) {
          child.material = child.userData.defaultMaterial;
        }
      });
    }
    selectedBone = bone;
    bone.traverse((child) => {
      if (child.isMesh) child.material = highlightMaterial;
    });
    infoPanel.set('boneName', { text: bone.userData.displayName });
    infoPanel.set('boneFact', { text: bone.userData.fact });
  }

  function registerBone(group, name, fact) {
    group.name = name;
    group.userData.displayName = name;
    group.userData.fact = fact;
    group.traverse((child) => {
      if (child.isMesh) {
        child.name = name;
        child.userData.defaultMaterial = child.material;
      }
    });
    root.add(group);
    group.userData.home = group.position.clone();
    group.userData.homeQuaternion = group.quaternion.clone();
    bones.push(group);
    traits(group, {
      grab: true,
      onPress: () => selectBone(group),
    });
    return group;
  }

  function addCapsuleBone(name, fact, position, radius, length, rotationZ = 0) {
    const group = new THREE.Group();
    const shaft = new THREE.Mesh(capsuleGeometry(radius, length), boneMaterial);
    shaft.scale.z = 0.8;
    group.add(shaft);
    group.position.set(position[0], position[1], position[2]);
    group.rotation.z = rotationZ;
    return registerBone(group, name, fact);
  }

  // Humerus: shoulder ball above, shaft, and broad distal elbow end.
  const humerus = new THREE.Group();
  const humerusShaft = new THREE.Mesh(capsuleGeometry(0.010, 0.105), boneMaterial);
  humerusShaft.scale.z = 0.8;
  humerus.add(humerusShaft);
  const humeralHead = ellipsoid(0.015, 0.016, 0.014);
  humeralHead.position.set(-0.003, 0.066, 0);
  humerus.add(humeralHead);
  const humeralCondyle = ellipsoid(0.015, 0.009, 0.010);
  humeralCondyle.position.set(0, -0.063, 0);
  humerus.add(humeralCondyle);
  humerus.position.set(0, 0.375, 0);
  registerBone(
    humerus,
    'Humerus',
    'The single long bone of the upper arm. Its head joins the shoulder blade; its lower end meets the radius and ulna at the elbow.'
  );

  // Forearm in anatomical position: radius on the thumb side.
  const radius = new THREE.Group();
  const radiusShaft = new THREE.Mesh(capsuleGeometry(0.007, 0.082), boneMaterial);
  radiusShaft.scale.z = 0.78;
  radius.add(radiusShaft);
  const radialHead = ellipsoid(0.009, 0.004, 0.008);
  radialHead.position.set(0, 0.047, 0);
  radius.add(radialHead);
  const radialWrist = ellipsoid(0.012, 0.008, 0.009);
  radialWrist.position.set(0, -0.047, 0);
  radius.add(radialWrist);
  radius.position.set(0.017, 0.240, 0);
  registerBone(
    radius,
    'Radius',
    'The forearm bone on the thumb side. It rotates around the ulna to turn the palm up or down and carries much of the load at the wrist.'
  );

  const ulna = new THREE.Group();
  const ulnaShaft = new THREE.Mesh(capsuleGeometry(0.0065, 0.088), boneMaterial);
  ulnaShaft.scale.z = 0.76;
  ulna.add(ulnaShaft);
  const olecranon = ellipsoid(0.010, 0.012, 0.011);
  olecranon.position.set(0, 0.053, -0.002);
  ulna.add(olecranon);
  ulna.position.set(-0.015, 0.240, 0);
  registerBone(
    ulna,
    'Ulna',
    'The forearm bone on the little-finger side. Its olecranon forms the point of the elbow and creates the main hinge with the humerus.'
  );

  function addCarpal(name, fact, position, scale) {
    const group = new THREE.Group();
    const mesh = ellipsoid(scale[0], scale[1], scale[2]);
    group.add(mesh);
    group.position.set(position[0], position[1], position[2]);
    return registerBone(group, name, fact);
  }

  addCarpal(
    'Scaphoid',
    'A boat-shaped carpal on the thumb side. It links the two wrist rows and helps stabilize and guide wrist motion.',
    [0.031, 0.178, 0],
    [0.017, 0.011, 0.010]
  );
  addCarpal(
    'Lunate',
    'A crescent-shaped wrist bone that meets the radius and helps transfer force between the hand and forearm.',
    [0.006, 0.178, 0],
    [0.015, 0.011, 0.011]
  );
  addCarpal(
    'Triquetrum',
    'A pyramid-shaped carpal on the little-finger side. It meets the hamate and contributes to wrist movement.',
    [-0.018, 0.175, 0],
    [0.015, 0.010, 0.010]
  );
  addCarpal(
    'Pisiform',
    'A pea-shaped sesamoid bone within the flexor carpi ulnaris tendon. It sits on the palm side of the triquetrum.',
    [-0.019, 0.176, 0.014],
    [0.015, 0.010, 0.008]
  );
  addCarpal(
    'Trapezium',
    'The distal carpal at the thumb base. Its saddle joint with the first metacarpal allows the thumb to oppose the fingers.',
    [0.034, 0.155, 0],
    [0.015, 0.010, 0.010]
  );
  addCarpal(
    'Trapezoid',
    'A small wedge-shaped carpal that supports the second metacarpal and stabilizes the base of the index finger.',
    [0.015, 0.154, 0],
    [0.015, 0.009, 0.009]
  );
  addCarpal(
    'Capitate',
    'The largest carpal. It sits centrally, meets mainly the third metacarpal, and transmits force through the hand.',
    [-0.004, 0.153, 0],
    [0.015, 0.012, 0.010]
  );
  addCarpal(
    'Hamate',
    'A carpal on the little-finger side with a projecting hook. It supports the ring and little metacarpals and anchors soft tissues.',
    [-0.025, 0.152, 0],
    [0.016, 0.011, 0.010]
  );

  // Five metacarpals form the palm.
  addCapsuleBone(
    '1st metacarpal',
    'The thumb metacarpal connects the trapezium to the proximal phalanx. Its saddle joint gives the thumb exceptional mobility.',
    [0.050, 0.132, 0],
    0.006,
    0.040,
    0.53
  );
  addCapsuleBone(
    '2nd metacarpal',
    'This palm bone connects the wrist to the index finger and provides a stable base for precision gripping.',
    [0.025, 0.124, 0],
    0.0055,
    0.043,
    0.06
  );
  addCapsuleBone(
    '3rd metacarpal',
    'This central palm bone connects the capitate to the middle finger and forms a stable axis for the hand.',
    [0.006, 0.125, 0],
    0.0058,
    0.042,
    0
  );
  addCapsuleBone(
    '4th metacarpal',
    'This palm bone links the wrist to the ring finger. Its mobile knuckle helps the palm wrap around objects.',
    [-0.012, 0.124, 0],
    0.0054,
    0.042,
    -0.06
  );
  addCapsuleBone(
    '5th metacarpal',
    'This palm bone supports the little finger. Its movement lets the little-finger side of the hand cup during a grip.',
    [-0.028, 0.120, 0],
    0.005,
    0.044,
    -0.10
  );

  function capitalized(text) {
    return text.charAt(0).toUpperCase() + text.slice(1);
  }

  function addPhalanx(digit, kind, position, radius, length, rotationZ = 0) {
    const name = capitalized(digit) + ' ' + kind + ' phalanx';
    let fact;
    if (kind === 'proximal') {
      const nextBone = digit === 'thumb' ? 'distal phalanx' : 'middle phalanx';
      fact = 'The first bone of the ' + digit + ' after its metacarpal. It bends to begin the finger curl and meets the ' + nextBone + '.';
    } else if (kind === 'middle') {
      fact = 'The central bone of the ' + digit + ' finger. Its hinge joints let the finger curl around objects and straighten again.';
    } else {
      fact = 'The last bone of the ' + digit + '. It supports the fingertip and nail and provides a firm platform for touch and pinch.';
    }
    return addCapsuleBone(name, fact, position, radius, length, rotationZ);
  }

  // The thumb has two phalanges; each other digit has three.
  addPhalanx('thumb', 'proximal', [0.069, 0.094, 0], 0.0048, 0.0254, 0.35);
  addPhalanx('thumb', 'distal', [0.079, 0.067, 0], 0.0045, 0.017, 0.20);

  addPhalanx('index', 'proximal', [0.028, 0.0775, 0], 0.0047, 0.0276, 0.025);
  addPhalanx('index', 'middle', [0.028, 0.046, 0], 0.0042, 0.0176, 0.025);
  addPhalanx('index', 'distal', [0.028, 0.022, 0], 0.0040, 0.014, 0.025);

  addPhalanx('middle', 'proximal', [0.006, 0.0785, 0], 0.0049, 0.0312, 0);
  addPhalanx('middle', 'middle', [0.006, 0.043, 0], 0.0044, 0.0212, 0);
  addPhalanx('middle', 'distal', [0.006, 0.0185, 0], 0.0041, 0.0148, 0);

  addPhalanx('ring', 'proximal', [-0.016, 0.0765, 0], 0.0046, 0.0298, -0.02);
  addPhalanx('ring', 'middle', [-0.016, 0.0435, 0], 0.0042, 0.0186, -0.02);
  addPhalanx('ring', 'distal', [-0.016, 0.020, 0], 0.0039, 0.0142, -0.02);

  addPhalanx('little', 'proximal', [-0.0325, 0.075, 0], 0.0042, 0.0236, -0.04);
  addPhalanx('little', 'middle', [-0.0325, 0.048, 0], 0.0039, 0.0142, -0.04);
  addPhalanx('little', 'distal', [-0.0325, 0.027, 0], 0.0037, 0.0126, -0.04);

  infoPanel = ui(`
    <style>
      .card { width: 460px; display: flex; flex-direction: column; gap: 12px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #1d2128; border-color: #46505e; border-width: 2px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .subtitle { color: #aeb8c7; font-size: 22px; }
      .bone-name { color: #ffd47a; font-size: 28px; font-weight: 700; }
      .body { color: #e0e4ea; font-size: 22px; }
      .status { color: #9fc3ff; font-size: 22px; }
      .button { padding-top: 12px; padding-bottom: 12px; padding-left: 16px; padding-right: 16px;
                border-radius: 12px; background-color: #356cc8; }
      .button-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Arm bone explorer</span>
      <span class="subtitle">30 bones from shoulder to fingertips - palm view.</span>
      <span class="bone-name" id="boneName">Humerus</span>
      <span class="body" id="boneFact">Tap any bone to see its name and function.</span>
      <span class="body">Pinch and drag a bone to pull it apart. The button below returns every bone to its place.</span>
      <span class="status" id="assemblyStatus">Model assembled: 30 bones.</span>
      <button class="button" id="reassemble"><span class="button-text">Reassemble arm</span></button>
    </div>`,
    { width: 0.26, position: [-0.26, 0.275, 0.01], rotationY: 0.25 }
  );
  root.add(infoPanel.object3D);

  const quizPanel = ui(`
    <style>
      .card { width: 480px; display: flex; flex-direction: column; gap: 11px;
              padding-top: 18px; padding-bottom: 18px; padding-left: 20px; padding-right: 20px;
              border-radius: 18px; background-color: #20242b; border-color: #46505e; border-width: 2px; }
      .title { color: #ffffff; font-size: 30px; font-weight: 700; }
      .progress { color: #aeb8c7; font-size: 22px; }
      .question { color: #ffffff; font-size: 23px; font-weight: 700; }
      .answer { padding-top: 10px; padding-bottom: 10px; padding-left: 14px; padding-right: 14px;
                border-radius: 11px; background-color: #303741; }
      .answer-text { color: #f1f3f6; font-size: 22px; }
      .feedback { color: #d7dbe2; font-size: 22px; }
      .score { color: #9fc3ff; font-size: 23px; font-weight: 700; }
      .next { padding-top: 11px; padding-bottom: 11px; padding-left: 15px; padding-right: 15px;
              border-radius: 11px; background-color: #356cc8; }
      .next-text { color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
    </style>
    <div class="card">
      <span class="title">Arm bone quiz</span>
      <span class="progress" id="progress">Question 1 of 5</span>
      <span class="question" id="question">Question</span>
      <button class="answer" id="answer0"><span class="answer-text" id="answer0text">Answer</span></button>
      <button class="answer" id="answer1"><span class="answer-text" id="answer1text">Answer</span></button>
      <button class="answer" id="answer2"><span class="answer-text" id="answer2text">Answer</span></button>
      <span class="feedback" id="feedback">Choose an answer. Feedback appears here.</span>
      <span class="score" id="score">Score: 0</span>
      <button class="next" id="next"><span class="next-text" id="nextText">Next question</span></button>
    </div>`,
    { width: 0.27, position: [0.26, 0.255, 0.01], rotationY: -0.25 }
  );
  root.add(quizPanel.object3D);

  selectBone(humerus);

  let reassembling = false;
  infoPanel.on('reassemble', 'click', () => {
    reassembling = true;
    infoPanel.set('assemblyStatus', { text: 'Reassembling - release any bone you are holding.' });
  });

  const questions = [
    {
      question: 'Which is the single long bone of the upper arm?',
      answers: ['Humerus', 'Femur', 'Tibia'],
      correct: 0,
      explanation: 'The humerus runs from the shoulder to the elbow. The femur and tibia are leg bones.',
    },
    {
      question: 'In anatomical position, which forearm bone is on the thumb side?',
      answers: ['Ulna', 'Radius', 'Capitate'],
      correct: 1,
      explanation: 'The radius is on the thumb side. The ulna is on the little-finger side.',
    },
    {
      question: 'How many carpal bones are in one wrist?',
      answers: ['5', '14', '8'],
      correct: 2,
      explanation: 'Eight carpals form two rows of four. Five metacarpals form the palm.',
    },
    {
      question: 'Which structure forms the bony point of the elbow?',
      answers: ['Olecranon of the ulna', 'Head of the radius', 'Distal phalanx'],
      correct: 0,
      explanation: 'The olecranon is the large proximal projection of the ulna that you can feel at the elbow tip.',
    },
    {
      question: 'What are the 14 bones of the fingers and thumb called?',
      answers: ['Metacarpals', 'Phalanges', 'Vertebrae'],
      correct: 1,
      explanation: 'Four fingers have three phalanges each and the thumb has two: 4 x 3 + 2 = 14.',
    },
  ];

  let questionIndex = 0;
  let score = 0;
  let answered = false;
  let finished = false;

  function renderQuestion() {
    const item = questions[questionIndex];
    quizPanel.set('progress', { text: 'Question ' + (questionIndex + 1) + ' of 5' });
    quizPanel.set('question', { text: item.question });
    quizPanel.set('feedback', {
      text: 'Choose an answer. Feedback appears here.',
      color: '#d7dbe2',
    });
    quizPanel.set('score', { text: 'Score: ' + score });
    quizPanel.set('next', { display: 'none' });
    for (let i = 0; i < 3; i++) {
      quizPanel.set('answer' + i, { display: 'flex', backgroundColor: '#303741' });
      quizPanel.set('answer' + i + 'text', { text: item.answers[i] });
    }
  }

  function answerQuestion(choice) {
    if (answered || finished) return;
    answered = true;
    const item = questions[questionIndex];
    const correct = choice === item.correct;
    if (correct) score++;

    for (let i = 0; i < 3; i++) {
      quizPanel.set('answer' + i, { backgroundColor: '#303741' });
    }
    quizPanel.set('answer' + item.correct, { backgroundColor: '#216145' });
    if (!correct) {
      quizPanel.set('answer' + choice, { backgroundColor: '#81383b' });
    }

    quizPanel.set('feedback', {
      text: (correct ? 'Correct. ' : 'Not quite. ') + item.explanation,
      color: correct ? '#8ee2b4' : '#ffb0ad',
    });
    quizPanel.set('score', { text: 'Score: ' + score });
    quizPanel.set('nextText', {
      text: questionIndex === questions.length - 1 ? 'See result' : 'Next question',
    });
    quizPanel.set('next', { display: 'flex' });
  }

  for (let i = 0; i < 3; i++) {
    quizPanel.on('answer' + i, 'click', () => answerQuestion(i));
  }

  quizPanel.on('next', 'click', () => {
    if (finished) {
      questionIndex = 0;
      score = 0;
      answered = false;
      finished = false;
      renderQuestion();
      return;
    }
    if (!answered) return;

    if (questionIndex < questions.length - 1) {
      questionIndex++;
      answered = false;
      renderQuestion();
      return;
    }

    finished = true;
    quizPanel.set('progress', { text: '5 questions answered' });
    quizPanel.set('question', { text: 'Quiz complete: ' + score + ' / 5' });
    quizPanel.set('score', { text: 'Final score: ' + score + ' / 5' });
    for (let i = 0; i < 3; i++) {
      quizPanel.set('answer' + i, { display: 'none' });
    }

    let result;
    if (score === 5) {
      result = 'Excellent - you identified all five key ideas.';
    } else if (score === 4) {
      result = 'Strong work - review the explanation you missed, then try again.';
    } else if (score === 3) {
      result = 'Good start - tap the radius, ulna and wrist bones to review.';
    } else {
      result = 'Keep exploring - tap bones in the model and try the quiz again.';
    }
    quizPanel.set('feedback', { text: result, color: '#9fc3ff' });
    quizPanel.set('nextText', { text: 'Restart quiz' });
    quizPanel.set('next', { display: 'flex' });
  });

  renderQuestion();

  return {
    root,
    update(time, delta) {
      if (!reassembling) return;

      let stillMoving = false;
      const blend = 1 - Math.exp(-Math.min(delta, 0.05) * 11);

      for (const bone of bones) {
        if (isGrabbed(bone)) {
          stillMoving = true;
          continue;
        }

        bone.position.lerp(bone.userData.home, blend);
        bone.quaternion.slerp(bone.userData.homeQuaternion, blend);

        if (
          bone.position.distanceToSquared(bone.userData.home) > 0.000001 ||
          bone.quaternion.angleTo(bone.userData.homeQuaternion) > 0.006
        ) {
          stillMoving = true;
        }
      }

      if (!stillMoving) {
        for (const bone of bones) {
          bone.position.copy(bone.userData.home);
          bone.quaternion.copy(bone.userData.homeQuaternion);
        }
        reassembling = false;
        infoPanel.set('assemblyStatus', { text: 'All 30 bones are back in place.' });
      }
    },
  };
}

export default function build({ THREE, traits, ui, isGrabbed }) {
  const root = new THREE.Group();

  const SYSTEM_Y = 0.08;
  const ORBIT_Z_SCALE = 0.58;
  const LABEL_Y = 0.165;
  const LABEL_Z_ORBIT = -0.235;
  const LABEL_Z_COMPARE = -0.075;
  const COMPARE_BASE_Y = 0.008;
  const COMPARE_GAP = 0.02;
  const JUPITER_COMPARE_DIAMETER = 0.12;

  const planetData = [
    {
      name: 'Mercury', diameter: 4879, color: 0x9b9287, cssColor: '#c4b9aa',
      normalRadius: 0.015, orbitRadius: 0.050, displayPeriod: 26, phase: 0.4,
      fact: 'Mean diameter 4,879 km. Year: 88 Earth days. The smallest planet, with almost no atmosphere and no moons.',
    },
    {
      name: 'Venus', diameter: 12104, color: 0xd8aa61, cssColor: '#f0c77b',
      normalRadius: 0.016, orbitRadius: 0.083, displayPeriod: 44, phase: 2.2,
      fact: 'Mean diameter 12,104 km. Year: 225 Earth days. A dense CO2 atmosphere traps extreme heat; it spins backward.',
    },
    {
      name: 'Earth', diameter: 12742, color: 0x2e6ed0, cssColor: '#71a7ff',
      normalRadius: 0.017, orbitRadius: 0.116, displayPeriod: 60, phase: 4.4,
      fact: 'Mean diameter 12,742 km. Year: 365.25 days. One moon; the only world known to support life.',
    },
    {
      name: 'Mars', diameter: 6779, color: 0xb85435, cssColor: '#ef8a67',
      normalRadius: 0.0155, orbitRadius: 0.149, displayPeriod: 78, phase: 1.3,
      fact: 'Mean diameter 6,779 km. Year: 687 Earth days. Two small moons; iron-rich dust gives Mars its red color.',
    },
    {
      name: 'Jupiter', diameter: 139820, color: 0xc9976b, cssColor: '#e8c09a',
      normalRadius: 0.027, orbitRadius: 0.192, displayPeriod: 100, phase: 3.3,
      fact: 'Mean diameter 139,820 km. Year: 11.86 Earth years. The largest planet, with a storm called the Great Red Spot.',
    },
    {
      name: 'Saturn', diameter: 116460, color: 0xd8bd75, cssColor: '#f1d99b',
      normalRadius: 0.024, orbitRadius: 0.262, displayPeriod: 136, phase: 5.4,
      fact: 'Mean diameter 116,460 km. Year: 29.45 Earth years. Its bright rings are mostly pieces of water ice.',
    },
    {
      name: 'Uranus', diameter: 50724, color: 0x67c5cd, cssColor: '#9ce8ed',
      normalRadius: 0.021, orbitRadius: 0.320, displayPeriod: 164, phase: 0.9,
      fact: 'Mean diameter 50,724 km. Year: 84 Earth years. An ice giant rotating on its side, tilted about 98 degrees.',
    },
    {
      name: 'Neptune', diameter: 49244, color: 0x315fc4, cssColor: '#7699ff',
      normalRadius: 0.021, orbitRadius: 0.365, displayPeriod: 200, phase: 2.9,
      fact: 'Mean diameter 49,244 km. Year: 164.8 Earth years. An ice giant with the fastest winds known in the solar system.',
    },
  ];

  const panel = ui(`
    <style>
      .panel { width: 560px; display: flex; flex-direction: column; gap: 8px;
               padding-top: 16px; padding-bottom: 16px; padding-left: 18px; padding-right: 18px;
               background-color: #1a1d22; border-color: #48515f; border-width: 1px; border-radius: 18px; }
      .title { color: #ffffff; font-size: 32px; font-weight: 700; }
      .note { color: #bfc8d5; font-size: 20px; }
      .row { display: flex; flex-direction: row; align-items: center; justify-content: center; gap: 8px; }
      .btn { padding-top: 12px; padding-bottom: 12px; padding-left: 12px; padding-right: 12px;
             background-color: #343a45; border-radius: 11px; }
      .primary { background-color: #2f6fdb; }
      .speedButton { width: 48px; text-align: center; }
      .btnText { color: #ffffff; font-size: 20px; font-weight: 700; text-align: center; }
      .speedCaption { color: #d7dbe2; font-size: 20px; }
      .speedValue { width: 64px; color: #ffffff; font-size: 22px; font-weight: 700; text-align: center; }
      .infoCard { display: flex; flex-direction: column; gap: 6px;
                  padding-top: 12px; padding-bottom: 12px; padding-left: 14px; padding-right: 14px;
                  background-color: #252a32; border-radius: 12px; }
      .planetName { color: #71a7ff; font-size: 28px; font-weight: 700; }
      .fact { color: #e1e5eb; font-size: 22px; }
    </style>
    <div class="panel">
      <span class="title">Solar System</span>
      <span class="note" id="viewNote">Compressed orbits, sizes and timing. Tap a planet or its name.</span>
      <div class="row">
        <button class="btn primary" id="playButton"><span class="btnText" id="playText">Pause</span></button>
        <span class="speedCaption">Speed</span>
        <button class="btn speedButton" id="slowerButton"><span class="btnText">-</span></button>
        <span class="speedValue" id="speedText">1x</span>
        <button class="btn speedButton" id="fasterButton"><span class="btnText">+</span></button>
        <button class="btn" id="nextButton"><span class="btnText">Next planet</span></button>
      </div>
      <div class="row">
        <button class="btn primary" id="orbitButton"><span class="btnText" id="orbitText">Orbits: on</span></button>
        <button class="btn primary" id="labelButton"><span class="btnText" id="labelText">Labels: on</span></button>
        <button class="btn" id="compareButton"><span class="btnText" id="compareText">Compare sizes</span></button>
      </div>
      <div class="infoCard">
        <span class="planetName" id="planetName">Earth</span>
        <span class="fact" id="planetFact"></span>
      </div>
    </div>`, { width: 0.36, position: [0, 0.338, 0.16] });
  root.add(panel.object3D);

  const sphereGeometry = new THREE.SphereGeometry(1, 24, 16);
  const planets = [];
  let saturnRing = null;

  const orbitVertices = new Float32Array(128 * 3);
  for (let i = 0; i < 128; i++) {
    const angle = i / 128 * Math.PI * 2;
    orbitVertices[i * 3] = Math.cos(angle);
    orbitVertices[i * 3 + 1] = 0;
    orbitVertices[i * 3 + 2] = Math.sin(angle);
  }
  const orbitGeometry = new THREE.BufferGeometry();
  orbitGeometry.setAttribute('position', new THREE.BufferAttribute(orbitVertices, 3));
  const orbitMaterial = new THREE.LineBasicMaterial({
    color: 0x718096, transparent: true, opacity: 0.34, depthWrite: false,
  });

  const sun = new THREE.Mesh(
    sphereGeometry,
    new THREE.MeshStandardMaterial({
      color: 0xffc857, emissive: 0xff8a00, emissiveIntensity: 1.0, roughness: 0.7,
    }),
  );
  sun.name = 'Sun';
  sun.scale.setScalar(0.03);
  sun.position.set(0, SYSTEM_Y, 0);
  root.add(sun);

  for (let i = 0; i < planetData.length; i++) {
    const data = planetData[i];
    const material = new THREE.MeshStandardMaterial({
      color: data.color,
      emissive: data.color,
      emissiveIntensity: 0.07,
      roughness: 0.76,
      metalness: 0,
    });
    const mesh = new THREE.Mesh(sphereGeometry, material);
    mesh.name = data.name;
    mesh.scale.setScalar(data.normalRadius);
    mesh.position.set(
      Math.cos(data.phase) * data.orbitRadius,
      SYSTEM_Y,
      Math.sin(data.phase) * data.orbitRadius * ORBIT_Z_SCALE,
    );
    root.add(mesh);

    const orbit = new THREE.LineLoop(orbitGeometry, orbitMaterial);
    orbit.name = data.name + ' orbit';
    orbit.position.y = SYSTEM_Y;
    orbit.scale.set(data.orbitRadius, 1, data.orbitRadius * ORBIT_Z_SCALE);
    root.add(orbit);

    if (data.name === 'Saturn') {
      saturnRing = new THREE.Mesh(
        new THREE.TorusGeometry(1.65, 0.12, 6, 48),
        new THREE.MeshStandardMaterial({
          color: 0xe0cda4, roughness: 0.8, transparent: true, opacity: 0.88,
          side: THREE.DoubleSide,
        }),
      );
      saturnRing.name = 'Saturn rings';
      saturnRing.rotation.set(Math.PI / 2, 0, 0.28);
      mesh.add(saturnRing);
    }

    const label = ui(`
      <style>
        .tag { width: 150px; height: 58px; display: flex; align-items: center; justify-content: center;
               padding-top: 4px; padding-bottom: 4px; padding-left: 4px; padding-right: 4px;
               background-color: #1a1d22; border-color: ${data.cssColor}; border-width: 1px; border-radius: 10px; }
        .tagText { color: ${data.cssColor}; font-size: 24px; font-weight: 700; text-align: center; }
      </style>
      <button class="tag" id="pick"><span class="tagText">${data.name}</span></button>`,
      { width: 0.078, position: [(i - 3.5) * 0.086, LABEL_Y, LABEL_Z_ORBIT] });
    label.object3D.name = data.name + ' label';
    root.add(label.object3D);

    const leaderVertices = new Float32Array(6);
    leaderVertices[0] = (i - 3.5) * 0.086;
    leaderVertices[1] = 0.15;
    leaderVertices[2] = LABEL_Z_ORBIT;
    leaderVertices[3] = mesh.position.x;
    leaderVertices[4] = mesh.position.y;
    leaderVertices[5] = mesh.position.z;
    const leaderGeometry = new THREE.BufferGeometry();
    const leaderAttribute = new THREE.BufferAttribute(leaderVertices, 3);
    leaderAttribute.setUsage(THREE.DynamicDrawUsage);
    leaderGeometry.setAttribute('position', leaderAttribute);
    const leader = new THREE.Line(
      leaderGeometry,
      new THREE.LineBasicMaterial({
        color: data.color, transparent: true, opacity: 0.48, depthWrite: false,
      }),
    );
    leader.frustumCulled = false;
    root.add(leader);

    planets.push({
      ...data,
      mesh,
      material,
      orbit,
      label,
      leader,
      leaderVertices,
      leaderAttribute,
      labelX: (i - 3.5) * 0.086,
      omega: Math.PI * 2 / data.displayPeriod,
      compareRadius: data.diameter / 139820 * JUPITER_COMPARE_DIAMETER / 2,
      compareX: 0,
    });
  }

  let compareWidth = COMPARE_GAP * (planets.length - 1);
  for (let i = 0; i < planets.length; i++) {
    compareWidth += planets[i].compareRadius * 2;
  }
  let compareCursor = -compareWidth / 2;
  for (let i = 0; i < planets.length; i++) {
    const p = planets[i];
    compareCursor += p.compareRadius;
    p.compareX = compareCursor;
    compareCursor += p.compareRadius + COMPARE_GAP;
  }

  const baselineGeometry = new THREE.BufferGeometry();
  baselineGeometry.setAttribute('position', new THREE.Float32BufferAttribute([
    -compareWidth / 2, COMPARE_BASE_Y, 0,
    compareWidth / 2, COMPARE_BASE_Y, 0,
  ], 3));
  const baseline = new THREE.Line(
    baselineGeometry,
    new THREE.LineBasicMaterial({ color: 0xaeb8c6, transparent: true, opacity: 0.65 }),
  );
  baseline.name = 'True scale baseline';
  baseline.visible = false;
  root.add(baseline);

  const speeds = [0.25, 0.5, 1, 2, 4];
  let speedIndex = 2;
  let playing = true;
  let showOrbits = true;
  let showLabels = true;
  let compareMode = false;
  let selectedIndex = -1;
  let simulationTime = 0;

  function clearPlanetSelection() {
    if (selectedIndex >= 0) {
      const previous = planets[selectedIndex];
      previous.material.emissiveIntensity = 0.07;
      previous.label.set('pick', { backgroundColor: '#1a1d22' });
    }
  }

  function selectPlanet(index) {
    clearPlanetSelection();
    selectedIndex = index;
    const p = planets[index];
    p.material.emissiveIntensity = 0.22;
    p.label.set('pick', { backgroundColor: '#33445c' });
    panel.set('planetName', { text: p.name, color: p.cssColor });
    panel.set('planetFact', { text: p.fact });
  }

  function selectSun() {
    clearPlanetSelection();
    selectedIndex = -1;
    panel.set('planetName', { text: 'Sun', color: '#ffd166' });
    panel.set('planetFact', {
      text: "A G-type star about 1.39 million km across. It holds about 99.86% of the Solar System's mass.",
    });
  }

  function updateVisibility() {
    for (let i = 0; i < planets.length; i++) {
      const p = planets[i];
      p.orbit.visible = showOrbits && !compareMode;
      p.label.object3D.visible = showLabels;
      p.leader.visible = showLabels;
    }
  }

  function setView(compare) {
    compareMode = compare;
    for (let i = 0; i < planets.length; i++) {
      const p = planets[i];
      const radius = compare ? p.compareRadius : p.normalRadius;
      p.mesh.scale.setScalar(radius);
      if (compare) {
        p.mesh.position.set(p.compareX, COMPARE_BASE_Y + radius, 0);
      }
      p.label.object3D.position.z = compare ? LABEL_Z_COMPARE : LABEL_Z_ORBIT;
    }
    sun.visible = !compare;
    baseline.visible = compare;
    if (saturnRing) saturnRing.visible = !compare;
    if (compare && selectedIndex < 0) selectPlanet(2);

    panel.set('compareText', { text: compare ? 'Orbit view' : 'Compare sizes' });
    panel.set('compareButton', { backgroundColor: compare ? '#7253a3' : '#343a45' });
    panel.set('viewNote', {
      text: compare
        ? 'True relative diameters, one scale; rings hidden. Tap a name for info.'
        : 'Compressed orbits, sizes and timing. Tap a planet or its name.',
    });
    updateVisibility();
  }

  panel.on('playButton', 'click', () => {
    playing = !playing;
    panel.set('playText', { text: playing ? 'Pause' : 'Play' });
    panel.set('playButton', { backgroundColor: playing ? '#2f6fdb' : '#437357' });
  });

  panel.on('slowerButton', 'click', () => {
    speedIndex = Math.max(0, speedIndex - 1);
    panel.set('speedText', { text: speeds[speedIndex] + 'x' });
  });

  panel.on('fasterButton', 'click', () => {
    speedIndex = Math.min(speeds.length - 1, speedIndex + 1);
    panel.set('speedText', { text: speeds[speedIndex] + 'x' });
  });

  panel.on('nextButton', 'click', () => {
    selectPlanet(selectedIndex < 0 ? 0 : (selectedIndex + 1) % planets.length);
  });

  panel.on('orbitButton', 'click', () => {
    showOrbits = !showOrbits;
    panel.set('orbitText', { text: showOrbits ? 'Orbits: on' : 'Orbits: off' });
    panel.set('orbitButton', { backgroundColor: showOrbits ? '#2f6fdb' : '#343a45' });
    updateVisibility();
  });

  panel.on('labelButton', 'click', () => {
    showLabels = !showLabels;
    panel.set('labelText', { text: showLabels ? 'Labels: on' : 'Labels: off' });
    panel.set('labelButton', { backgroundColor: showLabels ? '#2f6fdb' : '#343a45' });
    updateVisibility();
  });

  panel.on('compareButton', 'click', () => setView(!compareMode));

  for (let i = 0; i < planets.length; i++) {
    const p = planets[i];
    traits(p.mesh, { grab: true, onPress: () => selectPlanet(i) });
    p.label.on('pick', 'click', () => selectPlanet(i));
  }
  traits(sun, { onPress: selectSun });

  setView(false);
  selectPlanet(2);

  return {
    root,
    update(time, delta) {
      const step = Math.min(delta, 0.05);
      const speed = speeds[speedIndex];
      if (playing && !compareMode) simulationTime += step * speed;

      for (let i = 0; i < planets.length; i++) {
        const p = planets[i];
        if (!isGrabbed(p.mesh)) {
          if (compareMode) {
            p.mesh.position.set(p.compareX, COMPARE_BASE_Y + p.compareRadius, 0);
          } else {
            const angle = p.phase + simulationTime * p.omega;
            p.mesh.position.set(
              Math.cos(angle) * p.orbitRadius,
              SYSTEM_Y,
              Math.sin(angle) * p.orbitRadius * ORBIT_Z_SCALE,
            );
            if (playing) p.mesh.rotation.y += step * speed * 0.08;
          }
        }

        const vertices = p.leaderVertices;
        vertices[0] = p.labelX;
        vertices[1] = 0.15;
        vertices[2] = p.label.object3D.position.z;
        vertices[3] = p.mesh.position.x;
        vertices[4] = p.mesh.position.y;
        vertices[5] = p.mesh.position.z;
        p.leaderAttribute.needsUpdate = true;
      }
    },
  };
}
